window.POLICIES = [{"id":"small-business-income-tax","title":"关于进一步支持小微企业和个体工商户发展有关税费政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第12号","publishedAt":"2023-08-02","effectiveAt":"2023-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠","企业所得税","个人所得税"],"audience":["小型微利企业","个体工商户"],"hot":98,"summary":"小型微利企业年应纳税所得额不超过300万元的部分，实际税负降到5%；个体工商户年应纳税所得额不超过200万元的部分，减半征收个人所得税。执行到2027年底。","sections":[{"no":"一","title":"小型微利企业所得税","text":"对小型微利企业年应纳税所得额不超过300万元的部分，减按25%计入应纳税所得额，按20%的税率缴纳企业所得税。"},{"no":"二","title":"个体工商户个人所得税","text":"对个体工商户年应纳税所得额不超过200万元的部分，减半征收个人所得税。个体工商户在享受现行其他个人所得税优惠政策的基础上，可叠加享受本条优惠政策。"},{"no":"三","title":"执行期限","text":"上述政策执行至2027年12月31日。"}],"interpretations":[{"sectionNo":"一","headline":"应纳税所得额300万元以内，实际税负5%","who":"小型微利企业：年应纳税所得额不超过300万元的部分。","materials":[],"window":"执行至2027年12月31日。","where":"按企业所得税申报渠道享受。","tip":"是「减按25%计入应纳税所得额，再按20%税率缴纳」，算下来实际税负5%；只对不超过300万元的部分适用。","evidence":{"headline":["减按25%计入应纳税所得额，按20%的税率缴纳企业所得税"],"who":["对小型微利企业年应纳税所得额不超过300万元的部分"],"window":["上述政策执行至2027年12月31日"],"where":["按20%的税率缴纳企业所得税"],"tip":["减按25%计入应纳税所得额"]}},{"sectionNo":"二","headline":"个体户200万元以内所得，个税减半且可叠加","who":"个体工商户，年应纳税所得额不超过200万元的部分。","materials":[],"window":"执行至2027年12月31日。","where":"按经营所得申报渠道享受。","tip":"可以和现行其他个人所得税优惠政策叠加享受。","evidence":{"headline":["减半征收个人所得税"],"who":["对个体工商户年应纳税所得额不超过200万元的部分"],"window":["上述政策执行至2027年12月31日"],"where":["减半征收个人所得税"],"tip":["个体工商户在享受现行其他个人所得税优惠政策的基础上，可叠加享受本条优惠政策"]}}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202308/content_6896379.htm","sourceNote":"请在税务总局官网「政策文件」栏按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"vat-small-scale","title":"关于增值税小规模纳税人减免增值税政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第19号","publishedAt":"2023-08-02","effectiveAt":"2023-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠","增值税","小规模纳税人"],"audience":["小规模纳税人","个体工商户","小微企业"],"hot":96,"summary":"小规模纳税人月销售额10万元（季度30万元）以下免征增值税；适用3%征收率的收入减按1%征收。执行到2027年底。","sections":[{"no":"一","title":"起征点免税","text":"对月销售额10万元以下（含本数）的增值税小规模纳税人，免征增值税。"},{"no":"二","title":"征收率下调","text":"增值税小规模纳税人适用3%征收率的应税销售收入，减按1%征收率征收增值税；适用3%预征率的预缴增值税项目，减按1%预征率预缴增值税。"},{"no":"三","title":"执行期限","text":"上述政策执行至2027年12月31日。"}],"interpretations":[{"sectionNo":"一","headline":"月销售额10万元以下，免征增值税","who":"月销售额10万元以下（含本数）的增值税小规模纳税人。","materials":[],"window":"执行至2027年12月31日。","where":"按增值税申报渠道享受。","tip":"口径是「月销售额10万元以下（含本数）」，超了就不再适用免征。","evidence":{"headline":["对月销售额10万元以下（含本数）的增值税小规模纳税人，免征增值税"],"who":["增值税小规模纳税人"],"window":["上述政策执行至2027年12月31日"],"where":["对月销售额10万元以下（含本数）的增值税小规模纳税人，免征增值税"],"tip":["月销售额10万元以下（含本数）"]}},{"sectionNo":"二","headline":"3%征收率减按1%征收","who":"适用3%征收率的增值税小规模纳税人；适用3%预征率的预缴增值税项目。","materials":[],"window":"执行至2027年12月31日。","where":"按增值税申报渠道享受。","tip":"预缴项目同样减按1%预征率预缴，不要按3%预缴后再申请退。","evidence":{"headline":["减按1%征收率征收增值税"],"who":["增值税小规模纳税人适用3%征收率的应税销售收入"],"window":["上述政策执行至2027年12月31日"],"where":["减按1%征收率征收增值税"],"tip":["适用3%预征率的预缴增值税项目，减按1%预征率预缴增值税"]}}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202308/content_6896287.htm","sourceNote":"请在税务总局官网按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"rd-super-deduction","title":"关于进一步完善研发费用税前加计扣除政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第7号","publishedAt":"2023-03-26","effectiveAt":"2023-01-01","status":"active","tags":["税收优惠","研发创新","科技型企业"],"audience":["科技型企业","制造业企业","有研发投入的企业"],"hot":88,"summary":"企业实际发生的研发费用，未形成无形资产的按100%加计扣除；形成无形资产的按成本的200%在税前摊销。所有符合条件行业均可享受。","sections":[{"no":"一","title":"第一条","text":"企业开展研发活动中实际发生的研发费用，未形成无形资产计入当期损益的，在按规定据实扣除的基础上，自2023年1月1日起，再按照实际发生额的100%在税前加计扣除；形成无形资产的，自2023年1月1日起，按照无形资产成本的200%在税前摊销。"},{"no":"二","title":"第二条","text":"企业享受研发费用加计扣除政策的其他政策口径和管理要求，按照《财政部国家税务总局科技部关于完善研究开发费用税前加计扣除政策的通知》（财税〔2015〕119号）、《财政部税务总局科技部关于企业委托境外研究开发费用税前加计扣除有关政策问题的通知》（财税〔2018〕64号）等文件相关规定执行。"},{"no":"三","title":"第三条","text":"本公告自2023年1月1日起执行，《财政部税务总局关于进一步完善研发费用税前加计扣除政策的公告》（财政部税务总局公告2021年第13号）、《财政部税务总局科技部关于进一步提高科技型中小企业研发费用税前加计扣除比例的公告》（财政部税务总局科技部公告2022年第16号）、《财政部税务总局科技部关于加大支持科技创新税前扣除力度的公告》（财政部税务总局科技部公告2022年第28号）同时废止。\n特此公告。\n财政部税务总局2023年3月26日\n\n政策解读"}],"interpretations":[{"sectionNo":"一","headline":"研发费用据实扣除后，再按100%加计扣除","who":"开展研发活动、实际发生研发费用的企业；费用化与资本化两种情形分别处理。","materials":[],"window":"自2023年1月1日起执行。","where":"按现行企业所得税申报渠道享受（具体口径按财税〔2015〕119号等文件执行）。","tip":"未形成无形资产的按实际发生额100%加计扣除；形成无形资产的按成本200%在税前摊销，两者不能混用。","evidence":{"headline":["再按照实际发生额的100%在税前加计扣除"],"who":["企业开展研发活动中实际发生的研发费用"],"window":["自2023年1月1日起"],"where":["按照《财政部国家税务总局科技部关于完善研究开发费用税前加计扣除政策的通知》（财税〔2015〕119号）"],"tip":["形成无形资产的，自2023年1月1日起，按照无形资产成本的200%在税前摊销"]}},{"sectionNo":"三","headline":"2021年第13号等三份旧公告同时废止","who":"此前按旧公告享受研发费用加计扣除的企业。","materials":[],"window":"自2023年1月1日起执行，旧公告同时废止。","where":"主管税务机关。","tip":"2023年起按本公告口径执行，别再引用2021年第13号、2022年第16号和第28号。","evidence":{"headline":["《财政部税务总局关于进一步完善研发费用税前加计扣除政策的公告》（财政部税务总局公告2021年第13号）"],"who":["财政部税务总局公告2021年第13号"],"window":["本公告自2023年1月1日起执行"],"where":["本公告自2023年1月1日起执行"],"tip":["《财政部税务总局科技部关于加大支持科技创新税前扣除力度的公告》（财政部税务总局科技部公告2022年第28号）同时废止"]}}],"sourceUrl":"https://zc.gjzwfw.gov.cn/art/2023/3/29/art_14_63825.html","sourceNote":"请在税务总局官网按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）；2026-11-09 条文按官方原文重切（3 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"startup-guarantee-loan","title":"关于进一步做好创业担保贷款财政贴息工作的通知","level":"national","region":"全国","issuer":"财政部 人力资源社会保障部 中国人民银行","documentNo":"财金〔2018〕22号","publishedAt":"2018-03-27","effectiveAt":"2018-03-27","status":"active","tags":["融资支持","贷款贴息","创业担保"],"audience":["创业者","小微企业","返乡创业人员","高校毕业生"],"hot":84,"summary":"个人创业担保贷款由财政贴息；小微企业当年新招用符合条件人员达到在职职工25%（超100人企业15%）即可申请，同一借款人贴息累计不超过3次，非贫困地区个人贷款按2年全额贴息。","sections":[{"no":"一","title":"加大政策支持力度","text":"（一）扩大贷款对象范围。除原规定的创业担保贷款对象（城镇登记失业人员、就业困难人员、复员转业退役军人、刑满释放人员、高校毕业生、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、建档立卡贫困人口）外，将农村自主创业农民纳入支持范围。将小微企业贷款对象范围调整为：当年新招用符合创业担保贷款申请条件的人员数量达到企业现有在职职工人数25%（超过100人的企业达到15%）、并与其签订1年以上劳动合同的小微企业。\n\n（二）降低贷款申请条件。个人创业担保贷款申请人贷款记录的要求调整为:除助学贷款、扶贫贷款、住房贷款、购车贷款、5万元以下小额消费贷款（含信用卡消费）以外，申请人提交创业担保贷款申请时，本人及其配偶应没有其他贷款。\n\n（三）放宽担保和贴息要求。对已享受财政部门贴息支持的小微企业创业担保贷款，可通过创业担保贷款担保基金提供担保形式支持。对还款积极、带动就业能力强、创业项目好的借款个人和小微企业，可继续提供创业担保贷款贴息，但累计次数不得超过3次。"},{"no":"二","title":"优化申请办理程序","text":"（四）健全服务机制。各地、各部门要简化流程、提高效率，为符合条件的创业者办理创业担保贷款提供便利化服务，探索将申请受理、材料审核、征信查询等贷款手续和担保手续一次性办结。有条件的地方，应积极探索电子化审批流转模式，优化贷款申请、审核、发放各环节，保障服务的快捷优质。\n\n（五）完善担保机制。鼓励各地聚焦第一还款来源，探索通过信用方式发放创业贷款，在不断提高风险评估能力的基础上，逐步取消反担保。对获得市（设区的市）级以上荣誉称号的创业人员、创业项目、创业企业，经金融机构评估认定的信用小微企业、商户、农户，经营稳定守信的二次创业者等特定群体原则上取消反担保。"},{"no":"三","title":"因地制宜推进工作","text":"（六）落实地方自主管理权限。符合中央规定标准的贷款产生的贴息资金支出，由中央和地方财政按规定比例共担，中央财政负担部分按照普惠金融发展专项资金管理办法有关规定在年度预算规模内核定。比照实施西部大开发政策的地区，执行西部地区分担比例。除贫困地区外的其他地区，对个人贷款按2年（第1年、第2年）全额贴息执行。各地应把握节奏，分清轻重缓急，财政贴息资金要按规定及时足额拨付到位，对超出中央规定的贷款贴息部分，由地方财政自行承担，具体贴息标准和条件由地方结合实际予以确定。对地方财政部门自行安排贴息的创业担保贷款，要与中央财政贴息支持的创业担保贷款分离管理，分账核算。\n\n（七）加强基础管理。各地应优化管理方式，提高管理效率，加强信息数据收集和统计工作，掌握贷款发放和财政贴息资金使用动态，防止重复申报、不当使用，防范道德风险、保障财政资金安全，及时将创业担保贷款信息纳入金融信用信息基础数据库。财政部将与人民银行建立合作机制，开展创业担保贷款贴息资金使用情况总结分析和后评估等工作，推动提升政策精准度，优化政策执行效果。"},{"no":"四","title":"加强监督管理","text":"（八）完善配套制度。各地、各部门要制定所辖地区创业担保贷款贴息资金管理办法、业务操作规程、工作人员管理办法等配套制度。鼓励各地结合实际，积极探索优化创业担保贷款风险分担机制和呆账核销机制，巩固提升创业担保贷款政策实施效果。各经办银行要按照人民银行等部门政策规定，严格贷前审核，强化贷中服务，加强贷后管理，不断提高贷款服务质量和效率。\n\n（九）强化部门协作。各地要进一步明确各部门职责，各司其职、各担其责。人力资源和社会保障部门主要负责审核贷款贴息对象申报资格；人民银行主要负责督促经办银行规范创业担保贷款发放；财政部门主要负责按规定拨付贴息及奖补资金。各级财政、人民银行、人力资源和社会保障部门及其工作人员在专项资金办理、审批、分配工作中，若存在以虚报、冒领等方式骗取或滞留、截留、挤占、挪用专项资金的情况，以及其他滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，按照《预算法》《公务员法》《行政监察法》《财政违法行为处罚处分条例》等法律法规追究相应责任；涉嫌犯罪的，移送司法机关处理。\n\n（十）加强绩效评价。地方财政部门要设定创业担保贷款财政贴息资金绩效目标和相应绩效指标，对资金实际产出和效益进行评估，加强对绩效目标的审核和下达，强化绩效目标执行监控，确保目标如期落实。可委托第三方开展绩效评价，不断优化资金分配和使用。\n\n（十一）组织专项检查。财政部驻各地专员办要加强资金使用监督，督促有关部门和金融机构不断提升管理和服务水平。除对省级财政部门报送的材料进行合规性、完整性、真实性审核外，应对创业担保贷款财政贴息政策执行情况组织专项检查，原则上每两年至少组织一次，及时发现问题，分析提出相关建议。对检查过程中发现的重大问题，要及时向财政部报告。\n\n（十二）推进信息公开。各地要强化信息公开意识，不断扩宽创业担保贷款信息公开范围，细化公开事项、内容、时限、方式、责任主体，增加公开手段和渠道，提升公众信息获取的便利度。在杜绝个人敏感信息泄露的前提下，对贷款拟发放对象要提前进行公示，对创业担保贷款管理规定、贷款审核发放、资金拨付情况等信息做到及时、全面、准确发布。"},{"no":"五","title":"做好组织实施","text":"（十三）切实真抓实干。各地、各部门要高度重视，将落实好创业担保贷款政策作为工作重要目标和重点内容。要结合实际制定当地工作计划，抓紧制定出台配套政策措施，明确年度目标任务和具体工作措施。扎实推进相关工作，确保取得实效。\n\n（十四）健全工作机制。各部门要加强配合、协同推进，既要防止管理错位，又要防止管理真空。各部门要定期不定期召开联席会议，加强沟通与信息共享，及时协商解决政策实施过程中存在的问题，构建平稳有序、高效顺畅的工作机制。\n\n（十五）强化服务意识。各地、各部门要加强组织领导，不断深入推进简政放权、优化服务改革，健全服务体系，整合服务资源，提升信息化水平，推进基层便民服务，提升人民群众的满意度。\n\n（十六）加大宣传力度。各地要着力探索积累经验，每年要总结并报告落实情况，综合运用各种媒介、方式，加强政策解释宣传。对优秀创业企业和个人，要树立典型，形成示范案例，以点带面、梯次推进。\n\n本通知自发布之日起施行，此前发布的有关创业担保贷款政策与本通知不一致的，以本通知为准。本通知印发前已生效的创业担保贷款合同，仍按原合同约定执行。\n\n财政部\n\n人力资源社会保障部\n\n中国人民银行\n\n2018年3月27日"}],"interpretations":[{"sectionNo":"一","headline":"小微招用符合条件人员达在职职工25%，才够创业担保贷款门槛","who":"个人：城镇登记失业人员、就业困难人员、复员转业退役军人、刑满释放人员、高校毕业生、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、建档立卡贫困人口，以及新纳入的农村自主创业农民。小微企业：当年新招用符合条件人员达到在职职工25%（超100人的企业达15%），并与其签订1年以上劳动合同。","materials":[],"window":"按经办银行与当地人社部门的贷款流程办理。","where":"经办银行；资格审核由人力资源和社会保障部门负责。","tip":"个人申请时，本人及配偶除助学贷款、扶贫贷款、住房贷款、购车贷款、5万元以下小额消费贷款外应没有其他贷款；贴息累计不超过3次。","evidence":{"headline":["当年新招用符合创业担保贷款申请条件的人员数量达到企业现有在职职工人数25%（超过100人的企业达到15%）"],"who":["将农村自主创业农民纳入支持范围"],"window":["并与其签订1年以上劳动合同的小微企业"],"where":["人力资源和社会保障部门主要负责审核贷款贴息对象申报资格"],"tip":["累计次数不得超过3次"]}},{"sectionNo":"二","headline":"这几类人可逐步取消反担保","who":"获得市（设区的市）级以上荣誉称号的创业人员、创业项目、创业企业；经金融机构评估认定的信用小微企业、商户、农户；经营稳定守信的二次创业者等特定群体。","materials":[],"window":"按经办银行与当地人社部门流程办理。","where":"经办银行；各地可探索通过信用方式发放创业贷款。","tip":"取消反担保是「原则上」，具体由地方和经办银行把握；文件鼓励聚焦第一还款来源、逐步取消反担保。","evidence":{"headline":["逐步取消反担保"],"who":["对获得市（设区的市）级以上荣誉称号的创业人员、创业项目、创业企业"],"where":["鼓励各地聚焦第一还款来源，探索通过信用方式发放创业贷款"],"tip":["原则上取消反担保"]}},{"sectionNo":"三","headline":"个人贷款按2年全额贴息，中央地方按比例分担","who":"符合中央规定标准的创业担保贷款；比照实施西部大开发政策的地区执行西部地区分担比例。","materials":[],"window":"个人贷款按2年（第1年、第2年）全额贴息；超出中央规定的贴息部分由地方财政自行承担。","where":"财政部门按规定拨付贴息及奖补资金。","tip":"地方自行安排贴息的创业担保贷款，要与中央财政贴息支持的分账核算、分离管理。","evidence":{"headline":["对个人贷款按2年（第1年、第2年）全额贴息执行"],"who":["比照实施西部大开发政策的地区，执行西部地区分担比例"],"window":["对超出中央规定的贷款贴息部分，由地方财政自行承担"],"where":["财政部门主要负责按规定拨付贴息及奖补资金"],"tip":["要与中央财政贴息支持的创业担保贷款分离管理，分账核算"]}}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/2018-12/31/content_5439367.htm","sourceNote":"财政部官网按文号检索；地方实施口径请查当地人社局文件；2026-11-08 核对：现有链接指向部委首页，原文链接待补；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"sample-one-time-startup-subsidy","title":"〔示例〕一次性创业补贴实施办法","level":"city","region":"示例地区","issuer":"示例市人力资源和社会保障局","documentNo":"示例人社〔2025〕1号","publishedAt":"2025-03-01","effectiveAt":"2025-03-01","expiresAt":"2026-12-31","status":"expiring","tags":["创业补贴","补贴申领"],"audience":["首次创业者","高校毕业生","返乡创业人员"],"hot":70,"summary":"这是用于演示地区级政策的示例数据：对首次创办小微企业或个体户、正常经营满一定期限的创业者，给予一次性创业补贴。真实标准请以当地文件为准。","sections":[{"no":"一","title":"补贴对象","text":"（示例条款）首次在本市创办小微企业或个体工商户，正常经营并依法缴纳社会保险费满6个月的创业者，可申请一次性创业补贴。"},{"no":"二","title":"补贴标准与申领","text":"（示例条款）补贴标准为每人一次性5000元至10000元，同一创业者只能享受一次；申请人应在经营满6个月后的12个月内提出申请。"}],"interpretations":[{"sectionNo":"一","headline":"首创办企业，经营满半年就能领","who":"本市户籍或在本市创业的首次创业者；创办主体需为小微企业或个体工商户，且本人依法缴纳社保满6个月。已享受过同类补贴的不能重复申请。","materials":["补贴申请表","营业执照副本","社保缴费记录","本人身份证与银行账户","经营场所证明"],"window":"经营满6个月后12个月内申请，逾期视为放弃。","where":"创业地街道（乡镇）便民服务中心或人社局线上申报入口。","tip":"示例数据，仅用于演示申请流程；各地金额与条件差异很大，务必核对本地当年文件。"},{"sectionNo":"二","headline":"5000到10000元，一生只能领一次","who":"符合对象条件且未重复享受的创业者。","materials":["同上一节材料","补贴发放确认单"],"window":"按季度集中审核发放。","where":"人社部门审核后拨付至本人账户。","tip":"部分地区要求「正常经营」需有实际流水，空壳注册通常无法通过审核。"}],"sourceUrl":"https://www.mohrss.gov.cn/","sourceNote":"本条为演示用示例数据，非真实政策，请勿据此申领","verified":false,"isSample":true,"numberStyle":"item","hunan":false},{"id":"changsha-one-time-startup-subsidy-2026","title":"关于开展长沙市一次性创业补贴（含大学生一次性创业补贴）申报工作的通知","level":"city","region":"长沙市","issuer":"长沙市人力资源和社会保障局","documentNo":"","publishedAt":"2026-05-25","effectiveAt":"","expiresAt":"","status":"active","tags":["创业补贴"],"audience":["初创企业","高校毕业生"],"summary":"长沙初创企业正常经营1年以上并吸纳就业，按吸纳人数补5000至30000元，大学生同项补1万至3万元。","sections":[{"no":"一","title":"一次性创业补贴申报","text":"（一）申报条件\n\n申报长沙市一次性创业补贴，须同时具备以下条件：\n\n1.在湖南湘江新区、芙蓉区、天心区、开福区、雨花区、望城区范围内登记注册的初创企业；登记注册时间在5年以内（自注册之日至申报之日不超过5年）；\n\n2.正常经营1年以上，吸纳1名及以上劳动者就业，缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态；\n\n3.符合长沙市产业发展方向；\n\n4.在信用中国无行政处罚、严重失信等记录；\n\n5.申报人为企业法定代表人，属于就业困难人员或返乡入乡农民工，持股比例不低于企业总股份的30%；\n\n申报人非企业第一任法定代表人的，不纳入补贴范围。\n\n（二）所需资料\n\n1.《长沙市一次性创业补贴申请表》（申报系统填写资料后自动生成）；\n\n2.营业执照、申报人身份证；企业股权分配证明资料；\n\n3.申报人属于返乡入乡农民工的需提供长沙市行政区域范围内户籍地乡镇（街道）人力资源社会保障服务站或村（社区）出具的返乡创业佐证资料；属于就业困难人员的无需提供佐证资料，由湖南湘江新区民政和社会保障局、各区人力资源和社会保障局在信息系统中核实。\n\n（三）补贴标准\n\n根据吸纳城乡劳动者就业人数申请5000至30000元不等的一次性创业补贴。吸纳城乡劳动者就业人数取申报前3个月缴纳城镇职工社会保险人数的平均值。吸纳1人的按5000元标准给予一次性创业补贴；吸纳1人以上的每增加1人给予1000元补贴，最高不超过30000元。已经享受过市财政同一项目补贴的，不能重复享受。"},{"no":"二","title":"大学生一次性创业补贴","text":"（一）申报条件\n\n申报大学生一次性创业补贴，须同时具备以下条件：\n\n1.在湖南湘江新区、芙蓉区、天心区、开福区、雨花区、望城区范围内登记注册的初创企业；登记注册时间在5年以内（自注册之日至申报之日不超过5年）；\n\n2.正常经营1年以上，吸纳1名及以上劳动者就业，缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态；\n\n3.符合长沙市产业发展方向；\n\n4.在信用中国无行政处罚、严重失信等记录；\n\n5.申报人为企业法定代表人，属于离校2年内高校毕业生，且持股比例不低于企业总股份的30%；\n\n申报人非企业第一任法定代表人的，不纳入补贴范围。\n\n（二）所需资料\n\n1.《长沙市大学生一次性创业补贴申请表》（申报系统填写资料后自动生成）；\n\n2.营业执照、申报人身份证、企业股权分配证明资料；\n\n3.申报人属于离校2年内高校毕业生的相关证明材料（毕业证或学信网学籍证明）。\n\n（三）补贴标准\n\n根据吸纳城乡劳动者就业人数申请10000至30000元不等的一次性创业补贴。吸纳城乡劳动者就业人数取申报前3个月缴纳城镇职工社会保险人数的平均值。吸纳1人的按10000元标准给予一次性创业补贴；吸纳1人以上的每增加1人给予1000元补贴，最高不超过30000元。已经享受过市财政同一项目补贴的，不能重复享受。"},{"no":"三","title":"申报流程","text":"（一）线上申报。长沙市一次性创业补贴、大学生一次性创业补贴进行线上申报。申报人登录湖南省政务服务网点击“高效办成一件事”，选择“大学生就业创业落户‘一件事’——创业补贴申领”（离校2年内高校毕业生）或“个人创业‘一件事’——创业补贴申领”（返乡入乡农民工、就业困难人员），按要求填写相关信息，并上传相关资料。\n\n（二）审核报送。湖南湘江新区民政和社会保障局、各区人力资源和社会保障局负责辖区内申报资料的审核，并做好实地考察工作，将符合条件的申报人名单报送至市人力资源社会保障局。\n\n（三）市级复审。市人力资源社会保障局对申报人资料进行复审，核定申报人是否符合申报条件，对符合条件的，核定其吸纳就业人数和应补贴金额，形成拟补贴名单。\n\n（四）网上公示。每个季度对该季度拟补贴的申报人名单在市人力资源社会保障局官网上进行公示，公示期为5个工作日。\n\n（五）资金拨付。受补贴名单公示完毕后，由湘江新区民政和社会保障局、各区县（市）人力资源和社会保障局按照相关规定将扶持资金拨付至申报人账户。"},{"no":"四","title":"补贴终止","text":"出现以下情形之一的，终止享受补贴：\n\n（一）申报审核期间，初创企业实体处于停业状态，或已注销、吊销营业执照的。\n\n（二）经核实有其他不符合补贴发放政策相关条件的。"},{"no":"五","title":"工作要求","text":"（一）加强宣传推荐。湖南湘江新区民政和社会保障局、各区人力资源和社会保障局要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向，代表先进生产力、生产方式的创新创业带动就业的先进典型。\n\n（二）严肃工作纪律。任何服务于补贴申报的公职人员不得假公济私、以权谋私、索拿卡要、刁难企业和个人，收受企业和个人财物。申报人应对申报资料的真实性负责。对在申报过程中弄虚作假的申报人，一经核实，取消申报资格，情节严重的纳入诚信黑名单，不再享受长沙市政府各类财政支持。"},{"no":"六","title":"相关解释","text":"（一）“初创企业”类型包括企业、个体工商户和农民专业合作社等。\n\n（二）普通高校是指国家教育行政部门批准或备案的实施高等学历教育为主的高等学校，包括全日制大学、独立学院、职业技术学院、高等专科学校。非全日制研究生享受与全日制研究生同等对待。\n\n（三）各县（市）根据本通知精神，可参照制定相关办法。\n\n（四）其他未尽事宜，由市人力资源社会保障局负责解释。"}],"interpretations":[{"sectionNo":"一","headline":"长沙首次创业满1年，补5000至30000元，按带动就业人数算","who":"在湘江新区及芙蓉、天心、开福、雨花、望城登记注册、注册未满5年的初创企业；正常经营1年以上、吸纳1人及以上就业、缴城镇职工社保6个月以上；申报人为法定代表人且属就业困难人员或返乡入乡农民工，持股不低于30%。","materials":["《长沙市一次性创业补贴申请表》（系统填报后自动生成）","营业执照、申报人身份证","企业股权分配证明资料","返乡创业佐证资料（返乡入乡农民工，由乡镇/街道人社服务站或村社区出具）"],"window":"登记注册5年以内、正常经营1年以上、社保缴满6个月；每季度公示一次拟补贴名单。","where":"湖南省政务服务网「高效办成一件事」→「个人创业『一件事』——创业补贴申领」线上申报。","tip":"申报人不是企业第一任法定代表人的，不纳入补贴范围；已经享受过市财政同一项目补贴的不能重复享受；就业困难人员不用自己提供佐证资料。","evidence":{"headline":["根据吸纳城乡劳动者就业人数申请5000至30000元不等的一次性创业补贴"],"who":["正常经营1年以上，吸纳1名及以上劳动者就业，缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态"],"materials":["《长沙市一次性创业补贴申请表》（申报系统填写资料后自动生成）"],"window":["登记注册时间在5年以内（自注册之日至申报之日不超过5年）"],"where":["申报人登录湖南省政务服务网点击“高效办成一件事”"],"tip":["申报人非企业第一任法定代表人的，不纳入补贴范围","已经享受过市财政同一项目补贴的，不能重复享受"]}},{"sectionNo":"二","headline":"离校2年内高校毕业生创业，补贴提到1万元起、最高3万元","who":"同区域内注册未满5年的初创企业；正常经营1年以上、吸纳1人及以上就业、缴社保3个月以上；申报人为法定代表人且属离校2年内高校毕业生，持股不低于30%。","materials":["《长沙市大学生一次性创业补贴申请表》（系统填报后自动生成）","营业执照、申报人身份证","企业股权分配证明资料","毕业证或学信网学籍证明"],"window":"登记注册5年以内、正常经营1年以上、社保缴满3个月。","where":"湖南省政务服务网「高效办成一件事」→「大学生就业创业落户『一件事』——创业补贴申领」。","tip":"大学生标准比普通标准高：吸纳1人按1万元起，每多1人加1000元，最高3万元；同样要求是第一任法定代表人。","evidence":{"headline":["根据吸纳城乡劳动者就业人数申请10000至30000元不等的一次性创业补贴"],"who":["申报人为企业法定代表人，属于离校2年内高校毕业生，且持股比例不低于企业总股份的30%"],"materials":["《长沙市大学生一次性创业补贴申请表》（申报系统填写资料后自动生成）"],"window":["缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态"],"where":["选择“大学生就业创业落户‘一件事’——创业补贴申领”"],"tip":["吸纳1人的按10000元标准给予一次性创业补贴；吸纳1人以上的每增加1人给予1000元补贴，最高不超过30000元"]}}],"sourceUrl":"http://rsj.changsha.gov.cn/xxgk/fdzdgk/zfcg_131322/cggg_131324/202605/t20260525_12390713.html","sourceNote":"2026-10-31 取自长沙市人力资源和社会保障局官网采购公告栏原文页；原文未标注文号，documentNo 留空；适用范围为湘江新区及芙蓉、天心、开福、雨花、望城区。；2026-11-08 核对：页面发布日期 2026-05-25","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-2026-business-environment-measures","title":"湖南省人民政府办公厅关于印发《湖南省以问题为靶心优化营商环境若干举措》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"湘政办发〔2026〕30号","publishedAt":"2026-06-04","effectiveAt":"","expiresAt":"2031-06-04","status":"active","tags":["营商环境","融资支持"],"audience":["民营企业","中小企业","个体工商户"],"summary":"湖南出台23条优化营商环境举措：政策找企与免申即享、限时清零拖欠民企账款、工商业电价降3—5分/度、入企检查一律扫码、涉企诉求统一归口受理。自印发之日起施行，有效期5年。","sections":[{"no":"一","title":"着力解决惠企政策获得感不强的问题","text":"一、着力解决惠企政策获得感不强的问题\n\n（一）推行“政策找企”主动服务。完善“政企通”涉企政策集中发布系统，分类归集、及时更新国家、省、市惠企政策，同步公开申报条件、审核标准、流程时限等要素，实时推送“湘易办”。加强政策拆解，完善政策标签体系，统一经营主体与惠企政策标注规则，开发“政策计算器”，集中归集涉企数据，为经营主体“精准画像”，点对点推送适配政策。通过“政企通”开展全链条产业政策梳理，依托“湘易办”上线“产业链政策地图”，实现产业政策查询“一站检索”。（责任单位：省工业和信息化厅、省数据局等省直相关单位，各市州人民政府。原则上第一位为牵头单位，以下均需各市州人民政府落实，不再列出）\n\n（二）打造惠企政策兑现“快车道”。出台惠企政策兑现平台管理办法，在省政务服务网建设“惠企政策直达快享专区”，实现申报入口“一键直达”。拓展“免申即享”“直达快享”政策覆盖面，提高兑现实效，可通过数据比对确认条件的兑现事项、普惠性奖补等，实现“无需申报、资金直达”。强化全流程穿透式监管，建立政策兑现超时预警督办机制。推行政策兑现“容缺受理+后置补正”模式，对非核心材料缺失的申报事项“先受理、后补正、快兑付”。（责任单位：省数据局、省财政厅、惠企政策制定单位）\n\n（三）健全惠企政策效能评估。建立惠企政策制定、宣讲、实施、反馈、优化闭环机制，每年开展一次惠企政策效能评估，持续清理、落实、新增一批涉企发展政策。探索运用人工智能大模型辅助开展政策效能分析。（责任单位：省发展改革委、省工商联、省司法厅、惠企政策制定单位）"},{"no":"二","title":"着力解决拖欠民企账款的问题","text":"二、着力解决拖欠民企账款的问题\n\n（四）限时清零存量拖欠。紧盯交通运输、农业、水利、住房城乡建设、教育、卫生健康等重点行业及国有平台公司拖欠民营企业账款问题，建立清偿台账。省级挂牌督办大额拖欠，市县分级包干，限期完成存量拖欠清零。用好地方政府专项债券、盘活存量资产等手段，鼓励通过债务置换、资产证券化等方式筹措清偿资金。将清欠成效纳入地方政府领导班子和领导干部综合考评、国有企业负责人经营业绩考核。（责任单位：省工业和信息化厅、省财政厅、省交通运输厅、省农业农村厅、省水利厅、省住房城乡建设厅、省教育厅、省卫生健康委、省委金融办、省委组织部、省国资委、各行业主管部门）\n\n（五）源头严防新增拖欠。严格执行“无预算不支出、无资金来源不开工”规定，按照工程进度及时足额拨付政府投资项目建设资金。建立账款支付临期、逾期、政务失信三级预警督办机制。推动行业协会等定期披露企业账期信息。对发现的存量台账以外的拖欠，甄别后按漏报瞒报或者新增拖欠处理，如属新增地方政府隐性债务，按有关规定严肃追责问责，由各地自行统筹资金资源限时化解。（责任单位：省财政厅、省工业和信息化厅、各行业主管部门）\n\n（六）加强诚信履约监管。依托现有系统建设“政府合同库”，规范合同线上备案，开放经营主体上传渠道，全量归集政府投资、招商引资、政府采购、工程建设、产业扶持等各类政府合同。聚焦政府负有给付义务的合同，建立全生命周期智慧监管制度。完善政府合同履约投诉管理运行机制。将经核实的机关、事业单位、国有企业违约失信情况纳入政务失信记录，结合审计项目加强监督。对失信主体，依规限制财政资金和扶持政策申请、项目申报、评先评优。（责任单位：省发展改革委、省财政厅、省商务厅、省住房城乡建设厅、省工业和信息化厅、省审计厅、省委组织部、省国资委、各行业主管部门）"},{"no":"三","title":"着力解决资源要素使用成本较高的问题","text":"三、着力解决资源要素使用成本较高的问题\n\n（七）降低企业用能成本。进一步优化电力资源配置，完善水电调度，争取省外优质低价电源，通过改革的手段降低工商业用户电价3—5分钱每千瓦时，每年降低全省企业用能成本30—50亿元。推动省内高速公路充电服务费下降0.1元每千瓦时，每年减少用户支出2000万元。从严核定天然气管道运输价格和配气价格，挖掘空间为用户降价减负。加快推行园区“转改直”，清理转供电环节不合理加价。实行园区通信配套设施与园区建设同步规划、施工、交付。（责任单位：省发展改革委、省能源局、国网湖南省电力公司、省交通运输厅、省高速集团、省市场监管局、省住房城乡建设厅、省通信管理局）\n\n（八）优化土地资源供给。全面实施工业项目“标准地”供应，分地区、分类采取差异化地价支持政策，切实降低企业用地成本。工业用地提高土地利用率和增加容积率的，不再增收土地价款。支持产业链关联企业联合拿地、联合建楼，简化办理工业物业产权分割及转让登记流程。按建筑面积超50%的建筑功能确定土地主导用途，制定土地混合开发和空间复合利用正面清单和管控要求，符合正面清单即视为符合详细规划。因政府原因或自然灾害等不可抗力导致开竣工违约的，可由市县政府集体研究后免除企业违约责任，本文件实施前已实际竣工验收的项目，可不再追究企业开竣工违约责任。（责任单位：省自然资源厅等省直相关部门）\n\n（九）提升金融服务质效。引导金融机构完善奖励政策和尽职免责、容错纠错制度，增加民营经济相关业务绩效考核权重，逐步提升民营经济贷款占比。加强“湘信贷”平台推广应用，订单平均受理时间压减至3个工作日以内，2026年、2027年撮合授信分别达1200亿元、1500亿元以上。完善小微企业融资协调工作机制，推广随借随还、无还本续贷等便利化产品，引导金融机构不盲目停贷、压贷、抽贷、断贷。建立省市县三级政府投资基金统筹管理机制，优化投资决策与投放，形成资金合力。健全政府性融资担保体系，加大保费补贴力度，引导降低担保费率和反担保要求。推行重点企业“金融特派员”制度，银行安排专员“一对一”提供融资辅导和服务。（责任单位：省委金融办、人民银行湖南省分行、湖南金融监管局、省发展改革委、省工业和信息化厅、省科技厅、省财政厅、省融资担保集团、各行业主管部门）\n\n（十）推进物流降本增效。加快推进“公转铁”“公转水”，培育铁水联运精品线路，扩大“一单制”“一箱制”试点。优化跨境多式联运顺势监管，支持内外贸同船运输。大力发展智慧物流，搭建全省物流信息平台，推行物流运价公开透明机制，推广共享物流、统仓统配等模式，推出物流类数据增信金融产品。稳妥推进全省高速公路限速优化调整，试点绿通车辆智能核验。推动航空口岸机场货站智慧化改造，优化场地分区及物流路线，符合条件进口货物实现24小时提离，出口货物实现“抵港直装”。（责任单位：省交通运输厅、省发展改革委、省财政厅、省商务厅、省高速集团、广铁集团长沙铁路物流中心、省港航水利集团、省机场管理集团、长沙海关）"},{"no":"四","title":"着力解决中介服务不规范的问题","text":"四、着力解决中介服务不规范的问题\n\n（十一）深化中介服务源头治理。各行业主管部门分领域编制中介服务事项清单，逐项明确中介服务内容、设定依据、服务时限、收费标准等要素，依托省网上中介服务超市集中发布并动态更新，清单之外一律不得强制或者变相要求申请人委托中介机构开展服务。进一步简化中介服务报告编制，突出必要信息和核心数据，按照简约、高效、便利原则，分级分类明确结果要件要求。规范各部门下属事业单位及主管的行业协会发展，结合事业单位改革，对依托行政权力、垄断中介服务的单位，予以撤并整合。（责任单位：省委社会工作部、省数据局、省委编办、省民政厅、各行业主管部门）\n\n（十二）加强中介服务跟踪管理。全面推广省网上中介服务超市，实现供需对接全程透明。开展中介服务质量跟踪评价，推行“好差评”制度，评价结果与入驻资格、业务承接挂钩。加强中介服务机构监管，建立中介机构不良行为记录库，将失信中介机构名单推送至“信用湖南”一体化平台，依法依规实施联合惩戒。严格规范中介服务收费，严查超标准收费、捆绑收费、变相牟利行为。（责任单位：省数据局、省发展改革委、省市场监管局、各行业主管部门）\n\n（十三）开展中介服务专项整治。聚焦投资项目审批、专项评估评价、检验检测、法律服务、信贷服务、招工服务等重点领域，分类开展中介服务专项整治，纳入群众身边不正之风和腐败问题集中整治重点。严格落实禁止在职、退休公职人员在中介机构兼职取酬的纪律规定，针对性开展审计监督。建立中介违规行为举报绿色通道，对查实的违规中介，清出中介超市，依法依规追责问责。（责任单位：省纪委监委、省委组织部、省委社会工作部、省民政厅、省审计厅、省数据局、各行业主管部门）"},{"no":"五","title":"着力解决涉企执法检查突出问题","text":"五、着力解决涉企执法检查突出问题\n\n（十四）全面深化“扫码入企”。深化“扫码入企、联码督查”，实现亮码入企、全程留痕、闭环监督。公安、税务等部门全面接入扫码入企系统。除法律法规另有规定外，所有入企行政检查、调研、服务等行为一律扫码登记，被检查对象可扫码核验执法资质、检查权限，有异议可一键反馈。建立企业“拒绝未扫码检查”保护机制，严肃查处未按规定扫码、以规避扫码为由要求企业前往相关单位现场办理业务等行为。（责任单位：省司法厅、省公安厅、省税务局、各行政执法部门）\n\n（十五）规范行政执法自由裁量权。依托全省行政执法和行政执法监督一体化平台，建立全省统一的行政处罚裁量权基准数据库、涉企执法案例库，通过案例公开、大数据比较、社会监督，压缩自由裁量空间。（责任单位：省司法厅、各行政执法部门）\n\n（十六）实施分级分类精准监管。健全“信用+风险”监管体系，建立“无感监测”对象清单和“无事不扰”事项清单，对风险低、信用好的企业优先采用非现场检查。动态更新轻微违法行为依法免罚、轻罚事项清单，扩大柔性执法适用范围。对违法行为轻微并及时改正、没有造成危害后果的，推广行政执法“观察期”制度。（责任单位：省司法厅、省市场监管局、省发展改革委、各行政执法部门）"},{"no":"六","title":"着力解决妨碍民营企业公平参与市场竞争的问题","text":"六、着力解决妨碍民营企业公平参与市场竞争的问题\n\n（十七）维护公平竞争秩序。全面开展市场准入效能评估，保障各类经营主体平等进入。定期发布基础设施、公共服务等领域适合民间资本参与的项目，不得设置隐性门槛。持续优化“机器管招投标”，重点规范复评管理、投诉处理等行政监督环节，建立全链条、穿透式数智化监管体系。深化招标投标领域突出问题整治，重点打击、公开曝光围标串标、买标卖标、转包、违法分包等损害市场秩序的违法违规行为。鼓励招标人对信用较好的企业免除投标担保。深化政府采购领域违法违规行为专项整治。（责任单位：省发展改革委、省市场监管局、省财政厅、省公共资源交易中心、各行业主管部门）\n\n（十八）推动市场高效畅通。完善企业跨区域迁移机制，实现只向迁入地申请一次。优化企业注销流程，推动长期未经营或停止经营企业和个体工商户市场退出。严肃查处对企业跨区域经营、迁移或者注销设置障碍等行为。推动行业部门、国有企业主动开放应用场景，建立面向民营企业常态化开放机制。拓展开放平台，支持有条件的市州、园区按照规定程序在重点国别地区设立联络代表处。（责任单位：省市场监管局、省发展改革委、省数据局、省税务局、省人力资源社会保障厅、省医保局、省直住房资金管理中心、省商务厅、省国资委、各行业主管部门）\n\n（十九）深化重点领域整治。建立恶意举报异常名录库，依法打击恶意索赔、敲诈勒索、缠诉闹访等违法行为。重拳整治平台经济乱象，重点规制利用数据和算法、技术、资本优势、平台规则实施的算法共谋、大数据杀熟、“二选一”限定交易、利用规则封禁屏蔽、附加不合理交易条件等垄断行为。严厉打击平台经营者利用市场支配地位向平台内经营者收取不公平高额费用、低于成本销售排挤竞争对手等行为。（责任单位：省市场监管局、省委社会工作部、省高级人民法院、省人民检察院、省发展改革委、省公安厅、各行业主管部门）"},{"no":"七","title":"着力解决民营企业“投诉无门”的问题","text":"七、着力解决民营企业“投诉无门”的问题\n\n（二十）完善诉求办理机制。发挥省民营经济发展局（省营商环境建设局）统一归口受理涉企诉求职能，迭代升级省营商环境诉求办理平台，优化诉求办理全链条闭环管理和服务体系。对深层次营商环境疑难问题，建立“法治会诊”机制，组织政法、公安、检察院、法院、司法行政、纪检、审计部门及行业专家等联合会诊解难。（责任单位：省发展改革委、省委政法委、省公安厅、省人民检察院、省高级人民法院、省司法厅、省纪委监委、省审计厅、各行业主管部门）\n\n（二十一）优化涉企法律服务。完善法律服务对接机制，提供送法进企、法治体检、纠纷调解等服务。加强涉外法律服务机构培育，建强涉外法律服务人才专家库，为出海企业提供公益法律服务。加强一流公证机构和公证领军人才培育，优化公证便企利企服务。依托综治中心加强诉讼、调解、仲裁等对接，提供一站式商事纠纷多元化解服务。（责任单位：省司法厅等省直相关部门）"},{"no":"八","title":"着力解决政商关系“亲清”不分的问题","text":"八、着力解决政商关系“亲清”不分的问题\n\n（二十二）规范政商交往行为。落实省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》，紧扣政商交往突出问题，聚焦企业需求和干部顾虑，推动构建亲而有度、清而有为的亲清新型政商关系。（责任单位：省纪委监委、省委统战部、省工商联）\n\n（二十三）激发干事创业活力。选取不同类型民营企业设立营商环境亲清监测点，动态收集企业意见建议。（责任单位：省委统战部、省工商联）落实“三个区分开来”，区别对待在推动企业发展中出现的失误错误，激励党政机关及公职人员主动担当作为。（责任单位：省纪委监委）对服务企业成效突出的公职人员，在评优评先、选拔任用中予以倾斜。（责任单位：省委组织部）\n\n各级各部门要压实责任，强化协同，细化举措，力戒形式主义，确保落地见效。省发展改革委要加强统筹协调、跟踪督导，提炼推广经验，通报问题不足，重要情况及时向省委、省人民政府请示报告，推动全省营商环境持续优化提升。\n\n本措施自印发之日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"一","headline":"政策主动找企业，符合条件可「免申即享」","who":"在湖南经营的各类经营主体，重点是需要申报惠企政策的企业；通过「政企通」「湘易办」获取政策与申报入口。","materials":[],"window":"持续推进；惠企政策效能评估每年开展一次。","where":"「政企通」涉企政策集中发布系统与「湘易办」平台；省政务服务网「惠企政策直达快享专区」。","tip":"可通过数据比对确认条件的兑现事项、普惠性奖补，目标是「无需申报、资金直达」；非核心材料缺失时可先受理后补正。","evidence":{"headline":["推行“政策找企”主动服务"],"who":["完善“政企通”涉企政策集中发布系统"],"window":["每年开展一次惠企政策效能评估"],"where":["在省政务服务网建设“惠企政策直达快享专区”"],"tip":["实现“无需申报、资金直达”"]}},{"sectionNo":"二","headline":"拖欠民企账款要限期清零，新增拖欠严查","who":"被机关、事业单位、国有企业拖欠账款的民营企业，重点行业包括交通运输、农业、水利、住建、教育、卫生健康及国有平台公司。","materials":["账款凭证与合同（用于主张清偿）"],"window":"限期完成存量拖欠清零；建立台账后按督办节点推进。","where":"省级挂牌督办大额拖欠、市县分级包干；可通过政府合同履约投诉机制反映。","tip":"「无预算不支出、无资金来源不开工」是源头约束；被核实的违约失信会进政务失信记录，并影响其财政资金与项目申报。","evidence":{"headline":["限期完成存量拖欠清零"],"who":["紧盯交通运输、农业、水利、住房城乡建设、教育、卫生健康等重点行业及国有平台公司拖欠民营企业账款问题"],"materials":["建立清偿台账"],"window":["限期完成存量拖欠清零"],"where":["省级挂牌督办大额拖欠，市县分级包干"],"tip":["无预算不支出、无资金来源不开工","将经核实的机关、事业单位、国有企业违约失信情况纳入政务失信记录"]}},{"sectionNo":"三","headline":"工商业电价降3—5分/度，工业用地不再因提容增收地价","who":"省内工商业用电企业、工业用地企业，以及有融资需求的民营企业。","materials":[],"window":"2026—2027年（金融部分明确两个年度的撮合授信目标）。","where":"电价由省发改委、省能源局、国网湖南电力落实；用地找自然资源部门；融资通过「湘信贷」平台。","tip":"工业用地提高利用率、增加容积率不再增收土地价款；因政府原因或不可抗力导致的开竣工违约，可申请免除违约责任。","evidence":{"headline":["降低工商业用户电价3—5分钱每千瓦时","不再增收土地价款"],"who":["引导金融机构完善奖励政策和尽职免责、容错纠错制度"],"window":["2026年、2027年撮合授信分别达"],"where":["加强“湘信贷”平台推广应用"],"tip":["工业用地提高土地利用率和增加容积率的，不再增收土地价款"]}},{"sectionNo":"四","headline":"中介清单之外不得强制委托，收费要透明","who":"需要办理审批、评估、检测、法律、信贷、招工等中介服务的经营主体。","materials":[],"window":"持续推进；专项整治按部署分批开展。","where":"省网上中介服务超市（清单发布、供需对接、「好差评」）。","tip":"清单之外一律不得强制或变相要求委托中介；超标准收费、捆绑收费、变相牟利可举报，失信中介会被联合惩戒。","evidence":{"headline":["清单之外一律不得强制或者变相要求申请人委托中介机构开展服务"],"who":["各行业主管部门分领域编制中介服务事项清单"],"window":["开展中介服务专项整治"],"where":["全面推广省网上中介服务超市"],"tip":["评价结果与入驻资格、业务承接挂钩"]}},{"sectionNo":"五","headline":"入企检查一律扫码，轻微违法多用免罚与观察期","who":"省内接受行政检查、调研、服务的各类企业。","materials":[],"window":"持续执行。","where":"扫码入企系统（公安、税务等部门已接入）；对未扫码检查可一键反馈。","tip":"企业有权拒绝未扫码检查；风险低、信用好的企业优先非现场检查；违法行为轻微并及时改正、没有造成危害后果的，可适用「观察期」。","evidence":{"headline":["所有入企行政检查、调研、服务等行为一律扫码登记"],"who":["建立企业“拒绝未扫码检查”保护机制"],"window":["实现亮码入企、全程留痕、闭环监督"],"where":["公安、税务等部门全面接入扫码入企系统"],"tip":["推广行政执法“观察期”制度","动态更新轻微违法行为依法免罚、轻罚事项清单"]}},{"sectionNo":"六","headline":"招投标不得设隐性门槛，信用好可免投标担保","who":"参与招投标、政府采购、跨区域迁移或注销的各类经营主体，重点是民营企业。","materials":[],"window":"持续执行。","where":"省公共资源交易中心（机器管招投标）、市场监管部门（迁移与注销）。","tip":"企业跨区域迁移只需向迁入地申请一次；招标人可对信用较好的企业免除投标担保；对设置迁移、注销障碍的行为会被查处。","evidence":{"headline":["鼓励招标人对信用较好的企业免除投标担保"],"who":["保障各类经营主体平等进入"],"window":["持续优化“机器管招投标”"],"where":["完善企业跨区域迁移机制，实现只向迁入地申请一次"],"tip":["严肃查处对企业跨区域经营、迁移或者注销设置障碍等行为"]}},{"sectionNo":"七","headline":"涉企诉求统一归口，疑难问题「法治会诊」","who":"在湖南经营、遇到政策兑现或执法争议的民营企业。","materials":[],"window":"持续执行。","where":"省民营经济发展局（省营商环境建设局）统一归口受理；省营商环境诉求办理平台。","tip":"深层次疑难问题可走「法治会诊」，由政法、公安、检察、法院、司法行政、纪检、审计及专家联合会诊。","evidence":{"headline":["统一归口受理涉企诉求职能"],"who":["发挥省民营经济发展局（省营商环境建设局）统一归口受理涉企诉求职能"],"window":["优化诉求办理全链条闭环管理和服务体系"],"where":["迭代升级省营商环境诉求办理平台"],"tip":["建立“法治会诊”机制"]}},{"sectionNo":"八","headline":"政商交往划边界，干事创业有容错","who":"与政府部门打交道的民营企业；以及服务企业的公职人员（激励与容错条款）。","materials":[],"window":"持续执行。","where":"省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》框架下；营商环境亲清监测点。","tip":"落实「三个区分开来」，对推动企业发展中的失误错误区别对待；服务企业成效突出的公职人员在评优评先、选拔任用中倾斜。","evidence":{"headline":["落实省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》"],"who":["选取不同类型民营企业设立营商环境亲清监测点"],"window":["推动构建亲而有度、清而有为的亲清新型政商关系"],"where":["紧扣政商交往突出问题，聚焦企业需求和干部顾虑"],"tip":["落实“三个区分开来”"]}}],"sourceUrl":"https://kjt.hunan.gov.cn/kjt/xxgk/zcfg/sbgfxwj/202606/t20260623_34009868.html","sourceNote":"2026-11-02 取自湖南省科技厅政策法规栏目转载原文页（省政府办公厅文件，网页发布 2026-06-04）；原文「本措施自印发之日起施行，有效期5年」，按网页发布日期推算有效期至 2031-06-04；省科技厅为转载栏目，正式文本以省政府门户发布为准。；2026-11-08 核对：页面发布日期 2026-06-04","verified":true,"isSample":false,"hunan":true,"numberStyle":"item","bodyVerified":"verbatim"},{"id":"hunan-2026-wage-guideline","title":"湖南省人力资源和社会保障厅关于发布湖南省2026年企业工资指导线的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅","documentNo":"湘人社规〔2026〕18号","publishedAt":"2026-01-01","effectiveAt":"2026-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["用工成本"],"audience":["各类企业","国有企业","非国有企业"],"summary":"2026年湖南企业工资指导线：上线8%、基准线6%、下线2%，适用于城镇各类企业；效益好的可往上线谈，效益差的可零增长甚至负增长，但不得低于当地最低工资。","sections":[{"no":"一","title":"2026年我省工资指导线","text":"一、2026年我省工资指导线\n\n(一)2026年我省企业工资指导线上线为8%。\n\n(二)2026年我省企业工资指导线基准线为6%。\n\n(三)2026年我省企业工资指导线下线为2%。"},{"no":"二","title":"工资指导线执行范围","text":"二、工资指导线执行范围\n\n2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体。\n\n(一)对经济效益比上年有较大增长幅度或扭亏成效显著的企业,可在工资指导线的基准线和上线区间内协商确定工资增长幅度。\n\n(二)现有工资水平已超过所在地在岗职工平均工资2倍的企业和经济效益比上年增长幅度较小的企业,可在工资指导线的下线与基准线的区间内协商确定工资增长幅度。\n\n(三)当年效益情况与往年持平或略有下降的企业,可结合自身实际参照下线确定工资增长幅度。\n\n(四)对于经营亏损、职工工资发放出现困难的企业,经与工会或职工代表协商,工资可以零增长或负增长,但支付给劳动者的工资不得低于当地最低工资标准。"},{"no":"三","title":"工作要求","text":"三、工作要求\n\n(一)全省各类企业应建立健全工资决定机制和正常增长机制,根据本企业经济效益和劳动生产率的具体情况,协商确定2026年度工资增长比例,合理安排工资增长。着力提高工资水平偏低、工资增长缓慢的普通职工,特别是生产一线及技术工人岗位人员工资水平,使生产一线职工工资增长幅度不低于职工平均工资增长幅度。\n\n1.国有企业(含国有独资、控股和实际控制的企业,下同)应按照国有企业工资决定机制改革的有关规定编制工资总额预算方案,在工资监管部门核准或备案的工资总额预算内,通过与工会开展工资集体协商,合理确定本企业2026年度的职工工资增长幅度和工资水平。\n\n2.非国有企业应依据工资指导线和劳动报酬增长与劳动生产率提高同步的要求,积极主动地与工会或职工协商代表开展工资集体协商,合理确定本企业2026年度的职工工资增长幅度和工资水平。\n\n(二)各级工会组织要加强对企业工会工作的指导,与企业共同协商工资分配制度、分配形式及工资调整幅度,促进企业发展与维护职工权益有机结合,合理提高职工工资水平。\n\n(三)各级人力资源社会保障行政部门要按规定做好国有企业工资总额执行结果的备案工作,加大对工资指导线和《湖南省企业工资集体协商条例》的宣传力度,加强对企业执行情况的监督检查,进一步发挥工资指导线的宏观调控作用,切实提升工资指导线的实施效果和社会影响力。\n\n本通知自2026年1月1日起施行,有效期一年。\n\n政策解读:湖南省2026年企业工资指导线政策解读\n\n湖南省人力资源和社会保障厅\n\n2026年9月28日"}],"interpretations":[{"sectionNo":"一","headline":"2026年工资增长：上限8%、基准6%、下限2%","who":"湖南省内城镇各类企业在与工会协商年度工资增长幅度时参照（原文先给出三条线，再在第二条明确适用范围）。","materials":[],"window":"2026年度工资增长协商时使用。","where":"由企业与工会或职工代表协商确定，报人社部门备案（国企工资总额另有核准/备案程序）。","tip":"三条线是协商区间不是强制标准；效益下滑时按下限甚至零增长谈，别越过当地最低工资。","evidence":{"headline":["企业工资指导线上线为8%","基准线为6%","2026年我省企业工资指导线下线为2%"],"who":["2026年我省企业工资指导线上线为8%"],"window":["2026年我省工资指导线"],"where":["(一)2026年我省企业工资指导线上线为8%"],"tip":["2026年我省企业工资指导线下线为2%"]}},{"sectionNo":"二","headline":"四类企业分别对应不同协商区间","who":"2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体。效益大幅增长或扭亏显著的企业，在基准线与上线之间谈；工资已超过当地在岗职工平均工资2倍、或增幅较小的企业，在下线与基准线之间谈；效益持平或略降的按下线；经营亏损、发薪困难的经协商可零增长或负增长。","materials":[],"window":"2026年度工资集体协商期间。","where":"企业内部工资集体协商；国企另需在工资总额预算内核准备案。","tip":"即使零增长或负增长，支付给劳动者的工资也不得低于当地最低工资标准；超额发放的「超2倍」企业不能往上限方向谈。","evidence":{"headline":["可在工资指导线的基准线和上线区间内协商确定工资增长幅度"],"who":["2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体","现有工资水平已超过所在地在岗职工平均工资2倍的企业"],"window":["2026年工资指导线"],"where":["可在工资指导线的下线与基准线的区间内协商确定工资增长幅度"],"tip":["工资可以零增长或负增长,但支付给劳动者的工资不得低于当地最低工资标准"]}},{"sectionNo":"三","headline":"企业要建工资协商机制，一线职工增幅不低于平均","who":"全省各类企业；国有企业需编制工资总额预算方案并在核准或备案的预算内协商，非国有企业依据工资指导线开展集体协商。","materials":["工资总额预算方案（国有企业）","工资集体协商相关材料"],"window":"2026年度；本通知自2026年1月1日起施行，有效期一年。","where":"企业工会/职工代表协商；国有企业报工资监管部门核准或备案；人社部门负责备案与监督检查。","tip":"文件特别要求提高一线及技术工人工资，使生产一线职工工资增长幅度不低于职工平均工资增长幅度。","evidence":{"headline":["协商确定2026年度工资增长比例"],"who":["国有企业(含国有独资、控股和实际控制的企业","非国有企业应依据工资指导线和劳动报酬增长与劳动生产率提高同步的要求"],"materials":["编制工资总额预算方案"],"window":["本通知自2026年1月1日起施行,有效期一年"],"where":["在工资监管部门核准或备案的工资总额预算内"],"tip":["使生产一线职工工资增长幅度不低于职工平均工资增长幅度"]}}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202610/t20261015_34081933.html","sourceNote":"2026-11-02 取自湖南省人社厅「厅发规范性文件」原文页（湘人社规〔2026〕18号，网页发布 2026-10-15，落款 2026-09-28）；原文「自2026年1月1日起施行，有效期一年」，据此推算有效期至 2026-12-31。；2026-11-08 核对：页面发布日期 2026-10-15","verified":true,"isSample":false,"hunan":true,"numberStyle":"item","bodyVerified":"verbatim"},{"id":"hunan-ai-zhifuwanqi-fund-2026","title":"关于组织开展2026年湖南省“人工智能+”“智赋万企”行动相关项目支持资金申报工作的通知","documentNo":"湘工信财务〔2026〕160号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2026-05-06","effectiveAt":"","expiresAt":"","status":"active","tags":["数字化转型"],"audience":["制造业企业","中小企业"],"summary":"2026年湖南省“人工智能+”“智赋万企”行动相关项目支持资金申报通知，对2025年9月3日实施方案发布以来获评的人工智能创新应用、工业互联网平台、数字化转型促进中心、高标准数字园区、国家级数字化转型标杆等事项给予奖励，网上申报截止2026年6月5日。","sections":[{"no":"一","title":"支持方向","text":"对2025年9月3日《实施方案》发布以来，符合条件的以下事项进行奖励：\n\n（一）支持人工智能创新应用。优秀算法产品、数据产品；通过国家网信办备案的生成式人工智能大模型、国家人工智能“揭榜挂帅”优胜单位；湖南省级人工智能终端产品、人工智能大模型、人工智能赋能新型工业化典型应用场景以及“人工智能+      ”十大示范场景（企业主体）。\n\n（二）支持工业互联网创新发展。国家级“双跨”工业互联网平台、湖南省工业互联网平台、湖南省“    5G+工业互联网”标杆工厂、工业互联网标识解析二级节点。\n\n（三）支持建设制造业数字化转型促进中心。国家级、湖南省制造业数字化转型促进中心。\n\n（四）支持建设高标准数字园区。国家级、湖南省高标准数字园区。\n\n（五）支持争创国家数字化智能化转型标杆。实体经济和数字经济深度融合、制造业数字化转型、人工智能赋能新型工业化（人工智能）、物联网赋能行业发展等国家级数字化典型案例；“数据要素×工业制造”等国家级赛事奖项；卓越级智能工厂；通过国家智能制造系统解决方案“揭榜挂帅”验收项目。"},{"no":"二","title":"申报条件","text":"（一）申报单位。申报单位应具有独立法人资格，或为独立核算并纳入最小法人统计的分公司或子公司，具有健全的财务管理机构和制度，依法纳税，能够严格落实资金管理要求，积极配合做好调查、调度、绩效评价等工作，信用状况良好。\n\n（二）申报项目。申报项目符合国家产业政策和有关法律法规，属于前述支持方向，经济社会效益显著，示范带动作用强。同一申报主体同一年度原则上申报不超过两个项目。\n\n（三）申报要求。详见《项目申报指南》（附件1）。\n\n（四）不符合申报条件的主要情况：\n\n1.违反安全生产、环境保护等规定，使用国家明令禁止设备进行建设的项目；\n\n2.项目单位在绩效评价中未获得通过，或在项目调度、经济运行调度等工作中不配合，造成不良影响的；\n\n3.存在被列入信用湖南网失信名单或近两年发生重大数据安全事件等其他严重问题的单位；\n\n4.存在税务、环保、安全等领域重大违法违规记录的单位；\n\n5.国家和省级文件明确不得重复申报财政资金的各类项目。"},{"no":"三","title":"申报程序","text":"（一）项目申报\n\n项目申报资料采取网上报送方式，不受理纸质申报资料。申报单位对照《项目申报指南》和申报材料模板（附件3）编制项目申请报告，通过湖南省工业和信息化厅项目管理系统（https://222.244.103.250:8181/pmp/a/login#）提交，各市州、县（市、区）工信部门及时在系统中审核上报。相关附件应全部插入到项目申请报告中一并上传，不接受多个文件上传。盖章页及相关证明材料须为原件扫描件，勿使用拍照方式。提交的所有项目资料应是可公开的，不得涉及国家秘密。\n\n（二）文件报送\n\n1.市州项目。由市州工业和信息化局负责组织项目的申报、初审等工作，市州财政局配合开展相关工作，市州工业和信息化局、财政局联合行文推荐、上报至省工业和信息化厅。财政省直管县（市）项目。由县（市）工业和信息化部门、财政部门参照市州项目的组织方式，联合行文推荐、上报至省工业和信息化厅，同时抄报所在市州工业和信息化局、财政局。中央在湘单位和省属单位项目。按照属地管理原则，通过所在地进行申报。\n\n2.各市州、财政省直管县（市）工业和信息化部门将推荐文件和《项目申报汇总表》（附件2）扫描上传至省工业和信息化厅项目管理系统，并报送纸质文件一式2份（只需红头文件和项目汇总表，不需要项目资料）至省工业和信息化厅人工智能与数字产业处。项目汇总表可编辑电子版发送到电子邮箱（hngxtrgznc@163.com）。\n\n3.网上申报及文件报送截止时间为2026年6月5日（星期五）24:00（项目管理系统将在申报截止时间自动关闭）。"},{"no":"四","title":"其他事项","text":"1.项目申报业务问题请向当地工业和信息化部门咨询（申报单位请注意所在地申报截止时间要求），或联系《项目申报指南》中各方向对应工作人员。项目管理系统操作问题咨询请联系：0731-88955465。\n\n2.各市州、财政省直管县（市）工业和信息化部门、财政部门须对申报项目资料及要件齐全性等认真把关，坚决杜绝虚假申报，不得推荐不符合条件的申报项目。对审核把关不严的地区，将予以通报批评。\n\n3.项目资料是资金安排、监督管理、绩效评价等工作的重要依据，申报单位对提交材料及附件的真实性、合法性、完整性负责，因申报材料不完善、不清晰、不正确、不符合要求等问题导致不能获得支持资金的，相关责任自负。对材料造假、使用同一凭证多头重复申报中央和省级财政补助资金的，一经查实即取消申报资格，三年内不得申报省工业和信息化厅项目资金。对获得资金支持却不配合全程监管等工作的，视情况收回已安排的资金。\n\n4.项目申报不收取任何费用。省工业和信息化厅、省财政厅未委托任何单位或个人为项目单位代理申报事宜，请相关单位自主申报，并按程序报送。如有任何中介机构或个人假借机关单位或工作人员名义进行推销或收取费用的，请向当地相关部门举报，谨防上当受骗。省工业和信息化厅举报受理电话：0731-88955596。\n\n附件：\n\n1.项目申报指南\n\n2.项目申报汇总表\n\n3.各支持方向申报材料模板（见挂网附件）\n\n湖南省工业和信息化厅\n\n湖南省财政厅\n\n2026年4月28日\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202605/t20260506_33970529.html","sourceNote":"湖南省工信厅官网公开正文，2026年度一次性奖励项目申报通知。；2026-11-08 核对：页面发布日期 2026-05-06；2026-11-09 条文按官方原文重切（4 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-equipment-upgrade-financing-2026","title":"关于组织开展第三批湖南省工业企业设备更新和技术改造项目融资补贴申报工作的通知","documentNo":"","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅、湖南省地方金融管理局、中国人民银行湖南省分行","publishedAt":"2026-09-30","effectiveAt":"","expiresAt":"","status":"active","tags":["融资支持"],"audience":["工业企业","制造业企业"],"summary":"第三批湖南省工业企业设备更新和技术改造项目融资补贴申报通知，对符合条件的工业企业设备更新技改项目给予贷款贴息或融资租赁补贴，项目须在湖南制造强省项目库入库，入库及系统申报截止2026年10月30日。","sections":[{"no":"一","title":"支持方向","text":"工业企业聚焦制造业智能化、绿色化、融合化发展和本质安全提升，以提升质量、增加品种、塑造品牌、节约成本、降低消耗、增强安全为目的，采取先进适用的新设备，对现有生产设施、生产工艺条件和辅助设施进行改造。"},{"no":"二","title":"申报基本条件","text":"1.申报单位一般应为具有独立法人资格，具有健全的财务管理机构和制度，能够严格落实资金管理要求，积极配合做好调查、调度、绩效评价等工作，诚信经营，依法纳税，无不良信用记录的工业企业。\n\n2.项目应为在建项目或在202  6年3月13日之后完工的项目，符合国家产业政策和有关法律法规，符合先进设备更新、数字化智能化改造、节能降碳改造、本质安全改造等设备更新和技术改造方向，预期经济社会效益较好，具有较强的示范带动作用。\n\n3.项目应在湖南制造强省项目库系统入库管理，接受常态化调度。由金融机构向项目提供了贷款或融资租赁，并于2024年3月7日（含）后完成贷款合同或融资租赁合同签订。\n\n4.申请贷款贴息的项目应满足以下条件：\n\n（1）项目总投资应在200万元及以上，贷款期限一年期（含）以上，贷款资金应于项目申报日前完成发放；项目贷款总额不得高于项目总投资；（2）项目设备计划总投资（包括设备采购，配套厂房及实验室等建设工程，以及软件和数据服务、安装费用等）占项目贷款总额的比例应不低于50%；（3）设备购置时间应在2024年3月7日（含）之后，购置时间早于此日期的设备不得计入设备投资之内；（4）项目已完成结算的设备投资额占设备计划总投资额的比重不低于3  0  %；（5）贷款需全部用于项目建设，不得用于购买原材料、日常经营周转、发放员工工资等；（6）贷款合同签订时间不得晚于项目完工时间；（7）已获得中央或省级贷款贴息融资补贴的贷款（2024年3月7日（含）以来）不得再次用于申报此次融资补贴。\n\n5.申请融资租赁补贴的项目，已结算的设备投资和单笔设备融资租赁合同均应在2024年3月7日（含）之后，且设备金额均不低于100万元。\n\n6.同一项目只能享受设备更新贷款中央财政贴息、省级贷款贴息、融资租赁补贴其中一项。\n\n7.存在下列情形的项目不予支持：\n\n（1）已经获得设备更新贷款中央财政贴息、省级贷款贴息或融资租赁补贴、2026年省先进制造业高地建设和中小企业发展专项重点产业项目、中小企业创新发展项目资金支持的项目。\n\n（2）纯新建项目，无设备更新和技术改造内容。\n\n（3）贷款期限低于一年（含提前还款后贷款期限低于一年）。\n\n（4）采用有关法律法规和产业政策明令禁止的设备或技术建设的项目。\n\n（5）项目实施单位在绩效评价中未获得通过，以及在项目调度、经济运行调度等工作中不配合、造成不良影响的。\n\n（6）申报单位在申报期间被发现存在信用、环保、安全等方面的严重问题。\n\n（7）企业或项目存在相关法律法规和政策规定不应予以支持的其他严重问题。"},{"no":"三","title":"基本程序","text":"1.项目实施企业通过湖南制造强省项目库系统填报完整的项目入库信息（http://222.240.80.54:18080/hnibdp-daq/login），由所在市州、县市区工信部门审核后入库管理。入库信息填报截止时间为2026年10月30日24:00。\n\n2.项目实施企业向当地县市区工信部门提出补贴申请，申请贷款贴息的项目应按照附件1、附件1-1提交申报资料，申请融资租赁补贴的项目应按照附件2、附件2-1提交申报资料。中央在湘单位和省属单位等项目按照属地管理原则，通过项目所在地进行申报。\n\n3.申报材料通过省工业和信息化厅项目管理系统（http://222.240.80.54:8086/pmp/a/login）上传提交。相关申请材料应盖章扫描后形成一个PDF文档上传（项目管理系统不接受多个文件上传）。所有申报资料须进行脱密处理。市州、县市区工信部门及时在系统中审核上报（项目管理系统关闭时间为2026年10月30日）。\n\n4  .县市区（以行政区划为准）工信部门履行项目审查主体责任，通过现场核查、资料审核等方式进行审核，商县市区财政部门后再报市州工信部门。\n\n5  .市州工信部门负责项目汇总、复核，商同级财政部门后向省工业和信息化厅推荐申报。\n\n6  .省工业和信息化厅会同省财政厅、省地方金融监管局、人民银行湖南省分行开展审核和资金测算工作。"},{"no":"四","title":"申报方式与要求","text":"（一）文件上报要求\n\n市州工信部门需于2026年10月30日前将正式推荐文件扫描上传至省工业和信息化厅项目管理系统，同时报送纸质推荐文件一式4份（仅红头文件和项目汇总表）至省工业和信息化厅投资规划处，并将项目汇总表电子版（必须是可编辑表格文件，不能是PDF或图片文件）发送到省工业和信息化厅投资规划处邮箱abc2212144@126.com。\n\n（二）文件上报收件人\n\n省工业和信息化厅投资规划处：李嘉璇电话：0731-889554  99\n\n地址：长沙市天心区新韶东路467号，邮编：410004"},{"no":"五","title":"特别提醒","text":"（一）各项目实施企业要对项目资料的申报事项真实性、数据准确性负责，由企业法人代表或法人代表委托授权人在申报资料上签名并加盖单位公章。由委托授权人签名的，应提供企业法人代表相关授权文书。对材料造假的，一经查实，立即取消申报资格、收回补助资金并依法依规处理。对获得补助资金支持却不配合后续监管的，视情况收回已安排的资金。\n\n（二）各市州、县市区工信部门要认真履行审查责任，对项目申报资料要件的齐全性、真实性等认真把关。坚决杜绝虚假申报，不得推荐不符合条件的项目，对审核把关不严的地方，将给予通报批评并追究责任。\n\n（三）金融机构应配合做好项目申报的资料准备。对金融机构参与项目信息造假、套取骗取补贴资金等情况，一经查实，将向金融监管部门通报。\n\n（四）本次申报不收取任何费用，从未委托任何单位或个人为申报单位代理申报事宜。任何机构或个人假借机关单位或工作人员名义进行推销，违背企业意愿收取费用，可向当地有关部门或省工业和信息化厅举报。省工业和信息化厅举报受理电话：0731-88955596。\n\n附件：\n\n1.第三批湖南省工业企业设备更新和技术改造项目贷款贴息申报汇总表\n\n1-1.第三批湖南省工业企业设备更新和技术改造项目贷款贴息申请报告（模板）\n\n2.第三批湖南省工业企业设备更新和技术改造项目融资租赁补贴申报汇总表\n\n2-1.第三批湖南省工业企业设备更新和技术改造项目融资租赁补贴申请报告（模板）\n\n附件下载：附件1-2\n\n湖南省工业和信息化厅\n\n湖南省财政厅\n\n湖南省地方金融管理局\n\n中国人民银行湖南省分行\n\n2026年9月30日\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/xxgk_71033/tzgg/202609/t20260930_34075438.html","sourceNote":"湖南省工信厅官网公开正文。该通知未标注独立文号，依据《关于修改〈湖南省工业企业设备更新和技术改造项目融资补贴实施办法〉的通知》（湘财产业〔2025〕5号）组织第三批申报。；2026-11-08 核对：页面发布日期 2026-09-30；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-guaranteed-loan-grads-2026","title":"湖南省人力资源和社会保障厅等三部门关于进一步优化创业担保贷款政策全力支持大学生等重点群体创业的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅、中国人民银行湖南省分行","documentNo":"湘人社规〔2026〕9号","publishedAt":"2026-08-14","effectiveAt":"2026-08-14","expiresAt":"2029-08-13","status":"active","tags":["贷款贴息"],"audience":["大学生","小微企业"],"summary":"大学生个人创业担保贷款最高额度提至50万元，按实际利率50%财政贴息，担保费率不高于0.1%并给予补贴。","sections":[{"no":"一","title":"加大政策扶持力度","text":"（一）扩大支持范围。将借款对象中的高校毕业生类别扩大为大学生，包括国内外高校在校学生或毕业5年内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年以内的毕业生。残疾人大学生可放宽至毕业8年内的毕业生。\n\n（二）提高贷款额度。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），将符合条件的大学生个人申请创业担保贷款，最高额度提高至50万元。\n\n（三）提高担保费补贴。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），政府性融资担保机构为大学生个人创业担保贷款提供担保的，收取担保费率不得高于0.1%，省财政按不高于担保金额的1.4%给予补贴。担保费补贴按实际承保期限计算，按年度补贴。"},{"no":"二","title":"完善资金保障与机制","text":"（一）优化财政贴息分担。对于大学生个人创业担保贷款所需贴息资金，由中央和省级财政承担，免除市县配套资金。对创业担保贷款贴息资金分担机制进行优化，分担比例为：脱贫县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担95%、脱贫县承担5%，其他市县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担75%、其他市县承担25%。各市州、县市区须严格落实本级应承担的贴息配套资金。\n\n（二）预拨贴息资金。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），建立贴息预拨机制，鼓励各市县财政按照当地创业担保贷款余额，年初预拨当年贴息资金，年底据实结算。贴息资金暂时不足的，由担保基金垫付，待财政贴息资金到位后直接拨付至担保基金。\n\n（三）完善基金风险分担和补充机制。将创业担保贷款纳入现有国家中小微企业贷款风险分担政策范围，各级可根据实际引入政府性担保公司担保。建立健全担保基金持续补充机制，担保基金不足的地区要及时补充。建立呆坏账代偿核销机制，每年开展一次呆坏账清理。\n\n（四）落实创业担保贷款奖补政策。落实我省创业担保贷款有关规定，省财政加大创业担保贷款奖补资金保障力度。省人力资源社会保障厅每年4月底前完成奖补资金分配方案。省财政厅每年5月底前完成奖补资金拨付。各级财政部门每年6月底前将奖补资金拨付至各单位。"},{"no":"三","title":"强化协同与宣传引导","text":"（一）健全协同与激励机制。省人力资源社会保障厅、省财政厅、人民银行湖南省分行要积极推动创业担保贷款政策落实，将发放创业担保贷款纳入年度省重点民生实事项目，将创业担保贷款担保情况纳入政府性融资担保公司绩效评价体系，并将创业担保贷款开展情况作为就业专项资金分配因素及纳入其他评价激励体系，鼓励各类银行积极参与，对服务优质、贡献突出的合作银行，在业务对接、省级财政资金存放等方面予以重点倾斜。各级人力资源社会保障、财政、人民银行等部门要提高政治站位，将落实创业担保贷款政策作为稳就业、促创业的重要举措，明确专人负责，压实工作责任。\n\n（二）优化经办服务。由省财政牵头、省融资担保集团旗下的省中小担保公司建设全线上经办的创业担保贷款数字化管理系统，接入人力资源社会保障、教育、金融监管等部门数据，推动资格审核、担保审批、银行授信、资金结算等流程并联审批。各级人力资源社会保障部门应加快人员资格审核速度，简化纸质资料，优化经办流程，及时推送担保机构。\n\n（三）加大宣传力度。各地要统筹宣传资源，创新宣传方式，充分利用政府网站、新闻发布、政策宣讲等多种渠道，广泛宣传政策内容、申请流程和典型案例，有效提高政策知晓度、覆盖面和获得感。"}],"interpretations":[{"sectionNo":"一","headline":"大学生个人创业担保贷款最高提到50万元","who":"国内外高校在校学生或毕业5年内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年以内的毕业生；残疾人大学生可放宽至毕业8年内。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"经办银行、政府性融资担保机构与当地人力资源社会保障部门。","tip":"担保费率不得高于0.1%，省财政按不高于担保金额的1.4%给予补贴，按实际承保期限年度补贴。","evidence":{"headline":["最高额度提高至50万元"],"who":["包括国内外高校在校学生或毕业5年内的大专、本科、硕士、博士毕业生"],"where":["政府性融资担保机构为大学生个人创业担保贷款提供担保的"],"tip":["收取担保费率不得高于0.1%，省财政按不高于担保金额的1.4%给予补贴"]}},{"sectionNo":"二","headline":"大学生贷款贴息由中央和省级承担，市县不用配套","who":"大学生个人创业担保贷款；脱贫县与其他市县分担比例不同。","materials":[],"window":"年初预拨当年贴息资金，年底据实结算；省人社厅每年4月底前完成奖补分配，省财政厅5月底前拨付。","where":"省级财政统筹，市县财政按规定落实本级应承担的配套资金。","tip":"脱贫县贴息资金由省财政统筹承担95%、县里承担5%；其他市县由省里承担75%、市县承担25%。","evidence":{"headline":["对于大学生个人创业担保贷款所需贴息资金，由中央和省级财政承担，免除市县配套资金"],"who":["脱贫县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担95%"],"window":["年初预拨当年贴息资金，年底据实结算"],"where":["各市州、县市区须严格落实本级应承担的贴息配套资金"],"tip":["其他市县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担75%、其他市县承担25%"]}}],"sourceUrl":"https://www.hunan.gov.cn/hnszf/szf/hnzb_18/2026/202615/szfbmwj_98721_88_1urmmqrurrdbvpccutqhrmsteguugvmdqkupkguegktvspfmfnnccnmvnkhnueqhqrmcrunhkbqgcqshkecsrgbnercksgkvunnqqdpsgvgpukgdtd/202608/t20260814_34045077.html","sourceNote":"2026-10-31 取自湖南省人民政府门户网站政府公报2026年第15期原文页；原文“自公布之日起施行，有效期3年”，公布日为公报发布日2026-08-14，据此推算有效期至2029-08-13。；2026-11-08 核对：页面发布日期 2026-08-14","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-one-time-startup-subsidy-2026","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于进一步做好一次性创业补贴工作的通知（试行）","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2026〕11号","publishedAt":"2026-08-05","effectiveAt":"2026-08-01","expiresAt":"2027-07-31","status":"active","tags":["创业补贴"],"audience":["小微企业","个体工商户"],"summary":"首次创办市场主体并正常经营1年以上，高校毕业生/在校学生补不低于1万元，其他重点群体不低于5000元。","sections":[{"no":"一","title":"补贴对象","text":"省内首次创办小微企业或从事个体经济,且所创办企业或个体工商户(以下称市场主体)自工商登记注册之日起正常运营1年以上的离校2年内高校毕业生、院校在校学生、就业困难人员、返乡入乡农民工。已在我省享受过一次性创业补贴的单位或个人,原则上不重复享受,各市州和县市区另有明确规定的除外。"},{"no":"二","title":"补贴标准","text":"就业困难人员、返乡入乡农民工创办的市场主体按最低不少于5000元/家的标准给予补贴。对离校2年内高校毕业生、院校在校学生创办的市场主体按最低不少于10000元/家的标准给予补贴。\n\n补贴所需资金从各地就业专项资金中列支。安排其他非就业专项资金用于发放一次性创业补贴的,可按照相应文件执行。"},{"no":"三","title":"补贴拨付流程","text":"(一)申请。符合条件的市场主体可采用线上或线下的方式申请一次性创业补贴。\n\n1.线上申请。符合条件的市场主体可通过“湘易办”高效办成个人创业“一件事”专区或“湘就业”小程序等线上平台填写并提交人员身份、项目等信息。\n\n2.线下申请。符合条件的市场主体可前往当地人力资源社会保障部门或相关窗口现场办理,并提供《一次性创业补贴申请表》、营业执照、国家企业信用信息公示系统下载的《企业年度报告》、法定代表人身份证明材料(具体要求见《人员身份证明材料》)。\n\n通过省人社一体化业务管理系统业务协同获得的信息,可不再提供相关证明材料。\n\n(二)审核。各级人力资源社会保障部门收到申请后,对申报资料进行审核。申请对象提供材料不实、不准导致审核错误的,后果由申请对象承担。\n\n(三)发放。审核通过后,各级人力资源社会保障、财政部门及时将补贴资金发放至补贴对象。"},{"no":"四","title":"相关要求","text":"(一)各级人力资源社会保障、财政部门要提高政治站位,将落实一次性创业补贴工作作为稳就业、促创业的重要举措。要依托省人社一体化业务管理系统,简化纸质材料、优化经办流程,切实提升经办效率。要加强政策宣传,不断提升政策知晓度。\n\n(二)各级财政、人力资源社会保障部门要严格按照相关规定,做好资金申报、审核和拨付工作,切实保障财政资金安全规范、高效精准使用。要统筹安排好资金,持续加大保障投入力度,确保政策落地见效。\n\n(三)本通知自2026年8月1日起施行,有效期一年。各地已有政策的,可按补贴对象从宽、补贴标准从高原则执行。各市州可结合实际制定细则,具备条件的,可适度放宽补贴对象、提高补贴标准。"}],"interpretations":[{"sectionNo":"一","headline":"省内首次创业、正常运营满1年，这四类人可领一次性补贴","who":"离校2年内高校毕业生、院校在校学生、就业困难人员、返乡入乡农民工；须在省内首次创办小微企业或从事个体经济，且自工商登记注册之日起正常运营1年以上。已在我省享受过一次性创业补贴的，原则上不重复享受。","materials":[],"window":"自工商登记注册之日起正常运营1年以上方可申请；本通知自2026年8月1日起施行，有效期一年。","where":"线上「湘易办」个人创业一件事专区或「湘就业」小程序；线下当地人力资源社会保障部门或相关窗口。","tip":"各市州和县市区另有明确规定的，可不按「不重复享受」处理；各地可按补贴对象从宽、补贴标准从高执行。","evidence":{"headline":["自工商登记注册之日起正常运营1年以上的离校2年内高校毕业生、院校在校学生、就业困难人员、返乡入乡农民工"],"who":["省内首次创办小微企业或从事个体经济"],"window":["本通知自2026年8月1日起施行,有效期一年"],"where":["可通过“湘易办”高效办成个人创业“一件事”专区或“湘就业”小程序等线上平台"],"tip":["各地已有政策的,可按补贴对象从宽、补贴标准从高原则执行"]}},{"sectionNo":"二","headline":"就业困难人员等补5000元起，大学生创业补1万元起","who":"就业困难人员、返乡入乡农民工创办的市场主体最低不少于5000元/家；离校2年内高校毕业生、院校在校学生创办的，最低不少于10000元/家。","materials":[],"window":"资金从各地就业专项资金中列支。","where":"各级人力资源社会保障、财政部门审核发放。","tip":"这是省级最低标准，各市州可结合实际提高；用其他非就业专项资金发放的，按相应文件执行。","evidence":{"headline":["按最低不少于5000元/家的标准给予补贴","按最低不少于10000元/家的标准给予补贴"],"who":["就业困难人员、返乡入乡农民工创办的市场主体","对离校2年内高校毕业生、院校在校学生创办的市场主体"],"window":["补贴所需资金从各地就业专项资金中列支"],"where":["各级人力资源社会保障、财政部门及时将补贴资金发放至补贴对象"],"tip":["可按照相应文件执行"]}},{"sectionNo":"三","headline":"线上用「湘易办」办，线下要交申请表、营业执照和年报","who":"符合条件的市场主体，线上或线下均可申请。","materials":["《一次性创业补贴申请表》","营业执照","国家企业信用信息公示系统下载的《企业年度报告》","法定代表人身份证明材料（按《人员身份证明材料》要求）"],"window":"收到申请后由人社部门审核，通过后由人社、财政部门发放。","where":"线上「湘易办」个人创业一件事专区、「湘就业」小程序；线下当地人社部门或窗口。","tip":"通过省人社一体化业务管理系统能协同到的信息，可以不再提供证明材料。","evidence":{"headline":["符合条件的市场主体可采用线上或线下的方式申请一次性创业补贴"],"who":["符合条件的市场主体可前往当地人力资源社会保障部门或相关窗口现场办理"],"materials":["《一次性创业补贴申请表》、营业执照、国家企业信用信息公示系统下载的《企业年度报告》"],"window":["各级人力资源社会保障部门收到申请后,对申报资料进行审核"],"where":["可通过“湘易办”高效办成个人创业“一件事”专区或“湘就业”小程序等线上平台","可前往当地人力资源社会保障部门或相关窗口现场办理"],"tip":["通过省人社一体化业务管理系统业务协同获得的信息,可不再提供相关证明材料"]}}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202608/t20260805_34040428.html","sourceNote":"2026-10-31 取自湖南省人社厅官网厅发规范性文件栏目原文页；有效期一年据原文“自2026年8月1日起施行，有效期一年”推算为2027-07-31。；2026-11-08 核对：页面发布日期 2026-08-05","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-sme-development-fund-2025","title":"关于做好2025年湖南省中小企业发展专项资金项目申报工作的通知","documentNo":"湘工信中小发展〔2025〕226号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2025-07-09","effectiveAt":"","expiresAt":"","status":"active","tags":["专项资金"],"audience":["中小企业","专精特新中小企业"],"summary":"2025年湖南省中小企业发展专项资金项目申报通知，以无偿补助方式重点支持专精特新发展类和完善服务体系类两类项目，明确申报基本条件、项目类别、名额分配、申报程序与资料要求，网上申报截止2025年8月7日。","sections":[{"no":"一","title":"申报基本条件","text":"1、在湖南省境内依法登记注册，一般应具有独立法人资格，或在湖南设立独立核算并纳入最小法人统计的分公司或子公司，截至2024年12月31日成立1年以上，申报单位应具有健全的财务管理机构和制度，能够严格落实资金管理要求，积极配合做好调查、调度、绩效评价等工作，具有良好信用。\n\n2、项目符合国家有关法律法规和产业政策，主要用于支持中小企业提升创新能力及专业化水平，优化创新创业环境，不断完善中小企业公共服务体系，开展中小企业开展合作交流等促进中小企业发展的相关工作。\n\n3、存在以下情形之一的，不得申报本专项资金项目：\n\n（1）已经申报2025年度其他省级财政专项资金补助类项目；\n\n（2）2024年已获得省先进制造业高地建设专项、省中小企业发展专项等省工业和信息化厅管理专项支持的补助类项目单位，不得申报本专项专精特新发展补助类项目；\n\n（3）2023-2024年连续两年获得省先进制造业高地建设专项、省中小企业发展专项等省工业和信息化厅管理专项支持的补助类项目单位，不得申报本专项完善服务体系补助类项目；\n\n（4）被列入“信用湖南”黑名单或者近两年在安全生产（含网络安全）、产品质量、生态环保等方面有严重不良信用记录；\n\n（5）在项目申报中存在弄虚作假行为的单位；\n\n（6）在绩效评价中未获得通过，以及在项目调度、企业服务等工作中极不配合，造成不良影响的，不得申报。"},{"no":"二","title":"申报项目类别","text":"2025年省中小企业发展专项资金以无偿补助方式重点支持以下两类项目：\n\n（一）专精特新发展类项目\n\n重点支持方向：支持中小企业进行数字化、网络化、智能化建设，购置仪器设备，改造场地设施，引进技术及服务，增强研发创新能力，改进产品质量，提高生产技术水平和生产效率，加快专精特新发展。\n\n重点支持范围：制造业中小企业，原则上是2024年认定的湖南省专精特新中小企业。项目符合专精特新发展方向，主要建设内容在2024年期间实施，主要投入发生在2024年，经济社会生态效益良好。\n\n市县区推荐名额分配：\n\n市州本级：长沙市7个，衡阳市5个，株洲市4个，湘潭市、常德市、张家界市、益阳市、郴州市、永州市各2个，邵阳市、岳阳市各3个，怀化市、娄底市各1个，湘西州8个。\n\n财政省直管县市：浏阳市、宁乡市、城步县、新宁县、资兴市各2个，其他财政省直管县市各1个。\n\n（二）完善服务体系类项目\n\n1、服务能力建设项目\n\n重点支持方向：为完善服务功能，进行的场地设施改造、软件升级、设备更新等软硬件投入（不含基建及厂房建设）。\n\n2、服务业务补助项目\n\n重点支持方向：为解决中小企业发展“急难愁盼”问题，开展“一起益企”中小企业服务、大学生创新创业服务、中小企业出海、“一月一链”中小企业融资促进等活动，推进中小企业商业价值信用贷款改革试点工作。\n\n重点支持范围：（1）有效期内的国家小型微型企业创业创新基地和国家中小企业公共服务示范平台；（2）全省中小企业公共服务平台网络窗口服务平台运营单位，有效期内的全省中小微企业核心服务机构；（3）省专精特新中小企业股权融资服务平台。\n\n1-2类项目市县区推荐名额分配：\n\n市州本级：长沙市7个，衡阳市、株洲市各4个，湘潭市、邵阳市、岳阳市、常德市、郴州市各3个，益阳市、永州市、娄底市、怀化市、张家界市各2个，湘西州5个。\n\n每个县（市区）各1个。"},{"no":"三","title":"项目申报程序","text":"（一）市州项目，由市州工业和信息化局牵头组织申报、审核等工作，市州财政局配合开展相关工作。市州工业和信息化局、财政局联合行文（含附件《2025年湖南省中小企业发展专项资金项目汇总表》，以下简称《项目汇总表》）上报省工业和信息化厅。\n\n（二）财政省直管县市项目，由县市工信部门、财政局参照市州项目的组织方式，联合行文（含《项目汇总表》）上报省工业和信息化厅，同时抄报所在市州工业和信息化局、财政局。\n\n（三）省直单位申报服务体系项目，由省直主管部门审核并行文报省工业和信息化厅。\n\n（四）审核部门对项目申报单位信用情况在“信用湖南”网站进行查询。各级工信部门要对项目是否符合国家法律法规和产业政策、是否符合专项资金支持范围和方向严格审查，对项目资料真实性、完整性、准确性、规范性严格审查。"},{"no":"四","title":"申报资料要求","text":"（一）项目申报资料提交方式：实行网上申报方式，不受理纸质申报资料。项目单位必须通过《湖南省工业和信息化厅项目管理系统》（https://222.244.103.250:8181/pmp/a/login）填报，严格按照项目类别申报模板（从《湖南省工业和信息化厅项目管理系统》中下载）编制申报资料、进行在线提交。各级工信部门及时对网上申报资料进行审核上报。\n\n（二）上报文件要求：市州和财政省直管县市工信部门将申报文件（PDF格式）和《项目汇总表》（Excel格式）上传到《湖南省工业和信息化厅项目管理系统》。\n\n（三）截止日期：2025年8月7日前完成项目申报系统审核上报及推荐文件上传流程，逾期不予受理。\n\n（四）其他事项\n\n1、项目资料是项目评审、资金安排、监督管理、绩效评价等工作的重要依据，各申报单位对项目资料真实性负责。\n\n2、所有申报内容需按照要求如实填写，准确完整，不得缺项漏项；申报材料真实性承诺及所提供的相关附件要求字迹及公章清晰；其他相关扫描件均要求资料字迹、印章清晰。主体材料不齐全的项目不予受理。\n\n3、项目申报系统填报的申报资料，包括企业申报材料真实性承诺、申请报告正文及相关附件，必须以一个完整的文档形式上传。\n\n4、专项资金的监管、绩效评价、审计等工作按照有关规定实施。各项目单位应当积极配合，如实申报有关事项。对报大建小、材料造假、使用同一凭证多头重复申报省级财政专项资金的，一经查实即取消申报资格，并登记为不良信用记录，三年内不得申报本专项资金。对获得专项资金支持却不配合全程监管，或不按约定完成项目建设的视情况收回已安排的资金。\n\n5、特别提醒：省工业和信息化厅、省财政厅未委托任何单位或个人为项目单位代理专项资金申报事宜。请相关单位按程序自主申报。凡发现代理申报，经查实将淘汰该项目。各级工信部门受理项目申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并向当地相关部门举报。"},{"no":"五","title":"联系人及地址","text":"（一）省工业和信息化厅\n\n地址：长沙市天心区新韶东路467号，邮编：410004。\n\n1、专精特新发展类项目联系人：孙丹，0731-88955539；\n\n2、完善服务体系类项目联系人：黄轶凡，0731-88955535。\n\n（二）省工业和信息化厅项目管理系统技术咨询\n\n联系人：张凯迪，0731-88955465。\n\n附件：2025年湖南省中小企业发展专项资金项目汇总表\n\n湖南省工业和信息化厅湖南省财政厅\n\n2025年7月8日\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202507/t20250709_33734493.html","sourceNote":"湖南省工信厅官网公开正文，2025年度一次性申报通知。；2026-11-08 核对：页面发布日期 2025-07-09；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-specialized-sme-2026-batch2","title":"关于组织开展2026年第二批湖南省专精特新中小企业申报工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅","documentNo":"","publishedAt":"2026-05-21","effectiveAt":"","expiresAt":"","status":"active","tags":["认定资质"],"audience":["中小企业","创新型中小企业"],"summary":"组织2026年第二批湖南省专精特新中小企业申报，须为有效期内创新型中小企业，经属地工信部门审核推荐、专家评审认定。","sections":[{"no":"一","title":"条件标准","text":"1.申报企业应在湖南省内依法设立，符合《中小企业划型标准规定》，遵守国家法律法规和行业规范。\n\n2.申报期间未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定。\n\n3.坚持企业自愿原则，符合《专精特新中小企业认定标准》（工信部企业〔2026〕2号，附件1）。\n\n4.重点聚焦制造强国重点产业（新一代信息技术产业、高档数控机床和机器人、航空航天装备、海洋工程装备及高技术船舶、先进轨道交通装备、节能与新能源汽车、电力装备、农机装备、新材料、生物医药及高性能医疗器械）、工业“六基”（核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础）、“4×4”现代化产业体系（现代石化、绿色矿业、食品加工、轻工纺织4大传统产业，工程机械、轨道交通装备、现代农业、文化旅游4大优势产业，数字、新能源、大健康、空天海洋4大新兴产业，以及人工智能、生命工程、量子科技、前沿材料4大未来产业）等领域。"},{"no":"二","title":"申报时间","text":"2026年5月20日-2026年6月1日"},{"no":"三","title":"申报方式","text":"1.申报企业须是有效期内的创新型中小企业，有效期内的专精特新中小企业、专精特新“小巨人”企业不再申报。\n\n2.按属地原则，申报企业须首先在优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下称“培育平台”）完成数字化水平评测，然后在培育平台进行线上申报，完整填写《专精特新中小企业申请书》，并打包上传佐证材料（附件2）。"},{"no":"四","title":"有关要求","text":"1.各市州工信部门要高度重视专精特新中小企业培育工作，认真履行职责，坚持条件标准，严格审核把关，确保申报质量。\n\n2.请各市州工信部门于6月1日前在培育平台提交审核意见，并将专精特新中小企业推荐函和汇总表（附件3，纸质件2份）报省工业和信息化厅，逾期不候。\n\n3.严禁弄虚作假。申报企业对申报材料的完整性、真实性、合法性负责，相关后果由申报企业自行承担。凡在申报过程中存在弄虚作假行为的，一经发现，取消本年度申报资格，并且三年内不得再次申报。\n\n4.严禁代理申报。省工业和信息化厅从未委托任何单位或个人为企业代理申报事宜，请相关企业按程序自主申报。凡委托代理申报的，一经发现，取消参评资格，且三年内不得再次申报。各级工信部门受理申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并请向当地相关部门举报。任何单位不得以参加收费培训班或解读班作为企业申报前提条件。\n\n联系电话：0731-88955419\n\n邮寄地址：长沙市天心区新韶东路467号\n\n培育平台相关问题咨询电话：85559832"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202605/t20260521_33982323.html","sourceNote":"2026-10-31 取自湖南省工业和信息化厅文件通知栏目原文页；原文未标注文号，documentNo 留空；申报窗口为2026-05-20至2026-06-01，认定标准依据工信部企业〔2026〕2号。；2026-11-08 核对：页面发布日期 2026-05-21","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"hunan-zhifuwanqi-digital-transformation-2025","title":"关于印发《深化“智赋万企”行动 加快制造业数字化转型实施方案》的通知","documentNo":"湘工信人工智能〔2025〕325号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2025-09-12","effectiveAt":"2025-09-03","expiresAt":"2028-09-02","status":"active","tags":["数字化转型"],"audience":["制造业企业","专精特新中小企业"],"summary":"湖南省深化“智赋万企”行动、加快制造业数字化转型的实施方案。提出到2027年规上工业企业数字化研发设计工具普及率超90%、关键工序数控化率超75%，并从评估诊断、人工智能应用、工业互联网、数字化转型促进中心、数字园区、争创国家级标杆等方面明确财政支持比例与上限。","sections":[{"no":"一","title":"目标要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神和习近平总书记关于湖南工作的重要讲话和重要指示批示精神，以深化“智赋万企”行动为抓手，以夯实数字基础设施为支撑，以推进企业数字化智能化改造为方向，深化数字技术在制造业大规模普及应用，加快数据和安全双向赋能，为推进新型工业化注入强劲动力。到2027年，全省规上工业企业数字化研发设计工具普及率、关键工序数控化率分别超过90%、75%，全省工业大市和重点园区规上工业企业实现数字化改造全覆盖，数字赋能、管理创新步伐明显加快。"},{"no":"二","title":"重点任务","text":"（一）推动数字基础设施建设\n\n1、提升智能算力供给。支持工业企业建设智算中心，鼓励重点地区和工业园区建设智算中心为企业提供算力服务，推动传统数据中心改造升级为智能计算中心。在严格落实国家关于算力基础设施布局要求的基础上，支持工业企业部署工业算力设备及面向特定场景的边缘计算设施。鼓励产学研合作开展工业算力创新应用部署，研发满足企业数字化转型需求的算法应用产品。支持全省算力调度和综合管理平台建设和运营，鼓励企业利用算力平台对接资源方购买算力。\n\n2、完善新型网络设施。鼓励工业企业内外网改造，支持工业企业建设5G独立专网，综合运用5G/5G-A、边缘计算、IPv6、时间敏感网络（TSN）等技术，部署新型工业路由器、交换机、网关、网管、标识中间件和算网一体化设备与系统。持续壮大工业互联网平台体系，推动国家级“双跨”工业互联网平台和省级工业互联网平台建设。支持建设国家工业互联网大数据中心湖南分中心。开展工业互联网标识解析体系“贯通”行动，支持链主企业建设运营工业互联网标识解析二级节点。加强关键信息基础设施的安全防护能力建设，提升安全防护水平。\n\n（二）推动产业“智改数转网联”\n\n3、健全数字服务体系。省市协同对省级及以上专精特新企业和规模以上工业企业数字化转型基础和需求“建档立卡”，并进行动态评估和监测。推动服务商为数字化转型意向企业开展咨询诊断，提供“一企一策”数字化解决方案。持续更新省级制造业数字化转型生态供给资源池，培育一批数字化、智能化等领域解决方案供应商，鼓励供应商为制造业企业提供优秀解决方案。支持有条件的单位建设深耕行业的制造业数字化转型促进中心，促进先进生产方式推广普及。\n\n4、“点线面”协同推进。“点”上培育数字化转型标杆。加快新一代信息技术在制造业企业的深度融合应用，持续推动企业上云上平台，每年培育一批省级制造业数字化转型标杆项目、“5G+工业互联网”标杆工厂，分级建设一批数字化转型标杆企业。深入开展两化融合管理体系贯标、数字化转型贯标、数据管理能力成熟度贯标（DCMM）。“线”上打造数字化供应链产业链。推动供应链龙头企业以商业订单为牵引构建数字化供应链体系，打造优势行业领域产业大脑和产业互联网平台，建设一批供应链产业链数字化转型典型案例，形成一批高质量制造业数据集，赋能供应链上下游中小企业数字化转型。“面”上推进重点集群和园区数字化转型。在国家级和省级先进制造业集群核心承载园区等区域，加快5G、工业互联网等新型基础设施的规模化建设应用，推动万兆园区建设，加快重点集群数字化转型，促进资源在线化、产能柔性化。推动建设高标准数字园区，探索园区数字化整体提升路径。\n\n（三）推动人工智能技术和智能装备推广\n\n5、推广人工智能创新应用。加快发展高性能智能芯片和传感器、智能机器人（含人形机器人）、智能移动终端、数字人等，培育一批人工智能终端产品；实施人工智能大模型建设计划，加强行业大模型的研发布局。开展“人工智能+制造”行动，加快人工智能技术在工业研发设计、中试验证、生产制造、营销服务、运营管理等环节的深度融合应用，打造一批人工智能赋能新型工业化典型应用场景。鼓励省内龙头企业建设具身智能训练场。\n\n6、加快智能装备部署应用。推广智能制造装备，重点推动装备制造业更新面向特定场景的智能成套生产线和柔性生产单元；电子信息制造业推进电子产品专用智能制造装备与自动化装配线集成应用；原材料制造业加快无人运输车辆等新型智能装备部署应用，推进催化裂化、冶炼等重大工艺装备智能化改造升级；消费品制造业推广面向柔性生产、个性化定制等新模式智能装备。梯度培育建设一批智能工厂，引导数字化水平较高的企业加快推进单机设备、制造单元、生产线、制造车间等智能化升级，持续建设一批智能工位、智能制造生产线（车间）和智能制造企业。\n\n（四）推动软硬件更新和安全防护\n\n7、推动基础软硬件一体化更新。推动重点产业链（集群）企业全面更新信息系统，重点推进计算整机、中央处理器（CPU）、图形处理器（GPU）、智能传感器、操作系统、数据库、办公软件等基础软硬件一体化迭代升级。鼓励省重点软件企业参与工业企业基础软硬件更新换代系统集成项目。加快省“首台套”重大技术装备、“首版次”软件产品、“首轮次”工程流片芯片、“首套件”基础电子元器件推广应用。加强软硬件耦合适配，重点推进上位机、工作站、实时数据库等基础软硬件一体化更新换代，全面更新智能操作系统、嵌入式操作系统、时序数据库、消息中间件等产品。\n\n8、加快工业软件应用迭代。推动重点产业链（集群）企业全面更新换代研发设计（CAD、CAE、PLM）、资源管理（ERP）、生产运营（MES、QMS、WMS）等各类工业软件。鼓励企业应用部署可编程逻辑控制器（PLC）、分布式控制系统（DCS）等工业操作系统。鼓励产业链龙头企业和工业软件企业、大专院校、科研院所合作开展供需结对攻关、产学研联合攻关。遴选推广省级优秀工业软件、工业操作系统产品和应用解决方案，建成动态更新的优秀工业软件资源池。推动组建省工业软件产业创新联盟，加快建设工业软件专业园区和工业技术软件化创新中心。鼓励本省工业软件企业布局和参与开源项目建设，基于开源项目开发定制化产品。鼓励重点产业链（集群）龙头企业牵头建设工业软件中试验证平台。\n\n9、提升工业信息安全防护能力。组织开展工业互联网“安全深度行”、“工业信息安全服务月”、“铸网”攻防演练等活动，依托网络安全和数据安全协调机制平台，深入开展工业互联网安全分类分级管理和数据安全分类分级管理工作。建设省工业互联网安全态势感知监测平台，加强企业网络安全设备更新改造，推动部署企业级工业互联网安全监测平台。加快建设国家网络安全产业园区（长沙），培育工业领域网络和数据安全服务机构资源池，打造网络和数据安全产业新高地。"},{"no":"三","title":"支持措施","text":"（一）支持开展评估诊断。支持各市州以政府购买服务的方式，组织服务商对具有数字化转型意向的工业企业开展诊断服务，省级财政对各市州购买诊断服务费用给予补贴，每家企业不超过2万元，已获得中小企业数字化转型城市试点资金支持的企业不重复纳入评估诊断。\n\n（二）支持人工智能创新应用。推动新型研发机构、软件企业研发算法产品和数据产品，对具有自主知识产权、满足企业数字化转型需求并推广应用的优秀算法产品、数据产品和人工智能高质量数据集，按项目投资额的2  0%给予支持，最高不超过100万元。支持通用大模型、行业大模型以及通用人工智能其他路径探索的应用研究，对通过国家网信办备案的生成式人工智能大模型、国家人工智能揭榜挂帅优胜单位，按项目投资额的30%给予支持，最高不超过300万元；对获评省级人工智能终端产品、省级人工智能大模型的单位，按项目投资额的2  0%给予支持，最高不超过100万元。推进人工智能赋能新型工业化，对获评省级人工智能赋能新型工业化典型应用场景的企业，按项目投资额的20%给予支持，最高不超过100万元。\n\n（三）支持工业互联网创新发展。加快推动工业互联网平台建设，对获评国家级“双跨”工业互联网平台、省级工业互联网平台的企业，分别按项目投资额的30%、20%给予支持，最高不超过300万元、1  00万元。深化5G+工业互联网融合应用，对获评省级“5G+工业互联网”标杆工厂的企业，按项目投资额的20%给予支持，最高不超过1  00万元。支持工业互联网标识解析二级节点建设，对取得“互联网域名服务”许可证并投入解析服务运营的企业，按项目投资额的20%给予支持，最高不超过100万元。\n\n（四）支持建设制造业数字化转型促进中心。培育专业化服务机构，对获评国家级、省级制造业数字化转型促进中心的单位，分别按项目投资额的30%、20%给予支持，最高不超过300万元、100万元。\n\n（五）支持建设高标准数字园区。推动重点园区数字化转型，对获评国家级、省级数字园区的园区，分别按项目投资额的30%、20%给予支持，最高不超过300万元、1  00万元。\n\n（六）支持争创国家数字化智能化转型标杆。对获评实体经济和数字经济深度融合、制造业数字化转型、人工智能赋能新型工业化、物联网赋能行业等国家级数字化典型案例的企业，以及入选“数据要素×工业制造”等国家级赛事奖项的企业，按项目投资额的30%给予支持，最高不超过300万元。对获评卓越级智能工厂的企业，按项目投资额的30%给予支持，最高不超过300万元；对通过国家智能制造系统解决方案“揭榜挂帅”项目验收的企业，按项目投资额的30%给予支持，最高不超过300万元。\n\n省开展“智赋万企”行动工作专班办公室负责日常工作协调、调度，各地同步建立工作推进机制，研究制定具体措施，抓好重点任务落实。积极向金融机构推荐有融资需求的制造业数字化转型重点项目。组织开展供需对接会、工业互联网一体化进园区、智能制造进园区等活动。各级工业和信息化主管部门、财政部门加强对“智赋万企”行动的政策支持，及时总结工作进展和成效，培育一批标杆企业及项目，推广典型经验和模式。"},{"no":"四","title":"本方案自公布之日起实施，有效期3年","text":"本方案自公布之日起实施，有效期3年。\n相关链接：《深化“智赋万企”行动加快制造业数字化转型实施方案》政策解读\n\n一图读懂《深化“智赋万企”行动加快制造业数字化转型实施方案》\n\n收藏\n\n国家部委网站\n\n发展改革委\n\n外交部\n\n卫生健康委\n\n国防部\n\n教育部\n\n科技部\n\n工业和信息化部\n\n公安部\n\n中央纪委国家监委\n\n民政部\n\n司法部\n\n财政部\n\n人力资源和社会保障部\n\n自然资源部\n\n生态环境部\n\n住房和城乡建设部\n\n交通运输部\n\n水利部\n\n农业农村部\n\n商务部\n\n应急管理部\n\n退役军人事务部\n\n文化和旅游部\n\n人民银行\n\n审计署\n\n海关总署\n\n税务总局\n\n市场监督管理总局\n\n广电总局\n\n民航局\n\n体育总局\n\n各省工信厅网站\n\n北京市经信局\n\n天津市工信局\n\n河北省工信厅\n\n辽宁省工信厅\n\n内蒙古工信厅\n\n黑龙江省工信厅\n\n浙江省经信厅\n\n安徽省经信厅\n\n河南省工信厅\n\n广东省工信厅\n\n湖北省经信厅\n\n重庆市经信委\n\n四川省经信厅\n\n贵州省工信厅\n\n云南省工信厅\n\n甘肃省工信厅\n\n陕西省工信厅\n\n宁夏工信厅\n\n青海省工信厅\n\n山西省工信厅\n\n吉林省工信厅\n\n上海市经信委\n\n江苏省工信厅\n\n福建省工信厅\n\n江西省工信厅\n\n山东省工信厅\n\n海南省工信厅\n\n广西工信厅\n\n新疆工信厅\n\n西藏经信厅\n\n各市州工信局网站\n\n长沙市工信局\n\n衡阳市工信局\n\n株洲市工信局\n\n湘潭市工信局\n\n邵阳市工信局\n\n岳阳市工信局\n\n常德市工信局\n\n张家界市工信局\n\n益阳市工信局\n\n郴州市工信局\n\n永州市工信局\n\n怀化市工信局\n\n娄底市工信局\n\n湘西州工信局\n\n直属机构\n\n湖南兵器工业高级技工学校\n\n中南工业学校\n\n湖南省汽车技师学院\n\n湖南省散装水泥和墙体材料改革办公室\n\n湖南无线电管理\n\n湖南省工业通信业节能监察中心\n\n湖南省电子信息产业研究院\n\n湖南省计算机软件资格考试办公室\n\n湖南省国防科技工业局技术开发中心\n\n网站地图"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202509/t20250912_33802671.html","sourceNote":"湖南省工信厅官网公开正文。有效期3年自2025-09-03公布日起算，到期日2028-09-02为推算。；2026-11-08 核对：页面发布日期 2025-09-12；2026-11-09 条文按官方原文重切（4 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"national-unemployment-stable-jobs-2026","title":"人力资源社会保障部 教育部 财政部 国家税务总局关于失业保险支持企业稳岗扩岗的通知","documentNo":"人社部发〔2026〕39号","level":"national","region":"全国","issuer":"人力资源社会保障部、教育部、财政部、国家税务总局","publishedAt":"2026-07-10","effectiveAt":"2026-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["就业补贴"],"audience":["企业","中小微企业"],"summary":"国家四部门延续实施失业保险稳岗扩岗政策：稳岗返还中小微企业按不超过上年度实缴失业保险费60%返还，一次性扩岗补助每招用1人不超过1500元，并优化技能提升补贴（初级/中级/高级分别不超过1000/1500/2000元）。政策执行期2026年1月1日至12月31日。","sections":[{"no":"一","title":"延续实施稳岗返还政策","text":"延续实施稳岗返还政策。参保企业足额缴纳失业保险费12个月以上,上年度未裁员或裁员率不高于上年度全国城镇调查失业率控制目标,30人(含)以下的参保企业裁员率不高于参保职工总数20%的,可以按规定享受失业保险稳岗返还。大型企业按不超过企业及其职工上年度实际缴纳失业保险费的30%返还,中小微企业按不超过60%返还。稳岗返还资金可用于职工生活补助、缴纳社会保险费、转岗培训、技能提升培训等稳定就业岗位以及降低生产经营成本支出。社会组织、律师事务所、会计师事务所以及以单位形式参保的个体工商户参照实施。"},{"no":"二","title":"延续实施一次性扩岗补助政策","text":"延续实施一次性扩岗补助政策。对招用毕业年度及离校两年内未就业高校毕业生、16—24岁登记失业青年,签订劳动合同并为其足额缴纳3个月以上失业、工伤、职工养老保险费的企业和社会组织,可按每招用1人不超过1500元的标准发放一次性扩岗补助。"},{"no":"三","title":"优化技能提升补贴政策","text":"优化技能提升补贴政策。参加失业保险12个月以上的企业在职职工或领取失业保险金人员,取得列入当地急需紧缺职业(工种)目录、职业种类与所在企业行业类别一致、数字和绿色职业等级证书之一的,可按初级、中级、高级分别领取不超过1000元、1500元、2000元的技能提升补贴,每人每年可享受1次补贴。对取得多项急需紧缺职业(工种)证书的,省级人力资源社会保障部门可结合本地实际,增加每人每年申请补贴次数,共计不超过3次。各地可在确保基金安全的前提下,探索更多证岗相适的情形,提升政策的针对性有效性,更好服务企业岗位需求、市场就业需要和地区产业发展。省级人力资源社会保障部门应就证岗相适情形向人力资源社会保障部备案。"},{"no":"四","title":"加强高品质服务供给","text":"加强高品质服务供给。各地要加强主动服务,畅通稳岗扩岗资金发放渠道,通过后台数据比对精准发放,充分释放政策红利。进一步优化稳岗返还“免申即享”经办模式,主动向符合条件的企业推送政策信息和资金用途,经确认领取后及时发放返还资金;对没有对公账户的小微企业,经企业确认及授权后,可将资金返还至当地税务部门协助提供的其缴纳社会保险费的账户。"},{"no":"五","title":"强化基金风险防控","text":"强化基金风险防控。各地要加强基金运行的监测和评估,优先确保失业保险待遇支出,合理确定各项政策支出标准。扎实开展高风险业务的预警处置,重点核查本省份有相关评价机构但批量持外省份同一评价机构所发证书申领技能提升补贴等情形。完善内控制度,在经办流程中设置区别于待遇审核发放的事后业务核查环节,明确专人负责。对存在风险隐患的业务,暂时无法通过信息共享核实的,可要求补充相关材料进行复核,切实防范冒领骗取和多发错发。\n各地要强化失业人员基本生活保障,持续做好失业保险金、代缴职工基本医疗保险(含生育保险)费等保生活待遇发放工作。实施稳岗返还、技能提升补贴的省(自治区、直辖市),上年末失业保险基金滚存结余备付期限应在1年以上。实施一次性扩岗补助政策所需资金从失业保险基金支出,上年末失业保险基金滚存结余备付期限不足1年的从就业补助资金支出。相关政策执行期限为2026年1月1日至12月31日。各地要高度重视,加强部门协作,优化经办流程,迅速行动,采取有效措施抓好政策落地见效。\n\n人力资源社会保障部教育部\n\n财政部国家税务总局\n\n2026年6月18日\n\n(此件主动公开)\n\n相关附件\n\n相关阅读\n\n国家部委网站\n\n省直政府网站\n\n省直单位网站\n\n市州县区网站\n\n站点地图\n\n其他"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/ztsy/zcrd/202607/t20260710_34024368.html","sourceNote":"湖南省人民政府门户网站转载人社部等四部门原文，2026-07-10发布；政策执行期2026-01-01至2026-12-31。；2026-11-08 核对：页面发布日期 2026-07-10；2026-11-09 条文按官方原文重切（5 条，自查召回 100%）","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false},{"id":"p-2020-3ff489","title":"湖南省社会保险补贴实施办法","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2020〕22号","publishedAt":"2020-11-03","status":"expired","tags":["社保补贴","就业补贴"],"audience":["小微企业","高校毕业生"],"summary":"小微企业招用离校2年内未就业高校毕业生并签订1年以上劳动合同的，按实际缴纳的基本养老保险、基本医疗保险、失业保险单位缴费部分给予最长1年社保补贴。","sections":[{"no":"一","title":"第一条","text":"根据《国务院关于进一步做好稳就业工作的通知》(国发〔2019〕28号)、《湖南省人民政府办公厅关于印发<应对新冠肺炎疫情影响进一步做好稳就业工作十六条措施>的通知》(湘政办发〔2020〕20号)和《湖南省财政厅 湖南省人力资源和社会保障厅关于印发〈湖南省就业专项资金管理办法〉的通知》(湘财社〔2018〕25号)等文件精神,结合实际制定本办法。"},{"no":"二","title":"第二条","text":"本省行政区域内各类企业(单位)和公益性岗位招用就业困难人员,或小微企业招用离校2年内未就业高校毕业生申请享受社会保险补贴,以及就业困难人员和离校2年内未就业高校毕业生灵活就业后申报享受社会保险补贴的,适用本办法。"},{"no":"三","title":"第三条","text":"社会保险补贴按照属地管理原则,由参保所在地人力资源和社会保障、财政部门按照本办法规定受理并核拨社会保险补贴资金。在省本级参保且符合享受补贴条件的,就业困难人员在就业困难人员认定地申领,高校毕业生在就业登记地申领。\n第二章 社会保险补贴对象"},{"no":"四","title":"第四条","text":"具备下列条件之一的对象可以按规定享受社会保险补贴:\n(一)企业(单位)招用就业困难人员或安排就业困难人员在公益性岗位工作,且依法参加社会保险,企业(单位)和职工个人按规定履行了社会保险费(基本养老保险费、基本医疗保险费和失业保险费)缴纳义务,并与之签订1年以上劳动合同的;\n(二)小微企业招用离校2年内未就业高校毕业生,且依法履行了社会保险费(基本养老保险费、基本医疗保险费和失业保险费)缴纳义务,并与之签订1年以上劳动合同的;\n(三)就业困难人员灵活就业后,以灵活就业人员身份参加社会保险、且履行了社会保险费缴纳义务的;\n(四)离校2年内未就业高校毕业生灵活就业后,以灵活就业人员身份参加社会保险、且履行了社会保险费缴纳义务的。\n第三章 社会保险补贴范围、期限和标准"},{"no":"五","title":"社会保险补贴范围","text":"社会保险补贴范围\n企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和小微企业招用离校2年内未就业高校毕业生的,可申请基本养老保险、基本医疗保险和失业保险补贴,不包括个人应缴纳的部分。就业困难人员和离校2年内未就业高校毕业生进行灵活就业登记后,可申请基本养老保险、基本医疗保险补贴。代发放工资或代缴社会保险费的第三方单位,以及毕业时间(毕业证发放时间)超过2年的高校毕业生,不在补贴范围之内。"},{"no":"六","title":"社会保险补贴期限","text":"社会保险补贴期限\n(一)企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和就业困难人员灵活就业后享受社会保险补贴最长不超过3年;初次核定其享受社会保险补贴时间不早于初次申报时间一年,领取养老保险待遇后不再申报本补贴。自初次核定其享受社会保险补贴之日起计算,距法定退休时间不足5年的,可延长享受至法定退休时间;提前退休的,以实际退休时间作为享受补贴截止时间,补贴起始时间不能追溯至初次核定享受政策之前;延迟退休的,以法定退休时间作为享受补贴截止时间,延迟退休期间不再继续享受补贴。\n(二)企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和就业困难人员灵活就业的,同一时间、同一对象只能享受企业吸纳社会保险补贴或灵活就业社会保险补贴之中的一种,不能同时享受;对同一人,在不同时间、不同单位,享受企业吸纳社会保险补贴和灵活就业社会保险补贴的累计时间不超过本办法规定的期限。\n(三)小微企业招用离校2年内未就业高校毕业生,给予最长不超过1年的社会保险补贴;对离校2年内未就业高校毕业生进行灵活就业登记的,给予最长不超过2年的社会保险补贴。补贴时限从初次核定其享受社会保险补贴之日起,至毕业时间满2年为止。不同小微企业招用同一符合条件高校毕业生的,均可按规定享受社会保险补贴,累计享受补贴时间不超过1年。同一符合条件高校毕业生,可在不同时间按规定享受小微企业吸纳社会保险补贴和灵活就业社会保险补贴。"},{"no":"七","title":"社会保险补贴标准","text":"社会保险补贴标准\n(一)对企业(单位)和公益性岗位招用就业困难人员、小微企业招用离校2年内未就业高校毕业生的,按其为就业困难人员和高校毕业生实际缴纳的基本养老保险费、基本医疗保险费、失业保险费单位缴费部分进行补贴,不包括个人应缴部分。未缴齐上述三种社会保险费的不予补贴。\n(二)符合条件的就业困难人员灵活就业社会保险补贴计算方式为:社会保险费缴费基数按上年度我省全口径社会平均工资的60%执行,费率按实际缴纳社会保险的费率执行。“4050”人员(女性年龄在40周岁以上、男性年龄在50周岁以上,下同)按上述方式计算金额的60%予以补贴,非“4050”人员按上述方式计算金额的40%予以补贴。\n(三)符合条件的离校2年内未就业高校毕业生灵活就业后社会保险补贴按前款非“4050”人员标准执行。\n第四章 社会保险补贴的申领"},{"no":"八","title":"社会保险补贴实行“先缴后补”方式","text":"社会保险补贴实行“先缴后补”方式。申请社会保险补贴企业(单位)按规定先行缴纳基本养老保险费、基本医疗保险费和失业保险费,且须通过湖南省公共就业服务信息管理平台(以下简称“省平台”)向社会保险费缴纳地人力资源和社会保障部门申报社会保险费补贴。"},{"no":"九","title":"第九条","text":"申报社会保险补贴企业(单位)应按照省平台要求填报录入相关信息并上传以下资料:\n1.营业执照副本(组织机构代码证);\n2.与招用的就业困难人员或高校毕业生签订的劳动合同;\n3.享受补贴对象的身份证;属高校毕业生的,还需上传毕业证书。"},{"no":"十","title":"第十条","text":"就业困难人员和离校2年内未就业高校毕业生申报灵活就业社会保险补贴的,在完成缴费后,前往社会保险费缴纳地各社区(村)或通过官方平台自主申报,按要求填报相关信息并录入上传以下资料:\n1.社会保障卡或银行卡;\n2.属高校毕业生的,还需上传毕业证书。\n申报社会保险补贴企业(单位)和个人,对填报录入的所有信息的真实性、准确性负责,对提交虚假错误信息导致的后果由填报单位和个人全部承担。\n第五章 社会保险补贴资金审核拨付"},{"no":"十一","title":"第十一条","text":"人力资源和社会保障部门应及时对企业(单位)提交的社会保险补贴申请通过省平台进行审核。审核通过的,将符合条件的企业(单位)相关补贴信息在同级人力资源和社会保障门户网站公示7天,无异议后,按规定将补贴资金拨付至企业(单位)银行账户。\n公益性岗位安排就业困难人员、小微企业招用离校2年内未就业高校毕业生的社会保险补贴申请和资金拨付,按照上述规定执行。"},{"no":"十二","title":"第十二条","text":"灵活就业人员提交的社会保险补贴申请由社区(村)完成资料录入和调查,提交给街道(乡镇)进行确认,街道(乡镇)完成确认后,提交当地人力资源和社会保障部门进行审核。\n审核通过的,将符合条件的人员相关补贴信息在同级人力资源和社会保障门户网站公示7天,无异议后,按规定将补贴资金拨付至申请者本人社会保障卡账户或银行卡。\n第六章 服务与监督"},{"no":"十三","title":"第十三条","text":"各级人力资源和社会保障部门以及街道(乡镇)、社区(村)应当指导企业(单位)、就业困难人员、高校毕业生申报办理社会保险补贴,并提供咨询服务。"},{"no":"十四","title":"第十四条","text":"人力资源和社会保障、财政部门之间要加强沟通合作,精简工作流程,加强信息化建设,实行网上申报和经办,为申报企业(单位)和个人提供便利。各地人社部门应及时将享受补贴人员姓名、补助标准等情况及时纳入省平台管理,并实现与财政部门的信息共享。"},{"no":"十五","title":"第十五条","text":"人力资源和社会保障部门要做好本行政区域社会保险补贴政策的宣传、落实和统计工作,定期收集上报实施社会保险补贴政策的相关情况和问题。"},{"no":"十六","title":"第十六条","text":"人力资源和社会保障部门要设立举报投诉电话,接受社会监督;对不符合补贴条件或非法恶意骗取社会保险补贴的企业(单位)和个人,应责令其改正并依法追回被骗取的社会保险补贴资金,同时按规定纳入相关信用体系;构成犯罪的,依法追究其刑事责任。"},{"no":"十七","title":"第十七条","text":"人力资源和社会保障部门、财政部门的工作人员违规办理社会保险补贴的,分别由人力资源和社会保障部门、财政部门责令其改正;情节严重的,依法追究相关人员责任。"},{"no":"十八","title":"第十八条","text":"对疏于管理、违规发放社会保险补贴的地区,省人力资源和社会保障厅、省财政厅将适当扣减其下年度就业补助资金。\n第七章 附则"},{"no":"十九","title":"本办法自2021年1月1日起施行,有效期5年","text":"本办法自2021年1月1日起施行,有效期5年。我省之前有关社会保险补贴政策与本办法不一致的,以本办法为准。国家、省有明确新规的,从其规定。"},{"no":"二十","title":"第二十条","text":"各级人力资源和社会保障、财政部门可结合本地实际出台具体实施细则。"}],"interpretations":[],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202011/13965787/files/595b67c2f8a940aa8afde9b0a6c964bc.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-09 按原文「自2021年1月1日起施行，有效期5年」推算 2021-01-01 至 2025-12-31","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","effectiveAt":"2021-01-01","expiresAt":"2025-12-31","hunan":true},{"id":"p-2023-093de0","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于深入推进创业孵化基地建设工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2023〕5号","publishedAt":"2023-05-08","status":"active","tags":["场地支持","创业补贴","就业补贴"],"audience":["小微企业","个体工商户"],"summary":"对经各级人力资源社会保障部门认定的创业孵化基地给予创业服务补助，每吸纳1家创业实体入孵按每家每月100元给予基地补助、创业实体在孵期间成功注册市场主体的按2000元每家给予一次性补助，每个基地每年享受创业服务补助总额最高不超过40万元，本通知自2023年5月10日起执行，有效期五年。","sections":[{"no":"一","title":"建设原则","text":"创业孵化基地建设按照“政府引导、园区主建、突出特色、注重实效”的原则，以培育市场主体和带动创业就业为导向，以推动创业孵化基地提质增量为目标，以强化优化创业孵化服务能力为重点，建设和认定一批管理规范、服务优良、孵化成功率高、创业带动就业效果好、辐射示范作用强的各级创业孵化基地，为创业者提供良好的创业场所和生态环境。"},{"no":"二","title":"目标任务","text":"各县市区至少有1家创业孵化基地，各市州至少要有2家省级创业孵化基地。全省创业孵化基地（含创业园区）总量保持在400家左右，在孵创业实体（含创业企业、创业团队、创业项目）1万家以上，力争实现创业带动就业5万人。"},{"no":"三","title":"工作措施","text":"（一）整合资源，加大建设力度。各级人力资源社会保障部门要将硬件好、资源优、服务能力强的各类创业园区、工业园区、院校创新创业学院等单位纳入建设范围，推动符合条件的单位积极申报认定创业孵化基地，推动有条件的县市区依托本地园区建设创业孵化基地。鼓励社会组织和民营企业积极参与创业孵化基地建设和运营，凝聚各方资源力量。各地要指导创业孵化基地面向不同产业行业、不同创业群体配齐配优服务，打造特色基地。\n\n（二）强化指导，提高服务水平。各地要推动创业孵化基地强化服务能力建设，指导孵化基地不断健全和完善孵化服务体系。各市州人力资源社会保障部门每年至少要开展1次创业孵化基地管理和服务人员业务培训班，重点提升基地创业项目指导、投融资对接、补贴政策申请、事务代办等服务能力，不断提高孵化服务水平。各地要为各创业孵化基地至少对接2名湖南省创业创新导师团成员（专家、讲师至少各1名），为在孵实体提供创业辅导、技术辅导、政策辅导、赛事辅导等服务，并将服务情况录入湖南省人社业务一体化经办平台（以下简称省平台）。\n\n（三）依托平台，优化服务经办。依托省平台建立全省创业孵化基地信息库和在孵创业实体信息库，各创业孵化基地和在孵创业实体要及时更新单位基本信息、运营管理信息等，确保各项信息真实、准确、完整，为基地建设运营和管理信息化智能化提供数据支撑。各创业孵化基地要通过省平台对创业项目、创业团队和初创企业从评估入园、孵化培育到转化出园的全生命周期进行跟踪管理，要指导协助在孵创业实体按省平台要求完整录入相关信息，准确记录运营情况，及时受理其服务请求并反馈服务结果。\n\n（四）规范发展，实行动态管理。各地每年开展1次创业孵化基地认定工作，将具备条件、积极性高的优秀单位认定为当地创业孵化基地。各地每年要对已认定的创业孵化基地进行复评，对照省平台内各孵化基地创业服务成效情况，对孵化效果欠佳、服务能力不足、工作配合度和群众满意度不高，以及不再符合创业孵化基地认定标准的单位，要取消认定并及时予以退出。"},{"no":"四","title":"政策支持","text":"（一）给予创业孵化基地创业服务补助。对经各级人力资源社会保障部门认定的创业孵化基地给予创业服务补助。创业孵化基地每吸纳1家创业实体入孵，按每家每月100元的标准给予基地补助；创业实体在孵期间成功注册市场主体的（在孵创业实体入孵前未注册市场主体），按2000元每家给予基地一次性补助；创业孵化基地内的各在孵创业实体与劳动者签订1年以上劳动合同，签订的劳动合同总人数超过50人的按3万元每年的标准给予基地补助，超过100人的按6万元每年的标准给予基地补助，超过150人的按9万元每年的标准给予补助。被认定为市级创业孵化基地的补助金额总数上浮20%，被认定为省级的补助金额总数上浮40%，被认定为国家级的补助金额总数上浮60%，就高不就低。同一创业孵化基地中的同一在孵创业实体注册多个市场主体的，只能计算1家，不重复补贴。每个基地每年享受创业服务补助总额最高不超过40万元，按照就业专项资金使用的有关规定，主要用于开展创业孵化基地服务项目清单中的有关服务，以及孵化基地服务能力建设和提升，所需资金从所在地就业专项资金中列支。\n\n（二）给予一次性创业补贴。对在孵实体中正常运营一年以上并吸纳一定规模就业的初创企业和初次注册的个体工商户，按规定给予一次性创业补贴，主要用于创业经营性场所租金补贴、一次性开办费补贴和商标补贴等。其中创业经营性场所租金补贴部分，由创业孵化基地代为申请代为支付。所需资金从所在地就业专项资金中列支。\n\n（三）鼓励开展创业服务和活动。支持湖南省创业创新导师团成员为在孵创业实体提供创业指导服务。对于每年积极提供创业服务次数多、满意度高的创业创新导师，优先吸纳为省级创业创新导师团成员；鼓励优秀创业创新导师成立创业指导工作室，为创业实践持续提供后续服务；各级人力资源社会保障部门可通过政府购买创业服务成果的方式，支持创业孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动，为创业者搭建资源对接的平台。所需资金从所在地就业专项资金中列支。\n\n（四）落实创业担保贷款相关政策。符合条件的创业孵化基地在孵创业实体申请20万元以下个人创业担保贷款的，免除反担保要求，按规定给予贴息。超过20万元且确需提供反担保的，市级以上创业孵化基地可为其在孵创业实体提供信用担保。\n\n（五）示范引领。各地要按照突出成效、重在特色、典型引领的原则，每年认定一批本级创业孵化基地，发文公布，授予牌匾，引领带动创业孵化基地做大做强，做精做专。\n\n各地安排的其他非就业专项资金用于支持创业孵化基地建设的，可按照自行制定的文件执行。"},{"no":"五","title":"工作要求","text":"（一）加强组织领导。各地要把创业孵化基地建设工作作为落实“创响三湘”行动和“五创联动”的重要举措，加强规划引导，做好基地认定、指导、服务、管理等工作，结合本地实际制定细则，认真落实各项补贴政策，切实提升创业孵化基地管理服务水平和孵化实效。\n\n（二）强化工作推动。各地要依托省平台实时掌握创业孵化基地政策落实、创业服务开展、带动就业和满意度情况，上述情况将作为全省创业带动就业相关工作评先评优和考核的重要评价指标，以及享受资金补贴的重要依据。\n\n（三）加强资金监管。各地要按照“谁使用、谁审核、谁负责”的原则，全面加强对创业孵化基地相关补贴资金的监管。要严格按照有关规定做好资金申报、审核和拨付工作，做到公开透明、公平公正，坚决杜绝优亲厚友、虚报冒领等行为。对存在徇私舞弊、套取骗取、贪污挪用等违法违纪行为的，依照法律法规和有关规定严肃追究责任。\n\n本通知自2023年5月10日起执行，有效期五年。此前有关规定与本通知不一致的，以本通知为准。\n\n联系人：胡川 0731-84900136\n\n附件：1.创业孵化基地认定的基本条件\n\n2.创业孵化基地认定及复核程序\n\n3.创业孵化基地服务项目清单\n\n4.创业孵化基地申请表\n\n5.在孵创业实体名册\n\n6.孵化基地补贴申请表"}],"interpretations":[{"sectionNo":"四","headline":"每吸纳1家实体每月补100元，基地每年最高补40万元","who":"经各级人力资源社会保障部门认定的创业孵化基地（补助给基地，不是给入孵企业）。被认定为市级、省级、国家级的，补助总额分别上浮20%、40%、60%，就高不就低。","materials":[],"window":"按年度核算，每个基地每年享受的创业服务补助总额最高不超过40万元。","where":"所在地人力资源社会保障部门；资金从所在地就业专项资金中列支。","tip":"同一在孵实体注册多个市场主体的，只计算1家，不重复补贴；在孵实体注册成功另按2000元/家给基地一次性补助。","evidence":{"headline":["按每家每月100元的标准给予基地补助","每个基地每年享受创业服务补助总额最高不超过40万元"],"who":["对经各级人力资源社会保障部门认定的创业孵化基地给予创业服务补助","被认定为省级的补助金额总数上浮40%"],"window":["每个基地每年享受创业服务补助总额最高不超过40万元"],"where":["所需资金从所在地就业专项资金中列支"],"tip":["只能计算1家，不重复补贴","按2000元每家给予基地一次性补助"]}},{"sectionNo":"四","headline":"在孵实体可申一次性创业补贴，租金补贴由基地代申请代付","who":"在孵实体中正常运营一年以上、并吸纳一定规模就业的初创企业和初次注册的个体工商户。","materials":[],"window":"正常运营一年以上方可申报。","where":"经营场所租金补贴部分，由创业孵化基地代为申请、代为支付。","tip":"补贴资金用于租金、一次性开办费和商标补贴，其中租金部分不直接发给创业者，而是由基地代收代付。","evidence":{"headline":["对在孵实体中正常运营一年以上并吸纳一定规模就业的初创企业和初次注册的个体工商户"],"who":["初创企业和初次注册的个体工商户"],"window":["正常运营一年以上"],"where":["由创业孵化基地代为申请代为支付"],"tip":["主要用于创业经营性场所租金补贴、一次性开办费补贴和商标补贴"]}},{"sectionNo":"四","headline":"在孵实体借20万元以下创业担保贷款，免反担保","who":"符合条件的创业孵化基地在孵实体（个人创业担保贷款）。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"经办银行与当地人力资源社会保障部门。","tip":"超过20万元且确需反担保的，市级以上创业孵化基地可为其在孵实体提供信用担保。","evidence":{"headline":["申请20万元以下个人创业担保贷款的，免除反担保要求"],"who":["符合条件的创业孵化基地在孵创业实体申请20万元以下个人创业担保贷款的"],"where":["按规定给予贴息"],"tip":["市级以上创业孵化基地可为其在孵创业实体提供信用担保"]}}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2023/07/14/20230714172148612rpbxgf.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：湘人社规〔2023〕5号，HNPR-2023-11003","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2023-c9b55d","title":"关于印发《湖南省中小企业发展专项资金管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、湖南省工业和信息化厅","documentNo":"湘财企〔2023〕6号","publishedAt":"2023-12-28","status":"active","tags":["专项资金"],"audience":["小微企业"],"summary":"专项资金由省级财政一般公共预算安排、采取财政补助和以奖代补等支持方式，支持中小企业提升创新能力及专业化水平、完善中小企业公共服务体系等，本办法自2024年1月1日起施行，有效期至2026年12月31日。","sections":[{"no":"一","title":"第一条","text":"为规范湖南省中小企业发展专项资金的使用管理，提高资金的使用效益，根据《中华人民共和国预算法》《中华人民共和国中小企业促进法》和《湖南省实施〈中华人民共和国中小企业促进法〉办法》等有关规定，结合我省实际，制定本办法。"},{"no":"二","title":"第二条","text":"本办法所称湖南省中小企业发展专项资金（以下简称专项资金），是指依据《中华人民共和国中小企业促进法》设立，由省级财政一般公共预算安排用于支持中小企业发展的资金。"},{"no":"三","title":"第三条","text":"专项资金管理使用遵循公开公正、择优高效的原则，围绕党中央、国务院和省委、省政府有关决策部署，重点引导完善中小企业公共服务体系、改善中小企业发展环境，突破制约中小企业发展的短板和瓶颈，支持中小企业高质量发展。"},{"no":"四","title":"第四条","text":"专项资金由省财政厅和省工业和信息化厅（以下简称省工信厅）按职责分工共同管理。省财政厅负责明确年度专项资金额度，会同省工信厅确定专项资金支持方向和重点、支持方式和标准；根据省工信厅报送的年度专项资金分配方案、绩效目标建议及有关材料，按程序下达预算、绩效目标并拨付资金；指导督促省工信厅开展监督管理工作。\n\n省工信厅负责提出专项资金年度支持方向和重点、资金需求测算方案、绩效目标；组织项目申报、汇总、审查、评审；根据年度预算编制要求，及时向省财政厅提供年度专项资金分配方案；加强业务指导、绩效管理、监督管理等工作；督促有关方做好专项资金支持政策实施工作。\n\n各市州、财政省直管县（市）财政、工信部门参照省级部门职责分工做好专项资金下达后的资金使用、项目报备、业务指导等工作，并进行监督和全过程绩效管理。\n\n资金申报、使用单位承担资金及项目绩效目标的真实客观申报，合规使用和有效管理的主体责任，负责直接受理资金申报材料的主管部门承担资金申报审核、资金使用监督的直接责任。"},{"no":"五","title":"第五条","text":"专项资金实行管理办法、申报通知、评审结果、分配结果、绩效评价全过程公开。"},{"no":"六","title":"专项资金的支持范围包括：","text":"专项资金的支持范围包括：\n\n（一）支持中小企业提升创新能力及专业化水平，优化创新创业环境。\n\n（二）支持完善中小企业公共服务体系，促进中小企业开展合作交流。\n\n（三）其他促进中小企业发展的工作。\n\n在符合上述支持方向内，每年根据党中央、国务院和省委、省政府有关决策部署，结合我省中小企业发展实际情况、亟待突破的短板和瓶颈等，由省财政厅、省工信厅按照零基安排、绩效导向的原则确定专项资金支持重点。对符合规定条件的新增重大项目和政策，省工信厅要组织开展事前绩效评估。"},{"no":"七","title":"第七条","text":"专项资金支持对象包括符合条件的项目或企业、中小企业公共服务平台等机构或载体，市县、园区等试点示范区域。"},{"no":"八","title":"第八条","text":"专项资金采取财政补助、以奖代补等支持方式，主要用于引导各级政府、社会资本等支持中小企业高质量发展。"},{"no":"九","title":"第九条","text":"专项资金不得用于平衡本级财政预算及偿还债务，不得用于行政事业单位人员经费、机构运转经费等。"},{"no":"十","title":"第十条","text":"专项资金分配可以采取因素法、项目法、因素法和项目法相结合等方式。"},{"no":"十一","title":"专项资金下达时间进度按照预算管理有关规定执行","text":"专项资金下达时间进度按照预算管理有关规定执行。省工信厅报送专项资金分配方案的时间不得晚于专项资金下达时限的前15日。各级财政部门应在收到专项资金指标发文30日内，将专项资金按要求拨付使用单位。"},{"no":"十二","title":"第十二条","text":"专项资金支付按照财政国库管理制度有关规定执行，涉及政府采购的，应当按照政府采购法律法规和有关制度执行。"},{"no":"十三","title":"第十三条","text":"省财政厅、省工信厅根据预算绩效管理和本办法的规定，以及专项资金有关支持政策文件，按照职责分工组织实施专项资金的绩效运行监控、绩效评价，加强绩效评价结果反馈应用。有关绩效评价结果，作为专项资金分配的重要参考。各市州、财政省直管县（市）财政、工信部门应按规定要求实施绩效评价。"},{"no":"十四","title":"省工信厅应当会同省财政厅加强对专项资金的监督管理","text":"省工信厅应当会同省财政厅加强对专项资金的监督管理。各市州、财政省直管县（市）工信、财政部门要建立健全专项资金使用管理、监督检查和跟踪问效制度，如发现资金申报、资金使用存在问题的，应当及时报告省工信厅和省财政厅。"},{"no":"十五","title":"第十五条","text":"资金使用单位收到专项资金后应当按照国家统一的财务会计制度规定管理。专项资金应当专款专用，主动接受财政、审计等部门的监督检查，不得用于支付各种罚款、捐款、赞助等。有关项目实施情况应当接受工信、财政等部门的调度和检查。"},{"no":"十六","title":"第十六条","text":"资金使用单位因市场环境、政策变化等导致不再符合专项资金支持标准的，应及时向直接受理其资金申报材料的工信、财政部门报告，有关工信、财政部门应及时向省工信厅、省财政厅报告。省工信厅会同省财政厅提出处理意见，市县有关部门督促落实，并按要求暂缓、停止拨付资金或收回已拨付资金。"},{"no":"十七","title":"第十七条","text":"专项资金应当严格执行有关财务、会计制度，实行专款专用，不得列支与项目无关的费用。"},{"no":"十八","title":"第十八条","text":"专项资金申报、评审、分配、拨付使用等过程中存在虚报、冒领、截留、挪用、滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，严格按照《中华人民共和国预算法》《中华人民共和国公务员法》《中华人民共和国监察法》《财政违法行为处罚处分条例》等国家有关规定追究责任，涉嫌犯罪的，移送司法机关处理。资金使用单位应当严格遵守财政财务制度和财经纪律，建立健全专项资金管理制度和内部控制制度，加强财务稽核和内部审计，自觉接受审计、财政及主管部门的监督检查。"},{"no":"十九","title":"第十九条","text":"本办法自2024年1月1日起施行，有效期至2026年12月31日。到期后，省财政厅组织开展该专项的实施期绩效评估，评估结果作为该专项存续的依据。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/ztzl/zxzj/zdbf/202403/t20240328_33265389.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2023-12-30","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2024-7ab56f","title":"关于进一步支持大学生创业就业的若干措施","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅、湖南省教育厅","documentNo":"湘人社规〔2024〕2号","publishedAt":"2024-05-17","status":"active","tags":["创业补贴","贷款贴息","融资支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"大学生初次创办企业或个体工商户正常经营1年以上的，一次性创业补贴最低标准提高至1万元；创业担保贷款额度最高提高至400万元，20万元以下免除反担保。","sections":[{"no":"一","title":"支持和鼓励高校科研人员和学生共同创业","text":"1、高校科研人员离岗与学生共同创办企业的,其本人职称、年龄、资历、科技成果形式、获奖层次、获得专利与否均不作为限制条件,经个人书面申请,单位批准同意,可以申请1次离岗创业,最长期限不超过3年,可在3年内保留人事关系。离岗创业期间,停发工资福利待遇,养老保险、医疗保险(含生育保险)和职业年金依法继续由人事关系所在单位缴纳,单位部分由单位承担,个人部分由个人负责。工伤保险在所创办的企业缴纳,发生工伤时依法享受工伤保险待遇。离岗创业期间,允许通过所创办企业申报职称,所获得的职称可以作为其返回事业单位后参加岗位竞聘的参考。创业业绩突出,年度考核被确定为优秀等次的,不占原单位年度考核优秀比例。提前返岗的,应提前书面报告其人事关系所在单位,单位应在三个月内为其安排相应岗位。本人提出解除聘用合同的,其人事关系所在单位应及时依法解除合同,个人人事档案由用人单位转移到同级人社部门所属人力资源档案管理机构免费保管。\n2、高校科研人员在职与学生共同创办企业的,可在不影响完成本职工作的基础上,经个人书面申请,单位批准同意,进行在职创办企业。期间允许继续享有参加职称评审、项目申报、岗位竞聘、培训、考核、奖励等各方面权利,工资、社会保险等各项福利待遇不受影响。允许与企业职工同等享有获取报酬、奖金、股权激励的权利,国家另有规定的从其规定。工伤保险由在职创办企业缴纳,其在人事关系所在单位外工作期间发生工伤的,依法享受工伤保险待遇,由相关企业承担工伤保险责任。经与人事关系所在单位协商一致,可以实行相对灵活、弹性的工作时间。"},{"no":"二","title":"加大对大学生创业的金融支持力度","text":"3、设立湖南省大学生创业投资基金,扶持大学生创业就业。基金主要投资于具有良好市场发展前景的初创型项目,采用股权投资模式,重点支持大学生主导的创业项目。\n4、降低创业担保贷款及贴息门槛,对于高校毕业生、创业孵化基地在孵实体、获得“中国创翼”创业创新大赛市级以上(含市级)奖项的项目和中国国际大学生创新大赛金奖的项目,申请20万元以下个人创业担保贷款的,免除反担保手续,并按规定给予贴息。健全追偿代偿和呆坏账核销机制,制定担保基金尽职免责和激励约束办法,合理提升担保基金代偿比例和效率。加大省级财政支持力度,探索建立各级风险共担机制。\n5、提高一次性创业补贴标准,对大学生初次创办的企业或初次注册的个体工商户,且正常经营1年以上的,按规定给予一次性创业补贴,最低补贴标准提高至1万元(各市州已制定一次性创业补贴标准的,就高不就低)。\n6、提高贷款额度,对大学生创办的符合贷款条件的小微企业,创业担保贷款额度最高提高至400万元。"},{"no":"三","title":"加大对大学生创业的培训和指导力度","text":"7、深入实施“马兰花”创业培训行动,将有创业意愿的在校大学生纳入创业培训补贴范围,强化创业基础培训和后续“陪跑”服务,全面落实“创办你的企业”“乡村领雁”培训课程后续服务补贴。完善创业培训后续服务内容和清单,加快制定“改善你的企业”“网络创业培训”等课程后续服务补贴标准。加强创业培训课程开发,组织专家团队开发适合大学生创业群体创业特性的培训课程体系。\n8、支持高校和社会力量建立“创业指导工作室”,支持工作室导师采用“揭榜挂帅”的方式,对大学生创业项目提供一对一指导、创业培训后续服务和创业“陪跑”服务等。鼓励成立创业服务协会、大学生创业者联盟等社会组织,组织开展创业讲堂、创业训练营、创业实训等创业服务活动。\n9、探索在职称(职务)评聘工作中单独设立大学生创业和就业指导专业,进一步畅通创业就业指导教师职称评审渠道。建立完善省级高校创业创新导师数据库,从高校、企业及社会创业就业服务机构遴选创业创新专家。支持高校从校外选聘创业创新专家担任兼职教师,充实高校创业创新师资力量,加快培养一支数量充足、素质优良、服务优质的创业就业导师人才队伍,为我省大学生创业就业指导和研究提供人才储备与智力支持。"},{"no":"四","title":"加大对大学生创业的示范引领力度","text":"10、开展优秀大学生创业项目认定,每年扶持一定数量的已纳入创业孵化基地入孵管理大学生创业项目或创业团队开展创业。对获评省级大学生创业孵化基地的给予重点支持,对各高校开展校园招聘工作,按规定给予校园招聘活动补助。\n11、鼓励各院校建设大学生创业孵化基地,并及时纳入我省创业孵化基地认定范围,开展大学生创业创新孵化示范基地评建,将大学生创业项目孵化时间延长至5年,按规定落实创业孵化基地创业服务补助。降低大学生创业团队入驻条件,优化服务经办流程,为大学生创业团队提供创业指导、开业指导等“一站式”孵化服务。鼓励其他院校以外的社会各创业孵化基地安排场地优先提供给大学生创业项目入驻,并给予场租和管理费用减免。"},{"no":"五","title":"加大对大学生创业的保障力度","text":"12、探索设置大学生创业保险,通过政保合作的方式,为大学生创业“兜底”,解除大学生创业的后顾之忧。完善大学生创业预警机制,对于创业失败大学生及时开展职业培训、就业援助、就业服务,帮助“再就业”“再创业”。\n13、坚持以赛促教、以赛促学、以赛促创,鼓励各级举办“中国创翼”创业创新大赛、中国国际大学生创新大赛、 “耀动三湘”网络创业直播大赛等各类创业大赛,引导不同学段学生积极参赛,激发大学生创业创新热情。鼓励与行业企业深化赛事合作,拓宽办赛资金筹措渠道。加强对各类大赛中涌现的优秀项目进行后续跟踪,推动一批大赛优秀项目落地。\n14、建设湖南省大学生创业就业大平台,融合信息服务、技术培训、机动实习、成果转化、企业孵化等内容,加强创业资源的整合与利用。在全省大学生创业创新孵化一体化服务平台、“湘就业”平台上设置创业服务专区,推动创业政策发布、信息查询、项目申报、资源对接等功能“一网集聚”,方便高校学生享受创业一站式服务。\n15、进一步优化政策资金申领流程,充分利用大数据比对等方式,减少申报资料提交,推动实现网上申报、网上审核、联网核查。对能依托管理信息系统或与相关单位信息共享、业务协同获得的个人及单位信息、资料的,不再要求单位及个人报送纸质材料,符合条件的要及时拨付资金。要加强全过程监督,对工作人员在项目申报、评选及资金拨付使用等工作中,存在滥用职权、玩忽职守、徇私舞弊等违纪违法行为的,依照国家有关法律法规追究相应责任。涉嫌犯罪的,依法移送司法机关处理。\n16、加强大学生创业宣传引导,利用短视频等各类新媒体资源,建立宣传矩阵,及时发布相关政策文件与政策解读。利用“创业微电影”等方式广泛宣传大学生创业优秀案例,树立大学生创业典型,培育高校创客文化。组织开展“企业家进校园讲好创业就业故事”等系列活动,遴选更多优质企业家深入高校开展创业创新公益活动,每年省级层面举办讲座不少于20场次,营造“鼓励创业、宽容失败”的良好氛围。\n本文件自2024年5月21日起执行,有效期五年。此前有关规定与本文件不一致的,以本文件为准。"}],"interpretations":[{"sectionNo":"二","headline":"大学生首次创业满1年，一次性补贴最低1万元","who":"大学生初次创办的企业或初次注册的个体工商户，且正常经营1年以上。各市州已制定一次性创业补贴标准的，就高不就低。","materials":[],"window":"正常经营1年以上方可申领。","where":"创业主体注册地的人力资源社会保障部门。","tip":"这是省级最低标准，各市州自己的标准更高时按高的执行。","evidence":{"headline":["最低补贴标准提高至1万元"],"who":["对大学生初次创办的企业或初次注册的个体工商户","各市州已制定一次性创业补贴标准的,就高不就低"],"window":["且正常经营1年以上的,按规定给予一次性创业补贴"],"where":["按规定给予一次性创业补贴"],"tip":["各市州已制定一次性创业补贴标准的,就高不就低"]}},{"sectionNo":"二","headline":"大学生申请20万元以下创业担保贷款，免反担保","who":"高校毕业生、创业孵化基地在孵实体、获得「中国创翼」市级以上奖项的项目、中国国际大学生创新大赛金奖项目。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"经办银行与当地人力资源社会保障部门。","tip":"大学生创办且符合条件的小微企业，创业担保贷款额度最高可提到400万元。","evidence":{"headline":["申请20万元以下个人创业担保贷款的,免除反担保手续,并按规定给予贴息"],"who":["对于高校毕业生、创业孵化基地在孵实体"],"where":["并按规定给予贴息"],"tip":["创业担保贷款额度最高提高至400万元"]}},{"sectionNo":"一","headline":"高校科研人员可离岗创业3年，保留人事关系","who":"高校科研人员离岗与学生共同创办企业的，经个人书面申请、单位批准同意。","materials":[],"window":"可申请1次离岗创业，最长期限不超过3年，期间保留人事关系。","where":"向本人人事关系所在单位申请。","tip":"离岗期间停发工资福利待遇，社保和职业年金单位部分仍由原单位承担、个人部分自己负责。","evidence":{"headline":["可以申请1次离岗创业,最长期限不超过3年,可在3年内保留人事关系"],"who":["高校科研人员离岗与学生共同创办企业的"],"window":["最长期限不超过3年"],"where":["经个人书面申请,单位批准同意"],"tip":["离岗创业期间,停发工资福利待遇"]}}],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS/file/2024/06/11/20240611090410597w5kpib.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2024-8a0745","title":"湖南省财政厅 湖南省人力资源和社会保障厅关于印发《湖南省就业补助资金管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、湖南省人力资源和社会保障厅","documentNo":"湘财社〔2024〕33号","publishedAt":"2024-12-27","status":"active","tags":["社保补贴","就业补贴","创业补贴"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"就业困难人员灵活就业社保补贴不超过其实际缴费的2/3、期限最长3年，小微企业招用高校毕业生给予最长1年社保补贴。","sections":[{"no":"一","title":"第一条","text":"根据《中华人民共和国预算法》《中华人民共和国就业促进法》《中共中央国务院关于全面实施预算绩效管理的意见》《中共中央国务院关于实施就业优先战略促进高质量充分就业的意见》《财政部人力资源社会保障部关于印发〈就业补助资金管理办法〉的通知》（财社〔2023〕181号）等相关法律法规和规定，为推动实施就业优先战略，促进高质量充分就业，落实各项就业创业扶持政策，规范就业补助资金管理，提高资金使用效益，结合我省实际，制定本办法。"},{"no":"二","title":"第二条","text":"本办法所称就业补助资金是由县级以上人民政府设立，由本级财政部门和人力资源社会保障部门共同管理，通过一般公共预算安排用于促进就业创业的专项资金。"},{"no":"三","title":"本办法所规范的就业补助资金包括：","text":"本办法所规范的就业补助资金包括：\n（一）中央财政安排我省的就业补助资金；\n（二）省市县各级财政年度预算安排的促进就业创业工作的专项资金；\n（三）社会各界为公益性就业服务提供的捐赠、资助等其他收入。\n失业保险基金中用于促进就业创业的支出，按国家和省有关规定执行。"},{"no":"四","title":"第四条","text":"县级以上人民政府应当根据当地就业状况和就业工作目标，在本级财政预算中安排就业补助资金用于促进就业创业工作，确保就业政策落实到位。"},{"no":"五","title":"就业补助资金管理应遵循以下原则：","text":"就业补助资金管理应遵循以下原则：\n（一）注重普惠，重点倾斜。落实国家和省普惠性的就业创业扶持政策，重点支持就业困难群体就业创业，适度向财政困难、就业工作任务重的地区倾斜，促进各类劳动者公平就业，推动地区间就业协同发展。\n（二）奖补结合，激励相容。优化机制设计，奖补结合，充分调动各级政策执行部门、政策对象等积极性。\n（三）科学合理，提升质效。提高政策可操作性和精准性，优化资金支持结构，加强监督与控制，以绩效导向、结果导向强化就业补助资金管理，并结合就业形势和工作任务变化对政策进行动态调整。\n第二章  资金支出范围"},{"no":"六","title":"第六条","text":"就业补助资金分为对个人和单位的补贴、公共就业服务能力建设补助两类。\n对个人和单位的补贴资金用于职业培训补贴、职业技能评价补贴、就业见习补贴、一次性求职补贴、一次性创业补贴、社会保险补贴、公益性岗位补贴及其他支出；公共就业服务能力建设补助资金用于就业创业服务补助和高技能人才培养补助及其他支出。\n同一项目就业补助资金补贴与失业保险基金补贴有重复的，个人和单位不可重复享受。"},{"no":"七","title":"职业培训补贴","text":"职业培训补贴。享受职业培训补贴的人员范围包括：防止返贫监测对象、毕业年度高校毕业生（含技工院校高级工班、预备技师班、技师班和特殊教育院校职业教育类毕业生，下同）、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员等（以下统称六类人员），以及符合条件的企业职工。\n职业培训补贴用于以下方面：\n（一）就业技能培训。对参加就业技能培训的六类人员，培训后取得符合规定证书的（包括职业资格证书、职业技能等级证书、专项职业能力证书、职业培训合格证书，下同），按规定标准给予职业培训补贴。\n（二）创业培训。对参加创业培训的六类人员和大中专院校在校学生（含中职、技校）、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工，培训后取得创业培训合格证书的，按培训类别给予一定标准的职业培训补贴。\n（三）企业职工岗位技能培训。对企业新录用的六类人员，与企业签订1年以上期限劳动合同，并于签订劳动合同之日起1年内参加由企业依托所属培训机构或政府认定的培训机构开展企业职工岗位技能培训的，培训后取得高级及以下规定证书的，按规定标准给予职工个人或企业培训补贴。\n对按国家有关规定参加企业新型学徒制培训企业在职职工（含与企业签订半年以上实习协议或就业协议的技工院校毕业年度在企业实习学生），培训后取得证书（含职业资格证书、职业技能等级证书、培养合格证书）的，按规定标准给予职工个人或企业培训补贴。\n对符合晋升等级条件的企业在职职工参加职业技能培训后，取得技师及以上职业资格证书或职业技能等级证书的，按规定标准给予职工个人或企业培训补贴。\n（四）项目制培训。各地人力资源社会保障、财政部门可按规定通过项目制方式，向符合条件的培训机构整建制购买就业技能培训或创业培训服务，开展定点、定向、定岗等项目定制培训，对承担项目制培训任务的培训机构，给予一定标准职业培训补贴。\n上述符合条件享受职业培训补贴政策的人员，每人累计最多享受3次（含职业技能培训补贴、创业培训补贴），自2024年1月1日起计算。同一职业（工种）不得重复同级或降级享受职业技能培训补贴。同一职业（工种）同一等级的职业技能培训补贴和失业保险参保职工技能提升补贴不能重复享受。\n职业培训补贴实行“先垫后补”和“信用支付”等办法，经职业培训补贴对象同意，可由培训机构先行垫付培训费用，代为申领培训补贴。支持有条件的地方探索为培训对象建立职业培训个人信用账户，鼓励培训对象自主选择培训机构和课程，并通过信用账户支付培训费用。"},{"no":"八","title":"职业技能评价补贴","text":"职业技能评价补贴。\n对通过初次职业技能评价并取得符合规定证书（包括职业资格证书、职业技能等级证书、专项职业能力证书，不含培训合格证）的六类人员，给予职业技能评价补贴。对纳入重点产业国家职业资格评价和职业技能等级认定目录的职业工种，可适当提高补贴标准。每人累计最多享受3次，自2024年1月1日起计算，同一职业（工种）不得重复同级或降级享受。"},{"no":"九","title":"就业见习补贴","text":"就业见习补贴。\n对符合条件的见习单位吸纳离校2年内未就业高校毕业生和16-24岁登记失业青年，给予一定标准的就业见习补贴。补贴标准按当地最低工资标准执行，对见习人员见习期满留用率达到50%以上的见习单位，见习补贴标准可提高至当地最低工资标准的120%，补贴期限最长不超过12个月。补贴用于见习单位支付见习人员见习期间基本生活费、为见习人员办理人身意外伤害保险，以及对见习人员的指导管理费用。"},{"no":"十","title":"一次性求职补贴","text":"一次性求职补贴。\n对在毕业学年积极求职创业的低保家庭、零就业家庭、防止返贫监测对象家庭和特困人员中的高校毕业生，残疾及获得国家助学贷款的高校毕业生，给予一定标准的一次性求职补贴。"},{"no":"十一","title":"一次性创业补贴","text":"一次性创业补贴。\n对在省内首次创办小微企业或从事个体经济，且所创办企业或个体工商户自工商登记注册之日起正常运营1年以上的离校2年内高校毕业生、就业困难人员、返乡入乡农民工给予企业或个体经营者一定标准的一次性创业补贴。"},{"no":"十二","title":"社会保险补贴","text":"社会保险补贴。\n享受社会保险补贴的人员范围包括：我省认定的符合条件的就业困难人员和高校毕业生。\n社会保险补贴用于以下方面：\n（一）就业困难人员社会保险补贴。对招用就业困难人员并缴纳社会保险费的单位，以及通过公益性岗位安置就业困难人员并缴纳社会保险费的单位，按其为就业困难人员实际缴纳的基本养老保险费、基本医疗保险费和失业保险费给予补贴，不包括就业困难人员个人应缴纳的部分。对就业困难人员灵活就业后缴纳的社会保险费，给予一定数额的社会保险补贴，补贴标准原则上不超过其实际缴费的2/3。就业困难人员社会保险补贴期限，除对距法定退休年龄不足5年的就业困难人员可延长至退休外，其余人员最长不超过3年（以初次核定其享受社会保险补贴时年龄为准）。\n就业困难人员灵活就业后享受社会保险补贴与单位招用（安置）就业困难人员享受的社会保险补贴的补贴期限合并计算。\n（二）高校毕业生社会保险补贴。对招用毕业年度和离校2年内未就业高校毕业生，与之签订1年及以上劳动合同并为其缴纳社会保险费的小微企业，给予最长1年的社会保险补贴，不包括高校毕业生个人应缴纳的部分。对离校2年内未就业的高校毕业生灵活就业后缴纳的社会保险费，给予一定数额的社会保险补贴，补贴标准原则上不超过其实际缴费的2/3，补贴期限最长不超过2年。\n高校毕业生灵活就业后享受社会保险补贴与小微企业招用高校毕业生享受的社会保险补贴的补贴期限合并计算。\n高校毕业生社会保险补贴与就业困难人员社会保险补贴的补贴期限合并计算。"},{"no":"十三","title":"公益性岗位补贴","text":"公益性岗位补贴\n公益性岗位安置对象为我省认定的符合条件的就业困难人员和通过市场渠道确实难以就业的困难高校毕业生（含脱贫家庭、低保家庭、零就业家庭及残疾高校毕业生等），优先安排符合岗位条件的距离法定退休年龄不足5年失业人员和零就业家庭成员。\n对公益性岗位安置的就业困难人员给予岗位补贴，补贴标准参照当地最低工资标准执行。\n公益性岗位补贴期限，除对距法定退休年龄不足5年的就业困难人员可延长至退休外，其余人员最长不超过3年（以初次核定其享受公益性岗位补贴时年龄为准）。对公益性岗位补贴期满后仍难以通过其他渠道实现就业的大龄就业困难人员、零就业家庭中的就业困难人员、重度残疾人等，可在到期退岗后重新认定，再次按程序通过公益性岗位予以安置，岗位补贴和社会保险补贴期限重新计算，并报送省人力资源社会保障厅、省财政厅备案，累计安置次数不超过2次。\n乡村公益性岗位补贴按照现行有关规定执行。"},{"no":"十四","title":"就业创业服务补助","text":"就业创业服务补助\n就业创业服务补助主要用于以下方面：\n（一）用于加强公共就业创业服务平台服务能力建设。重点支持公共就业创业服务机构加强就业信息网络系统建设及维护，开展城乡劳动力信息采集及更新，开展线上线下招聘活动及就业创业服务，开展就业创业宣传活动等。对于基层公共就业服务机构（含政府设立的家门口就业服务站、零工市场、人社驿站等）承担的免费公共就业服务和创业孵化基地开展的创业孵化服务，可根据工作量、专业性和成效等，给予一定的补助。对公共就业创业服务机构、高校开展的招聘活动和创业服务，可根据服务人数、成效和成本等，给予一定的补助。\n（二）用于向社会购买基本就业创业服务。县级以上人力资源社会保障、财政部门可按政府购买服务相关规定，向社会购买基本就业创业服务。基本就业创业服务包括向社会购买就业（职业）指导、就业（职业）规划、职业介绍、就业（创业）政策研究咨询、创业指导服务；人力资源市场调查、就业信息收集与统计分析（统计监测）、委托开展第三方检查核查、就业（创业）信息发布、有组织劳务输出和劳务协作；其他适合通过市场化方式提供的基本就业创业服务。"},{"no":"十五","title":"高技能人才培养补助","text":"高技能人才培养补助\n高技能人才培养补助重点用于高技能人才培训基地建设、技能大师工作室建设等项目支出。\n（一）高技能人才培训基地建设。各地应当结合区域经济发展、产业振兴发展规划和新兴战略性产业发展的需要，依托企业、院校、职业培训机构等具备高技能人才培训能力的单位，建设高技能人才培训基地，重点开展高技能人才研修提升培训、高技能人才评价、高技能人才课程研发、高技能人才成果交流等活动。\n（二）技能大师工作室建设。各地应当发挥高技能领军人才在带徒传技、技能攻关、技艺传承、技能推广等方面的重要作用，选拔行业企业生产和服务一线的优秀高技能人才，依托其所在单位建设技能大师工作室，开展培训、研修、攻关、交流等技能传承提升活动。\n（三）鼓励我省职业学校为省内先进制造业等重点产业的企业输送高技能人才，各地对本地职业学校为省内企业输送高技能人才的，可根据输送的高技能人才数量、质量和服务年限等条件，给予职业学校一定补助。补助流程和补助标准由各市州自行确定，报省人力资源社会保障厅备案后实施。"},{"no":"十六","title":"其他支出","text":"其他支出\n其他支出是指各地根据就业形势变化在确保国家确定的各项就业补贴政策落实到位的基础上，经省级人民政府批准，符合国家、省就业政策导向，与促进重点群体就业创业直接相关，现有补贴政策无法覆盖的就业创业扶持政策支出。\n对企业自行招用毕业年度和离校2年内未就业的高校毕业生及16—24岁登记失业青年，签订劳动合同，并按规定为其足额缴纳3个月以上的失业、工伤、职工养老保险费的，给予企业1500元每人的一次性吸纳就业稳岗补贴，与一次性扩岗补助不重复享受。"},{"no":"十七","title":"第十七条","text":"就业补助资金中对个人和单位的补贴资金的具体标准，已有明确规定的，按规定执行。未明确规定的，在符合既有原则的基础上，由省人力资源社会保障厅、省财政厅结合全省实际确定。各地应合理确定并科学控制公益性岗位补贴占比，严格控制就业创业服务补助和其他支出比例。"},{"no":"十八","title":"就业补助资金不得用于以下支出：","text":"就业补助资金不得用于以下支出：\n（一）办公用房、职工宿舍建设及维修，交通工具购置及运维支出。\n（二）发放工作人员工资、津贴补贴等支出。\n（三）“三公”经费支出。\n（四）普惠金融项下创业担保贷款（原小额担保贷款）贴息及补充创业担保贷款基金相关支出。\n（五）办公设备及耗材、报刊书籍订阅、走访慰问等支出。\n（六）赛事组织实施经费、奖金等支出。\n（七）按规定应由其他财政资金渠道安排的支出。\n（八）法律法规禁止的其他支出。\n不得对机关事业单位在编人员发放本办法中的补贴。\n个人、单位按照本办法申领获得的补贴资金，具体用途可由申请人或申请单位确定，不受本条规定限制。\n第三章  资金分配与下达"},{"no":"十九","title":"第十九条","text":"中央和省财政安排的就业补助资金，采取因素法与项目法相结合的方式。除用于国家级、省级项目之外，其他资金坚持“不定基数、因素分配、注重绩效”的原则，因素法分配下达到市州本级和省直管县。\n项目法分配的资金采取评审、评议、竞争性分配、集体研究等方式确定支持对象。\n对落实就业优先政策、推动高质量充分就业、促进重点群体就业创业等任务完成较好的市州、县市区进行评选评价，在分配就业补助资金时予以适当支持。\n对重点群体就业任务较重、承担国家和省重大活动、创业带动就业成效明显的地区，在分配就业补助资金时予以适当支持。"},{"no":"二十","title":"第二十条","text":"因素法分配的因素包括基础因素、投入因素、工作成果因素、重点工作因素等四类，并通过绩效调节系数和财力调节系数进行调节。其中：\n（一）基础因素权重为35%，包括常住人口数、登记失业人数等，重点考虑就业工作任务量。\n（二）投入因素权重为15%，包括地方财政投入、资金结余消化等，重点考虑地方投入力度和预算执行情况，引导地方加大投入，加快预算执行。\n（三）工作成果因素权重为15%，包括就业工作综合绩效评价、城镇新增就业人数、资金使用管理绩效等，重点考虑就业工作成果完成情况。\n（四）重点工作因素权重为35%，包括高校毕业生就业创业、乡村振兴、职业培训等工作，每年根据人力资源社会保障部、财政部和省委、省政府工作重点适时调整。\n每年分配资金选择的因素、权重、方式及增减幅上下限，可根据年度全省就业整体形势和工作任务重点适当调整。\n绩效调节系数和财力调节系数分别通过绩效评价结果和财政困难程度系数确定。"},{"no":"二十一","title":"第二十一条","text":"在因素法分配中央和省级财政就业补助资金时，省级人力资源社会保障部门负责会同有关部门提供资金测算需要的与就业相关的基础数据、绩效评价结果和资金分配建议。省级财政部门负责收集汇总资金结转结余、预算执行、财政困难程度系数等业务相关数据。各单位按照“谁提供、谁负责”的原则，对所提供数据的准确性、完整性、及时性负责。"},{"no":"二十二","title":"第二十二条","text":"高技能人才培养补助资金实行项目管理，各地人力资源社会保障部门应当编制高技能人才培养中长期规划，确定本地区支持的高技能人才重点领域。对经人力资源社会保障部、财政部备案同意的国家级高技能人才培养项目，根据备案结果给予分类分档补助。省级高技能人才培养项目由省人力资源社会保障厅会同省财政厅组织实施，按规定给予补助。"},{"no":"二十三","title":"第二十三条","text":"省、市州级财政、人力资源社会保障部门应当在收到上级资金分配通知后30日内，正式下达就业补助资金预算；省、市州级财政、人力资源社会保障部门应当将本级政府预算安排给下级政府的就业补助资金在本级人民代表大会批准预算后60日内正式下达到下级财政、人力资源社会保障部门。省级资金分配方案抄送财政部湖南监管局。\n地方各级财政、人力资源社会保障部门在收到上级财政转移支付预算时，应核对无误后再下达。如发现问题，应立即向上级财政、人力资源社会保障部门报告。地方不得擅自分配处置存疑的转移支付资金。\n地方各级财政、人力资源社会保障部门部门应对其使用的就业补助资金提出明确的资金管理要求，及时组织实施各项就业创业政策。"},{"no":"二十四","title":"第二十四条","text":"各级人力资源社会保障、财政部门应对就业补助资金全面实施预算绩效管理，建立健全全过程预算绩效管理链条，做好事前绩效评估，加大绩效目标审核力度。建立部门全面监控和财政重点监控机制，年度预算结束后，应当开展绩效自评，每年选择部分重点资金和项目开展部门评价和财政评价。将绩效评价作为项目调整、预算调整以及下一年预算安排的重要依据。全面强化绩效目标管理，做好绩效运行监控和绩效评价，并加强绩效评价结果应用，加大绩效信息公开力度，提高资金配置效率和使用效益。鼓励各地探索建立科学规范的绩效考核目标体系，积极推进就业补助资金的绩效管理。\n第四章  资金管理与监督"},{"no":"二十五","title":"第二十五条","text":"各级人力资源社会保障部门要在坚持转变政府职能、提高行政效能的基础上，梳理并公开本地区就业补贴政策清单，明确申请材料、申领流程、经办渠道、办理时限等。应当建立和完善就业资金发放台账，做好就业资金管理的基础工作，有效甄别享受补贴政策人员和单位的真实性，特别是对补贴金额大、人数多、期限长的补贴对象要加强核查抽查，防止出现造假行为。落实好政府采购等法律法规的有关规定，规范采购行为。\n各级人力资源社会保障、财政部门应按规定加强信息化建设，依托湖南省人力资源社会保障一体化业务管理系统，将补贴申请、受理、审核、拨付纳入系统管理，并实现就业数据与财政、社保、工商、税务、民政等数据信息共享。对能依托系统或与相关单位信息共享、业务协同获得的信息和资料，不再要求提供纸质材料。对面向个人的补贴，具备条件的可通过社会保障卡发放。"},{"no":"二十六","title":"第二十六条","text":"就业补助资金严格按照国库集中支付管理制度相关规定支付。资金使用过程中，涉及政府采购的，应按照政府采购有关法律法规及制度执行。\n各级财政、人力资源社会保障部门应加快预算执行进度，及时拨付到位，盘活存量资金，提高资金使用效益，结转结余资金按照中央和省有关盘活财政存量资金的规定进行管理。"},{"no":"二十七","title":"第二十七条","text":"各级财政、人力资源社会保障部门应建立健全财务管理规章制度，强化内部财务管理，严格落实财务管理规定，落实岗位设置权限分设和权限不相容要求，优化业务流程，加强内部风险防控。"},{"no":"二十八","title":"第二十八条","text":"各级财政、人力资源社会保障部门应加强对就业补助资金管理使用情况的监督检查，主动开展自查互查、交叉检查或委托第三方检查等，自觉接受巡视巡察、审计等部门的检查和社会监督。"},{"no":"二十九","title":"第二十九条","text":"各级财政、人力资源社会保障部门应按照财政预决算管理的总体要求，做好年度预决算工作，并按要求向社会公开。"},{"no":"三十","title":"第三十条","text":"各级人力资源社会保障、财政部门应做好信息公开工作，通过当地媒体、部门网站等向社会公开年度就业工作总体目标、工作任务完成、各项补贴资金的使用等情况。\n各项补贴资金的使用情况公开内容包括：享受各项补贴的单位名称或人员名单（含隐藏部分位数的身份证号码）、补贴标准及具体金额等。其中，公益性岗位补贴还应公开公益性岗位名称、设立单位、安置人员名单、享受补贴时间等；一次性求职补贴应在发放前在校内公示。\n各级人力资源社会保障、财政部门要严格遵守国家有关个人信息保护的法规制度，既保证资金使用公开透明，又避免个人敏感信息泄露。"},{"no":"三十一","title":"第三十一条","text":"各级人力资源社会保障、财政部门应当建立用人单位、个人责任追究机制，对虚报、冒领、套取就业补助资金补贴补助的，责令退回，依法纳入社会信用体系，实施多部门联合惩戒，涉及犯罪的，依法移送司法机关。"},{"no":"三十二","title":"第三十二条","text":"各级财政、人力资源社会保障部门应建立就业补助资金“谁使用、谁负责”的责任追究机制。\n各级财政、人力资源社会保障部门及其工作人员在就业补助资金的分配审核、使用管理等工作中，存在违反本办法规定的行为，以及其他滥用职权、玩忽职守、徇私舞弊等违法违规行为的，依法追究相应责任。涉嫌犯罪的，依法移送有关机关处理。\n对疏于管理、违规使用资金的地方，将相应扣减其下一年度就业补助资金；情节严重的，取消其下一年度获得就业补助资金的资格，并在全省范围内予以通报。\n第五章  附 则"},{"no":"三十三","title":"第三十三条","text":"本办法由省财政厅、省人力资源社会保障厅根据各自职能负责解释。各市县财政、人力资源社会保障部门严格按本办法执行。"},{"no":"三十四","title":"本办法自发布之日起施行，有效期5年","text":"本办法自发布之日起施行，有效期5年。有效期内国家出台新规定与本办法不一致的，以国家新规定为准。此前有关政策文件关于就业补助资金的规定与本办法不一致的，以本办法为准。"}],"interpretations":[{"sectionNo":"十二","headline":"灵活就业社保补贴最高补实际缴费的2/3，最长3年","who":"我省认定的就业困难人员（灵活就业或以单位招用、公益性岗位安置），以及毕业年度和离校2年内未就业的高校毕业生（小微企业招用或灵活就业）。","materials":[],"window":"就业困难人员最长不超过3年，距法定退休年龄不足5年的可延长至退休；高校毕业生被小微企业招用的最长1年，灵活就业的最长2年。","where":"当地人力资源社会保障部门，通过湖南省人社一体化业务管理系统办理。","tip":"单位招用与灵活就业的社保补贴期限合并计算；高校毕业生社保补贴与就业困难人员社保补贴期限也合并计算。","evidence":{"headline":["补贴标准原则上不超过其实际缴费的2/3"],"who":["我省认定的符合条件的就业困难人员和高校毕业生"],"window":["其余人员最长不超过3年（以初次核定其享受社会保险补贴时年龄为准）","给予最长1年的社会保险补贴","补贴期限最长不超过2年"],"where":["依托湖南省人力资源社会保障一体化业务管理系统"],"tip":["高校毕业生社会保险补贴与就业困难人员社会保险补贴的补贴期限合并计算"]}},{"sectionNo":"十一","headline":"省内首次创业、正常运营满1年，可领一次性创业补贴","who":"离校2年内高校毕业生、就业困难人员、返乡入乡农民工；须在省内首次创办小微企业或从事个体经营，且自工商登记注册之日起正常运营1年以上。","materials":[],"window":"自工商登记注册之日起正常运营1年以上方可申领。","where":"当地人力资源社会保障部门；补贴政策清单、申请材料、经办渠道由各地人社部门公开。","tip":"具体补贴标准本办法未定死，由省人力资源社会保障厅、省财政厅结合全省实际确定，各市县按本地口径执行。","evidence":{"headline":["给予企业或个体经营者一定标准的一次性创业补贴"],"who":["离校2年内高校毕业生、就业困难人员、返乡入乡农民工"],"window":["自工商登记注册之日起正常运营1年以上"],"where":["梳理并公开本地区就业补贴政策清单"],"tip":["由省人力资源社会保障厅、省财政厅结合全省实际确定"]}}],"sourceUrl":"https://czt.hunan.gov.cn/czt/xxgk/zcfg/gfxwj/202502/t20250220_33591654.html","sourceNote":"2026-11-09 核对：原文页只挂 doc 附件，正文取自该附件且逐句比对一致（143/145 句命中，2 句为切条残句）；网页文号 湘财社〔2024〕33号、发文日期 2024-12-27、信息有效时间 2030-01-07","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-178898","title":"湖南省人力资源和社会保障厅 湖南省科学技术厅 湖南省财政厅 湖南省市场监督管理局关于印发《关于支持大学生创业孵化基地建设的若干措施》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省科学技术厅、湖南省财政厅、湖南省市场监督管理局","documentNo":"湘人社规〔2025〕31号","publishedAt":"2025-09-28","status":"active","tags":["场地支持","创业补贴","认定资质"],"audience":["小微企业","高校毕业生"],"summary":"2025至2026年每年认定30家省级大学生创业孵化基地，按功能分别给予40万元、50万元、60万元一次性培育奖补，垂直领域试点每家叠加最高20万元。","sections":[{"no":"一","title":"明确总体建设目标","text":"着眼大学生创业生态良好需求,打造一批布局合理、功能完善、运营规范的大学生创业孵化基地。到2027年底,全省创业孵化载体总量稳定在700家左右,其中,能够为大学生提供创业服务的孵化基地300家左右(每年评定一批省级大学生创业孵化基地)。全省年均孵化大学生创业项目5000个左右,孵化成功率不低于60%。"},{"no":"二","title":"坚持分类梯次建设","text":"按照不同服务功能定位,分类建设大学生创业孵化基地。全面建设一批能够为大学生创业提供一定办公场地、生活配套、创业活动、创业培训、事务代理、管理咨询等基础服务的“空间”类孵化基地;布局建设一批能够提供试验平台、检测条件等专业化服务的“平台”类孵化基地;重点建设一批能够提供专利、金融、产业等投融资服务,助力创业实体快速成长的“投资”类孵化基地。"},{"no":"三","title":"建设一批专业化孵化基地","text":"发挥特色产业集群优势,引导科研院所、工程(技术、测试)中心、园区、企业等参与建设大学生创业孵化基地。依托区域特色产业和优势资源,打造具有引领作用的专业性大学生创业孵化基地。围绕重点产业链重点建设10家左右垂直领域大学生创业孵化基地。创业孵化基地内在孵项目登记注册为市场主体且以孵化基地所在地址为注册地址的,市场监管部门根据相关规定准予登记。"},{"no":"四","title":"分级落实奖励补助","text":"2025至2026年每年认定30家省级大学生创业孵化基地。对认定为省级大学生创业孵化基地的,给予一次性培育奖补,根据基地不同功能分别给予40万元、50万元、60万元奖补;对试点开展垂直领域建设的省级大学生创业孵化基地,叠加每家最高不超过20万元的一次性试点奖补。同时,符合我省省级大学生创业孵化基地有关规定的,给予补贴和补助。对符合条件的入孵项目和创业者,优先给予创业培训、创业担保贷款、一次性创业补贴等支持。各市州、县市区可结合实际制定本地支持大学生创业孵化基地和垂直领域孵化基地建设标准及奖励补助标准。"},{"no":"五","title":"推动试验测试设备共享","text":"已列入湖南省科研设施和科研仪器开放共享服务平台的科研设施和仪器,所依托的管理单位应支持大学生创新创业团队或个人用于科学研究和技术开发活动。科研设施和仪器提供开放共享服务,可按照成本补偿和非营利性原则收取费用,开放服务收费标准应采取适当方式向社会公布。针对大学生创业孵化基地的共享办法,另行制定。"},{"no":"六","title":"做好创业资源对接","text":"对由省级大学生创业孵化基地书面推荐的项目,直接进入湖南省大学生创业投资基金尽职调查阶段。相关部门为在孵项目和创业者匹配湖南省大学生创业导师、湖南省创业创新导师团成员,及时为有培训需求的孵化基地推荐创业培训机构、公共实训基地。各地可通过政府购买创业服务成果的方式,支持孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动。"},{"no":"七","title":"搭建交流协作平台","text":"加强孵化基地间的沟通协作,建立沟通协作机制,强化信息互通,促进资源共享,常态调研交流,解决困难问题,提供决策咨询,推动成立“湖南省大学生创业孵化基地协会”。"},{"no":"八","title":"完善线上服务功能","text":"依托省政务服务网和湘易办,建好用好“创业在湘”暨湖南省创业公共服务平台(含PC端和移动端),完善大学生专区“七个找”和“三地图”服务内容,展示孵化基地简介、工位、位置等基本信息,定期更新孵化载体地图。优化高效办成个人(大学生)创业一件事流程,将申请入驻创业孵化基地等多个事项集成办、极简办、掌上办。开设政务服务专窗,提供政策和业务咨询,加强与孵化基地、创业服务驿站的沟通联系,提高服务精准度和服务质效。"},{"no":"九","title":"健全评估评价机制","text":"依托“湖南人社一体化业务管理系统”动态管理大学生创业孵化基地,更新基地工作信息和在孵实体信息,定期调度相关情况,跟踪掌握相关数据,展开统计分析。每年开展大学生创业孵化基地认定复评工作,按标准进行分级分类调整;经相关程序,对服务能力不足、孵化效果欠佳、群众满意度不高、存在违法经营等情况的,撤销孵化基地资格。"},{"no":"十","title":"加强工作统筹协调","text":"人力资源社会保障部门牵头大学生创业孵化基地建设,科技、财政、市场监管等相关部门按职责参与共建共管。鼓励有条件有资源的创业孵化基地,吸纳更多大学生创业项目,建设成为大学生创业孵化基地。\n本措施自2025年8月1日起施行,有效期3年。"}],"interpretations":[{"sectionNo":"四","headline":"认定省级孵化基地，按功能分别补40万、50万、60万元","who":"被认定为省级大学生创业孵化基地的运营主体；试点开展垂直领域建设的基地可再叠加最高20万元一次性试点奖补。","materials":[],"window":"2025至2026年每年认定30家省级大学生创业孵化基地。","where":"省人力资源社会保障厅牵头，科技、财政、市场监管等部门按职责参与共建共管。","tip":"符合条件的入孵项目和创业者，还可优先获得创业培训、创业担保贷款、一次性创业补贴等支持；市州、县市区可另定本地奖补标准。","evidence":{"headline":["根据基地不同功能分别给予40万元、50万元、60万元奖补"],"who":["叠加每家最高不超过20万元的一次性试点奖补"],"window":["2025至2026年每年认定30家省级大学生创业孵化基地"],"where":["人力资源社会保障部门牵头大学生创业孵化基地建设"],"tip":["优先给予创业培训、创业担保贷款、一次性创业补贴等支持"]}},{"sectionNo":"三","headline":"在孵项目可用基地地址注册，全省重点建10家垂直领域基地","who":"围绕重点产业链建设的垂直领域大学生创业孵化基地；在孵项目登记注册时以孵化基地所在地址为注册地址的，市场监管部门准予登记。","materials":[],"window":"本措施自2025年8月1日起施行，有效期3年。","where":"市场监管部门办理登记；省人社厅牵头基地建设。","tip":"注册地址必须是孵化基地所在地址，否则不适用这条登记便利。","evidence":{"headline":["重点建设10家左右垂直领域大学生创业孵化基地"],"who":["创业孵化基地内在孵项目登记注册为市场主体且以孵化基地所在地址为注册地址的"],"window":["自2025年8月1日起施行,有效期3年"],"where":["市场监管部门根据相关规定准予登记"]}}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202510/t20251014_33824986.html","sourceNote":"2026-11-09 核对：正文与省人社厅原文页逐句比对一致（30/30 句命中），页面落款 2025-09-28、网页发布 2025-10-14，措施自 2025-08-01 施行、有效期3年；2026-11-09 按原文「自2025年8月1日起施行，有效期3年」推算 2025-08-01 至 2028-07-31","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2025-08-01","expiresAt":"2028-07-31","hunan":true},{"id":"p-2025-206f90","title":"邵阳市人力资源和社会保障局 邵阳市财政局关于在全市开展一次性创业补贴申报工作的通知","level":"city","region":"邵阳市","issuer":"邵阳市人力资源和社会保障局、邵阳市财政局","documentNo":"邵人社函〔2025〕56号","publishedAt":"2025-09-17","status":"active","tags":["创业补贴","就业补贴"],"audience":["小微企业","高校毕业生"],"summary":"邵阳个体门店经营者补5000元，离校2年内高校毕业生注册的个体门店补10000元；小微企业吸纳3名以上劳动者就业补10000元。","sections":[{"no":"一","title":"补贴对象","text":"在邵阳市范围内首次创办小微企业或从事个体门店的离校2年内高校毕业生（含留学回国学生，高等院校和大中专院校，高职院校大专及以上，技工院校高级工班、预备技师及技师班）、就业困难人员、返乡入乡农民工创业者。"},{"no":"二","title":"申报条件","text":"（一）创业项目或经营项目符合国家产业政策发展方向。\n（二）创业者年龄在法定劳动年龄内。\n(三)小微企业或个体门店自工商登记注册之日起正常运营1年以上。\n（四）个体门店经营者，依法参加基本养老保险（包括企业职工基本养老保险、灵活就业人员养老保险或城乡居民养老保险）。初创小微企业须吸纳3名以上（含3名）劳动年龄内的劳动者就业，并依法为其缴纳企业职工养老保险（孵化基地在孵实体项目不作此要求）且申请补贴时员工未离职。\n（五）出现以下情况的不符合申报条件：\n1. 小微企业或个体门店处于停业状态或有明确证据证实将注销、吊销营业执照的；\n2. 企业法人（或个体门店经营者）发生变更的或不是首次创业小微企业或从事个体门店的；\n3. 已享受过一次性创业补贴的企业或个体门店，不再重复享受补贴；\n4. 已享受过创业孵化基地经营场所租金补贴的；\n5. 同一个经营场所登记多家企业或个体门店的，不能重复享受一次创业补贴（孵化基地的在孵实体除外）；\n6. 门店招牌、创业项目经营地址与营业执照的注册名称和注册地址不一致的；\n7. 经核实，有其他不符合补贴政策情形的。"},{"no":"三","title":"补贴标准","text":"（一）对符合条件的个体门店经营者给予5000元的一次性创业补贴，对符合条件的离校2年内高校毕业生注册的个体门店，给予10000元的一次性创业补贴。\n（二）对符合条件的小微企业，吸纳3名以上（含3名）劳动者就业的按10000元的标准给予一次性创业补贴。\n（三）创业孵化基地中的在孵实体优先给予经营场所租金补贴，符合条件的个体门店按照5000元/家（离校2年内高校毕业生的个体门店给予10000元），符合条件的小微企业按照10000元/家给予补贴，由创业孵化基地代为申请代为支付。"},{"no":"四","title":"申报资料","text":"(一)《邵阳市一次性创业补贴申请审批表》（附件1）。\n（二）个体门店经营者或企业法人身份证及营业执照复印件。\n（三）个体门店经营者社保卡号或企业在银行开设的对公账号。\n（四）连续正常经营1年以上的有效证明资料：\n1. 税务部门开具的纳税凭证（按季度提供即可）或经营流水（流水多的企业，可视情况每个季度抽取1天提供即可）等凭证；\n2. 门面租赁合同及租金支付凭证。开办网店的，提供网店网址和平台实名认证信息、支付平台收支明细等。\n（五）创业孵化基地需提供为入孵实体减免租金的凭证。\n（六）人员类别证明资料：\n1. 离校 2 年内高校毕业生: 毕业证书复印件及学历证明(学信网下载打印), 留学回国学生提供教育部留学服务中心颁发的学历认证书复印件。\n2.返乡入乡农民工:本人户口本复印件。\n3. 就业困难人员：由人社部门从省一体化平台进行数据识别，不需要创业者提供相关身份证明材料。"},{"no":"五","title":"办理程序","text":"（一）自主申报。企业、创业孵化基地和个体门店按工商注册所在地属地原则申报受理，符合条件的可在每年10月31日前向注册所在地的县市区人力资源和社会保障部门提交申报材料，逾期不予受理。\n（二）审核审查。每年11月20日前，各县市区人力资源和社会保障部门分批次审核申报资料，确定补贴金额。\n（三）网上公示。县市区人力资源和社会保障部门将分批次审核情况，通过当地媒体或部门网站等向社会公示不少于5个工作日。\n（四）拨付资金。公示期满无异议后，县市区财政部门根据同级人力资源和社会保障部门拨款手续将补贴资金直接拨付到补贴对象提供的社保卡或对公银行账户。"},{"no":"六","title":"工作要求","text":"(一)高度重视。开展一次性创业补贴申报工作，是积极落实就业创业政策、稳就业的具体举措，各地要高度重视，认真抓好宣传发动，将一次性创业补贴工作抓实抓好。\n（二）严格把关。各地要严格把关，按照谁审核、谁把关、谁负责的原则，严格按照规定受理和审核申报资料，严防骗取补贴资金现象发生，确保补贴资金发挥实效。\n（三）严肃纪律。坚持依规申报，依规审核，对违规申报、弄虚作假骗取套取资金的单位和个人，一经查实，除追回补贴资金外，严格按有关规定追究相关人员的责任。\n其他未尽事宜，由市人力资源和社会保障局负责解释，本通知执行时间从发文之日起至2027年12月31日止，此前有关规定与本通知不一致的，以本通知为准，有效期内上级出台新规定与本通知不一致的，以上级新规定为准。"}],"interpretations":[{"sectionNo":"三","headline":"个体门店补5000元、大学生个体门店补1万元、小微企业补1万元","who":"在邵阳市范围内首次创办小微企业或个体门店的离校2年内高校毕业生（含留学回国学生）、就业困难人员、返乡入乡农民工。","materials":[],"window":"每年10月31日前向注册所在地县市区人社局提交材料，逾期不予受理。","where":"工商注册所在地的县市区人力资源和社会保障部门。","tip":"小微企业须吸纳3名以上（含3名）劳动者就业；已享受过一次性创业补贴的，不再重复享受。","evidence":{"headline":["对符合条件的个体门店经营者给予5000元的一次性创业补贴","给予10000元的一次性创业补贴"],"who":["在邵阳市范围内首次创办小微企业或从事个体门店的离校2年内高校毕业生"],"window":["在每年10月31日前向注册所在地的县市区人力资源和社会保障部门提交申报材料，逾期不予受理"],"where":["按工商注册所在地属地原则申报受理"],"tip":["吸纳3名以上（含3名）劳动者就业的按10000元的标准给予一次性创业补贴"]}},{"sectionNo":"四","headline":"材料要备齐审批表、营业执照、纳税凭证和租赁合同","who":"申报个人或企业；创业孵化基地申报代为申请租金补贴的，还需提供为入孵实体减免租金的凭证。","materials":["《邵阳市一次性创业补贴申请审批表》（附件1）","经营者或企业法人身份证、营业执照复印件","个体门店经营者社保卡号或企业对公账号","连续正常经营1年以上的纳税凭证或经营流水","门面租赁合同及租金支付凭证","毕业证书复印件及学信网学历证明（高校毕业生）","本人户口本复印件（返乡入乡农民工）"],"window":"申报截止每年10月31日；11月20日前完成审核；公示不少于5个工作日。","where":"县市区人社局受理审核，财政部门拨付到社保卡或对公账户。","tip":"就业困难人员不需要自己提供身份证明，由人社部门从省一体化平台数据识别。","evidence":{"headline":["《邵阳市一次性创业补贴申请审批表》"],"who":["创业孵化基地需提供为入孵实体减免租金的凭证"],"materials":["身份证及营业执照复印件","门面租赁合同及租金支付凭证","毕业证书复印件及学历证明"],"window":["公示不少于5个工作日"],"where":["拨付到补贴对象提供的社保卡或对公银行账户"],"tip":["由人社部门从省一体化平台进行数据识别，不需要创业者提供相关身份证明材料"]}}],"sourceUrl":"https://www.dxzc.gov.cn/jc_dxq/uploadfiles/202604/2026042216495444921.pdf","sourceNote":"2026-11-09 核对：原文页为 9 页扫描件（无文本层），已用 Windows OCR 逐页识别并与本条正文比对，36/36 句命中；因 OCR 有识别误差，未直接采用 OCR 文本，保留原录入正文","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"ocr","bodyVerifiedLock":true,"hunan":true},{"id":"p-2025-40c1cf","title":"关于印发《郴州市市级大学生创业孵化基地认定管理办法（试行）》的通知","level":"city","region":"郴州市","issuer":"郴州市人力资源和社会保障局、郴州市教育局、郴州市科学技术局、郴州市财政局","documentNo":"郴人社发〔2025〕13号","publishedAt":"2025-05-21","status":"active","tags":["场地支持","认定资质","创业补贴"],"audience":["小微企业","高校毕业生"],"summary":"市级大学生创业孵化基地要求入孵实体不少于20家、孵化面积1500平方米（含）以上，每吸纳1家实体入孵按每月140元补助基地，每个基地每年补助最高不超过40万元。","sections":[{"no":"一","title":"第一条","text":"为全面贯彻落实党的二十届三中全会精神，按照省委、省政府关于支持大学生创业“七个一”的工作要求，建设一批有特色、功能强的省级大学生创业孵化载体，进一步推进大学生创新创业。根据《湖南省人民政府办公厅关于印发〈湖南省大力支持大学生创业若干政策措施〉的通知》（湘政办发〔2024〕42号）、《湖南省人力资源和社会保障厅 湖南省财政厅关于深入推进创业孵化基地建设工作的通知》（湘人社规〔2023〕5号）、《湖南省人力资源和社会保障厅 湖南省教育厅 湖南省科学技术厅 湖南省财政厅关于印发〈湖南省省级大学生创业孵化基地认定管理办法（试行）〉的通知》（湘人社规〔2024〕28号）精神，制定本办法。"},{"no":"二","title":"第二条","text":"郴州市市级大学生创业孵化基地建设坚持政府引导、社会参与、市场运营、择优认定的原则，以在校大学生、高校应届毕业生等群体为主要孵化对象，以培育创业实体、促进创业带动就业为目标，具有滚动孵化功能，发挥示范引领和辐射带动作用。"},{"no":"三","title":"申报市级大学生创业孵化基地须达到以下标准：","text":"申报市级大学生创业孵化基地须达到以下标准：\n（一）以创业孵化为主营业务的各类创业孵化载体，无违法违规记录。\n（二）在孵实体数量。在孵实体数量不少于20家，其中入孵的在校大学生和毕业5年内（含）高校毕业生创业实体数量不少于1/3。或者扶持创业及带动就业的人员不少于40人，其中在校大学生和毕业5年内（含）高校毕业生人数不少于总人数的1/4。入孵创业实体孵化周期不超过5年。\n（三）孵化场地规模。孵化面积1500平方米（含）以上，拥有必要创业孵化场所和基础设施。应设立苗圃工位或独立办公房两种办公场所。其中，免费提供给大学生和毕业5年内（含）高校毕业生创业项目的场地不低于孵化面积的30%。\n（四）创业孵化服务。配备不少于3名工作人员负责基地运营管理，为入孵实体申请各项创业扶持政策，提供创业指导、创业培训、商务代办、投融资等服务。配备不少于4名创业导师，为创业者提供各类创业指导。\n（五）服务和管理。各项管理制度健全，已制定孵化服务目录清单，有明确的入驻和退出机制。"},{"no":"四","title":"第四条","text":"市级大学生创业孵化基地坚持公平公正、自愿申报、择优推荐的原则，参照市级创业孵化基地管理要求，每年认定或复评一次。"},{"no":"五","title":"申报认定程序：","text":"申报认定程序：\n（一）自主申报。各县市区人社部门牵头对照基本条件，联合相关部门对创业孵化基地进行考评，择优向市人社部门推荐，并提交以下材料：\n1.郴州市市级大学生创业孵化基地申报表；（附件1）\n2.在孵创业实体名册；（附件2）\n3.推荐函。\n（二）填报信息。按照全省创业孵化基地信息化管理的要求，指导创业孵化基地在“湖南人社一体化业务管理系统”中录入相关信息，保证数据真实准确完整。\n（三）组织核查。市人社部门组织专家对申报的孵化基地资料进行审核，并组织相关部门实地走访。\n（四）公示认定。对拟认定的市级大学生创业孵化基地，在市人社部门官方网站进行公示。对公示无异议的，由市级人社、教育、科技三部门联合发文认定为郴州市市级大学生创业孵化基地，并颁发牌匾，择优推荐省级大学生创业孵化基地认定。"},{"no":"六","title":"政策支持：","text":"政策支持：\n（一）补贴标准\n1.对于认定的郴州市市级大学生创业孵化基地，给予一定培育奖补，补助标准另行制定。所需资金从中省下达的市级就业专项资金中列支。\n2.对已认定的郴州市市级大学生创业孵化基地，参照湘人社规〔2023〕5号文件，根据每年创业孵化成效给予创业服务补助。所需资金从所在地就业专项资金中列支。具体标准如下：\n（1）市级大学生创业孵化基地每吸纳1家创业实体入孵，按每家每月140元的标准给予基地补助；\n（2）创业实体在孵期间成功注册市场主体的（在孵创业实体入孵前未注册市场主体），按2800元每家给予基地一次性补助；同一创业孵化基地中的同一在孵创业实体注册多个市场主体的，只能计算1家，不重复补贴。\n（3）创业孵化基地内扶持大学生或毕业5年内（含）高校毕业生创业或就业的，超过40人的按4.2万元每年的标准给予基地补助，超过80人的按8.4万元每年的标准给予基地补助，超过120人的按12.6万元每年的标准给予补助。\n每个基地每年享受创业服务补助总额最高不超过40万元，按照就业专项资金使用的有关规定，主要用于开展创业孵化基地服务项目清单中的有关服务，以及孵化基地服务能力建设和提升。按照湘人社规〔2023〕5号文件已认定的创业孵化基地，享受的创业服务补助就高不就低，不重复享受。\n（二）各级人社部门可通过政府购买创业服务成果的方式，支持市级大学生创业孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动，为创业者搭建资源对接的平台。指导设立“创业指导师工作室”，推动在孵项目和大学生创业导师建立“一对一”帮扶关系。为在孵实体提供创业筹备、创业运营、创业发展等方面的指引。每年在同一创业孵化基地内指导帮扶孵化成功实体注册5个以上的给予“创业指导师工作室”1万元创业带动就业补助。所需资金从所在地就业专项资金中列支。\n（三）推动政府扶持政策向孵化基地集中。各级人社、教育、科技、财政部门要加强政策的宣传和解读，主动为大学生创业孵化基地内的在孵项目落实相关政策和服务，在补贴、项目、课题、资金申报上加大支持力度。允许孵化基地按照各部门要求，组织在孵企业统一收集、统一申报，缩短审批时间。"},{"no":"七","title":"第七条","text":"依托“湖南人社一体化业务管理系统”对市级大学生创业孵化基地实行动态管理。市人社部门负责市级基地的工作指导、组织协调、认定核查等；县市区人社部门负责本地市级基地的推荐申报、服务指导、日常管理等。推荐认定环节做到公开透明、公平公正，坚决杜绝优亲厚友、虚报冒领等行为。对存在徇私舞弊、套取骗取、贪污挪用等违法违纪行为的，依照法律法规和有关规定严肃追究责任。"},{"no":"八","title":"第八条","text":"市级大学生创业孵化基地出现下列情形之一的，撤销资格并收回牌匾：\n（一）建设单位和运营单位已注销、吊销营业执照的。\n（二）未按要求申请复评或复评未通过的。\n（三）对孵化效果欠佳、服务能力不足、工作配合度和群众满意度不高，或相关部门提出处理意见后未能及时整改的。\n（四）违法经营和造成重大安全、重大质量事故的。\n（五）其他应当撤销市级基地资格的。"},{"no":"九","title":"第九条","text":"各相关部门要加强项目绩效管理，完善绩效指标体系，确保项目资金使用效益。加强绩效管理结果运用，作为政策优化调整的重要依据。"},{"no":"十","title":"第十条","text":"各县市区人社部门可根据本地实际，参照本办法自行制定县级大学生创业孵化基地认定管理办法。"},{"no":"十一","title":"本办法自2025年5月21日起执行，有效期两年","text":"本办法自2025年5月21日起执行，有效期两年。\n附件：1.郴州市市级大学生创业孵化基地申报表\n2.在孵创业实体名册"}],"interpretations":[{"sectionNo":"三","headline":"在孵实体20家以上、孵化面积1500平方米以上才能申报","who":"以创业孵化为主营业务的各类创业孵化载体，无违法违规记录；在孵实体不少于20家，其中在校大学生和毕业5年内高校毕业生创业实体不少于1/3；孵化面积1500平方米（含）以上；配3名以上运营人员和4名以上创业导师。","materials":["郴州市市级大学生创业孵化基地申报表","在孵创业实体名册","推荐函"],"window":"每年认定或复评一次，由县市区人社部门牵头推荐。","where":"县市区人社部门牵头考评推荐，市人社部门组织专家审核、实地走访并公示认定。","tip":"免费提供给大学生和毕业5年内高校毕业生的场地不低于孵化面积的30%；入孵实体孵化周期不超过5年。","evidence":{"headline":["在孵实体数量不少于20家","孵化面积1500平方米（含）以上"],"who":["其中入孵的在校大学生和毕业5年内（含）高校毕业生创业实体数量不少于1/3","配备不少于3名工作人员负责基地运营管理","配备不少于4名创业导师"],"materials":["郴州市市级大学生创业孵化基地申报表"],"window":["每年认定或复评一次"],"where":["市人社部门组织专家对申报的孵化基地资料进行审核"],"tip":["免费提供给大学生和毕业5年内（含）高校毕业生创业项目的场地不低于孵化面积的30%","入孵创业实体孵化周期不超过5年"]}},{"sectionNo":"六","headline":"每吸纳1家实体每月补140元，基地每年最高补40万元","who":"已认定的郴州市市级大学生创业孵化基地的运营方（不是入孵企业本身）；同一在孵实体注册多个市场主体的只算1家。","materials":["在孵创业实体名册","湖南人社一体化业务管理系统录入信息"],"window":"按年度核算，每个基地每年享受创业服务补助总额最高不超过40万元。","where":"市、县市区人社部门；资金从所在地就业专项资金中列支。","tip":"已按湘人社规〔2023〕5号认定的基地，创业服务补助就高不就低、不重复享受；另设「创业指导师工作室」年度帮扶孵化成功5家以上可补1万元。","evidence":{"headline":["按每家每月140元的标准给予基地补助","每个基地每年享受创业服务补助总额最高不超过40万元"],"who":["对已认定的郴州市市级大学生创业孵化基地","只能计算1家，不重复补贴"],"materials":["在孵创业实体名册"],"window":["每个基地每年享受创业服务补助总额最高不超过40万元"],"where":["所需资金从所在地就业专项资金中列支"],"tip":["享受的创业服务补助就高不就低，不重复享受","指导帮扶孵化成功实体注册5个以上的给予“创业指导师工作室”1万元创业带动就业补助"]}}],"sourceUrl":"https://czrsj.czs.gov.cn/18281/18295/content_3905671.html","sourceNote":"2026-11-09 核对：正文与郴州市人社局原文页逐句比对一致（60/60 句命中），页面落款 2025-05-21、文号 郴人社发〔2025〕13号，有效期两年","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-42786b","title":"关于印发《张家界市进一步降本减负优化营商环境九条措施》的通知","level":"city","region":"张家界市","issuer":"张家界市人民政府办公室","documentNo":"张政办发〔2025〕13号","publishedAt":"2025-07-17","status":"active","tags":["融资支持","场地支持","社保补贴"],"audience":["小微企业","高校毕业生"],"summary":"张家界降低融资、用能、用工、物流、中介、审批、用地、税费、制度性交易九方面成本，优化营商环境。","sections":[{"no":"一","title":"降低融资成本","text":"降低融资成本。严格落实支持小微企业融资协调工作机制，抓实“千企万户大走访”，保持小微企业信贷有效供给。加大首贷、信用贷、中长期贷款投放力度，推动法人银行普惠型小微企业贷款和民营企业贷款增速均高于各项贷款增速。持续优化小微企业续贷机制，覆盖2027年9月30日前到期的中型企业流动资金贷款。建立续贷沟通机制，贷款到期前1个月主动对接，实现“应续尽续”。根据LPR定价机制，及时主动调整涉企贷款利率。全面落实企业融资收费“两禁两限”规定，除银团贷款外不得对小微企业贷款收取承诺费、资金管理费，严格限制对小微企业及其增信机构收取财务顾问费、咨询费。积极推进农村“三信”创建，发挥信用信息支持产业融资的作用。充分发挥张家界“金融超市”平台、企业收支流水征信平台作用，加大信贷投放力度，力争小微企业信用贷款占比达20%以上。用好我市农业产业贷款风险补偿基金、产业发展基金，不断健全“政银保担投”全链条金融服务体系。（市政府办公室、中国人民银行张家界市分行、国家金融监管总局张家界监管分局、市发展改革委、市工业和信息化局、市农业农村局、市融资担保集团公司等按职责分工负责，各区县人民政府负责落实本区县工作；以下均需各区县人民政府负责落实本区县工作，不再列出）"},{"no":"二","title":"降低用能成本","text":"降低用能成本。积极对接和落实天然气管网“一张网、一个价”改革。加大对土木溪水厂和花岩水厂设施建设和改良力度。实行用电重点项目“项目长”负责制，对重点企业和电价水平长期较高的用户，开展“一企一策”指导，支持企业用活分时电价政策，常态开展工业园区客户走访行动。鼓励企业配置新型储能设施，提倡“低充高用”，鼓励园区企业加强余热利用。（市住房城乡建设局、国网张家界供电公司、市发展改革委、市自来水公司等按职责分工负责）"},{"no":"三","title":"加大用工保障和补贴降费力度","text":"加大用工保障和补贴降费力度。用好“用工超市”和“张家界就业”平台，加强就业岗位信息归集共享，2025年发布岗位30万个以上。利用5G技术将招聘信息动态推送至村组干部，加强线上直播带岗。精准发放一次性扩岗补助、吸纳就业困难人员、离校2年内未就业高校毕业生社会保险补贴、就业见习补贴。开展补贴性职业培训6500人次，落实补贴资金900万元。推广“订单式”培训，在湖南旅游技师学院开设企业定向技能培养班。继续落实社保降费政策，延续实施阶段性降低失业保险费率至1%政策。实现失业保险稳岗返还政策“免申即享”。进一步做好企业用工服务保障工作。（市人力资源社会保障局、市财政局等按职责分工负责）"},{"no":"四","title":"降低物流成本","text":"降低物流成本。调整优化运输结构，持续推进“公转铁”。推进铁路物流园建设，2025年完成项目招商引资和立项审批，2026年开工建设。引进1—2家多式联运现代物流企业入驻我市。加快货运设备更新升级，推广使用新能源货运车辆。严格执行鲜活农产品运输“绿色通道”政策，落实道路运输和水路运输燃油补贴申报与发放。推行农村客货邮融合发展模式，持续完善县乡村三级物流体系，加强分拨中心、配送中心和末端网点建设。（市交通运输局、市发展改革委、市商务局、张家界高新区管委会、市自然资源和规划局、市邮政管理局等按职责分工负责）"},{"no":"五","title":"降低中介服务成本","text":"降低中介服务成本。按照“政府引导、行业自律、市场调节”原则，深入推动中介服务改革，大力开展行政审批中介服务事项清理，梳理公布各类评估评价、检验检测等涉审中介服务事项清单，审批部门不得要求经营主体提供清单之外的中介服务报告。用好“中介超市”，实现机构选择、费用支付、报告上传、服务评价等全流程网上办理。引导成立中介服务行业协会或社会组织并加强行业自律，规范中介服务收费，严厉查处中介服务机构出具虚假证明或报告、谋取不正当利益、“官荐中介”等违规行为。（市委深改办、市发展改革委、市数据局、市政务服务中心、市市场监管局等按职责分工负责）"},{"no":"六","title":"降低行政审批成本","text":"降低行政审批成本。市、区县政务服务部门建立网办帮办领办机制，大力推行“全程网办”，根据企业和群众需求免费提供帮办领办服务，构建“除了网上办就是帮办领办”的政务服务新格局。强化行政效能分析以及在线监察，对“红黄牌”和“差评”加强处置，推动审批人员按期办、提速办、优质办。进一步推动工改系统改革，规划和自然资源、住房城乡建设部门审批时间再压缩20%以上。（市数据局、市政务服务中心等按职责分工负责）"},{"no":"七","title":"降低工业用地成本","text":"降低工业用地成本。用好“土地超市”，实现“一站式”选地购地，缩减企业拿地时间。探索建立城乡统一基准地价体系，支持产业用地“标准地”出让，采用工业用地长期租赁、先租后让、租赁与出让结合、弹性年期出让等供应方式，产业园区全面推进“用地清单制+告知承诺制”和“五即”（洽谈即服务、签约即供地、开工即配套、竣工即办证、达产即复核）供地模式。继续推进“验登合一”“多测合一”，针对小微企业免收不动产登记费。（市自然资源和规划局、市工业和信息化局、张家界高新区管委会等按职责分工负责）"},{"no":"八","title":"降低税费成本","text":"降低税费成本。精准推送结构性减税降费政策，实现“政策找人”“一企一策”个性化服务，推进惠企税务政策“直达快享”。提供数字化发票开具、交付、使用服务，降低企业票据管理成本和交易成本。优化纳税信用评价，提升“银税互动”质效，将企业纳税信用转化为融资信用，提升企业融资便利度。定期召开税企“面对面”座谈交流会，高效解决企业涉税问题。加强涉企收费长效监管，动态更新涉企收费目录，加大违规收费治理力度。（市税务局、市财政局、市发展改革委、市市场监管局等按职责分工负责）"},{"no":"九","title":"降低制度性交易成本","text":"降低制度性交易成本。积极主动融入全国统一大市场建设，修订《张家界市政府性投资工程招投标实施操作办法》，完善政府采购配套措施，推广“机器管招投标”，建立排除人工干预的公共资源交易模式，提高评标效率，约束专家自由裁量权。（市发展改革委、市财政局、市公共资源交易中心等按职责分工负责）"}],"interpretations":[{"sectionNo":"一","headline":"小微企业续贷「应续尽续」，不收承诺费和资金管理费","who":"在张家界经营的小微企业；普惠型小微企业贷款和民营企业贷款增速要求高于各项贷款增速。","materials":[],"window":"续贷机制覆盖 2027 年 9 月 30 日前到期的中型企业流动资金贷款，贷款到期前 1 个月银行主动对接。","where":"各经办银行、张家界「金融超市」平台；人民银行张家界市分行等按职责分工负责。","tip":"除银团贷款外，银行不得对小微企业贷款收取承诺费、资金管理费；财务顾问费、咨询费也严格限制。","evidence":{"headline":["贷款到期前1个月主动对接","建立续贷沟通机制"],"who":["保持小微企业信贷有效供给"],"window":["覆盖2027年9月30日前到期的中型企业流动资金贷款","贷款到期前1个月主动对接"],"where":["企业收支流水征信平台作用"],"tip":["除银团贷款外不得对小微企业贷款收取承诺费、资金管理费"]}},{"sectionNo":"三","headline":"社保补贴、扩岗补助、见习补贴照发，失业保险费率仍按1%","who":"招用就业困难人员、离校2年内未就业高校毕业生等的企业；以及符合条件的失业参保单位。","materials":[],"window":"2025 年计划发布岗位 30 万个以上、补贴性职业培训 6500 人次；阶段性降低失业保险费率至 1% 政策延续实施。","where":"市人力资源社会保障局、市财政局；稳岗返还「免申即享」。","tip":"稳岗返还是「免申即享」，不用企业自己跑申请；补贴资金规模为 900 万元。","evidence":{"headline":["延续实施阶段性降低失业保险费率至1%政策"],"who":["精准发放一次性扩岗补助、吸纳就业困难人员、离校2年内未就业高校毕业生社会保险补贴、就业见习补贴"],"window":["2025年发布岗位30万个以上","开展补贴性职业培训6500人次，落实补贴资金900万元"],"where":["市人力资源社会保障局、市财政局等按职责分工负责"],"tip":["延续实施阶段性降低失业保险费率至1%政策","失业保险稳岗返还政策"]}}],"sourceUrl":"http://www.zjj.gov.cn/c693/20250731/i1095938.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-5136c2","title":"湖南省财政厅等四部门关于实施大学生创业贷款财政补助政策的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、中共湖南省委金融委员会办公室、湖南金融监管局、中国人民银行湖南省分行","documentNo":"湘财金〔2025〕43号","publishedAt":"2025-10-21","status":"active","tags":["贷款贴息","融资支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"对在湘个人创业或合伙创业的大学生，个人创业贷款额度不超过50万元、小微企业及其他市场主体创业贷款额度不超过500万元，省财政按贷款实际利率的50%给予贴息、按担保金额的1.5%给予担保机构担保费补贴，本通知自印发之日起实施，有效期至2027年12月31日。","sections":[{"no":"一","title":"政策内容","text":"（一）支持对象与适用条件\n\n1.支持对象：在湘个人创业或合伙创业的大学生。\n\n2.适用条件：同时符合以下条件的创业贷款，可享受省财政补助。\n\n贷款发放时间：本通知印发之日起至2027年12月31日期间新发放。政策到期后如需延期，另行通知。\n\n贷款方式：通过信用贷款方式或由省内纳入再担保体系的政府性融资担保机构（以下简称担保机构）提供免费担保。\n\n贷款额度与利率：个人创业贷款额度不超过50万元，小微企业及其他市场主体创业贷款额度不超过500万元；贷款利率不超过同期贷款市场报价利率（LPR）加100个基点（Bps）。\n\n资金用途：专项用于大学生在湘创办市场主体（企业、个体工商户等）的日常经营、技术研发、设备采购等生产经营活动。\n\n主体资格：“大学生”指国内外在校学生或毕业5年（含）内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年（含）以内的毕业生。残疾人大学生可放宽至毕业8年（含）内的毕业生。\n\n（二）财政补助标准\n\n1.贴息：对经办银行发放的符合条件贷款，省财政按贷款实际利率的50%给予贴息，贴息期限最长不超过3年。逾期或展期的贷款，自逾期或展期之日起不再享受贴息。\n\n2.担保费补贴：省财政按担保金额的1.5%给予担保机构担保费补贴。担保费补贴按实际承保期限计算，按年度补贴。\n\n3.风险补偿：对担保机构与经办银行合作开展的大学生创业担保贷款业务，代偿率在5%（含）以内的部分，由省财政、担保机构、经办银行按40%、40%、20%的比例分担风险。"},{"no":"二","title":"经办银行与贷款流程","text":"（一）经办银行范围\n\n省财政补助政策适用于以下开发并运营大学生创业专属贷款产品的银行：中国工商银行等18家全国性银行在湘分支机构、湖南银行、长沙银行及省内各农村商业银行。\n\n（二）经办担保机构范围\n\n省财政补助政策适用于省内纳入再担保体系的政府性融资担保机构。\n\n（三）贷款申请\n\n符合条件的大学生，可向所在地经办银行提出贷款申请，并提供以下材料：\n\n身份证明：在校生提供学校盖章的在校证明；毕业生提供学信网信息查询截图及学历证书（或国外学历学位认证书）复印件。经办银行须核实其真实性。\n\n主体证明：借款人是个体工商户的，提供营业执照；借款人是小微企业或小微企业主的，需提供大学生合计持股比例不低于10%的股东身份证明、担任关键核心岗位（董事长、执行董事、总经理、副总经理、技术总监、营销总监、财务总监、生产总监等）证明及营业执照。\n\n（四）贷款审核与发放\n\n经办银行遵循市场化原则，独立审核、审批贷款申请，自主决定贷款发放与否及具体条件，对符合条件的申请应及时放款。需担保的贷款，经办银行可与担保机构合作，鼓励采用“见贷即保”或联合尽调模式，简化流程。鼓励经办银行、担保机构与大学生创业投资基金建立“投贷担”联动机制，对大学生创业投资基金投资的项目，降低贷款门槛和利率，建立绿色审批通道，优先发放贷款。"},{"no":"三","title":"财政补助资金流程","text":"（一）资金预拨\n\n省财政厅按年度向经办银行省级机构（全国性银行省级分行、城市商业银行总行、省农村信用社联合社）预拨贴息资金，向担保机构预拨担保费补贴和风险补偿资金。\n\n（二）资金结算\n\n1.贴息资金。经办银行收到预拨贴息资金后，在收取利息时直接扣减贴息部分。经办银行省级机构按季度向省委金融办数据平台报送贷款发放及贴息情况。每年1月20日前，经办银行省级机构向省委金融办提交上年度贴息资金结算申请及证明材料（贷款合同、借款人身份及主体证明、资金用途证明等）。省委金融办于3月10日前完成审核，将审核结果报省财政厅。省财政厅依据审核结果与经办银行完成年度结算。\n\n2.担保费补贴与风险补偿资金。担保机构发生的担保贷款业务须在省再担保系统备案。每年2月10日前，省再担保公司完成各担保机构上年度担保费补贴、风险补偿资金的结算审核，并将结果报省委金融办。省委金融办复核，并于3月10日前将复核结果报省财政厅。省财政厅依据复核结果与担保机构完成年度结算。"},{"no":"四","title":"监督管理","text":"（一）专款专用\n\n贷款主体须确保贷款资金专项用于生产经营活动，严禁虚报、冒领、套取、截留、挤占、挪用；严禁用于偿还其他债务、投资理财等套利活动及个人消费等非生产经营领域。\n\n（二）强化监管\n\n湖南金融监管局落实小微企业贷款差异化监管政策，督促经办银行严格审核资金用途，跟踪贷款使用，确保合规有效。人民银行湖南省分行引导银行机构用好用足各项结构性货币政策工具，充分发挥央行低成本资金的牵引撬动作用，加大首贷、信用贷款投放，创新特色金融产品，支持大学生创新创业。省再担保公司、省委金融办严格审核财政补贴资金申请，确保财政资金安全。\n\n（三）严格责任追究\n\n相关部门应加强全过程跟踪管理。发现违规使用贷款或财政补助资金的，须及时追回并依法依规追究贷款主体、经办银行及相关人员责任。贷款主体及经办银行须自觉接受财会监督、审计监督和行业监管。工作人员存在违规违纪行为的，依法追究责任，涉嫌犯罪的，移送司法机关处理。"},{"no":"五","title":"其他事项","text":"1、同一笔贷款如已获得省级财政补助资金的，不得重复享受本政策补助。\n\n2、执行中如遇问题，请及时向省财政厅、省委金融办报告。\n\n3、请各有关单位高度重视，认真贯彻执行。\n\n本通知自印发之日起实施，有效期至2027年12月31日。"}],"interpretations":[],"sourceUrl":"https://jyt.hunan.gov.cn/jyt/sjyt/bys/byszcjd/202603/t20260306_33928168.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布时间 2025-11-05","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-71aa02","title":"湘西自治州人民政府办公室关于印发《湘西州支持培育发展\"四上\"企业的若干措施》的通知","level":"city","region":"湘西土家族苗族自治州","issuer":"湘西土家族苗族自治州人民政府办公室","documentNo":"州政办发〔2025〕7号","publishedAt":"2025-05-12","status":"active","tags":["专项资金","认定资质"],"audience":["小微企业"],"summary":"湘西州新入规工业企业每户奖励10万元；新入库建筑业、房地产企业各奖励10万元；新入规限上批零住餐企业奖励6万元；新入规服务业企业奖励4万元。","sections":[{"no":"一","title":"完善转企升规奖励机制","text":"完善转企升规奖励机制。支持各类企业入规纳统：对新入规工业企业每户奖励10万元；对新入库有资质的建筑业企业每户奖励10万元；对新入库房地产开发经营业企业且本年度主营业务收入1000万元以上的，每户奖励10万元；对新入规的限额以上批发零售和住宿餐饮业企业每户奖励6万元；对新入规的服务业企业每户奖励4万元（其中申报省级奖励2万元，州级配套奖励2万元）。奖励分两次发放，入规（转企）后次年3月前奖励50%；若企业持续在库正常报数，第三年3月前再奖励剩余50%。已入规（转企）企业退规（注销）后再进或变更名称、地点、经营范围等进规达限转企的经营主体不再享受奖励。"},{"no":"二","title":"完善企业扩规提质奖励机制","text":"完善企业扩规提质奖励机制。对已在库的规上工业、建筑业、房地产开发经营、批发零售和住宿餐饮业、服务业企业，每年实现正增长且当年增速同比增长20%、40%、60%、80%、100%的，分别奖励1万元、2万元、3万元、4万元、5万元；对新入规的“四上”企业，在入规后第二年（含入规当年）达到条件即可享受该项政策，奖励资金于次年3月前一次性发放。该项政策考核指标中，工业、建筑业为产值，房地产业为商品房销售面积，其余行业为营业收入。"},{"no":"三","title":"完善规范管理奖励机制","text":"完善规范管理奖励机制。鼓励商业综合体、专业市场（包括二手车、建材、家居家装、农贸市场等）、特色商业街区、产业集聚区、民宿及旅拍等行业市场主体实施联营模式，联合组建统一收银、统一核算、统一报税、统一管理的法人企业，不断规范市场主体经营、管理和发展。对新纳入统计的规上服务业和限上批零住餐业企业，其年度营业收入分别达到入规标准10倍、20倍，且自入统年度次年起主营业务收入同比增长15%的，给予管理公司奖励20万元、50万元。奖励分两次发放，对达到条件的企业于次年3月发放50%；若企业持续在库，自首次发放之日起满12个月后（即第三年3月）兑付剩余50%。集中管理结算的企业中不得包含之前已退规退库的企业。"},{"no":"四","title":"完善助企服务机制","text":"完善助企服务机制。建立健全领导联系企业和“一对一”专班服务企业机制，持续开展“送解优”专项行动，帮助企业纾困解难。鼓励各县市、湘西高新区等园区通过购买服务等方式，选择管理规范、实力较强的专业中介机构，对拟升规入统和新升规入统的企业提供全过程咨询服务，包括建立健全原始凭证和电子统计台账、办理纳税申报、提供政策咨询等。优化入库预审工作，提高审核通过率。定期举办统计报表业务培训班，及时帮助企业统计人员解决业务中遇到的疑难问题。合理降低企业用工成本，对在库“四上”企业统计人员发放统计工作补贴。各县市、湘西高新区等园区可结合本地实际，给予本地区“四上”企业及在库“大个体”统计人员（报表人员）工作经费补贴，具体补贴金额和发放形式由县市、园区研究决定。（上述补贴不含行政事业单位和国有企业）"},{"no":"五","title":"完善企业发展资金支持机制","text":"完善企业发展资金支持机制。强化服务意识，靠前服务，指导帮助企业准确掌握并合规申报各项优惠政策。支持符合条件的“四上”企业，积极申报和争取国家级、省级各类专项资金、专项试点等。对符合条件的“四上企业”，州产业发展引导基金予以优先支持。鼓励各县市、湘西高新区对连续在库3年以上且符合一定条件和要求的企业给予流动资金贷款贴息支持，州内政府性融资担保机构对符合条件的企业提供融资担保支持。鼓励银行机构精准开发支持规上企业的融资产品，按照市场化原则在贷款规模、贷款利率、授信流程等方面制定优惠政策予以支持。实施创新型企业家培育工程，探索“政府出策出钱、企业育才留才”的人才培育机制。"},{"no":"六","title":"完善涉企检查监管机制","text":"完善涉企检查监管机制。对通过大数据比对、经济普查、统计调查等途径，梳理出来符合入统条件但未入统的企业，实行告知提示，告知提示后仍未申请入统的，应在企业信用档案中予以标记。指导行业协会开展行业信用评价，将是否入统作为信用评价指标纳入企业信用评价体系。将包括“四上”企业在内的市场主体纳入赋码保护范围，减少对企业正常生产经营的干扰，力争做到“无事不扰，有事必应”。依规进行柔性执法，推行“首违不罚”、轻微违法行为不予处罚或依法减轻处罚等措施，更多运用提醒告诫、行政指导等柔性措施，将服务贯穿于监管执法全过程、各环节。"},{"no":"七","title":"完善工作推进落实机制","text":"完善工作推进落实机制。建立由州发改委牵头，州财政局、州工信局、州科技局、州文旅广电局、州农业农村局、州住建局、州市场监管局、州交通运输局、州人社局、州商务局、州统计局、州税务局等部门共同参与的州支持培育发展“四上企业”工作联席会议制度，定期调度工作落实情况，研究解决存在的困难和问题。州直相关部门要按照行业门类分工，全面掌握本行业规上企业发展情况，及时督促、指导、服务市场主体升规（上限）入统。各县市、湘西高新区要高度重视培育发展“四上”企业工作，建立工作推进机制，加强对重点领域、重点园区、重点企业的监测分析和预警预测，细化工作措施，确保“四上”企业培育发展工作有序推进，“四上”企业数量规模和质量效益稳步提升。\n本通知自2025年5月12日起施行，有效期5年。"}],"interpretations":[],"sourceUrl":"http://xxgxq.xxz.gov.cn/zwgk/fdzdgknr/zcwjjjd/bmwj/202505/t20250529_2259185.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-09 按原文「自2025年5月12日起施行，有效期5年」推算 2025-05-12 至 2030-05-11","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2025-05-12","expiresAt":"2030-05-11","hunan":true},{"id":"p-2025-777f85","title":"关于印发《怀化市科技型企业知识价值贷款风险补偿实施办法》的通知","level":"city","region":"怀化市","issuer":"怀化市科学技术局、怀化市财政局、怀化市市场监督管理局、中国人民银行怀化市分行、国家金融监督管理总局怀化监管分局","documentNo":"怀科发〔2025〕20号","publishedAt":"2025-11-20","status":"active","tags":["融资支持","贷款贴息"],"audience":["小微企业"],"summary":"怀化设立2500万元知识价值贷款风险补偿资金，省、市按1:1比例分担；国家高新技术企业信用贷款风险补偿额度最高1000万元，信用担保贷款最高3000万元。原怀政办发〔2025〕5号已废止，本条为补位政策。","sections":[{"no":"一","title":"第一条","text":"为加快实现“三高四新”美好蓝图，深入实施“五新四城”战略，推动建立轻资产债权融资模式，破解科技型企业融资难题，推动“5+10”现代化产业体系高质量发展，根据《中共湖南省委关于深入学习贯彻党的二十届三中全会精神进一步全面深化改革奋力谱写中国式现代化湖南篇章的决定》《湖南省促进金融支持科技型中小企业创新发展若干规定》《湖南省科技型企业知识价值贷款风险补偿实施办法》精神，特制定本办法。"},{"no":"二","title":"第二条","text":"知识价值贷款风险补偿工作按照“政府引导、上下联动、风险分担、企业受益”的原则，由省科技厅和市人民政府对合作银行发放的信用贷款所产生的不良贷款本金，以及合作担保机构提供担保的贷款所产生的逾期未清偿本金进行有限补偿。"},{"no":"三","title":"第三条","text":"本办法所指的科技型企业知识价值贷款（以下简称“知识价值贷款”），是合作银行以科技型企业知识价值评分结果为参考，向科技型企业发放支持其开展科技创新活动的为期三年（含）以内的贷款。包括信用贷款和合作担保机构提供担保的信用担保贷款。"},{"no":"四","title":"第四条","text":"本办法所称的科技型企业知识价值贷款评价指标体系（以下简称“指标体系”，见附件1），是指依托创新积分\n\n制所设计的，根据科技型企业科创属性，涵盖知识产权、研发投入、科技人才、经营能力等创新要素并给予不同权重赋值的评价体系。省科技厅对知识价值贷款企业库内企业按照指标体系进行评价，原则上每年不少于一次，评价结果向合作银行、合作担保机构推送。省科技厅可视实际情况对指标体系进行适当调整。"},{"no":"五","title":"第五条","text":"本办法所称的知识价值贷款企业库（以下简称“企业库”），由国家高新技术企业、国家科技型中小企业以及其他科技型企业组成，其中其他科技型企业根据本办法确定。企业库内企业有效期为：国家高新技术企业从认定之日起三年、国家科技型中小企业从评定入库（国家科技型中小企业库）之日起一年、其他科技型企业从纳入企业库之日起一年。\n企业库内企业所属产业不属于“限制”或“禁止”类产业范畴，“限制”与“禁止”类产业根据国家最新版本产业结构调整指导目录划定的范围确定。企业库内企业不含房地产业、金融业和投资与资产管理类、地方政府投融资平台类、地方国有企业资本运营平台类企业。"},{"no":"六","title":"第六条","text":"本办法所称的不良贷款，参照《商业银行金融资产风险分类办法》（中国银行保险监督管理委员会中国人民银行令2023年第1号）执行。"},{"no":"七","title":"第七条","text":"怀化市设立2500万元知识价值贷款风险补偿资金，以财政预算预留方式保障，其中市本级1000万元，各县市区、怀化高新区、怀化国际陆港经开区按约定共同组成1500万元。根据各县市区、怀化高新区、怀化国际陆港经开区企业贷款需求，经县级申请，市科技局、市财政局、市市场监管局、市政\n\n府办（金融工作科）、人民银行怀化市分行、国家金融监管总局怀化监管分局共同审核，在1500万元风补资金总额保持不变的情况下，可按年度对县级组成进行调整。\n省科技厅和怀化市按1:1比例设立知识价值贷款风险补偿资金。省、市两级风险补偿资金对合作银行、合作担保机构的风险补偿实行总额控制，若累计补偿金额超出风险补偿资金总额，不再承担风险补偿责任。\n怀化市及各县市区、怀化高新区、怀化国际陆港经开区信用贷款和信用担保贷款的总和，均不能超出允许的最大贷款额度，超出部分不纳入风险补偿的范畴。贷款总额按录入贷款信息时间顺序累加计算。\n第二章组织与实施"},{"no":"八","title":"第八条","text":"市科技局、市财政局、市市场监管局、市政府办（金融工作科）、人民银行怀化市分行、国家金融监管总局怀化监管分局共同设立怀化市科技型企业知识价值贷款风险补偿工作机制，由市科技局牵头开展知识价值贷款风险补偿工作，其主要职责为：\n（一）共同制定相关制度性文件，指导各县市区、怀化高新区、怀化国际陆港经开区开展相关工作，并根据各自职责研究制定督促落实的相应措施；\n（二）审定科技型企业知识价值贷款风险补偿措施；\n（三）审议拟风险补偿企业名单；\n（四）考核评估科技型企业知识价值贷款风险补偿工作；\n\n（五）商定其他相关事项。"},{"no":"九","title":"市科技局具体职责如下：","text":"市科技局具体职责如下：\n（一）牵头制订相关制度性文件，会同市财政局编制市本级风险补偿资金安排总体计划，提出预算建议；\n（二）确定风险补偿工作市级运营管理机构，向省科技厅和市人民政府提出合作银行、合作担保机构建议；\n（三）支持和协调合作银行、合作担保机构开展知识价值贷款工作；\n（四）向合作银行、合作担保机构遴选推荐优质科技型企业；\n（五）职责范围内的其他工作事项。"},{"no":"十","title":"市财政局具体职责如下：","text":"市财政局具体职责如下：\n（一）负责市本级风险补偿资金预算管理，对资金安排进行程序性审核，会同市科技局对风险补偿事项拨付资金；\n（二）按省财政厅要求组织实施财政监督检查、绩效评价等工作；\n（三）按省财政厅要求对合作担保机构进行管理考核；\n（四）职责范围内的其他工作事项。"},{"no":"十一","title":"市市场监管局具体职责如下：","text":"市市场监管局具体职责如下：\n（一）整合企业注册登记、行政处罚、经营异常名录、严重违法失信等信用数据，构建企业信用档案；\n（二）职责范围内的其他工作事项。"},{"no":"十二","title":"市政府办（金融工作科）具体职责如下：","text":"市政府办（金融工作科）具体职责如下：\n（一）推动合作担保机构加快构建服务科技创新的专业化组织架构、管理体系以及风险评审和产品创新等机制；\n\n（二）对合作担保机构开展的科技担保业务合规与风险状况进行日常监督管理和风险防范处置；\n（三）推动合作担保机构建立容错机制、细化尽职免责清单；\n（四）职责范围内的其他工作事项。"},{"no":"十三","title":"人民银行怀化市分行具体职责如下：","text":"人民银行怀化市分行具体职责如下：\n（一）联合市科技局开展银行机构金融政策效果评估工作，作为动态调整怀化市合作银行的依据；\n（二）推动怀化市内合作银行加快建设科技金融专业团队，在信贷资源和绩效考评方面给予政策倾斜，适当下放授信审批等业务权限；\n（三）职责范围内的其他工作事项。"},{"no":"十四","title":"国家金融监管总局怀化监管分局具体职责如下：","text":"国家金融监管总局怀化监管分局具体职责如下：\n（一）推动怀化市内合作银行加快构建服务科技创新的专业化组织架构、管理体系以及风险评审和产品创新等机制；\n（二）做好科技创新领域金融风险防控，督导怀化市内合作银行对新产品、新业务、新模式的合规性进行审查，对知识价值贷款业务合规与风险状况进行日常监督管理；优化科技金融业务尽职免责机制；\n（三）职责范围内的其他工作事项。"},{"no":"十五","title":"第十五条","text":"怀化市科学技术事务中心为受托的市级运营管理机构，具体职责如下：\n（一）负责全市知识价值贷款工作，受理风险补偿申请，提出风险补偿建议，并按相关程序审定后上报；\n（二）为相关部门、合作银行、合作担保机构和科技型企业\n\n提供知识价值贷款风险补偿相关服务；\n（三）负责数据统计分析、业务风险预警，建立调度、监控、预警机制，协助在贷项目监控管理，督促合作银行和合作担保机构对补偿后项目依法追偿；\n（四）根据实际情况，按程序对县级风险补偿资金组成进行调整。\n（五）完成市科技局交办的其他工作。\n第三章合作银行"},{"no":"十六","title":"第十六条","text":"本办法所称的合作银行，是指自愿遵守相关规定，且与省科技厅、市人民政府签订合作协议的各商业银行。具体业务由签订合作协议的各商业银行在怀化市内设立的分支机构办理。"},{"no":"十七","title":"合作银行相关职责：","text":"合作银行相关职责：\n（一）制定和完善与风险补偿资金使用管理相关的内控制度，防范管理风险。定期对贷款的执行情况和资金的使用情况自查、自评，配合主管部门各项审计、监督、绩效评价工作。建立健全内部激励机制，加大对科技型企业的支持力度，简化贷款流程，提高贷款效率；\n（二）严格执行本办法和其他相关规定，保证贷款风险分类准确、信息完整；确保贷款企业全面准确了解知识价值贷款政策，做好相关服务工作；\n（三）将符合本办法规定的科技型企业贷款项目按程序录入知识价值贷款风险补偿管理平台，对录入信息贷款项目的真实\n\n性、完整性、合规性负责并提供承诺书，确保申请风险补偿的不良贷款项目符合本办法规定条件；\n（四）负责贷款项目的管理，及时向市、省级运营管理机构书面报送不良贷款项目情况。按规定申请补偿资金，上报已补偿不良贷款项目清收情况，妥善保管申请资料以及原始票据单证以备查验；\n（五）积极、尽责开展已补偿不良贷款项目的处置工作，收回的资金在扣除追偿费用后应按照本办法规定的补偿比例返还风险补偿资金。\n第四章合作担保机构"},{"no":"十八","title":"第十八条","text":"本办法所称的合作担保机构，是指合法开展科技担保业务、自愿遵守相关规定的政府性融资担保机构。符合条件的担保机构，由市科技局向省科技厅推荐备案，省科技厅公示确定合作担保机构名单。合作担保机构应与省科技厅和市人民政府签订合作协议。"},{"no":"十九","title":"合作担保机构相关职责：","text":"合作担保机构相关职责：\n（一）将符合本办法规定的贷款项目按程序录入知识价值贷款风险补偿管理平台，对录入信息的真实性、完整性、合规性负责，确保申请风险补偿的贷款项目符合本办法规定条件；\n（二）负责信用担保贷款项目的管理，对已代偿项目按规定申请补偿资金，上报已补偿贷款项目清收情况，妥善保管申请资料以及原始票据单证以备查验；\n（三）积极、尽责开展已补偿贷款项目的处置工作，收回的\n\n资金在扣除追偿费用后应按照本办法规定的补偿比例返还风险补偿资金。\n第五章贷款企业"},{"no":"二十一","title":"第二十一条","text":"本企业库内的其他科技型企业，是指至少具备下列条件之一的企业（具体入库指标界定及所需佐证材料见附件2）：\n1.拥有一项以上Ⅰ类知识产权（包含进入实质审查阶段的发明专利）或二项（含）以上Ⅱ类知识产权；\n2.全职员工中有1名以上博士学历（或者2名（含）以上硕士学历），或1名以上副高级及以上职称的科技人员；\n3.研发费用较上年维持正增长且会计核算健全、实行查账征收并且能够准确归集；\n4.主导或参与制（修）订过国际标准、国家标准、行业标准或地方标准。\n其他科技型企业在不低于本条规定入库条件前提下，由市科技局推荐入库，并提供相关佐证材料。"},{"no":"二十二","title":"第二十二条","text":"企业库内企业可自主选择采用信用贷款、信用担保贷款或两者组合，贷款期限不超过3年。\n国家高新技术企业和国家科技型中小企业，纳入风险补偿范围的信用贷款额度不超过1000万元，信用担保贷款额度不超过3000万元，贷款总额不超过3000万元；其他科技型企业，纳入\n\n风险补偿范围的信用贷款额度不超过300万元，信用担保贷款额度不超过1000万元，贷款总额不超过1000万元。\n超过风险补偿限额的贷款不予风险补偿，多家银行放款的按录入贷款信息时间顺序累加计算。"},{"no":"二十三","title":"第二十三条","text":"贷款企业获得的贷款必须用于本企业生产经营，不得用于转贷、委托贷款、并购贷款、国家产业政策禁止和限制的项目以及参与民间借贷、投资资本市场和个人消费等。合作银行应做好贷后管理，规范贷款企业资金用途，一经发现企业有上述不当行为的，由合作银行依照有关法律法规规定收回贷款，不享受风险补偿。一年期（含）以内贷款到期后，符合银行风控条件的企业可以向合作银行申请无还本续贷，同步纳入知识价值贷款风险补偿范畴，无还本续贷最长不超过两年。"},{"no":"二十四","title":"第二十四条","text":"获得贷款的企业应当按合同还本付息，配合合作银行开展贷后检查，及时报告重大事项变更情况，严格遵守信用，主动披露风险，其贷款合同履约情况纳入企业科研诚信记录及其主要高管人员个人征信记录。\n第六章信用贷款"},{"no":"二十五","title":"第二十五条","text":"本办法所称的信用贷款，是指合作银行以科技型企业知识价值评分结果为重要参考，向企业库内企业发放的为期三年（含）以内的无需不动产、准货币等资产抵押或第三方担保的贷款（借款人的法定代表人、股东或实控人及其配偶连带担保责任不视为第三方担保）。合作银行应主动落实减费让利政策要求，贷款利率在放款日最近一期公布的相应期限贷款\n\n市场报价利率（LPR）（以下简称“LPR”）基础上，加点幅度不超过140个基点。"},{"no":"二十六","title":"第二十六条","text":"省、市两级原则上按照不超过贷款本金损失的70%给予合作银行风险补偿，省、市两级风险补偿资金按照同比例进行补偿。"},{"no":"二十七","title":"第二十七条","text":"根据各合作银行、怀化市知识价值信用贷款业务不良率（按知识价值贷款的不良贷款余额除以在贷余额计算，风险补偿资金不冲抵不良贷款余额，以下简称“业务不良率”）\n情况，分类建立机构熔断、区域熔断机制。发生知识价值贷款业务熔断后，对于已经受理的业务，风险补偿资金继续履行风险补偿责任。当业务不良率压降至熔断线以下时，可以申请恢复新增业务。\n（一）机构熔断。若合作银行市级机构（含全市所有分支机构，下同）全市知识价值贷款业务不良率达到3%，市级运营管理机构向其发送风险预警提示，由合作银行市级机构在10个工作日内出具风险情况说明报告；若合作银行全市业务不良率达到5%以上（含），暂停该合作银行所有分支机构的新增业务（续贷业务除外）。合作银行业务不良率下降至5%以下的，可以向市、省级运营管理机构申请恢复新增业务。\n（二）区域熔断。若县市区、怀化高新区、怀化国际陆港经开区业务不良率达到10%（含），市级运营管理机构则向其发送风险预警提示（特殊情况该区域可申请下调业务不良率），该区域需出具风险说明报告，并于6个月内采取措施压降业务不良率，若6个月后业务不良率仍超过10%（含）的，市级运营管理\n\n机构将实施区域熔断，该区域将不得新增贷款（续贷业务除外）。\n对于追加风险补偿资金或业务不良率下降至10%以下的，可以向市级运营管理机构申请恢复新增业务。"},{"no":"二十八","title":"信用贷款程序如下：","text":"信用贷款程序如下：\n（一）入库企业向合作银行分支机构提交贷款申请，合作银行按照内部风控程序自主开展贷前审核，参考入库企业的知识价值评价结果，与符合条件的企业签订贷款合同。政府部门、运营管理机构除确定入库企业名单外，不以任何形式参与贷款授信事项的审核；\n（二）合作银行向库内企业发放贷款，并于发放贷款后30个工作日内在知识价值贷款风险补偿管理平台录入贷款信息（见\n附件3第一条）。未按规定录入信息的贷款项目原则上不纳入风险补偿范围。"},{"no":"二十九","title":"信用贷款风险补偿程序：","text":"信用贷款风险补偿程序：\n（一）银行申报。贷款逾期后，合作银行应积极与企业协商贷款还款方案，采取多种形式为企业生存和发展提供便利条件。\n逾期超过90天仍未全额收回的，由合作银行分支机构发起补偿申请，并将申请资料（见附件3第二条）报市级运营管理机构审核。逾期之日起12个月内合作银行未提出风险补偿申请的贷款项目，不再纳入风险补偿范围。\n（二）风险补偿实施。市级运营管理机构对合作银行分支机构申报材料完整性、是否符合本办法规定进行审核，经怀化市科技型企业知识价值贷款风险补偿工作机制商议，资料齐备的应在45个工作日内出具申请函（见附件4）及合作银行申报材料函告\n\n省级运营管理机构，材料不符的需书面反馈合作银行。市级运营管理机构在收到同意实施省级风险补偿的意见后，应督促有关县市区（怀化高新区、怀化国际陆港经开区）及时将应承担的风险补偿资金划拨至合作银行指定账号或办理相关经费拨付手续，并将资金划拨凭证或经费拨付手续相关材料寄送市级运营管理机构，超出县级风险补偿资金限额的，从市本级风险补偿资金中划拨至合作银行指定账号。足额补偿后，市级运营管理机构应将相关凭证寄送至省级运营管理机构。\n（三）银行追偿。合作银行收到风险补偿资金后，应积极开展已补偿贷款项目的追偿工作，每半年书面报告追偿工作情况，原则上于6个月内向市、省两级运营管理机构提交诉讼判决书、仲裁裁决书或其他有权机关出具的相关文书。如合作银行收到追偿所得，应在收到之日起45个工作日内，将扣除追偿费用后的剩余部分按原约定的风险分担比例返还，政府所得部分继续用于补充风险补偿资金。\n第七章信用担保贷款"},{"no":"三十","title":"第三十条","text":"本办法所称的信用担保贷款，是指合作担保机构为企业库内企业提供无抵（质）押反担保要求的信用担保服务，通过银行发放的贷款。"},{"no":"三十一","title":"第三十一条","text":"信用担保贷款利率在LPR基础上加点幅度不超过90个基点，担保费率原则上不超过0.5%/年，单笔期限不超过3年。"},{"no":"三十二","title":"银行按不低于贷款金额的30%、合作担保机构","text":"银行按不低于贷款金额的30%、合作担保机构\n\n按不高于贷款金额的70%分担风险责任。合作担保机构应分担部分，除纳入再担保备案按既定比例分险外，根据《关于实施支持科技创新专项担保计划的通知》（财金〔2024〕60号）、《关于实施科技创新担保计划的通知》（国融担函〔2024〕184号）\n对不同类型企业设置差异化风险分担比例的精神，省级和怀化市分别按照不超过逾期未清偿本金余额的5%给予合作担保机构风险补偿，风险补偿比例可根据国家、省相关政策相应调整。\n对科技型企业中的专精特新“小巨人”、专精特新中小企业、承担国家科技项目的中小企业，省级和怀化市不予风险补偿；对高新技术企业、国家依托“创新积分制”筛选出的科技型中小企业，省级和怀化市分别按照逾期未清偿本金余额的2%给予合作担保机构风险补偿；对科技型中小企业和本办法规定的其他科技型企业，省级和怀化市分别按照逾期未清偿本金余额的5%给予合作担保机构风险补偿。企业有多重资质的，按照《关于实施支持科技创新专项担保计划的通知》（财金〔2024〕60号）、《关于实施科技创新担保计划的通知》（国融担函〔2024〕184号）\n规定最高风险分担比例对应的企业类型，确定省级和怀化市承担的风险补偿比例。\n若信用担保贷款代偿余额（风险补偿资金不冲抵信用担保贷款代偿金额）超过信用担保贷款担保余额的10%（含）后，将暂停合作担保机构的信用担保贷款风险补偿业务。待前述比例降至10%以内，恢复办理风险补偿业务。"},{"no":"三十三","title":"信用担保贷款程序如下：","text":"信用担保贷款程序如下：\n（一）符合条件的科技型企业向银行及合作担保机构提出申\n\n请，银行参考入库企业的知识价值评价结果按规定发放贷款；\n（二）合作担保机构于发放贷款后45个工作日内在知识价值贷款风险补偿管理平台录入贷款信息（见附件3第三条）。未按规定录入信息的贷款项目原则上不纳入风险补偿范围。"},{"no":"三十四","title":"信用担保贷款风险补偿程序：","text":"信用担保贷款风险补偿程序：\n（一）担保机构申报。信用担保贷款发生风险，合作担保机构完成代偿后，由合作担保机构发起补偿申请，并将申请资料报市、省两级运营管理机构审核（见附件3第四条），原则上每年可申请两次；\n（二）风险补偿实施。市、省两级运营管理机构分别对合作担保机构申报材料完整性、以及是否符合本办法规定进行审核，资料齐备的应在45个工作日内经相关程序审定并出具独立的审核意见，反馈给合作担保机构，同意实施风险补偿的，应在出具审核意见后10个工作日内将各自应承担的风险补偿资金划拨至合作担保机构指定账号或办理相关经费拨付手续。\n（三）担保机构追偿。合作担保机构收到风险补偿资金后，应积极开展已补偿贷款项目的追偿工作，每半年书面报告追偿工作情况。如合作担保机构收到追偿所得，应在收到之日起45个工作日内，将扣除追偿费用后的剩余部分按原约定的风险分担比例返还，政府所得部分继续用于补充风险补偿资金。\n第八章监督管理"},{"no":"三十五","title":"第三十五条","text":"对同一企业的同一笔贷款，合作银行如已获得其他类别的风险补偿，不得再次申请本办法规定的风险补偿；合\n\n作担保机构申请本办法规定的风险补偿，除叠加省财政风险补偿外不得重复申请其他类别省级风险补偿，严禁政策套利。一经查实，收回风险补偿资金，取消合作资格。"},{"no":"三十六","title":"第三十六条","text":"合作银行、合作担保机构以及实施知识价值贷款工作的相关部门应建立尽职合规免责制度，并按规定向相关监管机构报告。对于已履职尽责的，合作银行、合作担保机构及相关部门可按照尽职合规免责有关规定免除相关工作人员全部或部分责任。"},{"no":"三十七","title":"第三十七条","text":"市科技局对合作银行、合作担保机构总体运作情况进行评价，将评价结果上报省科技厅、市人民政府，并提出评价结果使用建议。"},{"no":"三十八","title":"第三十八条","text":"对于因工作失职、失误导致风险补偿资金遭受损失的合作银行、合作担保机构，市科技局将向省科技厅、市人民政府建议，取消其下一年度参与知识价值贷款风险补偿相关合作。对于骗取、套取风险补偿资金的行为，一经查实，将收回已安排的风险补偿资金，并按照《财政违法行为处罚处分条例》（国务院令第588号）的相关规定进行处理，情节严重的，移交司法机关处理。\n第九章附则"},{"no":"三十九","title":"第三十九条","text":"风险补偿不改变合作银行、合作担保机构与借款人的债权债务关系，借款人仍按贷款合同和担保法律文件约定承担全部责任。"},{"no":"四十","title":"本办法自发布之日起实施，有效期5年","text":"本办法自发布之日起实施，有效期5年。在本办\n\n法到期后尚未到期的存量贷款，风险补偿资金继续履行风险补偿责任。2025年4月12日至本办法实施之日期间受理的知识价值信用贷款，其风险补偿按《怀化市科技型企业知识价值信用贷款风险补偿实施办法》（怀科发〔2023〕15号）规定执行。"},{"no":"四十一","title":"本办法由市科技局负责解释","text":"本办法由市科技局负责解释。\n\n附件1湖南省科技型企业知识价值贷款评价指标体系一级指标二级指标指标解释技术创新指标（7项)\n1.1研发费用金额（万元）\n研发费用支出主要包括研发活动的人工费用、直接投入费用、用于研发活动的仪器、设备的折旧费、用于研发活动的软件、专利权、非专利技术的摊销费用、新产品设计费、新工艺规程制定费以及其他研发活动相关费用\n1.2研发费用增速（%）\n填报期内企业研发投入增加额占上年研发投入总额的比例\n1.3研发费用占营业收入的比例（%）\n填报期内企业研发投入总额占营业收入总额的比例\n1.4科技人员占职工总数的比重（%）\n填报期内企业参加科技项目活动的人员总数，占企业从业人员期末人数的比例\n1.5与主营业务相关的发明专利申请量（件）\n填报期内企业作为第一申请人向境内外知识产权行政部门提出的与主责主业相关的发明专利申请并被受理后，按规定缴足申请费，符合进入初步审查阶段条件的件数\n1.6与主营业务相关的PCT专利申请量（件）\n填报期内企业作为第一申请人提出的与主责主业相关的PCT国际专利申请数量\n1.7企业技术合同成交额（万元）\n填报期内企业吸纳和输出的技术合同成交总额（开发合作、转让合同）\n成长经营指标（6项）\n2.1高新技术产品收入（万元）\n填报期内企业生产的符合国家和省高新技术重点范围、技术领域和产品参考目录的全新型产品；或省内首次生产的换代型产品；或国内首次生产的改进型产品；或属创新产品等；具有较高的技术含量和较高的附加值的产品所形成的销售收入\n2.2营业收入（万元）\n填报期内企业从事主营业务或其他业务所取得的收入总额\n2.3营业收入增长率（%）\n填报期内企业营业收入增加额对上年营业收入总额的比率\n\n一级指标二级指标指标解释\n2.4研究生以上人员占比（%）\n填报期内企业最高一级教育为研究生教育并取得毕业证书或获得硕士、博士学位证书的人员总数（不包括肄业、结业、在读或辍学人员），占企业从业人员期末人数的比例\n2.5研发费用加计扣除金额（万元）\n研发费用加计扣除金额是指企业在开展研发活动中实际发生的费用，在按规定据实扣除的基础上，可额外按一定比例在税前加计扣除的金额\n2.6净资产利润率（%）\n填报期内企业净利润÷（期初所有者权益+期末所有者权益）÷2×100%辅助指标（5项）\n3.1吸纳应届毕业生人数（人）\n填报期内企业在境内各类高校毕业生中招收的应届毕业生数（包含国家承认的大专学历学生）\n3.2承担建设省级及以上研发或创新平台数量（项）\n企业近两年获批的省级及以上重点实验室等\n3.3获得省级及以上科技奖励数量（项）\n企业近两年作为第一单位获得的省级及以上科技奖励数量\n3.4承担省级及以上科技计划项目数量（项）\n企业近两年作为牵头单位承担的省级及以上科技计划项目数量（国家级科技计划项目可为项目或课题）\n3.5获得风险投资金额（万元）\n填报期内企业获得创投机构、风险投资机构的投资额区域特色指标根据区域科技创新特色设置若干指标按相关文件设置\n\n附件2纳入知识价值贷款企业库指标界定及佐证材料清单\n一、入库指标界定\n1.自主知识产权包括：（1）Ⅰ类知识产权：发明专利（包含进入实质审查阶段的发明专利）、植物新品种、国家级农作物品种、国家新药、国家一级中药保护品种、集成电路布图设计专有权；（2）Ⅱ类知识产权：仅指实用新型专利和软件著作权；\n2.研发费用是指企业研发活动中发生的相关费用，且按照《财政部国家税务总局科技部关于完善研究开发费用税前加计扣除政策的通知》（财税〔2015〕119号）等相关文件规定进行归集。\n二、所需提供的相关佐证材料\n1.企业营业执照扫描件（必须提供）；\n2.申请日前三天内的企业信用信息报告（通过省“一网通办”\n系统、湘易办APP、“信用中国（湖南）”查询下载）（必须提供）；\n3.自主知识产权证书扫描件；进入实质审查阶段的发明专利须提供通知书扫描件（根据选择的入库条件提供）；\n4.学历、学位证书或职称证书扫描件及社保缴纳凭证（根据选择的入库条件提供）；\n5.《研发费用加计扣除优惠明细表》（A107012表）或由第三方机构出具并能体现研发费用情况的财务报告（根据选择的入库条件提供）；\n6.国际标准、国家标准、行业标准或地方标准扫描件（根据选择的入库条件提供）。\n\n附件3贷款录入及风险补偿需提供佐证材料清单\n一、信用贷款录入已发放贷款企业的贷款金额、贷款利率、期限及借据号等信息，上传贷款合同、借据（线上贷款可提供相关系统截图）等相关资料。\n二、信用贷款风险补偿①补偿申请表（附件3-1）②贷款凭证（含贷款合同、放贷凭证，线上贷款可提供相关系统截图）③银行催收依据（含贷款逾期记录和催收通知书、人民法院受理通知或公安机关立案决定或仲裁机构受理回执等法律文书）④承诺函（附件3-2）。\n三、信用担保贷款录入已发放贷款企业的贷款金额、贷款利率、担保费率、主债权期限等信息，上传贷款合同、银行保证合同、委托担保协议或委托担保函等相关资料。\n四、信用担保贷款风险补偿①补偿申请表（附件3-3）②贷款合同③银行保证合同④委托担保协议或委托担保函⑤代偿通知书⑥代偿证明⑦代偿流水。\n\n附件3-1湖南省科技型企业知识价值贷款风险补偿资金申请表（合作银行）编号：\n一、申请合作银行：（盖章）\n收款行名称联系人及方式收款账户、账号申报日期年月日符合条件的信用贷款本金损失共计万元申请补偿金额万元（其中省级、实施区域各万元）\n相关情况说明及佐证材料\n一、贷款基本情况（说明企业和贷款基本情况、录入情况）\n二、风险贷款情况（说明风险贷款形成原因、认定情况、已采取的追偿措施、损失认定等）\n三、贷款追偿情况（介绍目前追偿工作进展，并承诺在获得省、市两级风险补偿后，将继续对贷款损失部分进行追偿并按规定返还）\n（可另附附件）\n二、知识价值贷款信息企业名称联系方式统一社会信用代码所在地录入流水号借款合同编号贷款起止日期利率贷款本金（万元）用途注：一式４份；省科技厅、市科技局，省（市）运营管理机构各1份。\n\n附件3-2承诺函我行已了解湖南省科技型企业知识价值贷款风险补偿相关政策、规定及有关要求，对申请***企业的知识价值贷款（贷款录入编号**）风险补偿作出如下承诺：\n1.在贷后管理过程中，已如实向实施区域与运营管理机构进行了风险告知；\n2.该笔贷款符合监管要求，并未申报其他省级风险补偿资金；\n3.该笔贷款用于贷款合同所述用途，未发生转贷、委托贷款、并购贷款、国家产业政策禁止和限制的项目以及参与民间借贷、投资资本市场和个人消费等；\n4.所提交的材料填写内容和数据真实、准确。\n若违反上述承诺，愿意承担由此带来的一切后果及相关法律责任。\n承诺人: \t**银行盖章年月日\n\n附件3-3湖南省科技型企业知识价值贷款风险补偿资金申请表（合作担保机构）\n编号：\n一、申请合作担保机构：\n收款行名称联系人及方式收款账户、账号申报日期年月日符合条件的信用担保贷款逾期未清偿本金余额共计万元申请补偿金额万元（其中省级、实施区域各万元）\n二、贷款企业信息企业名称联系方式统一社会信用代码所在地企业类型风险补偿比例\n三、知识价值信用担保贷款信息贷款银行名称银担风险分担比例录入流水号贷款合同编号委托担保协议编号保证合同编号贷款本金（万元）贷款起止日期贷款利率担保费率我司承诺该笔担保业务符合监管要求，提供的所有资料和信息真实、完整、准确。如申请项目存在违背《湖南省科技型企业知识价值贷款风险补偿实施办法》（湘科发〔2025〕72号）及相关协议的情形，我司将返还风险补偿资金，并承担由此带来的一切后果及相关法律责任。\n申请合作担保机构公章：\n年月日\n\n附件4关于申请湖南省科技型企业知识价值贷款风险补偿的函（参考样稿）\n省级运营管理机构：\n年月日，我单位收到银行提交的关于（企业名称）知识价值贷款的风险补偿资金申请材料，涉及贷款本金损失（万元）。依据《湖南省科技型企业知识价值贷款风险补偿实施办法》（湘科发〔2025〕72号）等文件规定，经调查核实等相关程序，我单位同意对该笔贷款进行风险补偿，补偿金额万元。现申请对该笔贷款进行省级风险补偿，补偿金额万元，并复函予以明确。\n（需以附件说明调查核实情况并加盖公章）\n**市级运营管理机构盖章年月日怀化市科学技术局办公室2025年11月26日印发"}],"interpretations":[],"sourceUrl":"https://www.huaihua.gov.cn/kjj/c132709/202511/c9a956f1301b49b68853a5f57a87483c/files/f28651ab2a52486eafb62085f25586ed.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-09 条文按官方原文重切（40 条，自查召回 100%）","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-85cf55","title":"永州市人民政府关于印发《永州市推动先进制造业高质量发展若干措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府","documentNo":"永政发〔2025〕2号","publishedAt":"2025-03-10","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业"],"summary":"永州对新认定国家级专精特新\"小巨人\"、国家级制造业单项冠军奖励50万元；省级专精特新中小企业、省级制造业单项冠军奖励20万元；新入统规模以上工业企业奖励不低于5万元。","sections":[{"no":"一","title":"明确工作目标","text":"到2027年，打造区域先进制造业高地取得重大进展。加快打造食品加工、智能家居、现代农业、文化旅游、新能源、数字产业等6个千亿级产业；推动约500家企业扩能升级。力争制造业增加值占地区生产总值比重提高到25%以上，数字经济核心产业增加值占地区生产总值比重提高到10%以上。高新技术制造业增加值占制造业增加值比重达20%以上，规模以上工业企业高端化智能化绿色化改造率达50%以上。"},{"no":"二","title":"优化区域布局","text":"（一）改造提升传统产业。大力推动食品加工、智能家居（家电）等传统产业提质增效、转型升级，着力培育消费品工业“三品”标杆企业。绿色食品产业，用活用足用好省农业农村厅、省发展改革委等四部门联合印发的《支持永州蔬菜出口高质量发展的若干政策措施》（湘农联〔2024〕38号），支持永州陆港熙可全球食品保鲜加工中心、永州首衡国际农产品交易中心建设，推进农产品精深加工和综合利用；支持道县、新田、江永、江华等县区依托本地资源优势，重点打造粤港澳大湾区“菜篮子”功能区，加快推进传统优势食品产区和地方特色食品产业发展。智能家居（家电）产业，支持新田、蓝山、双牌、东安等县区优化资源培育，大力推进“以竹代塑”“以竹代木”行动，着力打造农林产品加工产业集聚区。支持冷水滩、新田、江华等县区以智能家居（家电）、绿色板材及配套产业为重点，开展产品展览、供需对接等产业生态活动。〔市工信局、市商务局、市农业农村局、市林业局，各县市区人民政府（含管理区、永州经开区，下同）按职责分工负责，以下各项措施均需各县市区人民政府落实，不再列出〕\n（二）培育壮大新兴产业。抢抓国家“两重”“两新”重大机遇，加快培育壮大新能源新材料、数字产业等新兴产业。新能源新材料产业，深入推进新能源产业链上下游融合，以资源换产业，引进一批风光绿色装备制造项目，加快双牌天子山、江华湾水源抽水蓄能等绿能重点项目建设。推进道县锂多金属矿采选冶一体化深度开发应用，加快紫金锂业锂矿采选项目、6万吨碳酸锂冶炼项目建设，将道县建成中国重要的锂电新能源产业基地；加快湖南稀土新材料产业园、江华离子型稀土基地、零陵绿色锰系新材料产业园建设，将永州打造成全国重要的独居石综合利用基地、全国领先的锰系新材料产业基地和产品供应中心。数字产业，加快推进5G基础设施建设，布局和建设一批高性能算力中心，大力发展大数据、人工智能、移动互联网、云计算等绿色计算产业。加快新一代信息技术集成创新和融合应用，推动产品高端化、轻量化和全产业链发展，纵深推进“智赋万企”行动，打造更多应用场景。〔市工信局、市数据局（行政审批服务局）、市商务局按职责分工负责〕"},{"no":"三","title":"加快技术改造","text":"（三）支持企业设备更新。抢抓政策机遇，引导企业开展工业领域大规模设备更新。每年支持120家左右工业企业开展技术改造和设备更新，到2027年，推动约500家工业企业就地扩能提质增效。对当年在建且通过湖南省制造强省项目库系统入库的设备更新和技术改造项目，总投资达到500万元以上的，择优向工业和信息化部、省工业和信息化厅推荐争取技术改造再贷款和贴息等政策支持；更新设备投资达到100万元及以上的，对项目一年期（含）以上设备购置贷款，由受益财政按贷款本金的1%给予贴息，贴息期限1年。单个项目贴息1次，最高不超过50万元，单个企业每年最多贴息2个项目。（市工信局、市发改委、市财政局按职责分工负责）\n（四）支持企业数智改造。重点打造一批省级及以上标杆示范企业，推动更多企业实现“智改数转”互联。到2027年，力争推动“上云”企业15000家以上、“上平台”企业1200家以上，新增40家以上企业通过国家两化融合管理体系贯标评定。培育一批数字化转型服务商，对开展两化融合、网络安全分类分级等各类数字化转型服务的服务商，当年完成服务企业20家、40家、60家以上的，由受益财政分别给予5万元、10万元、15万元一次性奖励。对当年新增的两化融合管理体系贯标企业、数字化转型贯标企业、“5G+工业互联网”标杆工厂、工业互联网平台、省100个标志性新基建项目、省级数字化转型标杆项目、省级人工智能赋能新型工业化典型应用场景，由受益财政奖励20万元/个。对被工业和信息化部当年新认定的卓越级智能工厂的企业，由受益财政奖励50万元/个；对当年新认定的省级智能制造标杆企业、车间，由受益财政分别奖励20万元/个、10万元/个。对成功入选“湖南省智能制造系统解决方案供应商推荐目录”的企业，由受益财政奖励10万元/个。〔市工信局、市财政局、市数据局（行政审批服务局）按职责分工负责〕\n（五）支持企业技术创新。持续推进规模以上工业企业创新研发活动全覆盖工作，支持企业开展新技术、新产品、新工艺研发应用。对当年新认定的国家级、省级工业设计中心，由受益财政分别奖励20万元、10万元。鼓励企业争取“五首”产品认定（首台套技术装备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件），对当年新认定国家级、省级“五首”产品的企业，由受益财政分别奖励50万元、20万元。对被工业和信息化部当年新认定为国家技术创新示范企业的工业企业，由受益财政给予20万元一次性奖励。对当年新认定为国家级、省级中试基地（平台）的工业企业，由受益财政分别给予50万元、10万元一次性奖励。（市工信局、市科技局、市财政局按职责分工负责）\n（六）支持企业低碳转型。聚焦冶金、建材、纺织等重点领域，加快传统产业转型升级，积极稳妥推进工业领域碳减排。鼓励企业开展协同降碳行动，探索减污降碳协同增效有效模式，推动低碳协同示范和数字化绿色化协同转型。围绕重点行业和领域，培育绿色工厂、绿色园区，严控污染排放，加速循环化改造，积极争取创建零碳工业园区、国家级绿色工业园区，力争每年打造1—2家省级绿色园区、创建5家省级以上绿色工厂，对评为国家级、省级绿色工厂的企业，由受益财政分别给予100万元、50万元一次性奖励。加快园区内企业实施系统性清洁生产改造，鼓励工业企业开展自愿性清洁生产审核，对通过省工业和信息化厅自愿性清洁生产审核验收的工业企业，由受益财政给予3万元一次性奖励。（市工信局、市财政局按职责分工负责）\n（七）支持企业品牌提升。推动企业建立新型质量管理体系和品牌培育管理体系，鼓励企业参与标准制定，持续培育制造业质量标杆企业，遴选推荐一批典型案例，提高企业产品质量和品牌价值。对当年新认定的国家级、省级制造业质量标杆企业，由受益财政分别给予50万元、10万元一次性奖励；对当年新认定的湖南省原材料、消费品工业“三品”标杆企业，由受益财政给予5万元奖励。（市市场监管局、市工信局、市财政局按职责分工负责）\n（八）支持企业融通发展。落实大中小企业融通创新“携手行动”，全力培育单项冠军等优质企业，支持中小微企业走专精特新发展之路。到2027年，培育国家级专精特新“小巨人”企业18家以上、省级专精特新中小企业400家以上，国家级制造业单项冠军企业5家以上、省级制造业单项冠军企业20家以上。对当年新认定的国家级专精特新“小巨人”企业、国家级制造业单项冠军企业，由市本级财政奖励50万元；对当年新认定的省级专精特新中小企业、省级制造业单项冠军企业一次性奖励20万元，其中中心城区（冷水滩区、零陵区、永州经开区）企业的奖励资金由市、区两级财政各承担50%，其他县（市）企业的奖励资金由受益县（市）财政承担，奖励标准不低于20万元。对当年通过复核的国家级专精特新“小巨人”企业，由市本级财政奖励5万元；对当年通过复核的省级专精特新中小企业，由受益县市区财政奖励1万元。持续开展新增规模以上工业企业行动，每年新增规模以上工业企业100家以上，由受益财政安排规模以上工业企业培育专项资金，对当年新入统规模以上工业企业，给予不低于5万元的一次性奖励。（市工信局、市财政局按职责分工负责）"},{"no":"四","title":"强化要素保障","text":"（九）加大政策要素保障。市本级财政每年预算安排3000万元先进制造业专项资金支持新型工业化发展。引导银行机构聚焦小微企业融资需求，合理确定信贷投放节奏，力争中小企业综合融资成本稳中有降。对重点项目、重点企业，在用工、用地、用林、用能、用气上给予重点支持，进一步优化营商环境，依法平等保护企业合法权益。〔市财政局、市工信局、市人社局、市自然资源和规划局、市林业局、市城管局、市数据局（行政审批服务局）、中国人民银行永州市分行按职责分工负责〕\n（十）支持开展表扬激励。对扩能升级效果明显的重点存量工业企业，优先推荐申报“湖南省民营企业100强”“新湖南贡献奖”“全国优秀企业家”“湖南省优秀企业家”“大国工匠”“劳动模范”等国家级、省级先进集体和个人。加大宣传力度，营造尊重和弘扬企业家精神的良好社会氛围。（市委统战部、市发改委、市工信局、市工商联、市总工会按职责分工负责）\n本文件自公布之日起施行，有效期至2027年12月31日。奖励事项涉及同类奖补政策的，按就高标准执行，对已获得上级奖补资金的同一事项，市县财政不重复奖励。我市已有的政策与本政策规定不一致的，以本政策为准。政策执行过程中，若法律法规和上级政策另有规定的，从其规定。年度内发生较大及以上生产安全事故、环境污染事故及其他重大违法违规行为的企业不予享受政策支持。本文件的具体解释工作由市工信局承担。"}],"interpretations":[],"sourceUrl":"https://zt.yzcity.gov.cn/cnyz/szfwj/202503/1846bc5bdb19429e908c66220dee6359.shtml","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-a301d3","title":"湘潭市一次性创业补贴和创业经营场所租金补贴办法","level":"city","region":"湘潭市","issuer":"湘潭市人力资源和社会保障局、湘潭市财政局","documentNo":"","publishedAt":"2025-06-04","status":"active","tags":["创业补贴","场地支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"湘潭市首次创办小微企业或个体经营正常运营1年以上并吸纳就业的，一次性创业补贴3000-15000元；大学生创业还可享经营场所租金补贴第一年每月800元、第二年每月600元。","sections":[{"no":"一","title":"一次性创业补贴申报条件及标准","text":"(一)申报条件\n申报一次性创业补贴(含大学生一次性创业补贴),需同时具备以下条件:\n1.在我市范围内首次登记注册的初创企业,登记注册时间在5年以内(以首次营业执照登记的成立日期为准,2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间,以此类推)。\n2.申报一次性创业补贴需正常运营1年以上,吸纳2名以上(含2名)城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态。其中,申报大学生一次性创业补贴需正常运营1年以上,吸纳1名以上城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态。\n3.符合湘潭市产业发展方向。\n4.近两年在信用中国(湖南湘潭)无行政处罚等违法记录,无知识产权或其他经济、法律纠纷。\n5.申报一次性创业补贴的企业法定代表人需属于就业困难人员或返乡入乡农民工。其中,申报大学生一次性创业补贴的企业法定代表人需属于毕业2年内的普通高校、职业学校、技工院校学生和留学归国人员。法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的,不纳入补贴范围。\n(二)补贴标准\n根据吸纳城乡劳动者就业人数情况,一次性创业补贴标准为3000元至15000元不等。吸纳城乡劳动者就业人数取近6个月缴纳城镇职工社会保险人数,吸纳2人(含2人)就业的补贴3000元,吸纳2人以上就业的每增加1人给予1000元补贴,最高不超过15000元。\n其中,大学生一次性创业补贴标准为10000元、12000元或15000元不等。吸纳城乡劳动者就业人数取近3个月缴纳城镇职工社会保险人数,吸纳1-5人(含5人)就业的,补贴12000元;吸纳5人以上就业的,补贴15000元。对于我市认定的高校类大学生创业孵化基地内的大学生创业主体,正常运营1年以上的,经专家评审认定,可放宽缴纳城镇职工社会保险费条件,补贴10000元。\n已经享受过市财政同一项目补贴的,不能重复享受。\n(三)所需资料\n1.《湘潭市一次性创业补贴(含大学生一次性创业补贴)申请表》(附件1)。\n2.营业执照或其他登记注册证明,法定代表人身份证,公司股权分配证明资料。\n3.法定代表人相关证明材料。返乡入乡农民工需提供湘潭市行政区域范围内户籍地乡镇(街道)人力资源社会保障服务站出具的返乡入乡创业佐证资料;毕业生需提供毕业证;留学归国人员需提供经教育部门认证的佐证资料。\n就业困难人员无需提供佐证资料,由市县人社部门在信息系统中核实。\n4.申报一次性创业补贴需提供近6个月的城镇职工社会保险费缴纳证明。其中,申报大学生一次性创业补贴需提供近3个月的城镇职工社会保险费缴纳证明(对于我市认定的高校类大学生创业孵化基地内的大学生创业主体,可不提供城镇职工社会保险费缴纳证明,但需提供正常经营相关交易证明材料)。\n5.其他佐证资料。"},{"no":"二","title":"第二条","text":"创业经营场所租金补贴申报条件及标准(仅限大学生群体创业)\n(一)申报条件\n申报创业经营场所租金补贴,需同时具备以下条件:\n1.在我市范围内首次登记注册的初创企业,登记注册时间在5年以内(以首次营业执照登记的成立日期为准,2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间,以此类推)。\n2.正常运营1年以上,吸纳1名以上城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态。\n3.符合湘潭市产业发展方向。\n4.近两年在信用中国(湖南湘潭)无行政处罚等违法记录,无知识产权或其他经济、法律纠纷。\n5.法定代表人属于毕业2年内的普通高校、职业学校、技工院校学生和留学归国人员,法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的,不纳入补贴范围。\n使用自有房产创业及各创业孵化基地内享受免费入驻的企业,不纳入创业经营场所租金补贴范围。\n(二)补贴标准\n第一年每月800元、第二年每月600元。补贴期限自营业执照成立日期的次月至补贴有效期内,连续计算两年。实际租金低于补贴标准的,按实际租赁合同约定的租金额度给予补贴。同一初创企业最多申请两次、累计不超过2年的经营场所租金补贴。申报企业有多处经营场所的,只能就一处经营场所提出申请。已经享受过市财政同一项目补贴的,不能重复享受。\n(三)所需资料\n1.《湘潭市创业经营场所租金补贴申请表》(附件2).\n2.营业执照或其他登记注册证明,法定代表人身份证,公司股权分配证明资料。\n3.法定代表人属于大学生群体的相关证明材料。毕业生需提供毕业证;留学归国人员需提供经教育部门认证的佐证资料。\n4.近3个月的城镇职工社会保险费缴纳证明。\n5.房产证明(如无房产证则提供商品房销售合同)、租赁合同、缴纳租金的发票和转账记录(注明租赁起止时间段)等。\n6.其他佐证资料。"},{"no":"三","title":"申报流程","text":"(一)自主申报。符合条件的创业主体按工商注册(或登记机关)属地管理原则,向所在的市、县市区人力资源和社会保障局申报。\n(二)考察审核。人社部门受理申请后,在每季度末月进行审核,核定申报企业吸纳就业人数及补贴金额,并做好实地考察工作。\n(三)网上公示。考察审核完成后确定的补贴企业名单,应在同级人力资源和社会保障局官网上进行公示,公示期为5个工作日。公示期间无异议,或者有异议但经调查不成立的,由同级人力资源和社会保障局行文公布。\n(四)资金拨付。受补贴名单公布后,由人社部门汇总补贴对象信息报送至同级财政部门,按照相关规定将补贴资金拨付至申报企业账户,并在\"湖南人社一体化业务管理系统\"内录入补贴信息。"},{"no":"四","title":"补贴终止","text":"出现以下情形之一的,终止享受补贴:\n1.申报审核期间,初创企业实体处于停业状态,或已注销、吊销营业执照的。\n2.经核实有其他不符合补贴发放政策相关条件的。"},{"no":"五","title":"工作要求","text":"(一)加强宣传推荐。市县人社部门要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向,代表先进生产力、生产方式的创新创业带动就业的先进典型。\n(二)严格审核把关。市县人社部门要严格按照文件要求,严格审核、认真把关,确保真实性。财政部门要加强资金监管,充分提高资金使用效率。\n(三)严肃工作纪律。市县人社部门要优化服务,提供便捷申报受理渠道。申报企业或个人应对申报资料的真实性负责。对有违规申报、弄虚作假、骗取套取等行为的申报企业和个人,一经核实,取消申报资格,情节严重的纳入诚信黑名单,不再享受湘潭市政府各类财政支持,并依法依规作出处理和追究相关单位和个人责任。"},{"no":"六","title":"相关说明","text":"(一)\"初创企业\"类型包括小微企业和个体工商户。\n(二)普通高校是指国家教育行政部门批准或备案的实施高等学历教育为主的高等学校,包括全日制大学、独立学院、职业技术学院、高等专科学校。按照湘教通〔2020〕66号文件精神,非全日制研究生享受与全日制研究生同等的创业扶持政策。\n(三)一次性创业补贴(含大学生一次性创业补贴)资金从各级就业补助资金中列支;创业经营场所租金补贴从各级财政配套的就业补助资金中列支。\n(四)其他未尽事宜,由市人力资源和社会保障局、市财政局负责解释。\n(五)本办法自发布之日起施行,有效期不超过3年。"}],"interpretations":[{"sectionNo":"一","headline":"首次创业满1年可申补贴，个体补3000元起、最高1.5万元","who":"在湘潭市范围内首次登记注册、注册时间5年以内的初创企业；正常运营1年以上并吸纳2名以上城乡劳动者就业、缴纳城镇职工社保6个月以上；法定代表人须为就业困难人员或返乡入乡农民工，持股不低于30%。申报大学生补贴的，法定代表人须为毕业2年内的高校/职业/技工院校学生或留学归国人员。","materials":[],"window":"正常运营1年以上、社保连续缴纳6个月以上（大学生为3个月）方可申报。","where":"工商注册（登记）所在地的市、县市区人力资源和社会保障局。","tip":"吸纳人数按近6个月缴纳城镇职工社会保险的人数计算；法定代表人近两年才变更为符合条件群体的，不纳入补贴范围。","evidence":{"headline":["一次性创业补贴标准为3000元至15000元不等"],"who":["需正常运营1年以上,吸纳2名以上(含2名)城乡劳动者就业","缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态"],"window":["正常运营1年以上"],"where":["向所在的市、县市区人力资源和社会保障局申报"],"tip":["法定代表人持股比例不低于公司总股份的30%","吸纳城乡劳动者就业人数取近6个月缴纳城镇职工社会保险人数"]}},{"sectionNo":"二","headline":"大学生创业租金补贴：第一年每月800元、第二年每月600元","who":"仅限大学生群体创业：首次登记注册5年内的初创企业，正常运营1年以上、吸纳1名以上劳动者就业并缴社保3个月以上，法定代表人须为毕业2年内的高校/职业/技工院校学生或留学归国人员。","materials":["《湘潭市创业经营场所租金补贴申请表》（附件2）","营业执照或其他登记注册证明、法定代表人身份证","公司股权分配证明资料","法定代表人属于大学生群体的证明材料（毕业证等）"],"window":"自营业执照成立日期的次月起连续计算，最长2年；同一企业最多申请两次。","where":"市、县市区人力资源和社会保障局。","tip":"用自有房产创业的、以及孵化基地内免费入驻的企业，不纳入租金补贴范围；多处经营场所只能选一处申报。","evidence":{"headline":["第一年每月800元、第二年每月600元"],"who":["创业经营场所租金补贴申报条件及标准(仅限大学生群体创业)"],"materials":["《湘潭市创业经营场所租金补贴申请表》","公司股权分配证明资料"],"window":["同一初创企业最多申请两次、累计不超过2年的经营场所租金补贴"],"where":["向所在的市、县市区人力资源和社会保障局申报"],"tip":["使用自有房产创业及各创业孵化基地内享受免费入驻的企业,不纳入创业经营场所租金补贴范围","只能就一处经营场所提出申请"]}}],"sourceUrl":"http://www.xiangtan.gov.cn/jc2021/xtsjczwgk/uploadfiles/202509/2025090516413958809.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-a3f757","title":"娄底市人民政府办公室关于印发《娄底市支持\"三电\"产业高质量发展若干措施》的通知","level":"city","region":"娄底市","issuer":"娄底市人民政府办公室","documentNo":"娄政办发〔2025〕9号","publishedAt":"2025-09-02","status":"active","tags":["场地支持","融资支持"],"audience":["小微企业"],"summary":"娄底支持\"三电\"（电机、变压器、家电）产业发展，建立梯度培育库，优化用地政策，加强金融服务和人才引育配套。","sections":[{"no":"一","title":"发展产业集群","text":"发展产业集群。坚持需求牵引,发挥龙头企业引领带动作用,以硅钢和“三电”产业链吸引新能源汽车、智能装备制造、工业机器人等终端应用企业。支持境内外“三电”产业链上下游企业和投融资企业通过绿地投资、股权债权投资、实物投资、无形资产投资、收购并购等方式来娄开展合作。(责任单位:市工信局、市商务局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"二","title":"梯度培育优质企业","text":"梯度培育优质企业。建立“三电”企业梯度培育库,深化服务,分阶段、分目标、分类别实行梯度式培育,推动形成“三电”及其配套中小企业协同发展新格局。发展壮大龙头企业,推动龙头企业参与行业标准制定,鼓励多元化与国际化布局,提升龙头企业品牌影响力。培育创新骨干企业,加快培育一批产品层次高、市场影响力大、具备先发优势的标志性创新型骨干企业。培育高成长性中小微企业,持续开展新增规模工业企业行动,深入实施“科技小巨人”培育计划,培育一批主营业务突出、竞争力强、成长性好的高水平中小微企业。(责任单位:市工信局、市科技局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"三","title":"优化用地政策","text":"优化用地政策。针对“三电”产业特点实施差异化供地策略,对快速成长且固定资产投入较少的产业项目,通过灵活设置用地年限降低企业初始投资成本,项目土地出让允许分期缴纳土地价款,自签订合同之日起1年内缴纳完毕,配套建立弹性续期机制。对上下游配套企业,采用“先租后让、租让结合”用地模式,优先保障标准化厂房供应。(责任单位:市资规局、市住建局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"四","title":"加快项目筹建投产","text":"加快项目筹建投产。强化市、区两级联动,简化建设报批流程,推行并联审批模式,协助企业“零跑动”高效办理各类涉企行政审批手续。落实帮办服务制度,跟踪项目开工建设和投产达产全流程,对重大项目实行“一事一议”协调,跨部门解决企业诉求,鼓励企业“拿地即动工”“竣工即投产”。(责任单位:市发改委、市资规局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"五","title":"降低企业要素成本","text":"降低企业要素成本。加强电力保障,探索“光伏+储能+微电网”集成模式,协调新能源发电企业与年用电量超500万千瓦时的“三电”企业,建立能源应急保障机制,优先保障重点项目稳定用电。加强气源保障,积极对接上游企业,多渠道筹措气源,推进LNG(液化天然气)储备站建设,加快市政燃气基础设施建设,提高应急调峰和燃气输配能力。加强环保要素保障,建设集中式污水处理、危废处理中心及公共检测实验室,对重大“三电”项目优先统筹使用市域内污染物排放总量指标,精准调剂主要污染物总量指标。优化物流网络,加快涟水复航、洛湛铁路益娄段电气化改造工程等重大项目建设,打造“制造业物流枢纽”。(责任单位:市发改委、市生态环境局、市住建局、市交通运输局、国网娄底供电公司、相关燃气公司,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"六","title":"支持科技创新","text":"支持科技创新。鼓励企业加大研发投入,支持企业用数智技术、绿色技术改造提升传统产业,推动企业设备更新、工艺升级及管理创新,支持租赁关键设备和生产线,实施“技术攻关+产业化应用”重大科技示范工程,加强知识产权创造、运用、保护、管理和服务。引导“三电”企业接入工业互联网平台,推荐数字化转型、智能化改造项目申报国家级、省级智能制造试点。支持各高校和科研所与企业共建高水平科技成果转化平台,促进科技成果就近就地转化应用。鼓励市级科研补贴(补助)资金向“三电”企业倾斜,鼓励市级创业基金推动“三电”科技成果转化落地,助力“三电”企业高端化、智能化、绿色化。(责任单位:市科技局、市发改委、市财政局、市工信局、市市场监管局、市创发集团,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"七","title":"建立供应链协同机制","text":"建立供应链协同机制。针对“三电”产业对特种钢材、铜铝等原材料的高度依赖,协调建立跨区域原材料储备联盟。通过大宗物资集采、战略储备等方式平抑价格波动,稳定供应链成本,建立原材料供需预警机制,提前做好产能调配和应急储备。建立“三电”供需对接平台,定期组织上下游企业开展采购洽谈会,推动供应链上下游企业实现协同采购、协同制造、协同物流,促进大中小企业专业化分工协作,快速响应客户需求,缩短生产周期和新品上市时间,降低生产经营和交易成本。(责任单位:市工信局、市发改委、市市场监管局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"八","title":"创新金融服务","text":"创新金融服务。加强政银企对接,定期开展“行长走市县·金融送解忧”行动,适时组织“三电”产业融资对接会;完善“金融超市”平台功能,创新优化金融服务产品,积极为“三电”产业链上下游企业提供差异化融资支持。引导金融机构持续开发“三电贷”“三电担”等专属产品,探索应收账款融资、预付款融资、库存融资、订单融资等供应链融资模式,完善信贷审批流程,缩短贷款审批时限。加快推进设立创投子基金,引导娄底“材料谷”产业基金等投资“三电”企业。充分发挥商业保理、融资租赁等金融牌照作用,为“三电”企业提供银票、商票质押融资和订单保理融资等供应链金融服务。(责任单位:市政府办、市财政局、市国资委、中国人民银行娄底市分行、国家金融监督管理总局娄底监管分局、市城发集团,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"九","title":"强化人才引育配套","text":"强化人才引育配套。聚焦人才队伍梯次化、能力全面化、使用实战化,完善构建“引育用”全链条机制。支持企业柔性引进各类人才,鼓励有条件的企业与高校等共建高技能、跨学科复合型人才培训基地。实施“技能人才定向培养计划”,鼓励“三电”企业与高职院校合作开设“钢铁冶金”“电力电子”等专业订单班,由企业参与课程设计,毕业生直接输送至重点企业。建设园区人才公寓,按照需求提供阶梯式住房保障,对重点引进的高层次人才,提供购房补贴配套服务。建立“人才服务一卡通”制度,整合医疗、教育、交通等优质资源,提升人才归属感。(责任单位:市委组织部、市科技局、市人社局、市教育局、市财政局、市工信局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)"},{"no":"十","title":"强化政企沟通与执法监督","text":"强化政企沟通与执法监督。为“三电”产业相关企业配备营商环境联企服务专员,纳入营商环境监测。各级营商环境部门、司法行政部门发现破坏营商环境的问题线索,经交办、督办,内部纠偏效果不好的,依法依规依纪移送纪检监察机关核查处理。(责任单位:市纪委监委、市营商环境办、市司法局、各行政执法部门)\n十"},{"no":"十一","title":"建立推动落实工作机制","text":"建立推动落实工作机制。市“三电”产业工作专班定期调度工作进展情况,对相关责任单位政策落实情况进行调研,跟踪评估政策实施效果。相关部门严格按照职责分工,推进政策落实落地。(责任单位:市工信局,娄星区人民政府、娄底经开区管委会)\n本政策适用对象为入驻娄星区、娄底经开区(含娄星产业园)的“三电”终端成品或主要零配件生产企业。其他县(市)可以参照执行。本政策自公布之日起施行,有效期5年。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202509/t20250924_33813505.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-ab4238","title":"益阳市人民政府办公室关于印发《益阳市支持大学生创业十二条措施》的通知","level":"city","region":"益阳市","issuer":"益阳市人民政府办公室","documentNo":"益政办发〔2025〕10号","publishedAt":"2025-07-30","status":"active","tags":["创业补贴","贷款贴息","场地支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"为大学生创业提供个人最高30万元、合伙创业或小微企业最高400万元的创业担保贷款并按实际利率给予50%贴息，对首次创办小微企业或从事个体经济且正常运营1年以上的在校大学生或离校2年内高校毕业生最高给予1万元一次性创业补贴，自2025年8月1日起施行，有效期至2029年7月31日。","sections":[{"no":"一","title":"帮扶创业主体，完善政策支持","text":"帮扶创业主体，完善政策支持\n（一）提供创业担保贷款贴息及专属信贷支持。为大学生创业提供贷款支持，个人创业最高可贷30万元，合伙创业或小微企业最高可贷400万元，财政部门按实际利率给予50%贴息。同时推出支持青年创业者、青年领办企业及新市民的专属信贷产品，建立“白名单”推送机制。（责任单位：市人力资源社会保障局、市财政局、团市委、人民银行益阳市分行、益阳金融监管分局按职责分工负责）\n\n（二）给予一次性创业补贴支持。对首次创办小微企业或从事个体经济，且所创办企业或个体工商户自工商登记注册之日起正常运营1年以上的在校大学生或离校2年内高校毕业生，根据实际投入、带动就业人数，最高给予1万元的一次性创业补贴。（责任单位：市人力资源社会保障局、市财政局按职责分工负责）\n\n（三）支持创建大学生创业孵化载体。开展大学生创业孵化基地认定工作，对首次认定的益阳市市级大学生创业孵化基地，给予5万元/家的一次性培育奖补，对已认定的益阳市市级大学生创业孵化基地，参照《关于深入推进创业孵化基地建设工作的通知》（湘人社规〔2023〕5号），根据创业孵化成效给予每年最高不超过40万元的创业服务补助。（责任单位：市人力资源社会保障局、市财政局、市科技局、市教育局按职责分工负责）\n\n（四）给予减税降费支持。高校毕业生在毕业年度内从事个体经营，符合规定条件的，在3年内按一定限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税；对销售额在免税标准以下的小规模纳税人免征阶段性增值税，对小微企业和个体工商户按规定减免所得税。对国家级、省级科技企业孵化器和大学科技园以及国家备案众创空间按规定免征增值税、房产税、城镇土地使用税。（责任单位：市税务局）\n\n（五）加大人才政策倾斜。将市大学生创业典型纳入市级人才计划。在益阳市银城青年人才项目创业类中，针对大学生创业者开设单独赛道，按程序将市大学生创业典型纳入市级人才计划名单，享受相应人才政策。（责任单位：市委组织部、团市委按职责分工负责）"},{"no":"二","title":"深化创业培训，增强创业能力","text":"深化创业培训，增强创业能力\n（六）加强创业导师队伍建设与指导服务。重点打造一支由10名核心实战型导师和120名专业导师组成的市级创业导师团队，构建覆盖高等教育、企业管理、法律咨询、金融财务等多领域的综合性导师体系，实现创新创业导师资源的共建共享。结合“益起来创业”系列创业服务活动，组织开展导师进基地、进校园活动，为大学生创业项目提供专业化、多元化、精细化的创业指导；并对有需要、有潜力的创业项目，安排创业导师开展结对帮扶。（责任单位：市科技局、市教育局、市人力资源社会保障局、团市委按职责分工负责）\n\n（七）开展创业课程定制培训。完善创业培训课程体系，针对不同创业阶段、创业类型、创业需求的大学生，提供定制化GYB、SYB、IYB、网络创业、创业模拟实训等课程培训，按规定给予创业培训补贴，提升大学生创业能力。（责任单位：市人力资源社会保障局、市教育局按职责分工负责）\n\n（八）支持大学生在涉农领域创业就业。市农村产权交易中心设立专项服务窗口，为大学生创业提供土地流转、技术指导等政策咨询服务。组织有返乡下乡创业意向大学生参与高素质农民培训，将返乡创业大学生纳入产业发展带头人重点培育对象，开展农村创业项目专题培训。（责任单位：市农业农村局）"},{"no":"三","title":"拓展孵化空间，助力创业成长","text":"拓展孵化空间，助力创业成长\n（九）给予大学生创业场地支持服务。大学生创业孵化基地免费提供不低于孵化面积30%的场地给大学生和毕业5年内（含）高校毕业生创业项目，并给予入驻项目场地租金首年全额补贴，次年补贴50%。支持优秀大学生落户中南科创园、龙山港、华盛创业园以及监管企业管理的商铺创业，为其提供必要的管理服务，并予以一定的租金优惠。（责任单位：市人力资源社会保障局、市财政局、市科技局、市教育局、市国资委、益阳高新区管委会按职责分工负责）\n\n（十）给予大学生创业者保障性租赁住房优惠。面向符合条件的大学生创业者供应保障性租赁住房，面积扩大到120平方米以内，租金不高于同地段同品质市场租赁住房租金的80%，实行动态管理。（责任单位：市住房城乡建设局）\n\n（十一）设立市、县两级“大学生创业一站式服务中心”，推行“零打扰”监管和“零跑腿”审批服务模式。推行“不上一次门”制度，对新设立且无投诉举报、无安全隐患的大学生创业企业，实行“首年免检”政策，并实施“轻微免罚”“首违不罚”等柔性执法措施。推进“高效办成一件事”改革，确保“个人创业一件事”落地实施，实现全流程办理。为大学生创业企业提供最大程度的“无事不扰”和“有需必应”的服务环境。（责任单位：市发展改革委、市科技局、市人力资源社会保障局、市市场监管局、团市委、市税务局，各县市区人民政府按职责分工负责）"},{"no":"四","title":"弘扬创业精神，营造社会氛围","text":"弘扬创业精神，营造社会氛围\n（十二）打造“‘益’起创青春”宣传品牌，构建全方位创新创业生态。举办“青年夜校·创新创业专场”“益阳市青年创新创业大讲堂”“‘益’起创青春 携手向未来”益阳政企青年解难题促发展主题沙龙等活动，搭建政企对话平台，弘扬新时代创新创业精神，持续激发高校学子创新潜能。同步构建媒体宣传矩阵，开设《正青春 好创业》政策解读专栏和《青春“益”起创》典型宣传栏目，形成“活动赋能+媒体发声”的全方位宣介创业工作，立体化展示青年创业典型，多维度推广基层创新经验，在全社会营造尊重创业、支持创新的良好氛围。（责任单位：市委宣传部、团市委、益阳日报社、市广播电视台按职责分工负责）\n\n大学生创业主体须依法经营并履行社会责任，在享受同类政策时，遵循“奖补不重复”原则。本文件自2025年8月1日起施行，有效期至2029年7月31日。在文件有效期内，如遇法律法规或有关政策调整变化的，从其规定。"}],"interpretations":[{"sectionNo":"一","headline":"大学生创业最高贷30万元、合伙或小微企业最高400万元，贴息50%","who":"在益阳创业的大学生（含在校大学生、离校2年内高校毕业生）；合伙创业或小微企业可提高额度。","materials":[],"window":"按创业担保贷款经办流程办理。","where":"市人力资源和社会保障局、市财政局、人民银行益阳市分行等按职责分工办理。","tip":"财政按实际利率给予50%贴息；另有面向青年创业者、青年领办企业及新市民的专属信贷产品和「白名单」推送机制。","evidence":{"headline":["个人创业最高可贷30万元，合伙创业或小微企业最高可贷400万元，财政部门按实际利率给予50%贴息"],"who":["为大学生创业提供贷款支持"],"where":["市人力资源社会保障局、市财政局、团市委、人民银行益阳市分行、益阳金融监管分局按职责分工负责"],"tip":["建立“白名单”推送机制"]}},{"sectionNo":"一","headline":"大学生首次创业满1年，一次性补贴最高1万元","who":"首次创办小微企业或从事个体经济，且自工商登记注册之日起正常运营1年以上的在校大学生或离校2年内高校毕业生。","materials":[],"window":"自工商登记注册之日起正常运营1年以上。","where":"市人力资源和社会保障局、市财政局按职责分工办理。","tip":"补贴金额按实际投入和带动就业人数核定，最高1万元，不是人人1万元。","evidence":{"headline":["最高给予1万元的一次性创业补贴"],"who":["对首次创办小微企业或从事个体经济，且所创办企业或个体工商户自工商登记注册之日起正常运营1年以上的在校大学生或离校2年内高校毕业生"],"window":["自工商登记注册之日起正常运营1年以上"],"where":["市人力资源社会保障局、市财政局按职责分工负责"],"tip":["根据实际投入、带动就业人数"]}}],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202509/t20250924_33813484.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2025-09-24","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-c1c73c","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于印发《湖南省创业培训管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2025〕15号","publishedAt":"2025-07-25","status":"active","tags":["创业补贴","就业补贴"],"audience":["小微企业","高校毕业生"],"summary":"GYB培训补900元/人次、SYB培训补1400元/人次，由培训机构先垫后补，证书发放3个月内代为申领。","sections":[{"no":"一","title":"第一条","text":"为贯彻落实省委、省政府关于推动大学生创新创业决策部署，优化创业培训管理，提升创业培训质量。根据《人力资源社会保障部等7部门关于健全创业支持体系提升创业质量的意见》(人社部发〔2025〕5号)、《人力资源社会保障部关于实施职业技能提升行动创业培训“马兰花计划”的通知》（人社部函〔2020〕109号）、《中国就业培训技术指导中心关于印发<马兰花创业培训项目组织实施规程>等技术文件的通知》（中就培函〔2025〕62号）、《湖南省人民政府办公厅关于印发〈湖南省大力支持大学生创业若干政策措施〉的通知》（湘政办发〔2024〕42号）和《湖南省财政厅 湖南省人力资源和社会保障厅关于印发〈湖南省就业补助资金管理办法〉的通知》（湘财社〔2024〕33号）等有关文件制定本办法。"},{"no":"二","title":"第二条","text":"本办法所指创业培训包括GYB（产生你的企业想法）、SYB（创办你的企业）、IYB（改善你的企业）、EYB（扩大你的企业）、网络创业培训（电商、直播）、创业模拟实训和乡村领雁创业培训，以及经省级创业培训主管部门开展试点或认定的培训课程。"},{"no":"三","title":"第三条","text":"对以下人员可以给予创业培训补贴：防止返贫监测对象、毕业年度高校毕业生（含技工院校高级工班、预备技师班、技师班和特殊教育院校职业教育类毕业生）、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员，以及大中专院校在校学生（含中职、技校）、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工。\n第二章  机构和师资管理"},{"no":"四","title":"开展创业培训的机构应符合以下条件：","text":"开展创业培训的机构应符合以下条件：\n（一）具有独立法人资格的职业培训机构、就业创业培训（实训）中心、创业孵化基地、创业指导师工作室和各类院校、众创空间等实体，可申请开展创业培训；\n（二）申请开展培训的课程，至少与3名以上对应课程的创业培训授课讲师签订不低于2年的授课协议；\n（三）有2名以上专职管理人员负责创业培训及后续服务的组织工作；\n（四）与2名以上创业创新导师团成员签订不低于1年的服务协议；\n（五）开展创业培训的机构，应配置2间创业培训理论教学专用教室（单间面积≥60㎡）及1间创业培训实操教学专用教室（面积≥120㎡），并配备不少于40台电脑，配有不低于100M高速宽带接入，且须具备教师休息室、档案室、工作人员办公室等基本办公场地；\n（六）已安装远程移动视频监控系统，能实现培训过程的实时监控并记录；\n（七）教学管理、学员管理、财务及安全管理等制度健全，近年来未发生社会不良影响事件；\n（八）能按时按质完成创业培训主管部门下达的培训任务，并使用省厅确定的教学辅助平台。"},{"no":"五","title":"第五条","text":"各市州人力资源社会保障部门按照公开规范、保障质量、提升效益的原则，从符合条件的单位中择优确定承接创业培训课程的培训机构，或者通过政府采购招标方式确定培训定点机构。"},{"no":"六","title":"第六条","text":"培训机构原则上每3年认定一次，报省创业培训主管部门备案后，录入省人社一体化业务管理系统（以下简称“省平台”），并实时更新培训机构信息，进行动态管理。"},{"no":"七","title":"第七条","text":"对新开展的创业培训课程，各市州人力资源社会保障部门根据培训需求，可组织专家评审，从已认定的创业培训机构中，择优选择机构实施，并报省创业培训主管部门备案。"},{"no":"八","title":"第八条","text":"各级创业培训主管部门要定期对创业培训机构开展考核评价，对存在以下情形之一的，创业培训主管部门可视情节给予限期整改、暂停培训、取消培训资格等处分，并将处分情况记录至省平台。\n（一）对创业培训机构丧失培训资质和办学许可、自动放弃创业培训定点机构服务资格及其他原因导致无法正常开展创业培训的；\n（二）未认真履行培训机构职责，逃避检查，拒不接受主管部门监管核查的；\n（三）未按规定执行培训技术标准或不接受省平台师资派遣、培训质量低、绩效评价差的；\n（四）出借、出租办学资质，违规颁发培训合格证书，将培训项目转包或委托给其他单位或个人的；\n（五）发布虚假招生简章或者广告，弄虚作假，套取骗取补贴资金的；\n（六）未按照开班备案信息开展培训或连续两年未正常开展创业培训工作的；\n（七）各级审计、巡视巡察、纪检监察、信访举报、资金绩效评价发现有重大问题的；\n（八）管理混乱、违规收费、有举报投诉，造成重大社会不良影响的；\n（九）法律法规禁止的其他情形。\n自取消创业培训定点机构服务资格之日起，该单位3年内不得参与创业培训业务。涉嫌违法犯罪的，依法移送有关机关处理。"},{"no":"九","title":"创业培训师资管理按照我省有关规定执行","text":"创业培训师资管理按照我省有关规定执行。\n第三章 组织实施"},{"no":"十","title":"第十条","text":"创业培训课程应按照人社部中国就业培训技术指导中心或省创业培训主管部门确定的技术标准开展培训。"},{"no":"十一","title":"第十一条","text":"培训机构在筹备开班前，应通过省平台发布拟开班信息，接受网上报名和现场报名。GYB培训在招募学员时，应重点面向院校学生和青年群体，可整建制开展培训。其他培训课程招募学员时，应筛选有创业愿望和培训需求的对象开展培训。"},{"no":"十二","title":"第十二条","text":"培训机构在正式开班前，应提前3个工作日通过省平台向当地创业培训主管部门提交《创业培训开班申请表》（附件1）、学员登记表和课程安排表。创业培训主管部门应在3个工作日内在省平台完成备案。"},{"no":"十三","title":"GYB课程每班不超过40人","text":"GYB课程每班不超过40人；SYB、IYB、网络创业培训课程每班不超过30人；EYB课程每班不超过25人；创业模拟实训和乡村领雁创业培训课程每班不超过35人。培训机构应每班安排1名工作人员担任班主任。"},{"no":"十四","title":"GYB课程原则上安排24课时","text":"GYB课程原则上安排24课时；SYB、IYB、网络创业培训、创业模拟实训和乡村领雁创业培训课程原则上安排56课时；EYB培训原则上安排48课时；每课时45分钟，每日最多可上8个课时。"},{"no":"十五","title":"第十五条","text":"课程实施中需使用的教学辅助平台由省创业培训主管部门按照对应课程技术标准和培训需求组织专家评审择优确定。"},{"no":"十六","title":"第十六条","text":"学员完成培训并经考核合格后，由创业培训主管部门颁发《创业培训合格证书》，具体按照省人力资源社会保障厅印发的《关于启用创业培训电子证书的通知》（湘人社函〔2022〕137号）执行。"},{"no":"十七","title":"第十七条","text":"有后续服务需求的学员可在创业培训结课时按照《创业培训后续服务需求清单》（附件2），通过省平台提交后续服务申请。培训机构可组织签约导师或创业指导师工作室为学员提供后续服务。"},{"no":"十八","title":"第十八条","text":"培训机构应如实记录学员考勤信息，培训过程影像资料和后续服务情况等档案材料，留存备查，保存期限不少于3年。\n第四章 补贴资金的申领和拨付"},{"no":"十九","title":"第十九条","text":"细化创业培训补贴计算方式，按照“钱随事走”的原则，将创业培训补贴分为课程培训补贴和后续服务补贴两个阶段，避免培训机构“一培了之”，所需资金从就业补助资金中列支。具体补贴标准如下：\n（一）课程培训补贴。GYB课程900元/人次（其中600元支付机构，300元用于教学辅助平台系统的使用、维护）；SYB课程1400元/人次；IYB课程1600元/人次；网络创业培训、创业模拟实训和乡村领雁创业培训1700元/人次（其中1400元支付机构，300元用于教学辅助平台系统的使用、维护）；EYB培训费用由个人和财政共同承担，补贴标准由各地自行确定。\n（二）后续服务补贴。培训机构按创业学员需求组织开展后续服务的，经服务后学员3个月内成为新增或现有市场主体的法定代表人或股东等人员的，按800元/人的标准给予培训机构补贴。培训机构可根据后续服务成效支付签约导师或创业指导师工作室相应比例的服务费。GYB不纳入后续服务补贴范围。"},{"no":"二十","title":"第二十条","text":"创业培训补贴实行“先垫后补”，由培训机构先行垫付培训费用，证书发放3个月内向当地创业培训主管部门代为申领创业培训补贴。申请时应当提交以下资料：\n1.创业培训补贴申请表（附件3）；\n2.创业培训补贴人员名册（附件4）；\n3.培训补贴代为申请协议（附件5）；\n4.缴纳培训费用凭证：培训定点机构开具的收费凭证、票据或税务发票原件；\n5.培训学员的身份类别证明材料，按照《人员类别证明材料》（附件6）的要求提供；\n6.工商营业执照，以及学员为该市场主体法定代表人或股东等人员的佐证资料，通过省平台数据协同的可不提供。\n同一班期创业培训补贴可将课程培训补贴和后续服务补贴分开提交申请，也可合并提交申请。"},{"no":"二十一","title":"培训机构应及时申请创业培训补贴","text":"培训机构应及时申请创业培训补贴。各级人力资源社会保障部门接到补贴申请后，应在15个工作日内完成审核工作。审核通过后，在当地人力资源社会保障网或政府公共服务网上公示，公示期为5天。公示期满无异议的，各地按照现行部门职责分工，人力资源社会保障部门或财政部门在接到申报补贴资料2个月内将补贴资金拨付到培训机构在银行开立的基本账户，同时由人力资源社会保障部门将资金拨付情况按规定录入省平台。"},{"no":"二十二","title":"第二十二条","text":"符合条件的补贴对象，同类别创业培训课程每人只可享受一次补贴。自2024年1月1日起，每人累计最多享受3次（与职业技能培训补贴合并计算）。\n第五章 监督管理"},{"no":"二十三","title":"第二十三条","text":"省就业服务中心负责组织制定全省创业培训工作规划、拟定年度指导性计划，持续完善创业培训信息系统，不断优化教学管理、师资管理、培训监管等制度，指导市州组织开展创业培训。各级创业培训主管部门负责具体组织实施及培训机构监管、师资监管、培训监管等工作。各级财政部门负责补贴资金的筹措，及时拨付补贴资金。"},{"no":"二十四","title":"第二十四条","text":"各级人力资源社会保障部门要依托省平台开展创业培训各项业务，落实“凡补必进，不进不补”工作要求。要定期组织创业培训业务培训，防范经办风险。要指导培训机构对学员定期回访，及时了解其创业就业情况，提升创业培训补贴资金绩效。"},{"no":"二十五","title":"第二十五条","text":"各级人力资源社会保障部门、财政部门应加强创业培训补贴资金使用监管，加大补贴资金核查力度。各级人力资源社会保障部门要加大日常巡查、定期检查和临时抽查力度，对于弄虚作假、骗取、套取补贴资金的单位和个人，依法追究其法律责任。\n第六章 附则"},{"no":"二十六","title":"本办法自2025年7月25日起施行，有效期5年","text":"本办法自2025年7月25日起施行，有效期5年。有效期内国家出台的新规定与本办法不一致的，以国家新规定为准。此前有关政策文件关于创业培训管理的规定与本办法不一致的，以本办法为准。\n附件：1.创业培训开班申请表\n2.创业培训后续服务需求清单\n3.创业培训补贴申请表\n4.创业培训补贴人员名册\n5.创业培训补贴代为申请协议（模板）\n6.人员类别证明材料"}],"interpretations":[{"sectionNo":"十九","headline":"GYB补900元、SYB补1400元，后续服务再补800元/人","who":"参加创业培训并取得合格证书的十类人员：防止返贫监测对象、毕业年度高校毕业生、城乡未继续升学的应届初高中毕业生、农村转移就业劳动者、城镇登记失业人员、就业困难人员，以及大中专院校在校学生、离校2年内未就业高校毕业生、登记自主创业人员、有创业意愿的企业单位职工。","materials":[],"window":"证书发放3个月内由培训机构代为申领。","where":"当地创业培训主管部门（人社部门），通过省人社一体化业务管理系统办理。","tip":"同类别课程每人只可享受一次，自2024年1月1日起累计最多3次（与职业技能培训补贴合并计算）；GYB不纳入后续服务补贴。","evidence":{"headline":["GYB课程900元/人次","SYB课程1400元/人次","按800元/人的标准给予培训机构补贴"],"who":["对以下人员可以给予创业培训补贴"],"window":["证书发放3个月内向当地创业培训主管部门代为申领创业培训补贴"],"where":["向当地创业培训主管部门代为申领创业培训补贴"],"tip":["每人累计最多享受3次","GYB不纳入后续服务补贴范围"]}},{"sectionNo":"二十","headline":"学员先免费学，机构垫钱、发证后3个月内代为申领补贴","who":"承接创业培训的定点培训机构代学员申领；学员本人不用自己跑补贴流程。","materials":["创业培训补贴申请表（附件3）","创业培训补贴人员名册（附件4）","培训补贴代为申请协议（附件5）","缴纳培训费用凭证（收费凭证、票据或税务发票原件）","学员身份类别证明材料（附件6）","工商营业执照及学员为法定代表人或股东的佐证资料"],"window":"证书发放3个月内申领；人社部门15个工作日内完成审核，公示5天，2个月内拨付资金。","where":"当地创业培训主管部门","tip":"通过省平台数据协同能查到的营业执照等材料，可以不再提供。","evidence":{"headline":["由培训机构先行垫付培训费用"],"who":["由培训机构先行垫付培训费用，证书发放3个月内向当地创业培训主管部门代为申领"],"materials":["培训补贴代为申请协议（附件5）","培训学员的身份类别证明材料"],"window":["应在15个工作日内完成审核工作","公示期为5天"],"where":["向当地创业培训主管部门代为申领创业培训补贴"],"tip":["通过省平台数据协同的可不提供"]}}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202509/t20250913_33803293.html","sourceNote":"2026-11-09 核对：原文页只挂 docx 附件，正文取自该附件且逐句比对一致（91/91 句命中）；网页发文日期 2025-07-25、信息时效期 2030-09-24；2026-11-09 按原文「自2025年7月25日起施行，有效期5年」推算 2025-07-25 至 2030-07-24","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","effectiveAt":"2025-07-25","expiresAt":"2030-07-24","hunan":true},{"id":"p-2025-c63084","title":"关于促进专精特新中小企业高质量发展的若干措施","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2025〕3号","publishedAt":"2025-02-28","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业"],"summary":"长沙首次认定的专精特新\"小巨人\"企业每家一次性奖励50万元；重点项目每家每年最高补助30万元；数字化改造最高补助30万元。","sections":[{"no":"一","title":"建立梯度培育体系","text":"建立梯度培育体系。构建“专精特新中小企业—专精特新'小巨人'后备企业—专精特新'小巨人'企业”的梯度培育体系。围绕重点产业集群和产业链，梳理出一批创新能力强、赛道前景好、市场竞争优势显著的优质中小企业，分层动态建立企业培育体系，实施精准培育。推动科技型中小企业培育为高新技术企业，加快实现升规纳统。对首次认定的专精特新“小巨人”企业，每家给予一次性50万元奖励。（责任单位：市工业和信息化局、各区县市人民政府、园区管委会）"},{"no":"二","title":"精准支持科技创新","text":"精准支持科技创新。支持专精特新中小企业自筹建设或者与高校院所、医疗机构等联合共建技术创新中心。支持认定为高新技术企业的专精特新中小企业与国家级创新平台及高校院所组建新型研发机构。支持专精特新中小企业开展行业关键技术攻关和关键产品研发，鼓励企业牵头组建创新联合体，承担市级科技重大专项以及“揭榜挂帅”项目。鼓励专精特新中小企业依托长沙市科技创新综合信息平台发布技术需求清单；组织高校院所与专精特新中小企业开展产学研合作对接，支持专精特新中小企业主动吸纳承接高校院所科技成果，鼓励开展技术转让、技术开发、技术许可。指导支持专精特新中小企业开展标准创新型企业培育评价，对参与制定国际、国家和市级地方标准的企业，按规定给予一次性奖励。为企业开展质量诊断服务，指导专精特新中小企业导入先进质量管理模式，支持企业积极争创政府质量奖。（责任单位：市科技局、市工业和信息化局、市市场监管局）"},{"no":"三","title":"强化知识产权保护","text":"强化知识产权保护。将更多专精特新中小企业列入知识产权优势企业培育对象。依托国家专利导航综合服务平台，推进专精特新中小企业深度参与高校院所存量专利盘活工作。对符合条件的专精特新中小企业提供快速预审、快速确权和快速维权的知识产权综合服务。引导专业机构加强专精特新中小企业知识产权培训。（责任单位：市知识产权局）"},{"no":"四","title":"支持重点项目建设","text":"支持重点项目建设。支持专精特新“小巨人”后备企业深耕专业细分赛道，提升创新能力和竞争力；重点围绕打造新动能、攻坚新技术、开发新产品和强化产业链配套能力，依规定每年遴选一批重点项目，结合企业主营业务、研发创新、知识产权、数字化水平等综合指标，按照每家企业每年最高不超过30万元的标准给予补助。建立专精特新中小企业项目建设储备机制，实施动态管理，加强综合服务，积极支持符合要求的企业申报中央、省级资金项目。（责任单位：市工业和信息化局、市财政局）"},{"no":"五","title":"强化融资支持","text":"强化融资支持。发挥长沙市小微企业信贷风险补偿基金、长沙市中小企业转贷引导基金作用，推动银行业金融机构面向专精特新中小企业开发特色产品，提供应急转贷资金支持。强化供应链金融服务，探索搭建综合服务平台。建设政府引导基金与专精特新中小企业投资对接机制。依规定遴选符合条件的专精特新重点企业列入上市培育对象；做实北京证券交易所、全国股转系统长沙服务基地，健全战略合作机制，提升服务质效。聚焦重点产业链专精特新中小企业融资需求，开展投融资路演活动。（责任单位：市工业和信息化局、市委金融办、市财政局）"},{"no":"六","title":"强化人才服务","text":"强化人才服务。实施专精特新中小企业就业创业扬帆计划，将专精特新中小企业纳入重点企业用工保障范围。建设市域产教联合体，加强校企对接，开展专场招聘活动。探索推动具备条件的专精特新中小企业开展高级职称自主评定，赋予专精特新“小巨人”企业高层次人才举荐权。在企业员工职称评定中，不将论文作为硬性要求，支持将新产品研发等工作绩效作为评价的重要参考，对高端人才探索以业绩陈述代替论文答辩。大力支持专精特新中小企业吸引集聚高端人才，推荐符合条件的企业和人才申报市级“两大重点人才工程”、省级“芙蓉计划”、国家重点人才计划等人才项目，办理高层次人才分类认定，在人才落户、住房、子女教育和“长沙市卓越工程师”等享受政府津贴专家选拔中予以支持。加大人才平台建设力度。支持符合条件的专精特新“小巨人”企业建设院士工作站、专家工作站，分别给予每家企业100万元、60万元经费支持。支持符合条件的专精特新“小巨人”企业建设博士后科研工作站、博士后创新创业实践基地，分别给予每家企业100万元、60万元经费支持。专项支持专精特新中小企业举办符合长沙产业发展方向和人才需求的学术会议、专业论坛。（责任单位：市委人才办、市教育局、市科技局、市人力资源社会保障局、市科协）"},{"no":"七","title":"支持市场开拓","text":"支持市场开拓。促进大中小企业融通创新，分行业梳理专精特新中小企业产业链分布和协作清单，以集群和产业链为单位，精准推动专精特新中小企业与大企业开展市场、技术、人才对接。推动省、市国有企业开放创新资源和应用场景，与专精特新中小企业加强供需对接。对接国家中小企业国际合作协会、市级“走出去”联盟、公共信息服务平台等服务资源，组织开展专项培训，推动重点行业专精特新中小企业抱团“出海”、链式“出海”。支持专精特新中小企业参加境外展会，利用海外知名搜索引擎、社交媒体、电商平台开展线上推广营销，开展管理体系认证、境外产品认证、境外专利申请和境外商标注册，按规定给予资金支持。（责任单位：市工业和信息化局、市商务局）"},{"no":"八","title":"推进数字化发展","text":"推进数字化发展。深入推进智赋万企行动，支持中小企业上云、上平台。推进中小企业数字化转型城市试点工作。分行业推进中小企业数字化改造，对纳入试点的中小企业开展数字化改造给予补贴，按照每家企业不高于数字化改造采购总额30%的比例给予补助，其中每家企业补助金额最高不超过30万元。在使用中央财政资金按上述标准给予补助的基础上，市级财政根据实际情况给予配套支持，每家企业补助金额最高不超过30万元。打造一批数字化转型标杆，建设中小企业数字化转型公共服务平台，引导服务商研发推广“小快轻准”数字化产品和解决方案。支持专精特新中小企业建设智能制造工厂、打造应用场景。（责任单位：市工业和信息化局）"},{"no":"九","title":"促进绿色化发展","text":"促进绿色化发展。支持专精特新中小企业开展节能诊断、节能技术改造和建设工业绿色微电网。优先支持专精特新中小企业建设绿色工厂，创建绿色供应链管理企业。鼓励专精特新中小企业节约集约用地，在符合国土空间规划、不改变用途和保障安全的前提下，对专精特新中小企业通过厂房加层、厂区改造、内部用地整理等方式提高工业用地（不含工业地产）利用率和容积率的，不再增收土地价款。（责任单位：市发展改革委、市工业和信息化局、市自然资源规划局）"},{"no":"十","title":"优化企业服务","text":"优化企业服务。落实专精特新中小企业分层培育政策和服务措施，集成服务资源，提供精准服务。建立专精特新中小企业政府服务专员制度。链接全国中小企业服务一张网，建立线上线下一体化中小企业服务平台，开设专精特新中小企业服务专区，建立政策推送直达系统，完善困难问题帮扶分办系统。依托平台功能征集企业需求，开展融资服务、优才招聘、知识产权、企业管理、市场开拓等服务活动，对服务成效突出的企业服务机构按照每家机构最高不超过20万元的标准给予补助。（责任单位：市工业和信息化局、各区县市人民政府、园区管委会）\n本文件自2025年3月1日起施行，有效期3年，由市工业和信息化局负责具体解释工作。"}],"interpretations":[],"sourceUrl":"http://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202502/t20250228_11761924.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-09 按原文「自2025年3月1日起施行，有效期3年」推算 2025-03-01 至 2028-02-29","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2025-03-01","expiresAt":"2028-02-29","hunan":true},{"id":"p-2025-ed049d","title":"关于开展一次性创业补贴申报工作的通知","level":"city","region":"株洲市","issuer":"株洲市人力资源和社会保障局","documentNo":"株人社发〔2025〕8号","publishedAt":"2025-07-23","status":"active","tags":["创业补贴","就业补贴"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"株洲首次创办企业或个体工商户正常经营1年以上的重点群体，个体工商户补1万元、企业补2万元；大学生创业个体补2万元、企业补3万元。","sections":[{"no":"一","title":"申报条件","text":"（一）申报株洲市一次性创业补贴，需同时满足以下条件：\n1.在株洲市行政区域内首次登记注册的创业企业或个体工商户，登记注册时间在5年以内（以首次营业执照登记的成立日期为准，例如申报2025年度一次性创业补贴的，工商注册时间应在2020年1月1日至2024年12月31日之间），且有固定经营场所。\n2.创业项目符合国家产业发展方向，信用状况良好，无拖欠职工工资、欠缴社会保险费等违法违规信用记录。\n3.个体工商户经营者、企业法定代表人属于下列重点就业群体：返乡入乡农民工；大学生（在校及毕业两年内，含普通高校、职业学校、技工院校和留学归国人员）；就业困难人员。\n4.正常经营1年以上，且个体工商户经营者需带动2名以上劳动者就业，企业需带动5名以上劳动者就业，企业要求缴纳半年以上企业职工养老保险且处于正常缴纳状态。属于大学生创业企业的，带动劳动者就业可以放宽至3名以上，在校生可暂缓缴纳养老保险，当年毕业的大学生按在校生类别申报。\n（二）已申请过人社部门创业补贴的，不得重复申报。"},{"no":"二","title":"补贴标准","text":"（一）个体工商户按10000元/户的标准给予补贴，企业按20000元/户的标准给予补贴。\n（二）属于大学生创业的，个体工商户按20000元/户标准给予补贴、企业按30000元/户标准给予补贴。"},{"no":"三","title":"申报资料","text":"（一）补贴申请表\n《 年度株洲市一次性创业补贴申报表》（附件1）。\n《 年度株洲市在校生一次性创业补贴申报表》（附件2）。\n（二）申报对象基本信息资料\n包含个体工商户经营者或企业法人身份证复印件、营业执照、企业银行开户账号（个体工商户提供银行卡复印件）或其他登记注册证明复印件。\n（三）正常经营一年以上佐证资料\n包含经营场所房产证或租赁合同复印件、职工花名册、劳动合同复印件、经营流水、工资发放证明、企业公司简介、财务报表、员工参加企业职工基本养老保险证明。\n（四）信用佐证资料\n提供信用中国（湖南株洲）或国家企业信用信息公示系统无违法记录证明材料。\n（五）首次创业佐证资料\n提供国家市场监管系统市场主体投资任职情况查询材料。\n（六）申报对象就业重点群体佐证材料\n1.返乡入乡农民工提供户口本或农村土地承包经营权证复印件，以及以下任意一项转移就业经历证明：与原单位签订的劳动合同、返乡前缴纳的社会保险证明、户籍地乡镇（街道）公共服务办公室出具的返乡创业佐证资料等。\n2.普通高校、职业学校、技工院校和留学归国人员提供毕业证复印件或经教育部留学服务中心认证的国外学历学位认证书。在校生提供经学校创业就业指导部门审核的创业计划书、学生证复印件或学校出具的在校生身份证明。\n3.就业困难人员指按照《湖南省就业援助实施办法》进行身份认定，并在人社一体化平台中进行实名登记、动态管理的人员，包括：男满50周岁、女满40周岁人员；城镇零就业家庭人员；享受城市居民最低生活保障人员；残疾人员；失地农民；军队退役人员；市州级以上劳动模范；烈士家属；抚养未成年子女的单亲家庭成员；连续失业1年以上的其他登记失业人员。就业困难人员无需提交身份佐证材料，由人社部门在人社一体化平台信息系统中核实。"},{"no":"四","title":"申报流程","text":"（一）公开申报\n市人社局在官网（http://rsj.zhuzhou.gov.cn）公布政策文件。申报对象向工商注册地所在县市区人社局申报（在校生向所在学校申报），申报资料一式两份，统一用A4纸打印，按资料清单顺序装订成册。\n（二）组织初审\n县市区人社局负责受理辖区内申报对象的申报资料并组织初审（学校受理在校生的申报资料审批后报县市区人社局初审）。初审工作人员通过资料审核、实地走访等方式，核实各类证明、证件原件和资料复印件的真实性，核定申报对象经营情况、带动就业情况、补贴标准。初审完成后，由初审单位在申报表、汇总表签署意见并加盖公章。\n（三）汇总复核\n县市区人社局初审完成后，填报《株洲市一次性创业补贴汇总表》（附件3），自留一份，交市人社局一份。市人社局对申报资料的真实性、准确性进行复核，确定拟补贴对象及补贴金额。\n（四）官网公示\n复核通过后，市人社局将拟发放补贴名单在官网公示5个工作日。\n（五）资金拨付\n公示无异议后，由人社部门汇总补贴对象信息报送至同级财政部门，依据相关规定拨付补贴资金，并在“湖南人社一体化业务管理系统”内录入补贴信息。"},{"no":"五","title":"工作要求","text":"（一）加强政策宣传。各相关单位要充分利用网络、报纸、电视等媒体，多渠道、多形式宣传补贴政策，提高政策知晓度，扩大政策覆盖面，鼓励和支持更多有意愿、有能力的群体通过创业带动就业。\n（二）严格审核把关。各县市区人力资源和社会保障局、相关单位要严格按照文件要求，严谨审核，认真把关，确保申报资料的真实性。\n（三）严肃工作纪律。工作人员不得假公济私、以权谋私、索拿卡要、刁难企业和个人，收受企业和个人财物。申报企业和个人应对资料的真实性负责。对在申报过程中弄虚作假的申报企业和个人，一经核实，追回补贴资金、取消申报资格，依法纳入社会信用体系，不得再享受我市人社部门各类创业扶持政策。"},{"no":"六","title":"其他事项","text":"（一）当年度一次性创业补贴申报期截止至当年10月31日。\n（二）本通知自下发之日起实施，有效期5年。有效期内上级出台新规定与本通知不一致的，以上级新规定为准。\n（三）其他未尽事宜，由市人力资源和社会保障局负责解释。\n株洲市人力资源和社会保障局\n2025年7月23日"}],"interpretations":[{"sectionNo":"二","headline":"个体户补1万元、企业补2万元，大学生创业翻倍","who":"在株洲市行政区域内首次登记注册、登记时间在5年以内并有固定经营场所的创业企业或个体工商户；经营者或法定代表人须属返乡入乡农民工、大学生（在校及毕业两年内）、就业困难人员。","materials":[],"window":"按年度组织申报，工商注册时间需落在规定区间内（申报2025年度的为2020-01-01至2024-12-31）。","where":"工商注册地所在县市区人社局；在校生向所在学校申报。","tip":"已申请过人社部门创业补贴的，不得重复申报；大学生创业企业带动就业可放宽至3人以上。","evidence":{"headline":["个体工商户按10000元/户的标准给予补贴，企业按20000元/户的标准给予补贴","企业按30000元/户标准给予补贴"],"who":["在株洲市行政区域内首次登记注册的创业企业或个体工商户，登记注册时间在5年以内"],"window":["工商注册时间应在2020年1月1日至2024年12月31日之间"],"where":["向工商注册地所在县市区人社局申报（在校生向所在学校申报）"],"tip":["已申请过人社部门创业补贴的，不得重复申报"]}},{"sectionNo":"一","headline":"正常经营满1年、企业带动5人就业才够条件","who":"个体户经营者需带动2名以上劳动者就业，企业需带动5名以上并缴纳半年以上企业职工养老保险且处于正常缴纳状态；大学生创业企业可放宽到3名以上。","materials":[],"window":"正常经营1年以上。","where":"县市区人社局初审，市人社局复核。","tip":"在校生可暂缓缴纳养老保险，当年毕业的大学生按在校生类别申报。","evidence":{"headline":["正常经营1年以上，且个体工商户经营者需带动2名以上劳动者就业，企业需带动5名以上劳动者就业"],"who":["企业要求缴纳半年以上企业职工养老保险且处于正常缴纳状态"],"window":["正常经营1年以上"],"where":["县市区人社局负责受理辖区内申报对象的申报资料并组织初审"],"tip":["在校生可暂缓缴纳养老保险，当年毕业的大学生按在校生类别申报"]}},{"sectionNo":"四","headline":"向注册地县市区人社局申报，公示5个工作日后拨付","who":"符合条件的申报对象；在校生由学校受理后报县市区人社局初审。","materials":["申报资料一式两份，A4纸打印并按清单顺序装订成册"],"window":"市人社局复核后官网公示5个工作日，无异议再拨付。","where":"工商注册地县市区人社局；公示在市人社局官网（rsj.zhuzhou.gov.cn）。","tip":"初审会实地走访核实经营情况与带动就业人数，材料要能对上实际用工。","evidence":{"headline":["市人社局将拟发放补贴名单在官网公示5个工作日"],"who":["学校受理在校生的申报资料审批后报县市区人社局初审"],"materials":["申报资料一式两份，统一用A4纸打印，按资料清单顺序装订成册"],"window":["公示5个工作日"],"where":["市人社局在官网（http://rsj.zhuzhou.gov.cn）公布政策文件"],"tip":["通过资料审核、实地走访等方式，核实各类证明、证件原件和资料复印件的真实性"]}}],"sourceUrl":"https://rsj.zhuzhou.gov.cn/c923/20250723/i2399858.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2025-fda7b9","title":"关于印发《郴州市一次性创业补贴实施办法》的通知","level":"city","region":"郴州市","issuer":"郴州市人力资源和社会保障局、郴州市财政局","documentNo":"郴人社发〔2025〕28号","publishedAt":"2025-10-27","status":"active","tags":["创业补贴","场地支持","就业补贴"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"在校大学生、离校2年内高校毕业生、就业困难人员、返乡入乡农民工首次在郴州创办市场主体且正常运营1年以上，个体工商户补5000元、初创企业补5000元至15000元。","sections":[{"no":"一","title":"补贴对象","text":"对在校大学生和离校2年内高校毕业生（含留学回国学生，高等院校和大中专院校，高职院校大专及以上，技工院校高级工班、预备技师及技师班）、就业困难人员、返乡入乡农民工首次在我市创办小微企业或从事个体经营，以及在各级人社部门认定的创业孵化基地场所内首次开办符合产业政策范畴的初创企业和个体工商户，可按规定申报一次性创业补贴。"},{"no":"二","title":"申报条件","text":"申报一次性创业补贴需同时具备以下条件：\n（一）在我市范围内登记注册的初创企业和个体工商户，登记注册时间在5年以内（以首次营业执照登记的成立日期为准，2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间，以此类推）。\n（二）正常运营1年以上，吸纳2名以上（含2名）城乡劳动者就业（不含法定代表人）。其中，在校大学生和离校2年内高校毕业生申报一次性创业补贴需吸纳1名以上城乡劳动者就业（不含法定代表人）。\n（三）创业主体经营范围符合国家产业发展方向，不含建筑业（包含建筑、安装、修缮、装饰及其他工程作业）、娱乐业（包含歌厅、舞厅、KTV、棋牌室、酒吧、台球、桑拿、美体按摩、足浴、网吧、氧吧等）、广告业、销售不动产、转让土地使用权、房产中介等其他国家政策不予鼓励扶持的产业实体。\n（四）企业法定代表人属于在校大学生、离校2年内高校毕业生、就业困难人员或返乡入乡农民工。法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的，不纳入补贴范围。\n（五）创业主体近两年在信用中国（湖南郴州）无行政处罚等违法记录，无知识产权或其他经济、法律纠纷。\n（六）在符合上述条件的情况下，各地根据资金预算对带动就业人数较多的申报企业进行优先扶持。"},{"no":"三","title":"补贴标准","text":"一次性创业补贴包括一次性开办费补贴、经营场所租金补贴和商标补贴。其中经营场所租金补贴和商标补贴仅限大学生创业主体和创业孵化基地入孵企业可享受。\n（一）一次性开办费补贴标准\n对符合条件的个体工商户，给予5000元的一次性开办费。对符合条件的初创企业，根据吸纳城乡劳动者就业人数情况，一次性开办费补贴标准为5000元至15000元。吸纳2人（含2人）就业的补贴5000元，吸纳2人以上就业的每增加1人给予1000元补贴，最高不超过15000元。其中，大学生初创企业吸纳1-5人（含5人）就业的补贴10000元；吸纳5人以上就业的补贴15000元。已经享受过同一项目补贴的，不能重复享受。\n（二）经营场所租金补贴标准（仅限大学生创业主体和创业孵化基地入孵企业可享受）\n1.经营场所属于工业行业企业的，按每月最高不超过8元/平方米的标准予以补贴。\n2.工业行业外的其他行业企业（含个体工商户），按每月最高16元/平方米的标准予以补贴，每年最高不超过10万元。实际租金低于补贴标准的，按实际交纳租金给予补贴。\n3.有多处经营场所的申报单位，在营业执照登记注册地申报，同一创业项目不得重复申报。经营场所租金补贴期限最长不超过2年，自工商登记注册之日起计算。使用自有房产创业的不纳入经营场所租金补贴范围。\n（三）商标注册补贴（仅限大学生创业群体和创业孵化基地入孵企业可享受）\n对符合条件的创业主体新获注册商标的，以商标注册证和付费票据据实补贴注册费用。在商标注册过程中产生的差旅费和委托代理费等费用不列入补贴范围。每个创业主体商标补贴个数最多不超过5个。"},{"no":"四","title":"申报资料","text":"1.《郴州市一次性创业补贴申请表》（附件1）。\n2.营业执照或其他登记注册证明，法定代表人身份证。\n3.身份证明材料：\n在校大学生：学生证复印件或学校证明、学信网学籍验证报告（学信网下载打印）；\n离校2年内高校毕业生：毕业证书复印件及学历证明（学信网下载打印），留学回国学生提供教育部留学服务中心颁发的学历认证书复印件；\n返乡入乡农民工提供户籍地址为村的户口本；乡镇或村出具的外出务工经历证明，或其他可印证有外出务工经历的资料、图片、车票、单据等。\n在各级人社部门认定的创业孵化基地场所内创业的，提供孵化基地入孵协议；\n就业困难人员无需提供佐证资料，由人社部门在湖南省人社一体化业务管理系统中核实。\n4.提供劳动合同复印件、员工花名册和带动就业人员近3个月的工资转账记录或参保凭证。\n5.房产证明（如无房产证则提供商品房销售合同）、租赁合同、缴纳租金的发票或收据、转账记录等，享受创业孵化基地租金减免的创业主体，租金减免金额按入孵协议的约定计算。\n6.信用中国（湖南郴州）查询记录。\n7.《商标注册证》原件及复印件，注册费发票复印件\n8.公司股权分配证明资料。\n9.其他佐证资料。"},{"no":"五","title":"申报流程","text":"（一）自主申报。按创业主体工商注册（或登记机关）属地管理原则，符合条件的申请人向所在地人力资源和社会保障部门申报，高新区、经开区创业主体向所在地综合服务中心申报。享受创业孵化基地租金减免的创业主体，经营场所租金补贴可由创业孵化基地代为申请。\n（二）考察审核。人社部门受理申请后，在每季度末月进行集中审核，结合实地考察情况，核定申报企业吸纳就业人数及补贴金额。\n（三）网上公示。考察审核完成后确定的补贴创业主体名单，应在同级人力资源和社会保障部门官网上或当地政府网站进行公示，公示期为5个工作日。\n（四）资金拨付。受补贴名单确定后，由人社部门汇总补贴对象信息报送至同级财政部门，按照相关规定将补贴资金拨付至申报企业账户，并在“湖南人社一体化业务管理系统”内录入补贴信息。"},{"no":"六","title":"补贴终止","text":"出现以下情形之一的，终止享受补贴：\n1.申报审核期间，创业主体处于停业状态，或已注销、吊销营业执照的。\n2.经核实有其他不符合补贴发放政策相关条件的。"},{"no":"七","title":"其他","text":"离校2年以上，3年以内高校毕业生首次在我市创办小微企业或从事个体经营，可参照本办法规定申报一次性创业补贴。补贴资金从郴州市支持大学生创业专项资金支出，支出流程按《郴州市支持大学生创业专项资金管理办法》（郴教发〔2025〕4号）相关规定执行。"},{"no":"八","title":"工作要求","text":"（一）加强宣传推荐。我市各级人社部门要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向，代表先进生产力、生产方式的创新创业带动就业的先进典型。\n（二）严格审核把关。我市各级人社部门要严格按照文件要求，严格审核、认真把关，确保真实性。财政部门要加强资金监管，充分提高资金使用效率。\n（三）严肃工作纪律。我市各级人社部门要优化服务，提供便捷申报受理渠道。申报企业或个人应对申报资料的真实性负责。对有违规申报、弄虚作假、骗取套取等行为的申报企业和个人，一经核实，取消申报资格，情节严重的纳入诚信黑名单，并依法依规作出处理和追究相关单位和个人责任。"},{"no":"九","title":"本办法由市人力资源和社会保障局、市财政局负责解释","text":"本办法由市人力资源和社会保障局、市财政局负责解释。"},{"no":"十","title":"本办法自公布之日起施行,有效期5年","text":"本办法自公布之日起施行,有效期5年。此前有关政策文件规定与本办法不一致的，以本办法为准。有效期内上级出台新规定与本办法不一致的，以上级新规定为准。\n附件：郴州市一次创业补贴申请表.doc"}],"interpretations":[{"sectionNo":"一","headline":"首次在郴州创业的这四类人，可领一次性创业补贴","who":"在校大学生、离校2年内高校毕业生（含留学回国学生，含技工院校高级工班及以上）、就业困难人员、返乡入乡农民工。须是首次在郴州创办小微企业或从事个体经营；或在认定的创业孵化基地内首次开办符合产业政策方向的初创企业、个体工商户。","materials":["学生证复印件或学校证明（在校大学生）","毕业证书复印件及学信网学历证明（离校2年内高校毕业生）","户籍地址为村的户口本、外出务工经历证明（返乡入乡农民工）","孵化基地入孵协议（基地内创业的）"],"window":"本办法自公布之日起施行，有效期5年。","where":"创业主体工商注册地的人力资源和社会保障部门；高新区、经开区创业主体向所在地综合服务中心申报。","tip":"就业困难人员不用自己找证明，由人社部门在湖南省人社一体化业务管理系统中核实。","evidence":{"headline":["首次在我市创办小微企业或从事个体经营"],"who":["对在校大学生和离校2年内高校毕业生（含留学回国学生","就业困难人员、返乡入乡农民工首次在我市创办小微企业或从事个体经营"],"materials":["学生证复印件或学校证明","毕业证书复印件及学历证明","返乡入乡农民工提供户籍地址为村的户口本","提供孵化基地入孵协议"],"window":["自公布之日起施行,有效期5年"],"where":["向所在地人力资源和社会保障部门申报"],"tip":["就业困难人员无需提供佐证资料，由人社部门在湖南省人社一体化业务管理系统中核实"]}},{"sectionNo":"二","headline":"注册5年内、正常运营满1年、吸纳2人以上才够条件","who":"在郴州登记注册5年以内的初创企业或个体工商户；正常运营1年以上并吸纳2名以上城乡劳动者就业（大学生创业只需吸纳1名）；法定代表人须属于四类群体之一且持股不低于30%；近两年无行政处罚记录。","materials":["营业执照","信用中国（湖南郴州）查询记录","公司股权分配证明资料","劳动合同复印件、员工花名册"],"window":"人社部门在每季度末月集中审核，名单公示5个工作日。","where":"所在地人力资源和社会保障部门","tip":"建筑业、娱乐业、广告业、销售不动产、房产中介等不在扶持范围；法定代表人近两年才变更为符合条件群体的，不纳入补贴范围。","evidence":{"headline":["登记注册时间在5年以内","正常运营1年以上，吸纳2名以上（含2名）城乡劳动者就业"],"who":["在校大学生和离校2年内高校毕业生申报一次性创业补贴需吸纳1名以上城乡劳动者就业","法定代表人持股比例不低于公司总股份的30%"],"materials":["信用中国（湖南郴州）查询记录"],"window":["在每季度末月进行集中审核","公示期为5个工作日"],"where":["向所在地人力资源和社会保障部门申报"],"tip":["不含建筑业（包含建筑、安装、修缮、装饰及其他工程作业）"]}},{"sectionNo":"三","headline":"个体户补5000元，企业按吸纳就业人数补5000至15000元","who":"符合条件的个体工商户与初创企业。经营场所租金补贴和商标注册补贴只给大学生创业主体和创业孵化基地入孵企业。","materials":["房产证明（无房产证可用商品房销售合同）","租赁合同","缴纳租金的发票或收据、转账记录","商标注册证原件及复印件、注册费发票"],"window":"经营场所租金补贴期限最长不超过2年，自工商登记注册之日起计算。","where":"所在地人社部门；享受孵化基地租金减免的，经营场所租金补贴可由孵化基地代为申请。","tip":"已享受过同一项目补贴的不能重复享受；用自有房产创业的不纳入租金补贴；商标补贴每个主体最多5个。","evidence":{"headline":["对符合条件的个体工商户，给予5000元的一次性开办费","一次性开办费补贴标准为5000元至15000元"],"who":["经营场所租金补贴和商标补贴仅限大学生创业主体和创业孵化基地入孵企业可享受"],"materials":["房产证明（如无房产证则提供商品房销售合同）","《商标注册证》原件及复印件，注册费发票复印件"],"window":["经营场所租金补贴期限最长不超过2年，自工商登记注册之日起计算"],"where":["经营场所租金补贴可由创业孵化基地代为申请"],"tip":["使用自有房产创业的不纳入经营场所租金补贴范围","每个创业主体商标补贴个数最多不超过5个"]}}],"sourceUrl":"https://czrsj.czs.gov.cn/18281/18298/content_3994248.html","sourceNote":"2026-11-09 核对：正文与郴州市人社局原文页逐句比对一致（69/69 句命中），页面落款 2025-10-27、文号 郴人社发〔2025〕28号，现行有效","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2026-2747c9","title":"岳阳市人民政府办公室关于印发《关于支持省域区域科技创新中心建设的若干措施》的通知","level":"city","region":"岳阳市","issuer":"岳阳市人民政府办公室","documentNo":"岳政办发〔2026〕3号","publishedAt":"2026-04-14","status":"active","tags":["研发创新","专项资金","融资支持"],"audience":["小微企业"],"summary":"岳阳实施石化产业科技重大专项单个项目最高支持100万元；前沿技术研究项目最高200万元；国家级创新平台最高支持200万元；创新创业大赛获奖项目1万-30万元不等。该市未检索到一次性创业补贴专项，本条为替代。","sections":[{"no":"一","title":"支持重点领域技术攻关","text":"（一）实施石化产业科技重大专项。聚焦绿色化工、高端新材料、现代石化装备等支柱产业，支持关键技术研发与“五首”（首台套、首批次、首版次、首轮次、首套件）产品示范，单个项目给予最高100万元资金支持。\n（二）实施“十大技术攻关”项目。围绕“1+3+X”现代化产业体系技术创新需求，每年遴选实施10项市级重大技术攻关项目，重点支持优势产业关键技术攻关与产业化应用，每个给予最高60万元资金支持。\n（三）开展前沿技术研究。推动人工智能、智能计算、合成生物、先进复合材料、医药健康、先进装备制造、循环经济等新兴产业和未来产业技术研究，每年实施1—2个原创性突破项目，每个给予最高200万元资金支持，并优先推荐纳入省市联动科技攻关项目。\n（四）优化重点研发项目布局。聚焦重点产业体系技术节点问题开展技术攻关，支持龙头企业牵头开展产业链协同创新，每个项目给予最高50万元资金支持。鼓励各县市区围绕主特产业创新发展，设立县域科技创新专项资金，重点支持2—3个科技创新项目。"},{"no":"二","title":"加大全社会研发投入","text":"（五）落实研发投入优惠政策。全面落实研发费用加计扣除和高新技术企业减征企业所得税等优惠政策，支持企业积极申报省企业研发财政奖补资金，做到优惠政策应享尽享。\n（六）鼓励高校、科研院所和医疗机构加大研发投入。对年度研发投入首次达100万元以上的科研院所，每家给予5万元资金支持；对年度研发投入首次达2000万元以上的高校和医疗机构，每家给予10万元资金支持；对年度研发投入高于往年最高年度研发投入的高校、科研院所和医疗机构，按年度研发投入增量部分的1%给予资金支持，每家最高20万元。\n（七）提升基础研究和应用基础研究能力。完善湖南省自然科学基金区域（岳阳市）联合基金机制，鼓励企事业单位出资参与，每个立项的联合基金项目给予5万元资金支持。设立应用基础研究专项资金，支持高校、科研院所和医疗机构等开展应用基础研究，每个立项项目给予最高5万元资金支持。"},{"no":"三","title":"支持科技创新平台建设","text":"（八）强化高能级创新和孵化平台建设。鼓励争创全国重点实验室、国家技术创新中心、国家制造业创新中心、国家新兴产业创新中心、国家产业技术工程化中心等高水平创新平台，对获批组建的，每个给予最高200万元资金支持。对新认定的标准级、卓越级国家级科技企业孵化器，每个分别给予20万元、30万元资金支持。\n（九）构建多层次创新平台体系。争创省级创新平台，健全完善市级创新平台。对新认定的省级创新平台按现有政策予以支持。鼓励创建市级重点实验室、技术创新中心、工程技术研究中心、新型研发机构等研究类平台，成果转化中试基地、创新联合体、科创飞地等成果转化类平台，科普基地、临床医疗技术示范基地、科技企业孵化器等服务类平台，专家工作站、博士创新站等人才引育类平台，对申报的项目符合产业发展需求的，结合绩效评价情况，每个给予最高20万元资金支持。"},{"no":"四","title":"加强创新主体培育","text":"（十）加快科技型企业培育。鼓励各县市区出台支持政策，建立“科技型中小企业—高新技术企业”梯次培育机制，对通过国家高新技术企业首次认定、复审的，给予资金支持。\n（十一）激发创新创业活力。积极举办岳阳市创新创业大赛，对获奖的项目，每个给予1万元至5万元不等的资金支持。支持承办中国创新创业大赛现代石化专业赛，由主办方对获奖的项目每个给予1万元至30万元不等的资金支持。"},{"no":"五","title":"促进科技成果转移转化","text":"（十二）开展科技成果转移转化后补助计划。对高校、科研院所和医疗机构在岳实施科技成果转移转化的，按照不超过全年技术开发和转让合同交易实际到账额1%的比例给予输出方资金支持，最高20万元；对企业承接高校、科研院所和医疗机构科技成果转移转化的，按照不超过全年技术开发和转让合同交易实际到账额1%的比例给予承接方资金支持，最高10万元。\n（十三）实施示范性科技成果转化项目。鼓励高质量科技成果在岳转化，每年评选一批具有示范效应的重大科技成果转化项目。对企业与高校或科研院所共同研发（含技术开发、技术转让、技术许可），取得关键技术突破和突出产业化效果，且持续进行技术迭代和成果产业化的科技成果转化项目，每个给予最高20万元资金支持。\n（十四）强化科技金融赋能。完善科技型企业知识价值贷款风险补偿机制，鼓励合作银行向符合条件的科技型企业发放不超过3000万元的知识价值贷款。落实科技金融“湘伴前行”计划，支持企业发行科技创新债券，发展壮大岳阳市政府产业投资基金，合作设立子基金，引导更多长期资本、耐心资本和优质资本支持科技创新。"},{"no":"六","title":"推进科技交流合作","text":"（十五）搭建区域合作桥梁。加强与长三角、京津冀等地的科技合作，深度对接武汉、长沙两大创新策源地，探索“研发在武汉长沙、转化在岳阳”创新模式，联动建设“武汉—岳阳—长沙经济科创走廊”。鼓励市外知名高校、科研院所和科技服务机构来岳建设技术转移中心，开展科技合作。对在岳阳市开展技术转移活动并取得显著成效的单位，按其技术转移实际绩效每家给予最高100万元资金支持。"},{"no":"七","title":"优化创新生态环境","text":"（十六）加大财政科技投入力度。贯彻落实《湖南省科学技术进步条例》，加强财政保障，将财政科技支出列为市、县两级财政预算保障重点,建立健全财政科技投入的稳定增长机制。\n（十七）加大科技创新战略研究。鼓励企事业单位专家、学者、企业家参与建设省域区域科技创新中心战略研究，实施一批科技创新、产业创新、体制机制创新等方面的科技创新战略研究项目，每个研究项目给予最高20万元资金支持。\n（十八）促进科技服务业发展。鼓励围绕全社会研发投入、创新主体培育、技术转移转化、技术推广等领域开展科技服务，优化科技服务业发展生态，对促进科技创新发展成效明显的科技服务单位，每家给予最高20万元资金支持。\n（十九）支持科学技术进步活动。鼓励申报科学技术奖，对获得国家、省科学技术奖的第一完成单位按照国家、省奖励标准1:1比例给予资金支持，每个最高100万元。\n（二十）选树科技创新典型。按程序开展科技研发、成果转化和产业化等方面作出突出贡献的科技工作者评选工作，在全社会营造浓厚创新氛围。\n（二十一）完善包容创新制度。支持科技人员敢于创新、先行先试。对原始记录等能够证明承担探索性强、风险高的科学技术研究开发项目的科技人员已经履行了勤勉尽责义务，且符合法律法规规定及决策程序，仍不能完成该项目的，不作负面评价，依法依规减轻或免除相关责任。\n以上措施自2026年4月14日起施行，有效期3年。政策支持总额以当年度财政科技创新专项预算为限。我市现行规定与本规定不一致的，以本规定为准。在施行过程中，如遇上级政策调整，以上级政策为准。"}],"interpretations":[],"sourceUrl":"https://www.yueyang.gov.cn/gfxwj/szfwj/content_2372867.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-09 按原文「自2026年4月14日起施行，有效期3年」推算 2026-04-14 至 2029-04-13","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","effectiveAt":"2026-04-14","expiresAt":"2029-04-13","hunan":true},{"id":"p-2026-41937b","title":"常德市人力资源和社会保障局关于延续实施扩大社会保险补贴范围政策的公告","level":"city","region":"常德市","issuer":"常德市人力资源和社会保障局","documentNo":"","publishedAt":"2026-09-02","status":"active","tags":["社保补贴"],"audience":["小微企业","高校毕业生"],"summary":"制造业、生活服务业、现代服务业领域的中小微企业吸纳重点群体就业并在2026年按规定缴纳三项社会保险费的，按照个人实际缴费额的25%给予社会保险补贴，每人累计享受补贴期限不超过12个月，申请期限截至2026年12月31日。","sections":[{"no":"一","title":"为进一步激励企业扩岗吸纳就业，助力重点群","text":"为进一步激励企业扩岗吸纳就业，助力重点群体稳定就业，根据有关文件规定，我市2026年延续实施扩大社会保险补贴范围政策。\n\n1.补贴对象\n\n重点行业领域的中小微企业吸纳重点群体就业，并在2026年按规定为其新缴纳或继续缴纳企业职工基本养老保险费、基本医疗保险费、失业保险费的，按照个人实际缴费额的25%给予社会保险补贴。重点行业领域包括：制造业、生活服务业、现代服务业，具体行业按照国家统计局的行业划分确定。重点群体包括：2026届高校毕业生、2024届和2025届离校未就业高校毕业生，登记失业半年以上人员和防止返贫致贫对象。对于符合《湖南省人力资源和社会保障厅湖南省财政厅关于落实扩大社会保险补贴范围政策有关工作的通知》（湘人社函〔2025〕84号）等文件规定条件，但在2025年未及时申领补贴的人员，可于2026年继续提出申请。\n\n2.申领期限\n\n补贴采用“先缴后补”的方式，可由企业或劳动者向社保参保地或企业所在地的公共就业服务机构提出申请。每人累计享受补贴期限不超过12个月，申请期限截至2026年12月31日。\n\n3.申报流程\n\n个人申报流程\n\n1.智慧人社或电子社保卡扫码登录湖南人社公共服务网上服务大厅（网址：https://ggfw.rst.hunan.gov.cn）。\n\n2.点击公共就业菜单。\n\n3.点击扩围社会保险补贴申请——申请。\n\n4.系统会自动生成身份证、社保卡信息，无社保卡的可以自录银行（填写好申报人的银行信息），申请人填写姓名、联系电话、人员类别（选择符合条件的人员类别）等信息后上传毕业证、身份证正反面、劳动合同后提交申请。\n\n企业申报流程\n\n1.登录界面（https://ggfw.rst.hunan.gov.cn/neaf-ui/#/login）\n\n企业专员使用电子社保卡登录。\n\n2.点击“公共就业”“企业吸纳人员管理”模块进行人员资料完善。\n\n3.填写信息，上传相关资料（仅高校毕业生需要毕业证）后点击保存。\n\n4.点击人员列表后的图标\n\n提交完成。\n\n4.政策咨询电话\n\n市本级7817805\n\n武陵区7230570\n\n鼎城区7375220\n\n西湖管理区2821992\n\n西洞庭管理区7509109\n\n汉寿县2337008\n\n桃源县6612138\n\n临澧县5891049\n\n澧县3127631\n\n石门县5165977\n\n津市市4237358\n\n安乡县4338528"}],"interpretations":[],"sourceUrl":"https://mohrss.changde.gov.cn/zhdt/gggs/content_78217097","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2026-09-02","verified":true,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":true},{"id":"p-2026-63153b","title":"优质中小企业梯度培育管理办法","level":"national","region":"全国","issuer":"工业和信息化部","documentNo":"","publishedAt":"2026-06-15","status":"active","tags":["认定资质","研发创新"],"audience":["小微企业"],"summary":"优质中小企业分科技和创新型中小企业、专精特新中小企业、专精特新\"小巨人\"企业三个梯度培育，认定后有效期3年，到期复核通过可延长。","sections":[{"no":"一","title":"第一条","text":"为加强和规范优质中小企业培育管理，促进中小企业专精特新发展，支撑推进新型工业化、发展新质生产力、建设现代化产业体系，根据党中央、国务院有关决策部署，制定本办法。"},{"no":"二","title":"第二条","text":"优质中小企业是指在产品、技术、工艺、管理、模式等方面创新能力强、专注细分市场、成长性好的中小企业，包括科技和创新型中小企业、专精特新中小企业、专精特新“小巨人”企业。科技和创新型中小企业具有较高专业化水平、较强研发创新能力和发展潜力，是优质中小企业的基础力量；专精特新中小企业实现专业化、精细化、特色化发展，创新能力强、质量效益好，是优质中小企业的骨干力量；专精特新“小巨人”企业位于产业基础核心领域、产业链关键环节，创新能力突出、掌握核心技术、细分市场占有率高、质量效益优，是优质中小企业的中坚力量。"},{"no":"三","title":"第三条","text":"优质中小企业梯度培育工作，坚持落实“两个毫不动摇”，坚持有效市场和有为政府相结合，坚持专精特新发展方向，坚持分层分类分级指导，坚持动态管理和精准服务。"},{"no":"四","title":"第四条","text":"工业和信息化部负责优质中小企业梯度培育工作的宏观指导、统筹协调和监督检查，推动出台相关支持政策，发布相关认定标准，负责专精特新“小巨人”企业认定工作。各省、自治区、直辖市及计划单列市、新疆生产建设兵团中小企业主管部门（以下统称省级中小企业主管部门）负责本地区优质中小企业培育和专精特新中小企业认定工作。\n其他机构未经授权不得开展与科技和创新型中小企业、专精特新中小企业、专精特新“小巨人”企业有关的认定、授牌等活动。"},{"no":"五","title":"第五条","text":"工业和信息化部建设优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下简称培育平台），搭建优质中小企业数据库。各级中小企业主管部门应通过培育平台组织开展认定工作，加强服务对接和监测分析，跟踪企业运行、发展态势、意见诉求，以及扶持政策与培育成效，有针对性地制定政策和开展精准服务。落实数字政府建设要求，推动数据互通共享，减轻企业数据填报负担。\n第二章 认定程序和认定标准"},{"no":"六","title":"第六条","text":"省级以上中小企业主管部门按照谁推荐、谁把关，谁审核、谁管理方式组织开展优质中小企业认定工作。"},{"no":"七","title":"第七条","text":"专精特新中小企业认定，由科技和创新型中小企业按属地原则自愿申报，省级中小企业主管部门根据专精特新中小企业认定标准（见附件1），组织对企业申请材料和相关佐证材料进行审核、实地核查和公示。公示通过的，由省级中小企业主管部门认定为专精特新中小企业。"},{"no":"八","title":"第八条","text":"专精特新“小巨人”企业认定，由专精特新中小企业按属地原则自愿申报，省级中小企业主管部门根据专精特新“小巨人”企业认定标准（见附件2），组织对企业申请材料和相关佐证材料进行初审、实地核查和公示。公示通过的，向工业和信息化部推荐。工业和信息化部组织对被推荐企业进行审核、抽查和认定。原则上每年第二季度组织开展专精特新“小巨人”企业认定工作。"},{"no":"九","title":"第九条","text":"各级中小企业主管部门应建立健全优质中小企业主动发现机制，充分挖掘产业链供应链、股权投资、知识产权、科技奖项、人才引育等数据，常态化发现潜在优质中小企业，定向邀请其参加认定。认定标准不降低。"},{"no":"十","title":"第十条","text":"在专精特新中小企业认定和专精特新“小巨人”企业推荐工作中，省级中小企业主管部门应健全审核机制、规范全过程管理，组织专家严格对照认定标准，重点对企业申请材料和数据的真实性、准确性、完整性，以及是否符合认定标准等情况进行审核。应采取“双随机”（随机抽取专家组成多个评审专家组、即时随机派发审核任务）形式开展审核，评审专家组应包含一定数量的产业专家和财务专家。"},{"no":"十一","title":"第十一条","text":"申报企业应在中华人民共和国境内依法设立，符合《中小企业划型标准规定》，遵守国家法律法规和行业规范。申报期间未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定。应自主、如实申报，按要求填写申请表格并提供必要佐证材料。"},{"no":"十二","title":"第十二条","text":"各级中小企业主管部门及其相关支撑单位应加强宣传培训，指导企业做好申报工作，不得以任何名义直接或变相向申报企业收取费用。"},{"no":"十三","title":"第十三条","text":"各级中小企业主管部门不得将审核认定相关工作委托第三方中介机构承担，应联合相关部门严格防范不良中介机构影响。\n第三章 动态管理"},{"no":"十四","title":"第十四条","text":"省级及以上中小企业主管部门应会同相关部门强化对优质中小企业的运行监测，挖掘利用好金融、信用、司法等各类数据信息，建立健全有进有出的动态管理机制，持续提高优质中小企业发展质量。"},{"no":"十五","title":"第十五条","text":"工业和信息化部按年度对中小企业专精特新发展质量进行评价，并将评价结果纳入中小企业发展环境第三方评估。对于评价得分较低的地区，采取限制推荐名额、控制数量增长等措施。对评价得分较低的企业，加强重点监测。"},{"no":"十六","title":"第十六条","text":"经认定的专精特新中小企业和专精特新“小巨人”企业有效期3年，每次到期前由认定部门组织复核（含实地抽查）。复核通过的，有效期延长3年。"},{"no":"十七","title":"第十七条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，可登录培育平台查询认定状态和有效期，并在每年5月31日前通过培育平台更新企业信息。在同一个有效期内，对首次未进行更新的企业，重点监测；对累计达两次未更新的企业，取消认定。"},{"no":"十八","title":"第十八条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，如发生合并、重组等与认定条件有关的重大变化，应在发生变化后的3个月内登录培育平台，填写重大变化情况报告表。不再符合认定标准的专精特新中小企业，由省级中小企业主管部门核实后取消认定；不再符合认定标准的专精特新“小巨人”企业，由省级中小企业主管部门核实后报工业和信息化部，由工业和信息化部取消认定。对于未报告重大变化情况的，取消复核资格，或取消认定。"},{"no":"十九","title":"第十九条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，如发生简单更名，应在3个月内在培育平台上同步完成名称变更申请。如发生跨区域迁移，应在3个月内在培育平台上提交跨区域迁移申请，并与迁入地中小企业主管部门联系。后续由迁入地中小企业主管部门负责相关培育和服务监测等工作，迁出地中小企业主管部门应做好配合。"},{"no":"二十","title":"第二十条","text":"有效期内的专精特新中小企业和专精特新“小巨人”企业，如发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定、被列入严重失信主体名单，或被发现存在数据造假情形，取消认定且三年内不得再次申报。对取消认定后完成信用修复并移出严重失信主体名单的企业，以及按照行业管理规定要求完成整改并获得相关行业管理部门认可的企业，可以三年内再次申报。"},{"no":"二十一","title":"第二十一条","text":"各级中小企业主管部门应完善机制，加强对优质中小企业的风险监测与处置，涉及专精特新“小巨人”企业的重大风险，应及时上报工业和信息化部。"},{"no":"二十二","title":"第二十二条","text":"任何组织和个人可针对优质中小企业相关信息真实性、准确性等方面存在的问题，向负责该企业认定的中小企业主管部门实名举报，并提供佐证材料和联系方式。对受理的举报内容，中小企业主管部门应及时向被举报企业核实。被举报企业未按要求回复或经核查举报内容属实的，视情节轻重要求企业整改，或取消认定。\n第四章 培育服务"},{"no":"二十三","title":"第二十三条","text":"各级中小企业主管部门应着力把功夫下到培育和服务上，坚持质量为先，不层层设定培育数量指标。针对本地区不同发展阶段、不同类型中小企业的特点和需求，强化政策支持、健全服务体系、完善企业治理和加强权益保护，不断优化中小企业发展环境，促进中小企业专精特新发展。"},{"no":"二十四","title":"第二十四条","text":"各级中小企业主管部门应认真贯彻落实建设全国统一大市场和规范招商引资行为有关政策要求，加强部门协同、上下联动。统筹运用财税、金融、科技、产业、人才等政策工具，加强用地、用能、用数等要素保障，着力推动惠企政策“免申即享、直达快享”，提高政策精准性和有效性。"},{"no":"二十五","title":"第二十五条","text":"各级中小企业主管部门应着力构建公共服务与市场化服务相互促进的服务体系。推动各级中小企业公共服务机构扩面提质，共同打造线上线下深度融合的全国中小企业服务网，提升服务覆盖面和企业获得感。发挥国家中小企业公共服务示范平台（基地）、中小企业特色产业集群、科技型企业孵化器、校企协同育人基地等平台载体作用，坚持中小企业需求导向，聚焦技术创新、大中小企业融通、数智化转型、权益保护、市场开拓、融资促进、管理提升、国际化发展等领域，提供精准高效公共服务。建立健全服务专员队伍，加强优质中小企业对口联系帮扶。广泛汇聚市场化服务资源，鼓励引导市场化服务机构提高服务标准化、规范化、精准化水平，不断丰富服务产品、提升服务质量。"},{"no":"二十六","title":"第二十六条","text":"各级中小企业主管部门应加强指导，强化人才教育培训，通过政府购买专业机构服务等方式加强面向中小企业的经营管理诊断、精益生产等咨询服务，促进中小企业提升公司治理和经营管理水平。充分发挥企业党组织作用，大力弘扬企业家精神、工匠精神和工程师文化，提升企业凝聚力和竞争力。"},{"no":"二十七","title":"第二十七条","text":"各级中小企业主管部门应积极会同有关部门强化落实支持中小企业发展的有关法律制度，依法保护中小企业产权和知识产权等合法权益。"},{"no":"二十八","title":"第二十八条","text":"在企业认定和培育服务过程中，各级中小企业主管部门及其相关工作人员应当保护企业商业秘密。\n第五章 附则"},{"no":"二十九","title":"第二十九条","text":"与优质中小企业产生投融资、并购重组、交易合作等相关市场行为，由相关主体自主决策、自行负责。"},{"no":"三十","title":"第三十条","text":"科技和创新型中小企业有关要求和标准，以工业和信息化部联合有关部门制定发布的文件为准。在相关文件发布前，科技和创新型中小企业涵盖有效期内的科技型中小企业和创新型中小企业，相关工作继续按照原有标准、工作程序和职责分工开展。"},{"no":"三十一","title":"本办法自2026年4月1日起实施","text":"本办法自2026年4月1日起实施。原《优质中小企业梯度培育管理暂行办法》中涉及专精特新中小企业和专精特新“小巨人”企业相关条款和认定标准同时废止。在本办法实施前认定的专精特新中小企业和专精特新“小巨人”企业继续有效，有效期到期后自动失效，失效后按本办法重新认定或复核。"},{"no":"三十二","title":"本办法由工业和信息化部负责解释","text":"本办法由工业和信息化部负责解释。\n附件1\n专精特新中小企业认定标准\n需同时满足以下六项指标：\n（一）已获得科技和创新型中小企业称号，截至上年末从事特定细分市场时间达3年以上。\n（二）上年度营业收入总额达1500万元以上或近两年新增股权投资（合格机构投资者的实缴额）总额2000万元以上，主营业务收入总额占营业收入总额比重不低于80%，上年末资产负债率不超过80%。\n（三）近两年研发费用均不低于100万元，且每年占营业收入比重均不低于3%。\n（四）拥有1项以上与主导产品相关的Ι类知识产权，且实际应用并已产生经济效益。对近三年获得省部级以上科学技术奖励（排名前三）或拥有经认定的省部级以上研发机构的企业，不考察本项指标。\n（五）主导产品在国内或国际细分市场占有率较为靠前，且享有一定知名度、影响力。\n（六）本年度中小企业专精特新发展评价得分达50分以上（复核企业近两年任意一年达50分以上即可）。指标体系见《中小企业专精特新发展评价指标体系（试行）》。\n附件2\n专精特新“小巨人”企业认定标准\n需同时满足以下七项指标：\n（一）已获得专精特新中小企业称号，截至上年末从事特定细分市场时间达3年以上。\n（二）上年度营业收入总额达5000万元以上，主营业务收入总额占营业收入总额比重不低于90%。近两年营业收入复合增长率不低于5%（复核企业不考查该项指标），上年末资产负债率不超过75%。\n（三）近两年研发费用合计不低于1200万元，且每年占营业收入比重均不低于3%。\n（四）拥有4项以上与主导产品相关的Ι类知识产权，且实际应用并已产生经济效益。对近三年获得国家级科技奖励（排名前三）的企业，不考察本项指标。\n（五）主导产品在国内或国际细分市场占有率达到10%以上或国内前三名，且享有较高知名度、影响力。\n（六）主导产品属于制造业核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础，或属于改造提升传统产业、培育壮大新兴产业、布局建设未来产业，位于产业链关键环节，对提升产业链供应链韧性和安全水平发挥重要作用。\n（七）本年度中小企业专精特新发展评价得分达60分以上（复核企业近两年任意一年达60分以上即可）。指标体系见《中小企业专精特新发展评价指标体系（试行）》。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/zcfg/gjjfg/202606/t20260615_34002090.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"clause","bodyVerified":"verbatim","hunan":false},{"id":"p-2026-76cd70","title":"衡阳市人民政府关于印发《关于全面落实\"三高四新\"美好蓝图进一步推动制造业高质量发展的若干支持政策》的通知","level":"city","region":"衡阳市","issuer":"衡阳市人民政府","documentNo":"衡政发〔2026〕1号","publishedAt":"2026-03-03","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业","高校毕业生"],"summary":"衡阳对新获评国家级、省级专精特新中小企业分别给予15万元、5万元奖励；国家专精特新\"小巨人\"项目最高补助30万元；数字化转型项目最高贴息60万元。","sections":[{"no":"一","title":"聚焦产业培塑，推动制造业提档升级","text":"聚焦产业培塑，推动制造业提档升级\n1.支持设备更新和技术改造。持续用力打造先进制造业高地，力促规模工业企业\"原地倍增\"，引导企业实施智能化、绿色化、融合化及本质安全改造等设施更新和技术改造项目。支持企业争取中央设备更新贷款贴息、省级工业企业设备更新和技术改造融资补贴，用足用好超长期特别国债资金，促进工业、电子信息、能源电力等重点领域企业加快更新改造步伐。\"原地倍增\"企业实施设备更新和技术改造项目，当年项目总投资达到200万元以上的，市级财政对项目一年期(含)以上贷款按贷款本金的2%给予贴息，单个企业最高不超过200万元；申请贷款贴息项目，设备投资占贷款金额比例应不低于30%。同一项目只能享受中央、省级、市级融资补贴中的一项。(责任部门:市工信局)\n2.推进企业加快数字化转型。深化\"智赋万企\"行动，提升中小企业数字化水平及核心竞争力，对数字化转型升级项目，年投资在200万元以上，单个企业自贷款合同签订后首次付息日起连续12个月按照年基准利率的60%予以贴息补助，最高不超过60万元(\"原地倍增\"贴息、数字化转型贴息原则上不重复享受)。支持开展数字化转型咨询诊断，鼓励企业争取省级诊断服务费补贴资金。(责任部门:市工信局)\n对新获评国家工信部相关试点示范项目、省级工业互联网平台、省级\"5G+工业互联网标杆工厂\"，给予每家最高不超过10万元奖励。对新获评\"两化\"融合管理体系贯标企业、数字化转型成熟度贯标企业、省级人工智能赋能新型工业化典型应用场景企业、省级数字新基建项目，给予每家不超过5万元奖励。带动产业链上下游更多配套中小企业\"上云上平台\"，培育\"上云上平台\"示范企业，给予每家不超过5万元补助。对通过工业互联网网络安全分类分级管理考核或工业和信息化领域数据安全管理考核的企业，给予每家不超过2万元补助。(责任部门:市工信局)\n3.培育壮大市场主体。对首次认定的规模以上工业企业，每家给予10万元的达规入统奖励。首次认定的资质等级建筑业企业、资质等级房地产开发企业、限额以上批零住餐企业、规模以上服务业企业每家分别给予2万元的达规入统奖励。培育专精特新企业，对新获评的国家级、省级专精特新中小企业分别给予15万元、5万元奖励。支持中小企业专精特新发展，推动中小企业转型升级，对国家专精特新\"小巨人\"企业、湖南省专精特新中小企业专精特新发展类项目按项目建设支出比例分别给予最高不超过30万元、20万元补助。支持举办\"创客中国\"衡阳市中小微企业创新创业大赛。加强中小企业服务体系建设，支持省级核心服务机构提升服务能力或开展相关服务业务，根据服务能力建设支出或服务业务支出规模进行补助，最高可补助10万元。降低企业上市股改税费成本，支持企业改制重组依规享受契税、土地增值税、所得税等相关减免与税务处理政策。积极推动企业依规申报多层次资本市场建设奖补资金。(责任部门:市政府办、市工信局、市发改委、市住建局、市商务局、市统计局、市税务局)\n4.打造制造业标杆企业。推动智能制造关键核心技术攻关，助力企业提升发展优势及市场份额，对新获评国家智能制造系统解决方案\"揭榜挂帅\"企业给予20万元奖励。对新认定的国家级、省级制造业单项冠军分别给予20万元、10万元奖励。对新认定的卓越级智能工厂、先进级智能工厂分别给予每家10万元、5万元奖励。鼓励企业开展产品全生命周期绿色管理，构建绿色制造体系，对新认定的省级绿色工厂、绿色供应链管理企业给予10万元奖励。对新认定的省级、市级消费品\"三品\"标杆企业，分别给予10万元、5万元奖励。对当年认定为湖南省首台套重大技术装备、首批次重点新材料、首版次软件、首套件基础电子元器件、首轮次工程流片芯片(简称\"五首\")产品的企业，给予每家不超过10万元奖励。对新增的\"军工资质\"企业给予10万元奖励；对国、省级军民融合示范项目企业，分别给予20万元、10万元奖励。(责任部门:市工信局、市委军民融合办)"},{"no":"二","title":"激发企业活力，增强科技创新发展动能","text":"激发企业活力，增强科技创新发展动能\n5.提升技术创新水平。对首次、再次获得认定的高新技术企业分别一次性奖励10万元、3万元。培育国省科技奖励企业，对入选企业给予10万元奖励；支持科技创新重大项目，每个给予30万元奖励；支持重点研发项目，每个给予10万元奖励；支持基础应用研究，每项给予3万元奖励。设立400万元企业研发费用辅导专项资金，支持县市区辅导企业建立规范的研发费用归集机制并做好会计辅助账。设立科技成果转化专项经费100万元，支持科技成果转化及转化服务能力提升项目。支持企业引进科技人才，支持举办\"双创大赛\"，营造创新创业氛围，提升企业创新创业水平。(责任部门:市科技局)\n6.促进产学研用深度融合。鼓励各产业链领军企业与相关高校、科研院所开展产学研合作，组建创新联合体。对重点产学研合作项目、一般产学研合作项目分别给予30万元、10万元补助，创新联合体给予20万元补助。对新认定的重点实验室、技术创新中心，按照国家级50万元、省级20万元标准，分别给予一次性奖励；对新列入的国家、省级科技孵化器，分别给予30万元、10万元项目资助；对新认定的工程研究中心、企业技术中心(发改部门评定)，按照国家级50万元、省级20万元标准，分别给予一次性奖励；对新认定的省级企业技术中心、省级工业设计中心(工信部门评定)，给予10万元奖励。统筹设立专项资金1亿元，支持衡阳智能衡器计量产业园加快建设国家计量人才实训中心、国家产业计量测试中心等公共技术平台，围绕产业发展开展技术攻关和应用示范；鼓励衡阳智能衡器计量产业园与知名院校、科研院所在人才培养、技术创新等方面开展合作，提高产业集聚程度。(责任部门:市科技局、市发改委、市工信局、衡阳智能衡器计量产业园)\n7.强化标准引领作用。鼓励企业积极参与标准制定，对主持、参与标准制定的企业进行奖励。对主持制定国际标准、国家标准的企业给予奖励，最高不超过40万元；参与制定国际标准、国家标准的企业，最高不超过15万元；主持、参与制定行业标准的企业，最高不超过15万元、10万元；主持、参与制定湖南省地方标准的企业，最高不超过10万元、5万元奖励(同一企业同一标准不重复奖励，累计奖励不超过100万元)。支持企业争创质量奖，对首次获得中国质量奖、省长质量奖、市长质量奖、湖南名品的企业，分别给予50万元、30万元、10万元、10万元奖励。利用物联网、云计算、大数据等技术手段，积极打造数字化、信息化、智能化的\"阳光计量\"交易及监管模式。(责任部门:市市场监管局、衡阳智能衡器计量产业园)\n8.推动知识产权量质齐升。提升知识产权创造运用水平及服务管理能力，对知识产权强链增效项目按10万元/个进行补助，对知识产权重点企业保护项目按6万元/个进行补助，对地理标志运用保护培育工程项目按6万元/个进行补助，对高价值发明专利培育及专利转化运用项目按10万元/个进行补助，对公共服务平台建设项目按10万元/个进行补助，对知识产权优质服务机构建设项目按5万元/个进行补助。对海外知识产权保护项目按6万元/个进行补助。对经国家知识产权局质押登记的专利、商标、数据知识产权质押融资予以补助，根据单笔融资额的0.2%予以补助，最高不超过3万元。(责任部门:市市场监管局)"},{"no":"三","title":"改善融资环境，提升金融服务质效","text":"改善融资环境，提升金融服务质效\n9.发挥产业基金带动效应。树立全市产业基金\"一盘棋\"思想，深化财政资金\"拨改投\"改革，精准布局战略性新兴产业，培育壮大耐心资本，以市场化基金运作方式支持企业发展。强化联动协同，对接省级金芙蓉等基金资源，协同已参股子基金形成合力，并推动有条件的县市区(园区)出资入股，支持市属国企围绕主业设立相关基金，共同扩大惠企资本供给。畅通产融对接，建立由市发改、工信、商务等部门及各园区负责的重点产业链优质项目定期推送机制，引导基金提前介入、予以支持。优化激励与风险管控，在坚守政策目标与资金安全底线的前提下，对实现综合超额收益的基金，可在收益分配上对管理机构及社会出资人给予适当让利，吸引更多社会资本参与企业培育。(责任部门:市发改委、市工信局、市财政局、市商务局、市国资委)\n10.落实创(就)业补贴政策。通过财政贴息引导金融机构加大创业担保贷款投放。对符合创业担保贷款条件的小微企业，按照贷款合同签订日贷款利率(且贷款利率在LPR+150PB以内)的50%给予贴息，贷款额度最高为400万元；贷款期限最长不超过2年；已享受过创业担保贷款政策的小微企业，贷款无逾期还清后可再次享受创业担保贷款，累计次数不得超过3次，再次享受时吸纳就业人员不得与之前申请时吸纳人员重复。落实财政补助支持实施各项就业扶持政策，对符合条件人员参加职业技能培训、高技能人才培训基地和技能大师工作室建设、公共就业服务机构服务能力建设等给予就业创业服务补助。鼓励用人单位吸纳就业，对就业见习、自主创业、就业参保给予补贴。按规定对就业困难人员、困难高校毕业生给予求职帮扶补贴。(责任部门:市财政局、市人社局)\n11.完善政府性融资担保体系。为企业提供融资担保和\"临时性超短期贷款\"(转贷)服务，备案担保项目单户融资担保金额原则上不超过1500万元，对于符合\"民间投资专项担保计划\"的担保额度最高可达2000万元(期限1年以上)，对于科技创新型中小企业单户融资担保金额最高可达3000万元。大力推广\"人才创业贷款担保\"等金融产品，为毕业5年内在我市中心城区自主创业、合伙经营的大学生提供30-110万元融资担保政策；为招用高校毕业生达到一定数量的小微企业提供最高500万元融资担保贷款，对担保费予以优惠。推动普惠金融高质量发展，依托普惠金融发展专项资金，加大对市融资担保公司资本注入力度，鼓励市融资担保公司及市小额贷款公司为中小微企业提供低费用非融资保函等服务，促进政府融资担保扩围加力。(责任部门:市财政局、市融资担保公司)"},{"no":"四","title":"强化服务保障，助力企业降本增效","text":"强化服务保障，助力企业降本增效\n12.优化政府采购环境。符合法定条件的供应商凭《湖南省政府采购供应商资格承诺函》参与政府采购活动，免收投标保证金及采购文件工本费。中小企业凭《中小企业申明函》享受相关评审价格扣除优惠政策。采取保函、电子增信等非现金形式缴纳合同履约保证金，对资信良好的中标企业，鼓励支持采购单位免收履约保证金。预算200万元以下的货物、服务项目和400万元以下的工程项目适宜由中小企业提供的，应面向中小企业采购；上述标准以上的项目适宜由中小企业提供的，应预留40%以上的份额专门面向中小企业，其中小微企业不低于60%。全面推行政府采购贷，中标企业凭政府采购中标通知书和政府采购合同，在湖南政府采购网衡阳分网线上融资平台上自主选择金融机构进行政府采购合同融资。搭建政府采购全流程查询与线上投诉平台，供应商可即时查询相关信息，提升政府采购的公开透明程度。(责任部门:市财政局)\n以上措施自公布之日起实施，有效期至2028年12月31日。执行过程中，如上级及我市另行出台文件对政策期限进行规定的，从其规定。本文件按现行财政体制按比例分级负担，市财政统一结算。各责任部门要结合自身职责职能制定实施细则，实行全程跟踪服务，加强政策宣传和对接，确保政策直达快享，力争各项政策的施行取得更大实效，进一步助推全市制造业高质量发展。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202610/t20261023_34087305.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"p-2026-d6dec6","title":"关于组织开展2026年湖南省专精特新中小企业申报和复核工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅","documentNo":"","publishedAt":"2026-01-27","status":"active","tags":["认定资质"],"audience":["小微企业"],"summary":"申报企业应在湖南省内工商登记注册、符合《专精特新中小企业认定标准》且须是省工业和信息化厅已公告的湖南省创新型中小企业，申报（复核）时间为2026年1月28日—2026年3月4日，须在优质中小企业梯度培育平台完成数字化水平评测后线上申报。","sections":[{"no":"一","title":"条件标准","text":"1、申报企业应在湖南省内工商登记注册，具有独立法人资格，符合《中小企业划型标准规定》。\n\n2、企业未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生重大安全（含网络安全、数据安全）、质量、环境污染等事故以及偷漏税等违法违规行为。\n\n3、坚持企业自愿原则，符合《专精特新中小企业认定标准》（工信部企业〔2022〕63号，附件1）。\n\n4、重点聚焦制造强国重点产业（新一代信息技术产业、高档数控机床和机器人、航空航天装备、海洋工程装备及高技术船舶、先进轨道交通装备、节能与新能源汽车、电力装备、农机装备、新材料、生物医药及高性能医疗器械）、工业“六基”（核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础）、“4×4”现代化产业体系（现代石化、绿色矿业、食品加工、轻工纺织4大传统产业，工程机械、轨道交通装备、现代农业、文化旅游4大优势产业，数字、新能源、大健康、空天海洋4大新兴产业，以及人工智能、生命工程、量子科技、前沿材料4大未来产业）等领域。"},{"no":"二","title":"申报（复核）时间","text":"2026年1月28日-2026年3月4日"},{"no":"三","title":"申报（复核）方式","text":"1、申报企业须是省工业和信息化厅已公告的湖南省创新型中小企业。有效期内的专精特新中小企业（湖南省专精特新“小巨人”企业）、专精特新“小巨人”企业不再申报。\n\n2、本次复核的企业为2022年、2023年认定和复核的湖南省专精特新“小巨人”企业，复核公告文件发布之前，企业仍属于有效期内的专精特新中小企业。有效期内的国家级专精特新“小巨人”企业无需参与复核。\n\n3、按属地原则，申报（复核）企业须首先在优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下称“培育平台”）完成数字化水平评测，然后在培育平台进行线上申报和复核，完整填写《专精特新中小企业申请书》，并打包上传佐证材料（附件2）。"},{"no":"四","title":"有关要求","text":"1、各市州工信部门要高度重视专精特新中小企业培育工作，认真履行职责，坚持条件标准，严格审核把关，确保申报（复核）质量。\n\n2、请各市州工信部门于3月4日前在培育平台提交审核意见，并将专精特新中小企业推荐函和汇总表（附件3，纸质件2份）报省工业和信息化厅，逾期不候。\n\n3、严禁弄虚作假。申报（复核）企业对申报材料的完整性、真实性、合法性负责，相关后果由申报（复核）企业自行承担。凡在申报（复核）过程中存在弄虚作假行为的，一经发现，取消本年度申报（复核）资格，并且三年内不得再次申报。\n\n4、严禁代理申报。省工业和信息化厅从未委托任何单位或个人为企业代理申报事宜，请相关企业按程序自主申报。凡委托代理申报的，一经发现，取消参评资格，且三年内不得再次申报。各级工信部门受理申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并请向当地相关部门举报。任何单位不得以参加收费培训班或解读班作为企业申报前提条件。\n\n联系电话：0731-88955419\n\n邮寄地址：长沙市天心区新韶东路467号\n\n培育平台相关问题咨询电话：85559832"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202601/t20260128_33904604.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2026-01-28","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":true},{"id":"vat-law-transition-preferential-2026","title":"财政部 税务总局关于增值税法施行后增值税优惠政策衔接事项的公告","level":"national","region":"全国","issuer":"财政部、税务总局","documentNo":"财政部 税务总局公告2026年第10号","publishedAt":"2026-02-28","effectiveAt":"2026-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠"],"audience":["小规模纳税人","小微企业","个体工商户"],"summary":"2026年至2027年，小规模纳税人月销售额10万元以下免征增值税，3%征收率应税收入减按1%征收。","sections":[{"no":"一","title":"增值税起征点标准","text":"自2026年1月1日至2027年12月31日,小规模纳税人发生应税交易,起征点标准如下:\n\n(一)以一个月为一个计税期间的,起征点为月销售额10万元。以一个季度为一个计税期间的,起征点为季度销售额30万元。\n\n(二)按次纳税的,起征点为每次(日)销售额1000元。一日内发生多次应税交易的,按日适用起征点标准。\n\n小规模纳税人发生应税交易,按照规定以扣除相关价款后的余额计算销售额或者允许从含税销售额中扣除相关价款后计算应纳税额的,以扣除相关价款后的不含税余额,适用本条起征点标准。"},{"no":"二","title":"免征增值税的项目","text":"(一)自2026年1月1日起,下列项目免征增值税。\n\n1.农业生产者销售的自产农产品。\n\n《中华人民共和国增值税法实施条例》(以下简称增值税法实施条例)第二十六条所称从事农业生产,是指直接从事植物的种植、收割和动物的饲养、捕捞;初级农产品,是指《财政部 税务总局关于增值税征税具体范围有关事项的公告》(财政部 税务总局公告2026年第9号)附件1《适用9%增值税税率货物范围注释》中的农产品。\n\n纳税人销售外购的初级农产品,以及用外购农产品生产、加工的初级农产品,不属于本项目免征增值税的范围,应当按照规定缴纳增值税。\n\n2.农业机耕、排灌、病虫害防治、植物保护、农牧保险以及相关技术培训业务,家禽、牲畜、水生动物的配种和疾病防治。\n\n增值税法第二十四条第一款第一项所称农业机耕,是指在农业、林业、畜牧业中使用农业机械进行耕作(包括耕耘、种植、收割、脱粒、植物保护等)的业务;排灌,是指对农田进行灌溉或者排涝的业务;病虫害防治,是指从事农业、林业、畜牧业、渔业的病虫害测报和防治的业务;农牧保险,是指为种植业、养殖业、畜牧业种植和饲养的动植物提供保险的业务;相关技术培训,是指与农业机耕、排灌、病虫害防治、植物保护业务相关以及为使农民获得农牧保险知识的技术培训业务;家禽、牲畜、水生动物的配种和疾病防治,包括与该项服务有关的提供药品和医疗用具的业务。\n\n3.医疗机构提供的医疗服务。\n\n增值税法实施条例第二十七条所称医疗机构,具体包括:各级各类医院、门诊部(所)、社区卫生服务中心(站)、急救中心(站)、城乡卫生院、护理院(所)、疗养院、临床检验中心,各级政府及有关部门举办的卫生防疫站(疾病控制中心)、各种专科疾病防治站(所),各级政府举办的妇幼保健所(站)、母婴保健机构、儿童保健机构,各级政府举办的血站(血液中心)等医疗机构,不包括营利性美容医疗机构。\n\n增值税法第二十四条第一款第二项所称医疗服务,是指医疗机构按照不高于地市级以上医疗保障部门牵头制定的医疗服务价格(包括政府指导价和按照规定由供需双方协商确定的价格等),为就医者提供《全国医疗服务价格项目规范》所列的各项服务,以及医疗机构向社会提供卫生防疫、卫生检疫的服务。\n\n4.残疾人个人提供的服务。\n\n增值税法第二十四条第一款第六项所称残疾人个人提供的服务,是指残疾人本人为社会提供的服务。\n\n5.托儿所、幼儿园提供的育养服务。\n\n增值税法实施条例第二十九条所称有关收费标准,是指公办托儿所、幼儿园经当地有关部门批准的收费标准,以及民办托儿所、幼儿园实行政府指导价管理或政府设置参考区间的实际收费标准。\n\n保育费、保育教育费超过规定收费标准的,以及以开办实验班、特色班和兴趣班等名义收取的费用,与入托、入园挂钩的赞助费、支教费等超过规定范围的各种费用,不属于免征增值税的范围。\n\n6.殡葬服务。\n\n增值税法第二十四条第一款第七项所称的殡葬服务,是指收费标准由各地价格主管部门会同有关部门核定,或者实行政府指导价管理的遗体接运(含抬尸、消毒)、遗体整容、遗体防腐、遗体存放(含冷藏)、遗体火化、骨灰寄存、吊唁设施设备租赁、墓穴租赁及管理等服务。\n\n7.学校提供的学历教育服务。\n\n(1)增值税法第二十四条第一款第八项所称的学历教育,具体包括:\n\n初等教育:普通小学、成人小学。\n\n初级中等教育:普通初中、职业初中、成人初中。\n\n高级中等教育:普通高中、成人高中、中等职业学校(包括普通中专、成人中专、职业高中、技工学校)。\n\n高等教育:普通本专科、成人本专科、网络本专科、研究生(博士、硕士)、高等教育自学考试、高等教育学历文凭考试。\n\n(2)增值税法实施条例第三十条所称学校,具体包括:\n\n普通学校;经地市级以上人民政府或者同级政府的教育行政部门批准成立、国家承认其学员学历的各类学校;经省级及以上人力资源社会保障行政部门批准成立的技工学校、高级技工学校;经省级人民政府批准成立的技师学院。上述学校均包括符合规定的从事学历教育的民办学校,但不包括职业培训机构等国家不承认学历的教育机构。\n\n(3)提供学历教育服务免征增值税的收入,是指学校为列入规定招生计划的在籍学生提供学历教育服务取得的收入,具体包括:经有关部门审核批准并按规定标准收取的学费、住宿费、课本费、作业本费、考试报名费收入,以及学校食堂提供餐饮服务取得的伙食费收入。除此之外的收入,包括学校以各种名义收取的赞助费、择校费等,不属于免征增值税的范围。\n\n8.农业生产用地,具体包括:\n\n(1)将国有农用地出租给农业生产者用于农业生产。\n\n(2)将土地使用权转让给农业生产者用于农业生产。\n\n(3)采取转包、出租、互换、转让、入股等方式将承包地流转给农业生产者用于农业生产。\n\n9.个人从事金融商品转让业务取得的收入。\n\n10.美国船级社(ABS)在非营利宗旨不变、中国船级社在美国享受同等免税待遇的前提下,在中国境内提供的船检服务。\n\n11.台湾航运公司、航空公司从事海峡两岸海上直航、空中直航业务在大陆取得的运输收入。\n\n台湾航运公司,是指取得交通运输部颁发的“台湾海峡两岸间水路运输许可证”且该许可证上注明的公司登记地址在台湾的航运公司。\n\n台湾航空公司,是指取得中国民用航空局颁发的“经营许可”或者依据《海峡两岸空运协议》和《海峡两岸空运补充协议》规定,批准经营两岸旅客、货物和邮件不定期(包机)运输业务,且公司登记地址在台湾的航空公司。\n\n12.土地所有者出让土地使用权和土地使用者将土地使用权归还给土地所有者。\n\n13.县级以上地方人民政府或自然资源行政主管部门出让、转让或收回自然资源使用权(不含土地使用权)。\n\n14.香港市场投资者(包括单位和个人)买卖股票、基金,具体包括:\n\n(1)通过深港通买卖深圳证券交易所上市A股取得的收入。\n\n(2)通过沪港通买卖上海证券交易所上市A股取得的收入。\n\n(3)通过基金互认买卖内地基金份额取得的收入。\n\n15.被撤销金融机构以货物、不动产、无形资产、有价证券、票据等财产清偿债务。\n\n被撤销金融机构,是指经中国人民银行、金融监管总局依法决定撤销的金融机构及其分设于各地的分支机构,包括被依法撤销的商业银行、信托公司、财务公司、金融租赁公司、信用社。除另有规定外,被撤销金融机构所属、附属企业,不享受被撤销金融机构增值税免税政策。\n\n16.人民银行对金融机构的贷款的利息收入。\n\n17.外汇管理部门在从事国家外汇储备经营过程中,委托金融机构发放的外汇贷款取得的利息收入。\n\n18.个人(不含个体工商户中的一般纳税人)销售自建自用住房。\n\n19.涉及家庭财产分割的个人无偿转让不动产、土地使用权。\n\n家庭财产分割,包括下列情形:离婚财产分割;无偿赠予配偶、父母、子女、祖父母、外祖父母、孙子女、外孙子女、兄弟姐妹;无偿赠予对其承担直接抚养或者赡养义务的抚养人或者赡养人;房屋产权所有人死亡,法定继承人、遗嘱继承人或者受遗赠人依法取得房屋产权。\n\n20.执法部门和单位处置罚没财产收入,且作为罚没收入如数上缴财政的。\n\n21.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 国家税务总局 外经贸部关于外国政府和国际组织无偿援助项目在华采购物资免征增值税问题的通知》(财税〔2002〕2号)和《财政部 国家税务总局关于外国政府和国际组织无偿援助项目在华采购物资免征增值税的补充通知》(财税〔2005〕13号)。\n\n(2)《财政部 税务总局关于全国社会保障基金有关投资业务税收政策的通知》(财税〔2018〕94号)。\n\n(3)《财政部 税务总局关于基本养老保险基金有关投资业务税收政策的通知》(财税〔2018〕95号)。\n\n(4)《财政部 税务总局 证监会关于交易型开放式基金纳入内地与香港股票市场交易互联互通机制后适用税收政策问题的公告》(财政部 税务总局 证监会公告2022年第24号)。\n\n(5)《财政部 税务总局关于法律援助补贴有关税收政策的公告》(财政部 税务总局公告2022年第25号)。\n\n(6)《财政部 税务总局关于国债等债券利息收入增值税政策的公告》(财政部 税务总局公告2025年第4号)。\n\n(7)《财政部 税务总局关于划转充实社保基金国有股权及现金收益运作管理税收政策的通知》(财税〔2025〕26号)。\n\n(二)自2026年1月1日至2027年12月31日,下列项目免征增值税。\n\n1.农业生产资料。\n\n(1)农膜、滴灌带、滴灌管和有机肥产品。\n\n(2)饲料产品。具体包括:\n\n单一大宗饲料。指以一种动物、植物、微生物或矿物质为来源的产品或其副产品。其范围仅限于糠麸、酒糟、鱼粉、饲用鱼油、草饲料及除豆粕以外的菜籽粕、棉籽粕、向日葵粕、花生粕等粕类产品。\n\n混合饲料。指由两种以上单一大宗饲料、粮食、粮食副产品及饲料添加剂按照一定比例配置,其中单一大宗饲料、粮食及粮食副产品的掺兑比例不低于95%的饲料。\n\n配合饲料。指根据不同的饲养对象的不同生长发育阶段的营养需要,将多种饲料原料按饲料配方经工业生产后,形成能满足饲养动物全部营养需要(除水分外)的饲料。\n\n复合预混料。指能够按照国家有关饲料产品的标准要求量,全面提供动物饲养相应阶段所需微量元素(4种或以上)、维生素(8种或以上),由微量元素、维生素、氨基酸和非营养性添加剂中任何两类或两类以上的组分与载体为原料、经高压浓缩制成的块状预混物,可供牛、羊等牲畜直接食用的饲料,属于浓缩饲料。\n\n浓缩饲料。指由蛋白质、复合预混料及矿物质等按一定比例配制的均匀混合物。\n\n矿物质微量元素舔砖。指以四种以上微量元素、非营养性添加剂和载体为原料,经高压浓缩制成的块状预混物,可供牛、羊等牲畜直接食用的饲料,属于浓缩饲料。\n\n宠物饲料不属于免征增值税的饲料。\n\n(3)批发和零售的种子、种苗、农药、农机。农机包括不带动力的手扶拖拉机和三轮农用运输车。\n\n(4)农民专业合作社销售本社成员生产的初级农产品,属于农业生产者销售的自产农产品。\n\n农民专业合作社向本社成员销售的农膜、种子、种苗、农药、农机。\n\n农民专业合作社,是指依法设立和登记的农民专业合作社。\n\n2.纳税人提供技术转让、技术开发和与之相关的技术咨询、技术服务。\n\n技术转让、技术开发,是指《财政部 税务总局关于增值税征税具体范围有关事项的公告》(财政部 税务总局公告2026年第9号)附件2《销售服务、无形资产、不动产注释》中的转让“技术”、提供“研发服务”范围内的业务活动。技术咨询,是指就特定技术项目提供可行性论证、技术预测、专题技术调查、分析评价报告等业务活动。与技术转让、技术开发相关的技术咨询、技术服务,是指转让方(或者受托方)根据技术转让或者委托开发合同的规定,为帮助受让方(或者委托方)掌握所转让(或者委托开发)的技术,而提供的技术咨询、技术服务业务,且这部分技术咨询、技术服务的价款与技术转让或者技术开发的价款应当在同一张发票上开具。\n\n纳税人申请免征增值税时,须持技术转让、开发的书面合同,到纳税人所在地省级科技、工信主管部门进行认定,并持有关的书面合同和科技、工信主管部门审核意见证明文件报主管税务机关备查。\n\n3.个人转让著作权。\n\n4.按照国家规定的收费标准向学生收取的高校学生公寓住宿费收入和高校学生食堂为高校师生提供餐饮服务取得的收入。\n\n5.家政服务企业由员工制家政服务员提供家政服务取得的收入。\n\n家政服务企业,是指在企业营业执照的规定经营范围中包括家政服务内容的企业。员工制家政服务员,是指同时符合下列3个条件的家政服务员:\n\n(1)依法与家政服务企业签订半年及半年以上的劳动合同或者服务协议,且在该企业实际上岗工作。\n\n(2)家政服务企业为其按月足额缴纳了企业所在地人民政府根据国家政策规定的基本养老保险、基本医疗保险、工伤保险、失业保险等社会保险。对已享受新型农村养老保险和新型农村合作医疗等社会保险或者下岗职工原单位继续为其缴纳社会保险的家政服务员,如果本人书面提出不再缴纳企业所在地人民政府根据国家政策规定的相应的社会保险,并出具其所在乡镇或者原单位开具的已缴纳相关保险的证明,可视同家政服务企业已为其按月足额缴纳了相应的社会保险。\n\n(3)家政服务企业通过金融机构向其实际支付不低于企业所在地适用的经省级人民政府批准的最低工资标准的工资。\n\n6.国家助学贷款取得的利息收入。\n\n7.福利彩票、体育彩票的发行收入。\n\n8.社会团体收取的会费。\n\n社会团体,是指依照国家有关法律法规设立或登记并取得《社会团体法人登记证书》的非营利法人。会费,是指社会团体在国家法律法规、政策许可的范围内,依照社团章程的规定,收取的个人会员、单位会员和团体会员的会费。\n\n9.中国邮政集团有限公司及其所属邮政企业提供的邮政普遍服务和邮政特殊服务。\n\n10.军队转业干部和随军家属就业。\n\n(1)从事个体经营的军队转业干部,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n为安置自主择业的军队转业干部就业而新开办的企业,凡安置自主择业的军队转业干部占企业总人数60%(含)以上的,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n享受上述优惠政策的自主择业的军队转业干部必须持有师以上部队颁发的转业证件。\n\n(2)从事个体经营的随军家属,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n为安置随军家属就业而新开办的企业,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n享受税收优惠政策的企业,随军家属必须占企业总人数的60%(含)以上,并有军(含)以上政治和后勤机关出具的证明。\n\n随军家属必须有师以上政治机关出具的可以表明其身份的证明。\n\n按照上述规定,每一名随军家属可以享受一次免税政策。\n\n11.供残疾人专用的假肢、轮椅、矫型器(包括上肢矫型器、下肢矫型器、脊椎侧弯矫型器)。\n\n12.粮食和商品储备收入,具体包括:\n\n(1)销售政府储备食用植物油。\n\n(2)粮食经营企业经营军队用粮、救灾救济粮、水库移民口粮。\n\n军队用粮:指凭相关凭证按军供价供应中国人民解放军和中国人民武装警察部队的粮食。\n\n救灾救济粮:指经县(含)以上人民政府批准,凭相关凭证按规定的销售价格向需救助的灾民供应的粮食。\n\n水库移民口粮:指经县(含)以上人民政府批准,凭相关凭证按规定的销售价格供应给水库移民的粮食。\n\n(3)国家商品储备管理单位及其直属企业承担商品储备任务,从中央或者地方财政取得的利息补贴收入和价差补贴收入。国家商品储备管理单位及其直属企业,是指接受中央、省、市、县四级政府有关部门(或者政府指定管理单位)委托,承担粮(含大豆)、食用油、棉、糖、肉、盐(限于中央储备)等6种商品储备任务,并按有关政策收储、销售上述6种储备商品,取得财政储备经费或者补贴的商品储备企业。利息补贴收入,是指国家商品储备管理单位及其直属企业因承担商品储备任务从金融机构贷款,并从中央或者地方财政取得的用于偿还贷款利息的贴息收入。价差补贴收入包括销售价差补贴收入和轮换价差补贴收入。销售价差补贴收入,是指按照中央或者地方政府指令销售上述储备商品时,由于销售收入小于库存成本而从中央或者地方财政获得的全额价差补贴收入。轮换价差补贴收入,是指根据要求定期组织政策性储备商品轮换而从中央或地方财政取得的商品新陈品质价差补贴收入。\n\n13.纳税人提供的直接或者间接国际货物运输代理服务。\n\n(1)纳税人提供直接或者间接国际货物运输代理服务,向委托方收取的全部国际货物运输代理服务收入,以及向国际运输承运人支付的国际运输费用,必须通过金融机构进行结算。\n\n(2)纳税人为大陆与香港、澳门、台湾地区之间的货物运输提供的货物运输代理服务参照国际货物运输代理服务有关规定执行。\n\n(3)委托方索取发票的,纳税人应当就国际货物运输代理服务收入向委托方全额开具增值税普通发票。\n\n14.合格境外投资者(QFII)委托境内公司在我国从事证券买卖业务、人民币合格境外机构投资者(RQFII)委托境内公司在我国从事证券买卖业务,以及经中国人民银行认可的境外机构投资银行间本币市场取得的收入。银行间本币市场包括货币市场、债券市场以及衍生品市场。\n\n15.统借统还业务利息收入。\n\n统借统还业务利息收入,是指统借统还业务中,企业集团或企业集团中的核心企业以及集团所属财务公司按不高于支付给金融机构的借款利率水平或者支付的债券票面利率水平,向企业集团或者集团内下属单位收取的利息。\n\n统借方向资金使用单位收取的利息,高于支付给金融机构借款利率水平或者支付的债券票面利率水平的,应全额缴纳增值税。\n\n统借统还业务,是指:\n\n(1)企业集团或者企业集团中的核心企业向金融机构借款或对外发行债券取得资金后,将所借资金分拨给下属单位(包括独立核算单位和非独立核算单位,下同),并向下属单位收取用于归还金融机构或债券购买方本息的业务。\n\n(2)企业集团向金融机构借款或对外发行债券取得资金后,由集团所属财务公司与企业集团或者集团内下属单位签订统借统还贷款合同并分拨资金,并向下属单位收取用于归还金融机构或债券购买方本息的业务。\n\n16.公募证券投资基金(封闭式证券投资基金、开放式证券投资基金)管理人运用基金买卖股票、债券取得的收入。\n\n17.期货保税交割业务,具体包括:\n\n(1)经国务院批准对外开放的货物期货品种保税交割业务。\n\n(2)上海国际能源交易中心股份有限公司的会员和客户通过上海国际能源交易中心股份有限公司交易的原油期货保税交割业务,大连商品交易所的会员和客户通过大连商品交易所交易的铁矿石期货保税交割业务。\n\n(3)上海期货交易所的会员和客户通过上海期货交易所交易的期货保税交割业务。\n\n18.金融同业往来利息收入,具体包括:\n\n(1)金融机构与人民银行所发生的资金往来业务。包括人民银行对一般金融机构贷款,商业银行购买央行票据、与央行开展货币掉期和货币互存,以及人民银行对商业银行的再贴现等。\n\n(2)银行联行往来业务。包括同一银行系统内部不同行、处之间所发生的资金往来业务,境内银行与其境外的总机构、母公司之间的资金往来业务,以及境内银行与其境外的分支机构、全资子公司之间的资金往来业务。\n\n(3)金融机构间的资金往来业务。是指经人民银行批准,进入全国银行间同业拆借市场的金融机构之间通过全国统一的同业拆借网络进行的短期(一年以下,含一年)无担保资金融通行为。\n\n(4)金融机构开展同业存款、同业借款、同业代付、买断式买入返售金融商品、质押式买入返售金融商品、同业存单,取得的利息收入。\n\n同业存款,是指金融机构之间开展的同业资金存入与存出业务,其中资金存入方仅为具有吸收存款资格的金融机构。\n\n同业借款,是指法律法规赋予此项业务范围的金融机构开展的同业资金借出和借入业务。其中,法律法规赋予此项业务范围的金融机构主要是指农村信用社之间以及在农村信用社营业执照业务范围中有反映为向金融机构借款业务的农村信用社。\n\n同业代付,是指商业银行(受托方)接受金融机构(委托方)的委托向企业客户付款,委托方在约定还款日偿还代付款项本息的资金融通行为。\n\n买断式买入返售金融商品,是指金融商品持有人(正回购方)将债券等金融商品卖给债券购买方(逆回购方)的同时,交易双方约定在未来某一日期,正回购方再以约定价格从逆回购方买回相等数量同种债券等金融商品的交易行为。\n\n质押式买入返售金融商品,是指交易双方进行的以债券等金融商品为权利质押的一种短期资金融通业务。\n\n同业存单,是指银行业存款类金融机构法人在全国银行间市场上发行的记账式定期存款凭证。\n\n金融机构,是指银行,包括人民银行、商业银行、政策性银行;信用社;证券公司、金融租赁公司、证券基金管理公司、财务公司、信托公司;保险公司;其他经中国人民银行、金融监管总局、中国证监会批准成立且经营金融保险业务的金融机构等。\n\n19.保险公司开办的一年期以上人身保险产品取得的保费收入。\n\n一年期以上人身保险,是指保险期间为一年期及以上返还本利的人寿保险、养老年金保险和其他年金保险,以及保险期间为一年期及以上的健康保险。\n\n人寿保险,是指以人的寿命为保险标的的人身保险。\n\n养老年金保险,是指以养老保障为目的,以被保险人生存为给付保险金条件,并按约定的时间间隔分期给付生存保险金的人身保险。\n\n养老年金保险应当同时符合下列条件:\n\n(1)保险合同约定给付被保险人生存保险金的年龄不得小于国家规定的退休年龄。\n\n(2)相邻两次给付的时间间隔不得超过一年。\n\n其他年金保险,是指养老年金以外的年金保险。\n\n健康保险,是指以因健康原因导致损失为给付保险金条件的人身保险。\n\n保险公司开办一年期以上人身保险,在保险监管部门出具备案回执或批复文件前依法取得的保费收入,属于上述规定的保费收入。\n\n20.纳税人提供再保险服务(境内保险公司向境外保险公司提供的再保险服务除外),实行与原保险服务一致的增值税政策。再保险合同对应多个原保险合同的,所有原保险合同均适用免征增值税政策时,该再保险合同适用免征增值税政策。否则,该再保险合同应按规定缴纳增值税。原保险服务,是指保险分出方与投保人之间直接签订保险合同而建立保险关系的业务活动。\n\n21.医疗机构接受其他医疗机构委托,按照不高于地市级以上医疗保障部门牵头制定的医疗服务价格(包括政府指导价和按照规定由供需双方协商确定的价格等),提供《全国医疗服务价格项目规范》所列的各项服务,可适用本公告第二条第一项“医疗机构提供的医疗服务”政策。\n\n22.为了配合国家住房制度改革,企业、行政事业单位按房改成本价、标准价出售住房取得的收入。\n\n23.住房公积金管理中心用住房公积金在指定的委托银行发放的个人住房贷款取得的利息收入。\n\n24.黄金生产和经营单位销售黄金(不包括以下品种:牌号为AU9999、AU9995、AU999、AU995,规格为50克、100克、1公斤、3公斤、12.5公斤的黄金,统称标准黄金)和黄金矿砂(含伴生金)。\n\n25.中国信达资产管理股份有限公司、中国中信金融资产管理股份有限公司、中国长城资产管理股份有限公司和中国东方资产管理股份有限公司及各自经批准分设于各地的分支机构(以下称资产公司),在收购、承接和处置剩余政策性剥离不良资产和改制银行剥离不良资产过程中开展的以下业务:\n\n(1)接受相关国有银行的不良债权,借款方以货物、不动产、无形资产、有价证券和票据等抵充贷款本息的,资产公司销售、转让该货物、不动产、无形资产、有价证券、票据以及利用该货物、不动产从事的融资租赁业务。\n\n(2)接受相关国有银行的不良债权取得的利息。\n\n(3)资产公司所属的投资咨询类公司,为本公司收购、承接、处置不良资产而提供的资产、项目评估和审计服务。\n\n政策性剥离不良资产,是指资产公司按照国务院规定的范围和额度,以账面价值进行收购的相关国有银行的不良资产。\n\n处置不良资产,是指资产公司按照有关法律、行政法规,为使不良资产的价值得到实现而采取的债权转移的措施,具体包括运用出售、置换、资产重组、债转股、证券化等方法对贷款及其抵押品进行处置。\n\n资产公司除收购、承接、处置规定的政策性剥离不良资产和改制银行剥离不良资产业务外,从事其他经营业务应一律依法纳税。\n\n除另有规定者外,资产公司所属、附属企业,不得享受资产公司免征增值税的政策。\n\n26.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 国家税务总局关于血站有关税收问题的通知》(财税字〔1999〕264号)。\n\n(2)《财政部 国家税务总局关于医疗卫生机构有关税收政策的通知》(财税〔2000〕42号)第三条。\n\n(3)《财政部 国家税务总局关于中国信达等4家金融资产管理公司税收政策问题的通知》(财税〔2001〕10号)。\n\n(4)《财政部 国家税务总局关于中国东方资产管理公司处置港澳国际(集团)有限公司有关资产税收政策问题的通知》(财税〔2003〕212号)。\n\n(5)《财政部 国家税务总局关于免征蔬菜流通环节增值税有关问题的通知》(财税〔2011〕137号)和《财政部 国家税务总局关于免征部分鲜活肉蛋产品流通环节增值税政策的通知》(财税〔2012〕75号)。\n\n(6)《财政部 国家税务总局关于熊猫普制金币免征增值税政策的通知》(财税〔2012〕97号)。\n\n(7)《财政部 税务总局 海关总署关于第18届世界中学生运动会等三项国际综合运动会税收政策的公告》(财政部 税务总局 海关总署公告2020年第19号)。\n\n(8)《财政部 税务总局关于支持小微企业融资有关税收政策的公告》(财政部 税务总局公告2023年第13号)。\n\n(9)《财政部 税务总局关于金融机构小微企业贷款利息收入免征增值税政策的公告》(财政部 税务总局公告2023年第16号)。\n\n(10)《财政部 税务总局关于延续执行农户、小微企业和个体工商户融资担保增值税政策的公告》(财政部 税务总局公告2023年第18号)。\n\n(11)《财政部 税务总局 科技部 教育部关于继续实施科技企业孵化器、大学科技园和众创空间有关税收政策的公告》(财政部 税务总局 科技部 教育部公告2023年第42号)。\n\n(12)《财政部 税务总局关于延续实施小额贷款公司有关税收优惠政策的公告》(财政部 税务总局公告2023年第54号)。\n\n(13)《财政部 税务总局关于延续实施供热企业有关税收政策的公告》(财政部 税务总局公告2023年第56号)(至2027年供暖期结束)。\n\n(14)《财政部 税务总局关于继续实施农村饮水安全工程税收优惠政策的公告》(财政部 税务总局公告2023年第58号)。\n\n(15)《财政部 税务总局关于延续实施边销茶增值税政策的公告》(财政部 税务总局公告2023年第59号)。\n\n(16)《财政部 税务总局关于延续免征国产抗艾滋病病毒药品增值税政策的公告》(财政部 税务总局公告2023年第62号)。\n\n(17)《财政部 税务总局关于延续实施金融机构农户贷款利息收入免征增值税政策的公告》(财政部 税务总局公告2023年第67号)。\n\n(18)《财政部 税务总局 中央宣传部关于延续实施文化体制改革中经营性文化事业单位转制为企业有关税收政策的公告》(财政部 税务总局 中央宣传部公告2023年第71号)。\n\n(19)《财政部 海关总署 税务总局关于哈尔滨2025年第九届亚洲冬季运动会税收政策的通知》(财税〔2024〕24号)。\n\n(20)《财政部 海关总署 税务总局关于2025年第12届世界运动会税收政策的通知》(财税〔2025〕15号)。"},{"no":"三","title":"适用简易计税方法的项目","text":"(一)自2026年1月1日至2027年12月31日,一般纳税人发生以下应税交易,可以选择适用简易计税方法,按照3%的征收率计算缴纳增值税。\n\n1.销售自行采掘的建筑用和生产建筑材料所用的砂、土、石料,和以自行采掘的砂、土、石料或其他矿物连续自行生产的砖、瓦、石灰(不含粘土实心砖、瓦)。\n\n2.小型水力发电单位销售自产的电力。小型水力发电单位,是指装机容量为5万千瓦以下(含5万千瓦)的小型水力发电单位。\n\n3.销售自来水。水利工程供应天然水比照销售自来水政策执行。\n\n4.寄售商店代销寄售物品(包括居民个人寄售的物品在内)。\n\n5.典当业销售死当物品。\n\n6.提供公共交通运输服务。公共交通运输服务,包括轮客渡、公交客运、地铁、城市轻轨、出租车、长途客运、班车。班车,是指按固定路线、固定时间运营并在固定站点停靠的运送旅客的陆路运输服务。\n\n7.以清包工方式提供的建筑服务。以清包工方式提供建筑服务,是指施工方不采购建筑工程所需的材料或只采购辅助材料,并收取人工费、管理费或者其他费用的建筑服务。\n\n8.为建筑工程老项目提供的建筑服务。建筑工程老项目,是指《建筑工程施工许可证》注明的合同开工日期在2016年4月30日前的建筑工程项目;《建筑工程施工许可证》未注明合同开工日期或者未取得《建筑工程施工许可证》但建筑工程承包合同注明的开工日期在2016年4月30日前的建筑工程项目。\n\n9.依据有关法律、法规批准设立的农村信用社、村镇银行、农村资金互助社、法人机构在县(市、区、旗)及县以下地区的农村合作银行和农村商业银行提供金融服务。县(市、区、旗)不包括直辖市和地级市所辖区。\n\n10.非企业单位提供的研发和技术服务、信息技术服务、鉴证咨询服务,以及销售技术、著作权等无形资产。\n\n11.公路经营企业收取开工日期在2016年4月30日前的高速公路的车辆通行费。高速公路的开工日期,以相关施工许可证明上注明的合同开工日期为准。\n\n12.提供电影放映服务、仓储服务、装卸搬运服务、收派服务和文化体育服务。\n\n13.提供非学历教育服务、教育辅助服务。\n\n14.资管产品管理人运营契约制资管产品过程中发生的增值税应税行为。\n\n资管产品管理人,包括银行、信托公司、公募基金管理公司及其子公司、证券公司及其子公司、期货公司及其子公司、私募基金管理人、保险资产管理公司、专业保险资产管理机构、养老保险公司。\n\n资管产品,包括银行理财产品、资金信托(包括集合资金信托计划、单一资金信托)、财产权信托、公开募集证券投资基金、特定客户资产管理计划、集合资产管理计划、定向资产管理计划、私募投资基金、债权投资计划、股权投资计划、股债结合型投资计划、资产支持计划、组合类保险资产管理产品、养老保障管理产品。\n\n15.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 海关总署 税务总局 国家药品监督管理局关于抗癌药品增值税政策的通知》(财税〔2018〕47号)。\n\n(2)《财政部 海关总署 税务总局 药监局关于罕见病药品增值税政策的通知》(财税〔2019〕24号)。\n\n(3)《财政部 海关总署 税务总局 药监局关于发布第二批适用增值税政策的抗癌药品和罕见病药品清单的公告》(财政部 海关总署 药监局公告2020年第39号)。\n\n(4)《财政部 海关总署 税务总局 药监局关于发布第三批适用增值税政策的抗癌药品和罕见病药品清单的公告》(财政部 海关总署 药监局公告2022年第35号)。\n\n(5)《财政部 税务总局关于延续实施中国邮政储蓄银行三农金融事业部涉农贷款增值税政策的公告》(财政部 税务总局公告2023年第66号)。\n\n(二)自2026年1月1日至2027年12月31日,一般纳税人发生以下应税交易,可以选择适用简易计税方法,按照5%的征收率计算缴纳增值税。\n\n1.2016年4月30日前签订的不动产融资租赁合同,或者以2016年4月30日前取得的不动产提供的融资租赁服务。\n\n2.收取开工日期在2016年4月30日前的一级公路、二级公路、桥、闸通行费。公路、桥、闸的开工日期,以相关施工许可证明上注明的合同开工日期为准。\n\n3.出租其2016年4月30日前取得的不动产。\n\n4.销售其2016年4月30日前取得(含自建)的不动产。\n\n5.转让其2016年4月30日前取得的土地使用权。\n\n6.房地产开发企业销售、出租自行开发的房地产老项目。\n\n房地产老项目,是指《建筑工程施工许可证》注明的合同开工日期在2016年4月30日前的房地产项目;《建筑工程施工许可证》未注明合同开工日期或者未取得《建筑工程施工许可证》但建筑工程承包合同注明的开工日期在2016年4月30日前的房地产项目。\n\n房地产开发企业以围填海方式取得土地并开发的房地产项目,以围填海工程《建筑工程施工许可证》或建筑工程承包合同注明的围填海开工日期确定合同开工日期。\n\n房地产开发企业购入未完工的房地产老项目继续开发后,以自己名义立项销售的不动产,属于房地产老项目。\n\n(三)纳税人发生以下应税交易,可以选择适用简易计税方法,按照规定征收率计算缴纳增值税。\n\n1.自2026年1月1日起,一般纳税人销售自己使用过的属于增值税法第二十二条规定不得抵扣且未抵扣进项税额的固定资产,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n固定资产,是指使用期限超过12个月的机器、机械、运输工具以及其他与生产经营相关的设备、工具、器具等。\n\n2.自2026年1月1日起,小规模纳税人(不含自然人)销售自己使用过的固定资产,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n3.自2026年1月1日起,销售旧货,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n旧货,是指进入二次流通的具有部分使用价值的货物(含旧汽车、旧摩托车和旧游艇),但不包括自己使用过的物品。\n\n4.自2026年1月1日起,个人(不含个体工商户中的一般纳税人)出租住房,按照简易计税方法依照3%征收率减按1.5%计算缴纳增值税。\n\n5.自2026年1月1日起,《财政部 税务总局 住房城乡建设部关于完善住房租赁有关税收政策的公告》(财政部 税务总局 住房城乡建设部公告2021年第24号)中现行有效的增值税优惠政策。\n\n6.自2026年1月1日至2027年12月31日,小规模纳税人发生除销售、出租不动产或者转让土地使用权之外的增值税应税交易,依照3%征收率减按1%征收率征收增值税;按规定预缴增值税的项目,当期在预缴地实现的全部价款、预收款(均不含增值税)合计达到增值税起征点的,减按1%预征率预缴增值税。\n\n7.自2026年1月1日至2027年12月31日,《财政部 税务总局关于延续实施二手车经销有关增值税政策的公告》(财政部 税务总局公告2023年第63号)中现行有效的增值税优惠政策。\n\n(四)有关规定。\n\n1.一般纳税人销售自行开发的房地产项目、提供建筑服务,可以按照房地产开发项目、工程建设项目选择适用简易计税方法。除上述情形外,一般纳税人应当就同一简易计税方法项目的全部应税交易一并选择适用简易计税方法。\n\n2.一般纳税人自选择适用简易计税方法当月起,36个月内不得变更;期限届满后,自选择适用一般计税方法当月起,36个月内不得再选择适用简易计税方法。\n\n3.纳税人按照简易计税方法依照规定征收率计算缴纳增值税的,按照下列公式计算销售额:\n\n销售额=含税销售额÷(1+规定征收率)"},{"no":"四","title":"允许从含税销售额中扣除相关价款的应税交易","text":"自2026年1月1日至2027年12月31日,纳税人发生下列应税交易,允许从含税销售额中扣除相关价款后计算销项税额或者应纳税额\n\n(一)金融机构开展贴现、转贴现业务,以其实际持有票据期间取得的利息收入作为销售额。\n\n金融机构开展贴现、转贴现业务需要就贴现利息开具发票的,由贴现机构按照票据贴现利息全额向贴现人开具增值税普通发票,转贴现机构按照转贴现利息全额向贴现机构开具增值税普通发票。\n\n(二)中国证券登记结算有限责任公司按规定提取的证券结算风险基金、收取的证券公司资金交收违约垫付资金利息、结算过程中收取的资金交收违约罚息,允许从含税销售额中扣除。\n\n(三)融资租赁和融资性售后回租业务。\n\n1.经国务院行业主管部门批准(含备案)从事融资租赁业务的纳税人,提供融资租赁服务,支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息和车辆购置税,允许从含税销售额中扣除。\n\n2.经国务院行业主管部门批准(含备案)从事融资租赁业务的纳税人,提供融资性售后回租服务,对外支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额(不含本金)中扣除。\n\n3.纳税人根据2016年4月30日前签订的有形动产融资性售后回租合同,在合同到期前提供的有形动产融资性售后回租服务,可以继续按照有形动产融资租赁服务缴纳增值税。\n\n继续按照有形动产融资租赁服务缴纳增值税的纳税人,经国务院行业主管部门批准(含备案)从事融资租赁业务的,根据2016年4月30日前签订的有形动产融资性售后回租合同,可以选择以下方法之一计算销项税额或者应纳税额:\n\n(1)向承租方收取的价款本金,以及对外支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额中扣除。\n\n纳税人提供有形动产融资性售后回租服务,计算当期销项税额或者应纳税额时可以扣除的价款本金,为书面合同约定的当期应当收取的本金。无书面合同或者书面合同没有约定的,为当期实际收取的本金。\n\n(2)支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额中扣除。\n\n4.经商务部授权的省级商务主管部门和国家经济技术开发区批准(含备案)的从事融资租赁业务的纳税人,实收资本达到1.7亿元的,从达到标准的当月起按照上述规定执行。\n\n(四)纳税人提供建筑服务适用简易计税方法计税的,支付的分包款允许从含税销售额中扣除。\n\n(五)一般纳税人提供劳务派遣服务,代用工单位支付给劳务派遣员工的工资、福利和为其办理的社会保险及住房公积金,允许从含税销售额中扣除。\n\n劳务派遣服务,是指取得《劳务派遣经营许可证》的劳务派遣公司,为了满足用工单位对于各类灵活用工的需求,将员工派遣至用工单位,接受用工单位管理并为其工作的服务。\n\n取得《保安服务许可证》的保安服务公司,提供安全保护服务(含武装守护押运服务)比照上述政策执行。\n\n(六)纳税人提供旅游服务,向旅游服务购买方收取并支付给其他单位或者个人的住宿费、餐饮费、交通费、签证费、门票费和支付给其他接团旅游企业的旅游费用,允许从含税销售额中扣除。\n\n(七)纳税人转让其2016年4月30日前取得的土地使用权,选择适用简易计税方法计税的,取得该土地使用权的原价允许从含税销售额中扣除。\n\n(八)一般纳税人销售其2016年4月30日前取得(不含自建)的不动产,选择适用简易计税方法计税的,以及小规模纳税人销售其取得(不含自建)的不动产(不含个人销售购买的住房),该项不动产购置原价或者取得不动产时的作价允许从含税销售额中扣除。\n\n(九)房地产开发企业销售房地产项目。\n\n房地产开发企业销售其开发的适用一般计税方法计税的房地产项目,受让土地时向政府部门支付的土地出让金、征地和拆迁补偿费用、土地前期开发费用和土地出让收益(以下统称土地价款),以及在取得土地时向其他单位或个人支付的货币形式拆迁补偿费用,允许从含税销售额中扣除。\n\n当期允许扣除的土地价款=(当期销售房地产项目建筑面积÷房地产项目可供销售建筑面积)×支付的土地价款\n\n当期销售房地产项目建筑面积,是指当期进行纳税申报的增值税销售额对应的建筑面积。\n\n房地产项目可供销售建筑面积,是指房地产项目可以出售的总建筑面积,不包括销售房地产项目时未单独作价结算的配套公共设施的建筑面积。\n\n房地产开发企业(包括多个房地产开发企业组成的联合体)受让土地向政府部门支付土地价款后,设立项目公司对该受让土地进行开发,同时符合下列条件的,可由项目公司按规定扣除房地产开发企业向政府部门支付的土地价款。\n\n1.房地产开发企业、项目公司、政府部门三方签订变更协议或补充合同,将土地受让人变更为项目公司;\n\n2.政府部门出让土地的用途、规划等条件不变的情况下,签署变更协议或补充合同时,土地价款总额不变;\n\n3.项目公司存续期间的全部股权由受让土地的房地产开发企业持有。\n\n(十)纳税人开展金银首饰以旧换新业务,旧金银首饰的作价允许从含税销售额中扣除。\n\n(十一)纳税人按照本公告第四条第三项至第九项规定从含税销售额中扣除的价款,应当取得符合法律、行政法规或者税务总局规定的合法有效凭证留存备查。否则,不得扣除。\n\n1.适用第四条第五项规定,以工资、福利支付记录,社会保险缴费记录以及住房公积金缴存记录为合法有效凭证。\n\n2.适用第四条第七、九项规定,向政府支付土地价款的,以省级以上(含省级)财政部门监(印)制的财政票据为合法有效凭证。\n\n3.适用第四条第七、八项规定,向其他单位或者个人支付的款项,以发票或者法院判决书、裁定书、调解书,以及仲裁裁决书、公证债权文书为合法有效凭证。如因丢失等原因无法提供取得不动产时的发票,以其他能证明契税计税金额的完税凭证等资料为合法有效凭证。\n\n4.适用第四条第九项规定,向其他单位或个人支付的货币形式拆迁补偿费用,以拆迁协议、拆迁双方支付和取得拆迁补偿费用凭证等能够证明拆迁补偿费用真实性的材料为合法有效凭证。\n\n5.除本项上述规定外,按以下规定执行。\n\n(1)支付给境内单位或者个人的款项,以发票或者省级以上(含省级)财政部门监(印)制的财政票据为合法有效凭证。\n\n(2)支付给境外单位或者个人的款项,以该单位或者个人的签收单据为合法有效凭证,税务机关对签收单据有疑义的,可以要求其提供境外公证机构的确认证明。\n\n(3)缴纳的税款,以完税凭证为合法有效凭证。\n\n纳税人取得的上述凭证属于增值税扣税凭证的,其进项税额不得从销项税额中抵扣。\n\n(十二)纳税人按照第四条第二项至第八项规定从含税销售额中扣除相关价款的,应按以下规定开具发票,否则,不得扣除。\n\n1.适用第四条第二、三、四、六项规定,从含税销售额中扣除的相关价款,不得开具增值税专用发票,可以开具普通发票。\n\n2.适用第四条第五、七、八项规定,全部含税销售额和扣除的价款应在同一张发票上分别列明,发票的税额按含税销售额扣除相关价款后计算。"},{"no":"五","title":"其他增值税优惠项目","text":"(一)自2026年1月1日至2027年12月31日,一般纳税人提供管道运输服务,对其增值税实际税负超过3%的部分实行增值税即征即退政策。\n\n增值税实际税负,是指纳税人当期提供管道运输服务实际缴纳的增值税额占纳税人当期提供管道运输服务取得的销售额的比例。\n\n(二)自2026年1月1日起,一般纳税人购进农产品,取得一般纳税人开具的增值税专用发票或海关进口增值税专用缴款书的,以增值税专用发票或海关进口增值税专用缴款书上注明的增值税额为进项税额;从按照简易计税方法依照3%征收率计算缴纳增值税的小规模纳税人取得增值税专用发票的,以增值税专用发票上注明的金额和9%的扣除率计算进项税额;取得(开具)农产品销售发票或收购发票的,以农产品销售发票或收购发票上注明的农产品买价和9%的扣除率计算进项税额。一般纳税人从农民专业合作社购进的免税农产品,可按9%的扣除率计算进项税额。\n\n(三)自2026年1月1日至2027年12月31日,药品生产企业销售自产创新药的销售额,为向购买方收取的全部价款,其提供给患者后续免费使用的相同创新药,不属于增值税视同应税交易范围。\n\n(四)自2026年1月1日起,下列文件中现行有效的增值税优惠政策继续实施。\n\n1.《财政部 国家税务总局关于软件产品增值税政策的通知》(财税〔2011〕100号)。\n\n2.《财政部 国家税务总局关于外国驻华使(领)馆及其馆员在华购买货物和服务增值税退税政策的通知》(财税〔2016〕51号)和《财政部 税务总局关于外国驻华使(领)馆及其馆员在华购买货物和服务增值税退税政策有关问题的补充通知》(财税〔2017〕74号)。\n\n3.《财政部 税务总局关于完善资源综合利用增值税政策的公告》(财政部 税务总局公告2021年第40号)。\n\n4.《财政部 海关总署 税务总局关于调整风力发电等增值税政策的公告》(财政部 海关总署 税务总局公告2025年第10号)第二条。\n\n(五)自2026年1月1日至2027年12月31日,下列文件中现行有效的增值税优惠政策继续实施。\n\n1.《财政部 国家税务总局关于粮食企业增值税征免问题的通知》(财税字〔1999〕198号)和《财政部 国家税务总局关于免征储备大豆增值税政策的通知》(财税〔2014〕38号)。\n\n2.《财政部 国家税务总局关于退还集成电路企业采购设备增值税期末留抵税额的通知》(财税〔2011〕107号)。\n\n3.《财政部 国家税务总局关于在部分行业试行农产品增值税进项税额核定扣除办法的通知》(财税〔2012〕38号)和《财政部 国家税务总局关于扩大农产品增值税进项税额核定扣除试点行业范围的通知》(财税〔2013〕57号)。\n\n4.《财政部 国家税务总局关于促进残疾人就业增值税优惠政策的通知》(财税〔2016〕52号)。\n\n5.《财政部 税务总局关于明确无偿转让股票等增值税政策的公告》(财政部 税务总局公告2020年第40号)。\n\n6.《财政部 税务总局关于集成电路企业增值税加计抵减政策的通知》(财税〔2023〕17号)。\n\n7.《财政部 税务总局关于工业母机企业增值税加计抵减政策的通知》(财税〔2023〕25号)。\n\n8.《财政部 税务总局 退役军人事务部关于进一步扶持自主就业退役士兵创业就业有关税收政策的公告》(财政部 税务总局 退役军人事务部公告2023年第14号)。\n\n9.《财政部 税务总局 人力资源社会保障部 农业农村部关于进一步支持重点群体创业就业有关税收政策的公告》(财政部 税务总局 人力资源社会保障部 农业农村部公告2023年第15号)。\n\n10.《财政部 税务总局关于民用航空发动机和民用飞机税收政策的公告》(财政部 税务总局公告2023年第27号)。\n\n11.《财政部 税务总局关于继续实施银行业金融机构、金融资产管理公司不良债权以物抵债有关税收政策的公告》(财政部 税务总局公告2023年第35号)。\n\n12.《财政部 商务部 税务总局关于研发机构采购设备增值税政策的公告》(财政部 税务总局公告2023年第41号)和《财政部 科技部 民政部 商务部 税务总局关于继续执行上海市浦东新区有关研发机构适用采购设备增值税政策资格认定事项的通知》(财税〔2023〕32号)。\n\n13.《财政部 税务总局关于先进制造业企业增值税加计抵减政策的公告》(财政部 税务总局公告2023年第43号)。\n\n14.《财政部 税务总局关于延续实施宣传文化增值税优惠政策的公告》(财政部 税务总局公告2023年第60号)和《财政部 税务总局关于更新宣传文化增值税优惠政策适用名单的公告》(财政部 税务总局公告2024年第11号)。\n\n15.《财政部 税务总局关于延续实施支持文化企业发展增值税政策的公告》(财政部 税务总局公告2023年第61号)。\n\n16.《财政部 海关总署 税务总局关于调整风力发电等增值税政策的公告》(财政部 海关总署 税务总局公告2025年第10号)第一条。\n\n17.《财政部 税务总局关于黄金有关税收政策的公告》(财政部 税务总局公告2025年第11号)。\n\n(六)《财政部 国家税务总局关于全面推开营业税改征增值税试点的通知》(财税〔2016〕36号)中附件2《营业税改征增值税试点有关事项的规定》“一般纳税人为甲供工程提供的建筑服务,可以选择适用简易计税方法计税”和《财政部 税务总局关于建筑服务等营改增试点政策的通知》(财税〔2017〕58号)“建筑工程总承包单位为房屋建筑的地基与基础、主体结构提供工程服务,建设单位自行采购全部或部分钢材、混凝土、砌体材料、预制构件的,适用简易计税方法计税”的规定自2026年1月1日起停止执行,纳税人在2026年1月1日前已适用简易计税方法的项目,继续按照原政策规定执行。"},{"no":"六","title":"施行日期","text":"本公告自2026年1月1日起实施。除本公告和增值税法、增值税法实施条例、《财政部 税务总局关于个人销售住房增值税政策的公告》(财政部 税务总局公告2025年第17号)外,在2025年12月31日前制发文件规定的国内环节增值税优惠政策同时停止执行。\n\n特此公告。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202602/t20260228_33923105.html","sourceNote":"2026-10-31 取自湖南省人民政府门户网站政策速递栏目转载页（信息来源：税务总局网站），原文落款2026年1月30日，本网发布2026-02-28；核心小规模纳税人优惠执行期2026-01-01至2027-12-31，故expiresAt记为2027-12-31。；2026-11-08 核对：页面发布日期 2026-02-28","verified":true,"isSample":false,"numberStyle":"item","bodyVerified":"verbatim","hunan":false}];
